	int g = gcd(na, nb);
		if (g != 0){
		na /= g; nb /= g;
	}
	if (n == 0 and (na != MA or nb != MB)){
		return 40000;
	}
	if (na == MA and nb == MB){
		return 0;
	}
	int& ans = dp[n][ma][mb];
	if (ans == NIL){
		int a = cost(n - 1, ma, mb);
		int b = cost(n - 1, ma + ch[n].a, mb + ch[n].b) + ch[n].c;
		ans = min(a, b); 
	}
	return ans;
}

int main(){
	ios_base::sync_with_stdio(false); cin.tie(NULL);
	cin >> N >> MA >> MB;	
	ch.resize(N + 1);
	memset(dp, NIL, sizeof dp);

	int a, b, c;
	for (int i = 1; i <= N; i++){
		cin >> a >> b >> c;
		ch[i] = {a, b, c};
	}
	//assert(gcd(MA, MB) == 1);

	int ans = cost(N, 0, 0);
	if (ans == 40000){
		ans = -1;
	}
	cout << ans << endl;

	return 0;
}

