struct C
{
    int a, b, c;
};
int N, Ma, Mb;
vector<C> A;


int solve(int pick, int acc_cost, int acc_na, int acc_nb, int target_sum)
{
    if(acc_na + acc_nb > target_sum)
        return -1;
    if(pick >= 0)
    {
        const C c = A[pick];
        acc_na += c.a;
        acc_nb += c.b;
        acc_cost += c.c;
    }
    if(acc_na + acc_nb > target_sum)
        return -1;
    if(acc_na + acc_nb  == target_sum)
        return (acc_na * Mb == acc_nb * Ma) ? acc_cost : -1;

    int min_cost = -1;
    for(size_t i = pick + 1; i < A.size(); ++i)
    {
        const int cost = solve(i, acc_cost, acc_na, acc_nb, target_sum);
        if(cost >= 0 && (min_cost < 0 || min_cost > cost))
            min_cost = cost;
    }
    return min_cost;
}

int main(int, char *[])
{
    cin >> N >> Ma >> Mb;
    int total_weight = 0;
    for(int i = 0; i < N; ++i)
    {
        C c;
        cin >> c.a >> c.b >> c.c;
        A.push_back(c);
        total_weight += c.a + c.b;
    }
    sort(A.begin(), A.end(), [] (C a, C b)->bool{return (a.a+a.b) < (b.a+b.b);});


    int min_cost = -1;
    for(int i = 1; i <= total_weight / (Ma + Mb); ++i)
    {
        const int ma = Ma * i;
        const int mb = Mb * i;
        const int cost = solve(-1, 0, 0, 0, ma + mb);
        if(cost >= 0 && (min_cost < 0 || min_cost > cost))
            min_cost = cost;
    }
    cout << min_cost << endl;
    return 0;
}

