        A += a[n - 1 - j];
        B += b[n - 1 - j];
        C += c[n - 1 - j];
      }
    }
    REP(j, 201) {
      int x = mb * (A + j) - ma * B;
      if (x % ma != 0) continue;
      x /= ma;
      if (x < 0 || x > 200) continue;
      if (mid[j][x] != INF) chmin(ans, C + mid[j][x]);
    }
