#include <iostream>
#include <vector>
#include <algorithm>

#define DRUGS_NUM_MAX 40
#define TOTAL_COST_MAX DRUGS_NUM_MAX * 1000

using namespace std;

struct Drug {
    int a;
    int b;
    int cost;
};

int n;
int ma;
int mb;
Drug drugs[DRUGS_NUM_MAX];

int min(int a, int b) {
    if(a < b) return a;
    return b;
}

int gcd(int a, int b) {
    while(a != b) {
        if(a < b) b -= a;
        else a -= b;
    }
    return a;
}

int total_cost(vector<int>& used_drugs) {
    int c = 0;
    for(auto it = used_drugs.begin(); it != used_drugs.end(); it++) {
        c += drugs[*it].cost;
    }
    return c;
}

bool is_achieved(vector<int>& used_drugs) {
    int a = 0, b = 0;
    for(auto it = used_drugs.begin(); it != used_drugs.end(); it++) {
        a += drugs[*it].a;
        b += drugs[*it].b;
    }

    int g = gcd(a, b);
    a = a / g;
    b = b / g;

    return a == ma && b == mb;
}

// 最小予算を返す
int _solve(int d, vector<int> used_drugs) {
    used_drugs.push_back(d);
    if(used_drugs.size() == n) return -1;

    int min_cost = TOTAL_COST_MAX;
    if(is_achieved(used_drugs))
        min_cost = total_cost(used_drugs);

    for(int i=0; i<n; i++) {
        if(find(used_drugs.begin(), used_drugs.end(), i) != used_drugs.end()) {
            continue;
        }

        int c = _solve(i, used_drugs);
        if(c == -1) continue;

        min_cost = min(min_cost, c);
    }

    if(min_cost == TOTAL_COST_MAX) return -1;
    return min_cost;
}

int solve() {
    int min_cost = TOTAL_COST_MAX;
    for(int i=0; i<n; i++) {
        min_cost = min(min_cost, _solve(i, vector<int>()));
    }
    if(min_cost == TOTAL_COST_MAX) return -1;
    return min_cost;
}

int main() {
    cin >> n >> ma >> mb;
    int g = gcd(ma, mb);
    ma = ma / g;
    mb = mb / g;

    int a, b, cost;
    for(int i=0; i<n; i++) {
        cin >> a >> b >> cost;
        drugs[i].a = a;
        drugs[i].b = b;
        drugs[i].cost = cost;
    }

    cout << solve() << endl;
}

