public:
	void solve() {
        int n, ma, mb;
        cin >> n >> ma >> mb;
        vector<vector<int>> dp(401, vector<int>(401, 0x7f7f7f7f));
        dp[0][0] = 0;
        for(int i=0; i < n; i++){
            int a, b, c;
            cin >> a >> b >> c;
            for(int j=400; j - a >= 0; j--){
                for(int k=400; k - b >= 0; k--){
                    updmin(dp[j][k], dp[j-a][k-b] + c);
                }
            }
        }
        int ret = 0x7f7f7f7f;
        for(int i = 1; i * max(ma, mb) <= 400; i++)updmin(ret, dp[i*ma][i*mb]);
        if(ret == 0x7f7f7f7f)cout << -1 << endl;
        else cout << ret << endl;
		return;
	};
};

