            if(mp2.count({i*Ma-sumA, i*Mb-sumB})) chmin(ans, x.second + mp2[{i*Ma-sumA, i*Mb-sumB}]);
        }
    }
    if(ans == INF) ans = -1;
    cout << ans << endl;
}

