	scanf("%d%d%d",&n,&ma,&mb);
	for(int i=0;i<n;i++)
		scanf("%d%d%d",&foo[i].a,&foo[i].b,&foo[i].c);
	sort(foo,foo+n,cmp);
	double bl=((double)ma)/((double)mb);
	int p,q;
	double rt;
	double too;
	int sum=0;
	int mins=100002;
	int flag=0;
	for(int i=0;i<n;i++){
		p=foo[i].a;
		q=foo[i].b;
		sum=foo[i].c;
		rt=((double)p)/((double)q);
