			if(rt==bl||too==bl){
				flag=1;
			}
			p+=foo[j].a;
			q+=foo[j].b;
			too=((double)p)/((double)q);
			if(abs(too-bl)<abs(rt-bl))
				sum+=foo[j].c;
			rt=too;
		}
		mins=min(mins,sum);
