  for (int i = 0; i < MAX_A + 1; i++) {
    for (int j = 0; j < MAX_B + 1; j++) {
      for (int k = 0; k < n; k++) {
        dp[i][j][k] = INT64_MAX / 3;
      }
    }
  }
  for (int i = 0; i < n; i++) {
    dp[0][0][i] = 0;
  }

