              std::min(dp[j][k][i - 1],
                       dp[j - drug[i].a][k - drug[i].b][i - 1] + drug[i].c);
        }
      }
    }
  }
  int search_a = ma, search_b = mb;
  int64_t result = INT64_MAX / 3;
  bool found     = false;
  while (search_a <= MAX_A && search_b <= MAX_B) {
    if (result > dp[search_a][search_b][n - 1]) {
      result = dp[search_a][search_b][n - 1];
      found  = true;
    }
    search_a += ma;
    search_b += mb;
  }
  if (found) {
    cout << result << endl;
  } else {
    cout << -1 << endl;
  }

  return 0;
}

