int result;
vector<drag> v;

void calc(int cost, int i, int m)
{
	if (i == n)
	{
		if (m != 0)
			return;
		if (cost == 0)
			return;
		if (cost < result)
			result = cost;
	}
	else
	{
		if (cost >= result)
			return;
		if (m > 0)
			return;

		//	次の製品がm = 0でもcostは高くなるのでx
		if (m == 0 && cost > 0)
		{
			result = cost;
			return;
		}

		if (cost + v[i].val <= 0)
		{
			calc(cost + v[i].val, i + 1, m + v[i].m);
			calc(cost, i + 1, m);
		}
	}
}


