#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N=4e2+20;
const int inf=1e5;
int n,A,B;
int dp[45][N][N];//dp[i][a][b] Ç°i¼þ ²ÄÁÏÎª[a,b]Ê±µÄ×îÐ¡¼ÛÇ® 
struct node{
	int a,b,c;
}p[N];
bool cmp(node a,node b)
{
	if(a.a==b.a)
	{
		if(a.b==b.b)
		return a.c<b.c;
		else
		return a.b<b.b;
	}
	return a.a<b.a;
}
int gcd(int a,int b)
{
	if(a%b==0)
	return b;
	else
	return gcd(b,a%b);
}
int main()
{
	while(cin>>n>>A>>B)
	{
		int ans=1e5;
		for(int i=0;i<=n;i++)
		{
			for(int j=0;j<=400;j++)
			{
				for(int k=0;k<=400;k++)
				dp[i][j][k]=inf;
			}
		}
		dp[0][0][0]=0;
		for(int i=1;i<=n;i++)
		{
			cin>>p[i].a>>p[i].b>>p[i].c;
		}
		sort(p+1,p+1+n,cmp);
		for(int i=1;i<=n;i++)
		{
			dp[i][0][0]=0;
			for(int j=400;j>=p[i].a;j--)
			{
				for(int k=400;k>=p[i].b;k--)
				{
					dp[i][j][k]=min(dp[i-1][j][k],dp[i-1][j-p[i].a][k-p[i].b]+p[i].c);
					int d=gcd(j,k);
					if(j/d==A&&k/d==B)
					{
						ans=min(ans,dp[i][j][k]);
					}
				}	
			}	
		}
		if(ans==1e5)
		ans=-1;

		cout<<ans<<endl;
	}
	return 0;	
}

