int dp[41][401][401];

int main(){
    int N,Ma,Mb;
    cin>>N>>Ma>>Mb;
    vector<int>A,B,C;
    for(int i=0;i<N;i++){
        int a,b,c;
        cin>>a>>b>>c;
        A.push_back(a);B.push_back(b);C.push_back(c);
    }
    for(int i=0;i<41;i++){
        for(int j=0;j<401;j++){
            for(int k=0;k<401;k++)dp[i][j][k]=1145141919;
        }
    }
    dp[0][A[0]][B[0]]=C[0];
    dp[0][0][0]=0;
    for(int i=1;i<N;i++){
        for(int ma=0;ma<=400;ma++){
            for(int mb=0;mb<=400;mb++){
                dp[i][ma][mb]=dp[i-1][ma][mb];
                if (ma-A[i]>=0&&mb-B[i]>=0) dp[i][ma][mb]=min(dp[i][ma][mb],dp[i-1][ma-A[i]][mb-B[i]]+C[i]);
            }
        }
    }
    int ans=114514;
    for(int ma=1;ma<=400;ma++)
    for(int mb=1;mb<=400;mb++){
        if(ma*Mb!=mb*Ma)continue;
        ans=min(ans,dp[N-1][ma][mb]);
    }
    cout<<((ans>=114514)?-1:ans)<<endl;

    return 0;
}

