#include <bits/stdc++.h>
using namespace std;

void chmin(int& a, int b){
    a = min(a, b);
}

int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

int main(){
    int N, Ma, Mb, a[40], b[40], c[40];
    cin >> N >> Ma >> Mb;
    for(int i=0; i<N; i++) cin >> a[i] >> b[i] >> c[i];

    // C[g][s] = グループgの選び方（1つ以上）で Mb*sumA - Ma*sumB = s となるときの最小コスト
    // sが負の値になり得るのでmap
    map<int, int> C[2];

    // グループgに属するのはインデックス [start[g], term[g]) の範囲のものとする
    int start[2] = {0, N/2}, term[2] = {N/2, N};

    for(int g=0; g<2; g++){
        int sz = term[g] - start[g];
        // 全列挙。1つ以上選ぶのでbits=0を見ない
        for(int bits=1; bits<(1<<sz); bits++){
            int s = 0, cost = 0;
            for(int i=0; i<sz; i++) if(nth_bit(bits, i)){
                s += Mb * a[i+start[g]] - Ma * b[i+start[g]];
                cost += c[i+start[g]];
            }
            if(C[g].count(s)){
                chmin(C[g][s], cost);
            }else{
                C[g][s] = cost;
            }
        }
    }

    // C[0][0], C[1][0], C[0][s] + C[0][-s] をそれぞれ調べる
    const int INF = 1e9;
    int ans = INF;
    for(int g=0; g<2; g++) if(C[g].count(0)) chmin(ans, C[g][0]);
    for(auto& p : C[0]){
        int s = p.first, c0 = p.second;
        if(C[1].count(-s)) chmin(ans, c0 + C[1][-s]);
    }
    if(ans == INF) ans = -1;
    cout << ans << endl;
    return 0;
}

