unsigned euclidean_gcd(unsigned a, unsigned b) {
  if(a < b) euclidean_gcd(b, a);
  unsigned r;
  while ((r=a%b)) {
    a = b;
    b = r;
  }
  return b;
}

int main(void){
    cin>>n>>ma>>mb;
    for(int i=0;i<n;i++)cin>>a[i]>>b[i]>>c[i];
    map<pair<int, int>, int> m1,m2;
    for(ll i=0;i<1<<n/2;i++){
        suma=0,sumb=0,sumc=0;
        for(int j=0;j<n/2;j++)if(i>>j & 1){
            suma+=a[j];sumb+=b[j];sumc+=c[j];
        }

        if(m1.count(make_pair(suma,sumb))){
            auto it = m1.find((make_pair(suma,sumb)));
            if(sumc < it->second)m2[make_pair(suma,sumb)]=sumc;    
        }
        else m1[make_pair(suma,sumb)]=sumc;
    }
    for(ll i=0;i<(1<<n/2)+1;i++){
        suma=0,sumb=0,sumc=0;
        for(int j=n/2;j<n;j++)if(i>>j & 1){
            suma+=a[j];sumb+=b[j];sumc+=c[j];
        }
        if(m2.count(make_pair(suma,sumb))){
            auto it = m2.find((make_pair(suma,sumb)));
            if(sumc < it->second)m2[make_pair(suma,sumb)]=sumc;
        }
        else m2[make_pair(suma,sumb)]=sumc;
    }
