    for(auto x: m1)for(auto y:m2){
        suma=x.first.first+y.first.first;
        sumb=x.first.second+y.first.second;
        sumc=x.second+y.second;
        if(suma == 0 || sumb==0)continue;
        gcdv=euclidean_gcd(suma,sumb);
        if(suma/gcdv == ma && sumb/gcdv == mb)minv=min(minv,sumc);
    }
    cout<<(minv==(int)1e9 ? -1 : minv)<<endl;
}

