using mix_t = pair<int, int>;

int get_gcd(int a, int b) {
  while (b > 0) {
    a %= b;
    swap(a, b);
  }
  return a;
}

int main() {
  auto start = high_resolution_clock::now();

  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, ma, mb;
  cin >> n >> ma >> mb;
  int g = get_gcd(ma, mb);
  ma /= g;
  mb /= g;

  map<mix_t, int> st, buf;
  for (int i = 0; i < n; ++i) {
    int a, b, c;
    cin >> a >> b >> c;
    buf.clear();

    buf[mix_t(a, b)] = c;

    for (const pair<mix_t, int>& it : st) {
      int ca = it.first.first;
      int cb = it.first.second;
      int cc = it.second;

      if (buf.find(it.first) == buf.end())
        buf[it.first] = it.second;
      else
        buf[it.first] = min(buf[it.first], it.second);

      ca += a;
      cb += b;
      cc += c;

      if (buf.find(mix_t(ca, cb)) == buf.end())
        buf[mix_t(ca, cb)] = cc;
      else
        buf[mix_t(ca, cb)] = min(buf[mix_t(ca, cb)], cc);
    }

    swap(st, buf);
  }

  int ans = -1;
  for (const pair<mix_t, int>& it : st) {
    int ca = it.first.first;
    int cb = it.first.second;
    g = get_gcd(ca, cb);
    ca /= g;
    cb /= g;
    if (ca == ma && cb == mb) {
      if (ans == -1)
        ans = it.second;
      else
        ans = min(ans, it.second);
    }
  }

  cout << ans << endl;

  cerr << "Total execution time : " << duration_cast<milliseconds>(high_resolution_clock::now() - start).count() << " ms" << endl;

  return 0;
}

