vector<int> f;


struct state{

    int A, B, C;

};

struct Compare{
    bool operator()(const state& lhs, const state & rhs) {
        return lhs.A *Mb - lhs.B*Ma < rhs.A*Mb - rhs.B*Ma;
    }
};

int main() {

    cin >> N >> Ma >> Mb;
    int half = N/2;
    int rest = N-half;
    a.resize(half);b.resize(half);c.resize(half);
    d.resize(rest);e.resize(rest);f.resize(rest);


    for(auto i = 0; i<half; i++){
        cin >> a[i] >> b[i] >> c[i];
    }
    for(auto i = 0; i<rest; i++){
        cin >> d[i] >> e[i] >> f[i];
    }

    set<state,Compare> st;

    for(auto i = 1; i< (1<<half); i++){

        auto temp = i;
        int count = 0;
        state val;
        val.A = 0;
        val.B = 0;
        val.C = 0;
        while(temp != 0){
            if(temp%2 == 1){
                val.A += a[count];
                val.B += b[count];
                val.C += c[count];
            }
            temp/=2;
            count++;
        }
        st.insert(val);
    }

    set<state,Compare> str;

    for(auto i = 1; i< (1<<rest); i++){

        auto temp = i;
        int count = 0;
        state val;
        val.A = 0;
        val.B = 0;
        val.C = 0;
        while(temp != 0){
            if(temp%2 == 1){
                val.A += d[count];
                val.B += e[count];
                val.C += f[count];
            }
            temp/=2;
            count++;
        }
        str.insert(val);
    }

    vector<int> pre;
    vector<int> after;
    vector<int> preC;
    vector<int> afterC;


    for(auto p = st.begin(); p != st.end(); p++){
        pre.push_back((p->A * Mb - p->B * Ma));
        preC.push_back(p->C);
    }

    for(auto p = str.begin(); p != str.end(); p++){
        after.push_back((p->A * Mb - p->B * Ma));
        afterC.push_back(p->C);
    }


    int ans = INT_MAX;
    for(auto i = pre.begin(); i != pre.end(); i++){

        auto p = find(all(after),- *i);

        if (p == after.end()) continue;

        ans = min(ans, preC[i-pre.begin()] + afterC[p-after.begin()] );

    }

    if (ans != INT_MAX){
        cout << ans << endl;
    }else{
        cout << -1 << endl;
    }

    return 0;
}

