int main () {

    int n,ma,mb; cin >>n>>ma>>mb;
    vector<int> a(n); vector<int> b(n); vector<int> c(n);
    rep(i,n) cin >> a[i] >> b[i] >> c[i];

    int n1 = n/2;
    vector<P> pairs1((1<<n1));

    for (int s = 0; s < (1<<n1); s++) {
        int suma = 0;
        int sumb = 0;
        int sumc = 0;
        for (int i = 0; i < n1; i++) {
            if (s & (1<<i)) {
                suma += a[i];
                sumb += b[i];
                sumc += c[i];
            }
        }
        pairs1[s] = P((ma+mb)*suma - ma*(suma+sumb), sumc);
    }

    sort(pairs1.begin(), pairs1.end());

    int ans = INF;
    for (int s = 0; s < (1<<(n-n1)); s++) {
        int suma = 0;
        int sumb = 0;
        int sumc = 0;
        for (int i = 0; i < (n-n1); i++) {
            if (s & (1<<i)) {
                suma += a[n1 + i];
                sumb += b[n1 + i];
                sumc += c[n1 + i];
            }
        }
        int m = ma*(suma+sumb) - (ma+mb)*suma;
        int ok = (1<<n1);
        int ng = -1;
        while (abs(ng-ok)>1) {
            int mid = (ok+ng)/2;
            if (m <= pairs1[mid].first) {
                ok = mid;
            } else {
                ng = mid;
            } 
        }
        if (m == pairs1[ok].first && sumc + pairs1[ok].second > 0) {
            if (ans > sumc + pairs1[ok].second) {
                ans = sumc + pairs1[ok].second;
            } 
        } 
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    } 

    return 0;
}

