    ll ans = INF;

    for (auto &e : p1) {

        P p = e.first;

        int a1 = p.first;
        int b1 = p.second;
        int c1 = e.second;

        for (P rate : rates) {
            int ta = rate.first - a1;
            int tb = rate.second - b1;

            if (p2.find(P(ta, tb)) == p2.end()) continue;
            cmin(ans, (ll) c1 + p2[P(ta, tb)]);

        }

    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
}

