                sumb += b[j+n1];
                sumc += c[j+n1];
            }
        }
        u[suma][sumb] = sumc;
        uu.push_back({suma,sumb});
    }
    ll ans = 1e18;
    rep(i, vv.size()){
        ll at = vv[i].fi;
        ll bt = vv[i].se;
        ll ma = Ma;
        ll mb = Mb;
        rep(j,400){
            ll ca = ma - at;
            ll cb = mb - bt;
            if((0 < ca && ca <= 400)){
                if((0 < cb && cb <= 400)){
                    if(u[ca][cb] == 0) continue;
                    if(v[at][bt] == 0) continue;
                    cmin(ans, u[ca][cb] + v[at][bt]);
                }
            }
            ma += Ma;
            mb += Mb;
        }
    }
    if(ans == 1e18){
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
}

