#define REP(i,m,n) for(int i = (m); i < (n);i++)
#define rep(i,n) REP(i,0,n)

class Prod {
public:
	int a,b;
	int cost;
	int id;
};
class State {
public:
	vector<Prod*> selection;
	vector<int> selected;
	int sa,sb;
	int sumCost;
	int ma,mb;
	State(int _ma,int _mb,int _n){
		ma = _ma;
		mb = _mb;
		sa=sb=sumCost=0;
		selected.resize(_n,0);
	}
	void Buy(Prod* _p) {
		sa += _p->a;
		sb += _p->b;
		sumCost += _p->cost;
		selection.push_back(_p);
		selected.at(_p->id) = 1;
	}
	bool HasProd(Prod* _p) {
		return (selected.at(_p->id) == 1);
	}
	bool OK() {
		return (sa % ma == 0) && (sb % mb == 0) && 
				(sa / ma == sb / mb);
	}
};
int main() {
	int n,ma,mb;
	cin >> n >> ma >> mb;
	vector<Prod> products;
	rep(i,n) {
		Prod p;
		cin >> p.a >> p.b >> p.cost;
		p.id = i;
		products.push_back(p);
	}
	queue<State> status;
	rep(i,n) {
		State st(ma,mb,n);
		Prod* p = &products.at(i);
		st.Buy(p);
		status.push(st);
	}

	int result = -1;
	while(!status.empty()) {
		State st = status.front(); status.pop();
		if(st.OK() && (result == -1 || result > st.sumCost)) {
			result = st.sumCost;
		}
		rep(i,n) {
			Prod* p = &products.at(i);
			if(st.HasProd(p))continue;
			State next = st;
			next.Buy(p);
			status.push(next);
		}
	}
	cout << result << endl;


	return 0;
}

