namespace MySpace{
    struct CartesianTree{
        struct Node{
            int x, y;
            ll summ;
            int sz;
            Node * L, * R;
        };

        Node * NewNode(int x)
        {
            Node * R = new Node();
            R->summ = x;
            R->x = x;
            R->y = (1 << 15) * rand() + rand();
            R->sz = 1;
            return R;
        }

        void describe(Node * Nd)
        {
            if (!Nd) return;
            describe(Nd->L);
            cout << Nd->x << " ";
            describe(Nd->R);
        }

        int get_sz(Node * Nd)
        {
            if (Nd) re Nd->sz; re 0;
        }

        ll get_summ(Node * Nd)
        {
            if (Nd) re Nd->summ; re 0;
        }

        ll update(Node * Nd)
        {
            Nd->summ = Nd->x + get_summ(Nd->L) + get_summ(Nd->R);
            Nd->sz = 1 + get_sz(Nd->L) + get_sz(Nd->R);
        }

        Node * Merge(Node * L, Node * R)
        {
            if (!L) return R;
            if (!R) return L;
            if (L->y < R->y)
            {
                L->R = Merge(L->R, R);
                update(L);
                return L;
            }
            else
            {
                R->L = Merge(L, R->L);
                update(R);
                return R;
            }
        }

        pair<Node *, Node *> Split(Node * Scope, int k)
        {
            if (!Scope) return {nullptr, nullptr};
            if (Scope->x <= k)
            {
                pair<Node *, Node *> a = Split(Scope->R, k);
                Scope->R = a.first;
                update(Scope);
                return {Scope, a.second};
            }
            else
            {
                pair<Node *, Node *> a = Split(Scope->L, k);
                Scope->L = a.second;
                update(Scope);
                return {a.first, Scope};
            }
        }

        pair<Node *, Node *> SplitSize(Node * Scope, int k)
        {
            if (!Scope) return {nullptr, nullptr};
            if (get_sz(Scope->L) < k)
            {
                pair<Node *, Node *> a = SplitSize(Scope->R, k - get_sz(Scope->L) - 1);
                Scope->R = a.first;
                update(Scope);
                return {Scope, a.second};
            }
            else
            {
                pair<Node *, Node *> a = SplitSize(Scope->L, k);
                Scope->L = a.second;
                update(Scope);
                return {a.first, Scope};
            }
        }

        void Add(Node *& Root, int x)
        {
            Node * Nd = NewNode(x);
            pair<Node *, Node *> a = Split(Root, x);
            a.first = Merge(a.first, Nd);
            Root = Merge(a.first, a.second);
        }
    };
    ll inq(ll x, ll q, ll mod)
    {
        if (q == 0) return 1;
        ll l = inq(x, q / 2, mod);
        if (q % 2) return l * l % mod * x % mod;
        return l * l % mod;
    }
};

