    SQWORD sqCost;
} ST_ELEM;

int main(void)
{
    SQWORD sqInput_N = inputSQWORD();
    SQWORD sqInput_Ma = inputSQWORD();
    SQWORD sqInput_Mb = inputSQWORD();

    vector<ST_ELEM> vecElem;

    for (SDWORD lIdx = 0; lIdx < sqInput_N; lIdx++) {
        SQWORD sqInput_a = inputSQWORD();
        SQWORD sqInput_b = inputSQWORD();
        SQWORD sqInput_c = inputSQWORD();

        vecElem.emplace_back(ST_ELEM{ sqInput_a, sqInput_b, sqInput_c});
    }

    /*
    *   dp(i)[j][k]
    *   i番目までの薬を使ったとき A = j, B = k となるようなコストの最小値 
    *   dp(i)[j][k] = min(dp(i-1)[j-A_i][k-B_i] + C_i)
    */
#define MAX_N_ELEM  (40)
#define MAX_QTY     (10)
#define SIZE_DP     (MAX_N_ELEM * MAX_QTY + 1)
    static SQWORD s_asqDpTbl[SIZE_DP][SIZE_DP];
    for (SQWORD sqIdxI = 0; sqIdxI < SIZE_DP; sqIdxI++) {
        for (SQWORD sqIdxJ = 0; sqIdxJ < SIZE_DP; sqIdxJ++) {
            s_asqDpTbl[sqIdxI][sqIdxJ] = MAX_SDWORD;
        }
    }
    s_asqDpTbl[0][0] = 0;

    for (auto elem: vecElem) {
        for (SQWORD sqIdxA = SIZE_DP - 1; 0 <= sqIdxA; sqIdxA--) {
            for (SQWORD sqIdxB = SIZE_DP - 1; 0 <= sqIdxB; sqIdxB--) {
                if ((elem.sqA <= sqIdxA) && (elem.sqB <= sqIdxB)) {
                    s_asqDpTbl[sqIdxA][sqIdxB]
                        = min(s_asqDpTbl[sqIdxA][sqIdxB], 
                              s_asqDpTbl[sqIdxA - elem.sqA][sqIdxB - elem.sqB] + elem.sqCost);
                }
            }
        }
    }

    SQWORD sqMinCost = MAX_SDWORD;
    for (SQWORD sqIdx = 1; sqIdx <= MAX_N_ELEM; sqIdx++) {
        SQWORD sqQtyA = sqIdx * sqInput_Ma;
        SQWORD sqQtyB = sqIdx * sqInput_Mb;
        if ((sqQtyA < SIZE_DP) && (sqQtyB < SIZE_DP)) {
            sqMinCost = min(sqMinCost, s_asqDpTbl[sqQtyA][sqQtyB]);
        }
    }
    if (MAX_SDWORD == sqMinCost) {
        printf("-1");
    } else {
        printf("%lld\n", sqMinCost);
    }
    return 0;
}

