ll dpf(ll n, ll A, ll B){
  if(v[n][A][B]==1){
    return dp[n][A][B];
  }else{
    v[n][A][B]=1;
    if(n==0){
      if(A==0 and B==0){
        dp[n][A][B]=0;
      }
    }else{
      dp[n][A][B] = dpf(n-1, A, B);
      if(A-a[n-1]>=0 and B-b[n-1]>=0){
        dp[n][A][B] = min(dpf(n-1, A-a[n-1], B-b[n-1])+c[n-1], dp[n][A][B]);
      }
    }
    return dp[n][A][B];
  }
}


