    vector <int> row(3);
    v.resize(n,row);
    int suma=0,sumb=0;
    for(int i=0;i<n;i++)
    {
        int a=nxt(),b=nxt(),c=nxt();
        v[i][0]=a;v[i][1]=b;v[i][2]=c;
        suma+=v[i][0];
        sumb+=v[i][1];
    }
    int test=INT_MAX;
    for(int mul=1;mul<=400;mul++)
    {
        int A=mul*ma;
        int B=mul*mb;
        if(A>suma||B>sumb)
            break;

        vector <vector <vector <int> > > dp;
        vector <int> r2;
        r2.resize(B+1,-1);
        vector <vector <int> > r1;
        r1.resize(A+1,r2);
        dp.resize(n,r1);
        if(v[0][0]<=A&&v[0][1]<=B)
            dp[0][v[0][0]][v[0][1]]=v[0][2];
        for(int i=1;i<n;i++)
        {
            dp[i]=dp[i-1];
            if(v[i][0]>A||v[i][1]>B)
                continue;

            for(int j=A;j>=0;j--){
                if(j-v[i][0]<0)
                        break;
                for(int k=B;k>=0;k--)
                {
                    if(j-v[i][0]<0||k-v[i][1]<0)
                        break;
                    if(dp[i][j-v[i][0]][k-v[i][1]]!=-1)
                    {
                        if(dp[i][j][k]==-1)
                            dp[i][j][k]=dp[i][j-v[i][0]][k-v[i][1]]+v[i][2];
                        else
                            dp[i][j][k]=min(dp[i][j][k],dp[i][j-v[i][0]][k-v[i][1]]+v[i][2]);
                    }
                }
            }

            if(dp[i][v[i][0]][v[i][1]]==-1)
                dp[i][v[i][0]][v[i][1]]=v[i][2];
            else
                dp[i][v[i][0]][v[i][1]]=min(dp[i][v[i][0]][v[i][1]],v[i][2]);



        }
        if(dp[n-1][A][B]!=-1)
            test=min(test,dp[n-1][A][B]);

    }

    if(test==INT_MAX)
        cout<<"-1\n";
    else
        cout<<test<<endl;




    return 0;   
}

