int opt(int i, int ca, int cb)
{
	int ra = ca/(__gcd(ca,cb) == 0?1:__gcd(ca,cb));
	int rb = cb/(__gcd(ca,cb) == 0?1:__gcd(ca,cb));
	if(ra == ma && rb == mb)
	{
		return 0;
	}
	if(i >= n) 
	{
		return INF;
	}
	if(dp[i][ca][cb]==-1)
	{
		dp[i][ca][cb] = min(opt(i+1,ca,cb),opt(i+1,ca+A[i],cb+B[i])+C[i]);
	}
	return dp[i][ca][cb];
}

