int modpow(int a, int n, int p) {
	if (n == 0) { return 1; }
	int m = n / 2;
	int x = modpow(a, n / 2, p);
	x *= x; x %= p;
	if (n % 2 == 1) { x *= a; x %= p; }
	return x;
}
int solve(int n, int x, vel& a,vel&b) {
	if (n == 0) {
		return x;
	}
	if (x == 0) { return 0; }
	if (x <= a[n-1] + 1) { return solve(n - 1, x - 1, a, b); }
	return b[n-1] + 1 + solve(n - 1, min(x - a[n - 1] - 2, a[n - 1]), a,b);
}
