	REP(i, n) scanf("%d %d %d", a + i, b + i, c + i);

	vector<pii> sa;
	REP(i, 1 << (n / 2)) {
		int suma = 0, sumb = 0, sumc = 0;
		REP(j, n / 2) if (i >> j & 1) {
			suma += a[j];
			sumb += b[j];
			sumc += c[j];
		}
		sa.push_back(pii(sumb * ma - suma * mb, sumc));
	}
	sort(ALL(sa));

	int ans = INF;
	REP(i, 1 << (n - n / 2)) {
