		REP(j, n - n / 2) if (i >> j & 1) {
			suma += a[j + n / 2];
			sumb += b[j + n / 2];
			sumc += c[j + n / 2];
		}
		int diff = sumb * ma - suma * mb;

		vector<pii>::iterator it = lower_bound(ALL(sa), pii(-diff, 0));
		if (it == sa.end()) continue;
		if (it->second != -diff || it->second + sumc == 0) continue;

		chmin(ans, it->second + sumc);
	}
	if (ans == INF) ans = -1;

	cout << ans << endl;
	return 0;
}

