void process(LIQUID liquid[], LIQUID mix, int n, int pos, int Ma, int Mb, int *min);
int main(){
	LIQUID liquid[MAX],mix = {0,0,0};
	int n,Ma,Mb;
	int i;
	int min = -1;
	cin >> n >> Ma >> Mb;

	for(i=0; i<n;i++){
	 cin >> liquid[i].a >> liquid[i].b >> liquid[i].c;
	}
	process(liquid,mix,n,0,Ma,Mb,&min);
	cout << min << endl;
}
void process(LIQUID liquid[], LIQUID mix, int n, int pos, int Ma, int Mb, int *min){
	if( pos == n )
		return;
	process(liquid,mix,n,pos+1,Ma,Mb,min);
	mix.a += liquid[pos].a;
	mix.b += liquid[pos].b;
	mix.c += liquid[pos].c;
	if( mix.a * Mb == mix.b * Ma ){
		if( *min == - 1 || *min > mix.c )
			*min = mix.c;
	}
	if( *min != -1 && *min < mix.c )
		return;
	process(liquid,mix,n,pos+1,Ma,Mb,min);
}

