int main() {
  size_t N;
  int Ma, Mb;
  scanf("%zu %d %d", &N, &Ma, &Mb);

  std::vector<int> a(N), b(N), c(N);
  for (size_t i=0; i<N; ++i)
    scanf("%d %d %d", &a[i], &b[i], &c[i]);

  size_t Na=N/2, Nb=N-Na;
  struct Pack { 
    int a, b, c;
    Pack(int a, int b, int c): a(a), b(b), c(c) {}
    bool operator <(const Pack &rhs) const {
      return (
          a != rhs.a? a < rhs.a 
          : b != rhs.b? b < rhs.b
          : c < rhs.c
          );
    }
  };

  std::vector<Pack> X, Y;
  for (int i=0; i<(1<<Na); ++i) {
    int a_=0, b_=0, c_=0;
    for (size_t j=0; j<Na; ++j)
      if (i>>j & 1) {
        a_ += a[j];
        b_ += b[j];
        c_ += c[j];
      }

    X.emplace_back(a_, b_, c_);
  }

  for (int i=0; i<(1<<Nb); ++i) {
    int a_=0, b_=0, c_=0;
    for (size_t j=0; j<Nb; ++j)
      if (i>>j & 1) {
        a_ += a[Na+j];
        b_ += b[Na+j];
        c_ += c[Na+j];
      }

    Y.emplace_back(a_, b_, c_);
  }

  std::sort(Y.begin(), Y.end());

  int inf=10000, res=inf;
  for (size_t i=0; i<X.size(); ++i) {
    int ma=Ma, mb=Mb;
    for (int r=1; r<=15; ++r, ma+=Ma, mb+=Mb) {
      if (ma < X[i].a || mb < X[i].b) continue;

      auto lb=std::lower_bound(
          Y.begin(), Y.end(), Pack(ma-X[i].a, mb-X[i].b, 0));

      if (lb < Y.end() && lb->a == ma-X[i].a && lb->b == mb-X[i].b) 
        res = std::min(res, X[i].c+lb->c);
    }
  }

  printf("%d\n", res<inf? res:-1);
}

