		int sum_a = 0, sum_b = 0, cost = 0;
		for(int j=0;j<z;j++){
			if(i>>j){
				sum_a += a[j];
				sum_b += b[j];
				cost += c[j];
			}
		}
		p[sum_a][sum_b] = min(cost,p[sum_a][sum_b]);
	}
	for(int i=0;i<k;i++) scanf("%d %d %d",a+i,b+i,c+i);
	for(int i=0;i<(1<<k);i++){
		int sum_a = 0, sum_b = 0, cost = 0;
		for(int j=0;j<k;j++){
			if(i>>j){
				sum_a += a[j];
				sum_b += b[j];
				cost += c[j];
			}
		}
		q[sum_a][sum_b] = min(cost,q[sum_a][sum_b]);
	}
