  for (int k = 0; k <= n; k++)
    for (int i = 0; i < MAXAB; i++)
      for (int j = 0; j < MAXAB; j++)
        dp[k][i][j] = INF;

  dp[0][0][0] = 0;

  for (int i = 1; i <= n; i++) {
    for (int j = 1; j < MAXAB; j++) {
      for (int k = 1; k < MAXAB; k++) {
        if (j - a[i] >= 0 && k - b[i] >= 0)
          dp[i][j][k] = min(dp[i - 1][k][j], dp[i - 1][j - a[i]][k - b[i]] + c[i]);
      }
    }
  }

  int ans = INF;

  for (int i = 1; i < MAXAB; i++) {
    for (int j = 1; j < MAXAB; j++) {
