int Nmax=40, abmax=10, cmax=100, INF=(Nmax+1)*cmax;
int N, a[41], b[41], c[41], ans;
int Ma, Mb;

int main() {
    cin >> N >> Ma >> Mb;
    for (int i=0; i<N; i++) cin >> a[i] >> b[i] >> c[i];

    int dpc[N+1][(N+1) * abmax][(N+1) * abmax];
    for (int n=0; n<N+1; n++) {
        for (int ca=0; ca<(N+1)*abmax; ca++) {
            for (int cb=0; cb<(N+1)*abmax; cb++) {
                dpc[n][ca][cb] = INF;
            }
        }
    }

    dpc[0][0][0] = 0;
    for (int n=0; n<N; n++) {
        for (int ca=0; ca<N*abmax; ca++) {
            for (int cb=0; cb<N*abmax; cb++) {
                if (dpc[n][ca][cb] == INF) continue;
                dpc[n+1][ca][cb] = min(dpc[n+1][ca][cb], dpc[n][ca][cb]);
                dpc[n+1][ca+a[n]][cb+b[n]] = min(dpc[n][ca+a[n]][cb+a[n]], dpc[n][ca][cb]+c[n]);
            }
        }
    }

    ans = INF;
    for (int n=0; n<N; n++) {
        for (int ca=1; ca<N*abmax; ca++) {
            for (int cb=1; cb<N*abmax; cb++) {
                if (Ma * cb == Mb * ca) ans = min(ans, dpc[n][ca][cb]);
            }
        }
    }

    if (ans != INF) cout << ans << endl;
    else cout << -1 << endl;

    return 0;
}

