using namespace std;

typedef long long ll;
typedef pair<int,int> ii;

#define MAX 50
int N,Ma,Mb,a[MAX],b[MAX],c[MAX];

void compute() {
  map<ii,ll> dp,next;
  rep(i,N) {
    next.clear();
    next = dp;
    if( dp.count(ii(a[i],b[i])) == 0 ) {
      next[ii(a[i],b[i])] = c[i];
    } else {
      next[ii(a[i],b[i])] = min(dp[ii(a[i],b[i])],(ll)c[i]);
    }
    for(auto v : dp) {
      ii fir = v.first;
      ll sec = v.second;
      fir.first  += a[i];
      fir.second += b[i];
      int gcd = __gcd(fir.first,fir.second);
      fir.first  /= gcd;
      fir.second /= gcd;
      if( next.count(fir) ) next[fir] = min(next[fir],sec+(ll)c[i]);
      else                  next[fir] = sec + (ll)c[i];
    }
    dp = next;
  }
  if( dp.count(ii(Ma,Mb)) ) cout << dp[ii(Ma,Mb)] << endl;
  else puts("-1");
}

int main() {
  cin >> N >> Ma >> Mb;
  rep(i,N) cin >> a[i] >> b[i] >> c[i];
  compute();
  return 0;
}

