        auto it1 = v1.begin();
        auto it2 = v2.rbegin();
        while (it1 != v1.end() && it2 != v2.rend()) {
            if (it1->first == 0) { it1++; continue; }
            if (it2->first == 0) { it2++; continue; }
            int diff = it1->first + it2->first;
            int cost = it1->second + it2->second;
            if (diff > 0) it2++;
            else if (diff < 0) it1++;
            else { ans = min(ans, cost); it1++; it2++; }
        }
    }
    cout << (ans == 1<<30 ? -1 : ans) << endl;
}

