void solve(vector<array<int,3>> &v,int r1,int r2)
{
   int loop=(1<<v.size())-1;
   //cout<<loop<<" "<<v.size()<<" "<<(1<<3)<<endl;
   int ma=0,mb=0,cost=0;
   for(int i=1;i<=loop;i++)
   {
     int temp=i;
     int j=0;
     while(temp>0)
     {
       int c=temp&1;
       if(c)
       {
       ma+=v[j][0];
       mb+=v[j][1];
       cost+=v[j][2];
       }
       j++;
       temp=temp>>1;
     }

     int g=__gcd(ma,mb);
     ma/=g;
     mb/=g;

     if(ma==r1 && mb==r2 && ans>cost)
     ans=cost;
   }
}
