        int G = __gcd(A, B);
        A /= G;
        B /= G;
        if (M[0] == A && M[1] == B) {
            ans = min(ans, d[0][i].c + d[1][idx].c);
        }
    }
    if (ans == INF) ans = -1;
    cout << ans << endl;

    return 0;
}

