//最大公約数
int gcd(int a, int b) {
	if (b == 0) {
		return a;
	}
	return gcd(b, a % b);
}

//最小公倍数
long long lcm(long long a, long long b) {
	long long old_old_a = a, old_old_b = b;
	long long old_a, old_b;
	while (b != 0) {
		old_a = a;
		a = b;
		old_b = b;
		b = old_a % b;
	}
	long long g = old_b;
	return old_old_a / g * old_old_b;
}

