//nPr
int nPr(int n, int r) {
	int ans = 1;
	for (int i = 0; i < r; i++) {
		ans *= n;
		n--;
	}
	return ans;
}


int nCr(int n, int r) {
	int ans = 1;
	int m = 1;
	int l = r;
	for (int i = 0; i < r; i++) {
		ans *= n;
		n--;
		m *= l;
		l--;
	}
	return ans / m;
}


//文を式として評価（ctoiと一緒に使用、+-のみ）
int eval(vector<char>s) {
	vector<int> num; vector<char>ope;
	int number = ctoi(s[0]);
	for (int i = 1; i < s.size(); i++) {
		if (s[i] == '+') {
			ope.push_back('+');
			num.push_back(number);
			number = 0;
		}
		else if (s[i] == '-') {
			ope.push_back('-');
			num.push_back(number);
			number = 0;
		}
		else {
			number = number * 10 + ctoi(s[i]);
		}
		if (i == s.size() - 1) {
			num.push_back(number);
		}
	}
	int ans = num[0];
	for (int i = 1; i < num.size(); i++) {
		if (ope[i - 1] == '+') {
			ans += num[i];
		}
		else if (ope[i - 1] == '-') {
			ans -= num[i];
		}
	}
	return ans;
}

