//union_find木
class Union_find {
	int par[100010], rank[100010];
	void init(int n) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}
	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] == find(par[x]);
		}
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) {
			return;
		}
		if (rank[x] < rank[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (rank[x] == rank[y]) {
				rank[x]++;
			}
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

//もう一つ

class union_find {
public:
	vector<int>parent;
	union_find(int n) {
		parent = vector<int>(n, -1);
	}
	int root(int a) {
		if (parent[a] < 0) {
			return a;
		}
		else {
			return parent[a] = root(parent[a]);
		}
	}
	int size(int a) {
		return -parent[root(a)];
	}
	bool connect(int a, int b) {
		a = root(a); b = root(b);
		if (a == b) {
			return false;
		}
		else {
			if (size(a) > size(b)) {
				swap(a, b);
			}
			parent[a] += parent[b];
			parent[b] = a;
			return true;
		}
	}
};

