int bfs() {
	int sy = 0, sx = 0, gy = h - 1, gx = w - 1;
	int r = h, c = w;
	queue<pair<int, int>>que;
	for (int i = 0; i < r; i++) {
		for (int j = 0; j < c; j++) {
			d[i][j] = inf;
		}
	}
	que.push(pair<int, int>(sy, sx));
	d[sy][sx] = 0;
	while (que.size() > 0) {
		pair<int, int>p = que.front();
		que.pop();
		if (p.first == gy && p.second == gx) {
			break;
		}
		for (int i = 0; i < 4; i++) {
			int ny = p.first + dy[i], nx = p.second + dx[i];
			if (0 <= ny && ny < r && 0 <= nx && nx < c && grid[ny][nx] != '#' && d[ny][nx] == inf) {
				que.push(pair<int, int>(ny, nx));
				d[ny][nx] = d[p.first][p.second] + 1;
			}
		}
	}
	return d[gy][gx];
}

//ダイクストラ法
struct edge {
	int to, cost;
};
int V;//頂点数
int max_v = inf;
typedef pair<int, int>P;
vector<edge>g[100010];//隣接リスト
int D[100010];//距離
void dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P>>que;
	fill(D, D + V, inf);
	D[s] = 0;
	que.push(P(0, s));

	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if (D[v] < p.first) {
			continue;
		}
		for (int i = 0; i < g[v].size(); i++) {
			edge e = g[v][i];
			if (D[e.to] > D[v] + e.cost) {
				D[e.to] = D[v] + e.cost;
				que.push(P(D[e.to], e.to));
			}
		}
	}
}

