    if(bit & (1<<i)){
      cnta+=a[l+i];
      cntb+=b[l+i];
      cntc+=c[l+i];
    }
   }
    ex[cnta][cntb]=true;
    rmap[mp(cnta,cntb)]=cntc;
  }

  int ans=inf;
  for(auto v:lmap){
    int A=v.first.first;
    int B=v.first.second;
    rep(i,0,250){
      int C=i;
      if((q*A+q*C-B*p)%p==0){
      int D=(q*A+q*C-B*p)/p;
        if(ex[C][D]){
          if(v.second+rmap[mp(C,D)]==0)continue;
         chmin(ans,v.second+rmap[mp(C,D)]); 
        }
      }
    }
  }
  if(ans==inf)ans=-1;
  cout<<ans<<endl;
  //////////////////
}

