const int NIL = -1;

struct chem{
	int a, b, c;
};

vector<chem> ch;

int dp[41][401][401];

int gcd(int a, int b){
	if (b == 0) return a;
	return gcd(a, a % b);
}
int N, MA, MB;

int cost(int n, int ma, int mb){
	int na = ma, nb = mb;
	int g = gcd(na, nb);
		if (g != 0){
		na /= g; nb /= g;
	}
	if (n == 0 and (na != MA or nb != MB)){
		return 40000;
	}
	if (na == MA and nb == MB){
		return 0;
	}
	int ans = dp[n][ma][mb];
	if (ans == NIL){
		int a = cost(n - 1, ma, mb);
		int b = cost(n - 1, ma + ch[n].a, mb + ch[n].b) + ch[n].c;
		ans = min(a, b); 
	}
	return ans;
}

