int32_t main() {
    int n,ma,mb; cin >> n >> ma >> mb;
    vector<int> a(n),b(n),c(n);
    rep (i,n) cin >> a[i] >> b[i] >> c[i];
    const int MAX = 2005, INF = 1e9;
    int v1[MAX*2] = {}, v2[MAX*2] = {};
    for (int &x : v1) x = INF;
    for (int &x : v2) x = INF;

    const int n1 = n/2, n2 = n-n/2;
    rep (s,1<<n1) {
        int x = MAX, y = 0;
        rep (i,n1) if (s&(1<<i)) x += mb*a[i] - ma*b[i], y += c[i];
        chmin(v1[x], y);
    }
    rep (s,1<<n2) {
        int x = MAX, y = 0;
        for (int i = n1; i < n; i++) {
            if (s&(1<<(i-n1))) x -= mb*a[i] - ma*b[i], y += c[i];
        }
        chmin(v2[x], y);
    }
    int mi = INF;
    rep (x,2*MAX) if (v1[x]+v2[x] != 0) chmin(mi, v1[x]+v2[x]);
    if (mi == INF) mi = -1;
    cout << mi << "\n";
}

#include <algorithm>
