using namespace std;
const int INF = (int)1e9 + 7;
template<class T> inline bool chmin(T &a, T b) { return a > b ? (a = b, 1) : 0; }
using pii = pair<int, int>;
pii operator+(pii a, pii b) { return {a.first + b.first, a.second + b.second}; }

int main() {
    int n; cin >> n;
    int ma, mb; cin >> ma >> mb;
    vector<pair<int, int>> ps(n);
    for (auto &p: ps) {
        int a, b, c; cin >> a >> b >> c;
        p = {a * mb - b * ma, c};
    }
    int n1 = n / 2, n2 = n - n1;
    map<int, int> mp1, mp2;
    for (int mask = 1; mask < 1 << n1; mask++) {
        pair<int, int> sum;
        for (int i = 0; i < n1; i++) if (mask >> i & 1) sum = sum + ps[i];
        int diff = sum.first, cost = sum.second;
        if (mp1.count(diff)) chmin(mp1[diff], cost);
        else mp1[diff] = cost;
    }
    for (int mask = 1; mask < 1 << n2; mask++) {
        pair<int, int> sum;
        for (int i = 0; i < n2; i++) if (mask >> i & 1) sum = sum + ps[i + n1];
        int diff = sum.first, cost = sum.second;
        if (mp2.count(diff)) chmin(mp2[diff], cost);
        else mp2[diff] = cost;
    }
    int mi = INF;
    for (auto &p: mp1) {
        if (p.first == 0) chmin(mi, p.second);
        else if (mp2.count(-p.first)) chmin(mi, p.second + mp2[-p.first]);
    }
    for (auto &p: mp2) {
        if (p.first == 0) chmin(mi, p.second);
    }
    cout << (mi == INF ? -1 : mi) << endl;
    return 0;
}

