const int INF = 1e4;
int n, ma, mb;
int a[40], b[40], c[40];
int dp[401][401];

int main() {
    scanf("%d %d %d", &n, &ma, &mb);
    for (int i = 0; i < n; i++) scanf("%d %d %d", &a[i], &b[i], &c[i]);
    for (int i = 0; i <= 400; i++) {
        for (int j = 0; j <= 400; j++) dp[i][j] = INF;
    }
    dp[0][0] = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 1; j <= 400; j++) {
            for (int k = 1; k <= 400; k++) {
                if (j - a[i] < 0 || k - b[i] < 0) continue;
                dp[j][k] = min(dp[j][k], dp[j - a[i]][k - b[i]] + c[i]);
            }
        }
    }

    int ans = INF;
    for (int i = 1; i * max(ma, mb) <= 400; i++) {
        ans = min(ans, dp[i * ma][i * mb]);
    }

    printf("%d\n", (ans == INF) ? -1 : ans);
    return 0;
}

