        for(int ai = 0 ; ai < nmax*abmax ; ai ++) {
            for (int bi = 0; bi < nmax*abmax ; bi++) {

                dp[ii][ai][bi] = INF;
            }
        }
    }

    dp[0][0][0] = 0;


    for(int ii = 0 ; ii < N ; ii ++){
        for(int ai = 0 ; ai < nmax*abmax ; ai ++) {
            for (int bi = 0; bi < nmax*abmax ; bi++) {
                if(dp[ii][ai][bi] == INF) continue;
                dp[ii+1][ai][bi] = min(dp[ii][ai][bi] , dp[ii+1][ai][bi]);
                dp[ii+1][ai+a[ii]][bi+b[ii]] = min(dp[ii+1][ai+a[ii]][bi+b[ii]] , dp[ii][ai][bi]+c[ii]);
            }
        }
    }


    int res = INF;
    for(int ma = 1 ; ma <= nmax*abmax ; ma ++) {
        for (int mb = 1; mb <= nmax*abmax; mb++) {
            if(ma*Mb == Ma*mb){
                res = min(res , dp[N-1][ma][mb]);
            }
        }
    }

