int yaku_b[40];
int yaku_c[40];
int init = 1145141919810;
int inf = 1145141919;
int memo[41][400][400];

int func(int num, int a, int b) //num番目まで来たときの割合がa,bだったときの最小コスト
{
	if (a < 0 || b < 0)
	{
		return inf;
	}
	if (memo[num][a][b] < init)
	{
		return memo[num][a][b];
	}
	if (num == 0)
	{
		if(a == 0 && b == 0)
			return 0;
		else
			return inf;
	}

	int ya = yaku_a[num - 1];
	int yb = yaku_b[num - 1];
	int yc = yaku_c[num - 1];
	int val1 = func(num - 1, a, b);
	int val2 = func(num - 1, a - ya, b - yb) + yc;
	return MIN(val1, val2);
}

