  dp[0][0][0] = 0;

  vector<int> ans;
  for (int k = 0; k < n; k++) {
    for (int i = 0; i < 401; i++) {
      for (int j = 0; j < 401; j++) {
        if (dp[k][i][j] == 99999) {
          continue;
        }

        int val = dp[k][i][j];
        if (ma * j == mb * i && val > 0) {
          ans.push_back(val);
        }

