          dp[k + 1][i + goods[k][0]][j + goods[k][1]] = val + goods[k][2];
        }

        if (dp[k + 1][i][j] > val) {
          dp[k + 1][i][j] = val;
        }
      }
    }
  }

  if (ans.empty()) {
    cout << "-1\n";
    return 0;
  }

  sort(begin(ans), end(ans));
  cout << ans[0] << "\n";
