  vector<tuple<int, int, int>> v;
  vector<vector<int>> lt(201, vector<int>(201, 1e6));
  for (int i = 0; i < n; ++i) {
    int a, b, c;
    cin >> a >> b >> c;
    v.push_back(make_tuple(a, b, c));
  }
  int m = n / 2;
  for (int i = 0; i < (1 << m); ++i) {
    int a = 0, b = 0, c = 0;
    for (int j = 0; j < m; ++j) {
      if ((i >> j) & 1) {
        a += get<0>(v[j]);
        b += get<1>(v[j]);
        c += get<2>(v[j]);
      }
    }
    lt[a][b] = min(lt[a][b], c);
  }
  int p = n - m, ans = 1e9;
  for (int i = 0; i < (1 << p); ++i) {
    int a = 0, b = 0, c = 0;
    for (int j = 0; j < p; ++j) {
      if ((i >> j) & 1) {
        a += get<0>(v[m + j]);
        b += get<1>(v[m + j]);
        c += get<2>(v[m + j]);
      }
    }
    for (int t = 0; t <= 200; ++t) {
      if ((t + b) % mb)
        continue;
      int s = ((t + b) / mb) * ma - a;
      if (s < 0 || s > 200)
        continue;
      if (ma * (b + t) == mb * (a + s)) {
        if (lt[s][t]) {
          ans = min(ans, lt[s][t] + c);
        }
      }
    }
  }
