        chmin(dp[i][j][k], dp[i-1][j][k]);
    }

    ll ans = INF;
    int ma = Ma, mb = Mb;
    while(ma <= amax && mb <= bmax){
        chmin(ans, dp[N][ma][mb]);
        ma += Ma; mb += Mb;
