struct S {
    int a, b, c;
};

int N, Ma, Mb;
vector<S> abc;
int ans = INT_MAX;

void dfs(int idx, int a, int b, int c) {
    if ((a > 0) && (b > 0)) {
        if (((double)Ma / Mb) == ((double)a / b)) {
            ans = min(ans, c);
        }
    }

    if (idx == N) {
        return;
    }

    if (c >= ans) {
        return;
    }

    dfs(idx + 1, a + abc[idx].a, b + abc[idx].b, c + abc[idx].c);
    dfs(idx + 1, a, b, c);
}

bool cmp(const S &a, const S &b) {
    return (a.c < b.c);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> Ma >> Mb;
    abc.resize(N);

    rep(i, N) {
        cin >> abc[i].a >> abc[i].b >> abc[i].c;
    }

    dfs(0, 0, 0, 0);
    cout << ((ans == INT_MAX) ? -1 : ans) << endl;
    return 0;
}

