      if ((i >> j) & 1) {
        a += get<0>(v[m + j]);
        b += get<1>(v[m + j]);
        c += get<2>(v[m + j]);
      }
    }
    for (int t = 0; t <= 200; ++t) {
      if ((t + b) % mb)
        continue;
      int s = ((t + b) / mb) * ma - a;
      if (s < 0 || s > 200)
        continue;
      if (a + s == 0 || b + t == 0) {
        continue;
      }
      if (lt[s][t]) {
        ans = min(ans, lt[s][t] + c);
      }
    }
  }
  if (ans >= 1e4) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }
}

