    ll modpow(ll b, ll p, ll m) {
        ll r = 1;
        for (; p; p >>= 1, b = b * b % m)
            if (p & 1)
                r = r * b % m;
        return r;
    }

    ll modinv(ll b, ll m) { return modpow(b, m - 2, m); }

    ll sumdigit(ll num) {
        ll res = 0;
        while (num) {
            res += num % 10;
            num /= 10;
        }
        return res;
