// Matrix class.
    template<class T, int size_m, int size_n>
    struct Matrix {
        T val[size_m][size_n];

        Matrix() {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    val[i][j] = 0;
        }

        /**
         * \brief Matrix type casting for another matrix of the same dimension.
         */
        template<class U>
        Matrix(Matrix<U, size_m, size_n> mat) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    val[i][j] = mat.val[i][j];
        }

        /**
         * \brief Construct a matrix from a 2D array.
         */
        Matrix(T **arr) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    val[i][j] = arr[i][j];
        }

        /**
         * \brief Returns the reference to the cell (i, j) in the matrix.
         */
        T &operator()(const int i, const int j) { return val[i][j]; }

        /**
         * \brief Explicitly cast the matrix to Matrix<U>.
         */
        template<class U>
        const Matrix<U, size_m, size_n> convert() { return Matrix<U, size_m, size_n>(*this); }

        const Matrix operator+=(const Matrix<T, size_m, size_n> mat) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    (*this)(i, j) += mat(i, j);
        }

        const Matrix operator-=(const Matrix<T, size_m, size_n> mat) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    (*this)(i, j) -= mat(i, j);
        }

        const Matrix operator+(const Matrix<T, size_m, size_n> mat) {
            Matrix<T, size_m, size_n> res = *this;
            res += mat;
            return res;
        }

        const Matrix operator-(const Matrix<T, size_m, size_n> mat) {
            Matrix<T, size_m, size_n> res = *this;
            res -= mat;
            return res;
        }

        /**
         * \brief Matrix-matrix multiplication.
         */
        template<int size_p>
        Matrix<T, size_m, size_p> operator*(Matrix<T, size_n, size_p> mat) {
            Matrix<T, size_m, size_p> res;
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_p; j++)
                    for (int k = 0; k < size_n; k++)
                        res(i, j) += (*this)(i, k) * mat(k, j);
            return res;
        }

        /**
         * \brief Matrix-vector multiplication.
         */
        Vector<T, size_n> operator*(Vector<T, size_n> vec) {
            Vector<T, size_n> res;
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    res.val[j] += val[i][j] * vec[j];
            return res;
        }
    };

// Vector class.
    template<class T, int size>
    struct Vector {
        /**
         * Specialization for Vector of size 2.
         */
        template<class U>
        static const Vector<U, 2> vec2(U a, U b) {
            Vector<U, 2> vec;
            vec.val[0] = a, vec.val[1] = b;
            return vec;
        }

        /**
         * Specialization for Vector of size 3.
         */
        template<class U>
        static const Vector<U, 3> vec3(U a, U b, U c) {
            Vector<U, 3> vec;
            vec.val[0] = a, vec.val[1] = b, vec.val[2] = c;
            return vec;
        }

        T val[size];

        /**
         * \brief Empty vector constructor.
         */
        Vector() {
            for (int i = 0; i < size; i++)
                val[i] = 0;
        }

        /**
         * \brief Vector type casting for another vector of the same size.
         */
        template<class U>
        Vector(Vector<U, size> vec) {
            for (int i = 0; i < size; i++)
                val[i] = vec.val[i];
        }

        /**
         * \brief Constructing a vector from an array.
         */
        Vector(T *arr) {
            for (int i = 0; i < size; i++)
                val[i] = arr[i];
        }

        /**
         * \brief Explicitly cast the vector to Vector<U> with the same size.
         */
        template<class U>
        Vector<U, size> convert() { return Vector<U, size>(*this); }

        const Vector operator+(const Vector &vec) const {
            Vector v = *this;
            v += vec;
            return v;
        }

        const Vector operator-(const Vector &vec) const {
            Vector v = *this;
            v -= vec;
            return v;
        }

        const Vector operator*(const Vector &vec) const {
            Vector v = *this;
            v *= vec;
            return v;
        }

        const Vector operator/(const Vector &vec) const {
            Vector v = *this;
            v /= vec;
            return v;
        }

        const Vector operator+=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] += vec.val[i];
            return *this;
        }

        const Vector operator-=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] -= vec.val[i];
            return *this;
        }

        const Vector operator*=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] *= vec.val[i];
            return *this;
        }

        const Vector operator/=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] /= vec.val[i];
            return *this;
        }

        /**
         * \brief Compute the dot product of two vectors.
         */
        const T dot(const Vector<T, size> vec) {
            T acc = 0;
            for (int i = 0; i < size; i++)
                acc += val[i] * vec.val[i];
            return acc;
        }
    };

    struct Log2Table {
        vector<int> val;
        // Last value that we computed to.
        int pmax = 0;

        Log2Table() {
            val.resize(1);
            val[0] = -1;
        }

        int get(int n) {
            if (n >= val.size()) {
                eprintf("Error: request log2[%d] but is not computed yet\n", n);
                exit(1);
            }

            return val[n];
        }

        void require(int n) {
            if (n < pmax)
                return;
            val.resize(n + 1);

            for (int i = 0; i < 30; i++)
                for (int j = max(1 << i, pmax + 1); j < min(1 << (i + 1), n + 1); j++)
                    val[j] = i;

            pmax = n;
        }
    };

    Log2Table log2t;

// Generic modular integer.
    template<int MOD, typename IntType = int>
    struct GModint {
        IntType val;

        GModint() : val(0) {}

        GModint(int v, bool safe = false) { val = safe ? v : ((v % MOD) + MOD) % MOD; }

        GModint(ll v, bool safe = false) { val = safe ? v : ((v % MOD) + MOD) % MOD; }

        explicit operator bool() const { return val != 0; }

        const bool operator==(const GModint &g) const { return val == g.val; }

        const bool operator!=(const GModint &g) const { return val != g.val; }

        const GModint operator+=(const GModint &g) { return *this = *this + g; }

        const GModint operator-=(const GModint &g) { return *this = *this - g; }

        const GModint operator*=(const GModint &g) { return *this = *this * g; }

        const GModint operator/=(const GModint &g) { return *this = *this / g; }

        const GModint operator^=(const GModint &g) { return *this = *this ^ g; }

        const GModint operator-() const { return GModint(val == 0 ? 0 : MOD - val, true); }

        const GModint operator+(const GModint &g) const {
            ll newval = val + g.val;
            if (newval >= MOD)
                newval -= MOD;
            return GModint(newval, true);
        }

        const GModint operator-(const GModint &g) const { return *this + (-g); }

        const GModint operator*(const GModint &g) const { return GModint(1ll * val * g.val); }

        const GModint operator/(const GModint &g) const { return *this * g.inv(); }

        template<class T>
        const GModint operator^(const T t) const { return GModint(modpow(val, t, MOD)); }

        const GModint inv() const { return GModint(modinv(val, MOD)); }
    };

    using Modint = GModint<1000000007>;

