int c[100005];

int cost(string s, string l, string r) {
    c[0] = 1;
    c[1] = s.substr(0, 2) == l || s.substr(0, 2) == r ? 1 : 2;

    for (int i = 2; i < s.length(); i++) {
        c[i] = c[i - 1] + 1;
        if (s.substr(i - 1, 2) == l || s.substr(i - 1, 2) == r) {
            c[i] = min(c[i], c[i - 2] + 1);
        }
    }

    return c[s.length() - 1];
}

