int main(int argc, char** argv) {
    int n, ma, mb; cin >> n >> ma >> mb;
    int c[n], d[n];
    for (int i = 0; i < n; i++) {
        int a, b; cin >> a >> b >> c[i];
        d[i] = a * mb - b * ma;
    }
    map<int, int> v1; // (diff -> cost)
    vector<int> diff(1<<20), cost(1<<20);
    int ans = 1<<30;
    for (int i = 0; i < min(20, n); i++)
        for (int s = 0; s < 1 << i; s++) {
            int s1 = (1<<i) | s;
            diff[s1] = diff[s] + d[i];
            cost[s1] = cost[s] + c[i];
            if (diff[s1] == 0) ans = min(ans, cost[s1]);
            else if (v1.find(diff[s1]) == v1.end()) v1[diff[s1]] = cost[s1];
            else v1[diff[s1]] = min(v1[diff[s1]], cost[s1]);
        }
    if (n > 20) {
        map<int, int> v2;
        for (int i = 20; i < n; i++)
            for (int s = 0; s < 1 << i-20; s++) {
                int s1 = (1<<i-20) | s;
                diff[s1] = diff[s] + d[i];
                cost[s1] = cost[s] + c[i];
                if (diff[s1] == 0) ans = min(ans, cost[s1]);
                else if (v2.find(diff[s1]) == v2.end()) v2[diff[s1]] = cost[s1];
                else v2[diff[s1]] = min(v2[diff[s1]], cost[s1]);
            }
        auto it1 = v1.begin();
        auto it2 = v2.rbegin();
        while (it1 != v1.end() && it2 != v2.rend()) {
            if (it1->first == 0) { it1++; continue; }
            if (it2->first == 0) { it2++; continue; }
            int diff = it1->first + it2->first;
            int cost = it1->second + it2->second;
            if (diff > 0) it2++;
            else if (diff < 0) it1++;
            else { ans = min(ans, cost); it1++; it2++; }
        }
    }
    cout << (ans == 1<<30 ? -1 : ans) << endl;
}

