  std::vector<int> a(n), b(n), c(n);
  for (int i = 0; i < n; i++) {
    std::cin >> a[i] >> b[i] >> c[i];
  }

  std::vector<std::vector<int>> table1(401, std::vector<int>(401, INF));
  std::vector<std::vector<int>> table2(401, std::vector<int>(401, INF));
  std::vector<std::vector<int>> t(401, std::vector<int>(401, INF));
  table1[0][0] = 0;
  table2[0][0] = 0;

  for (int k = 0; k < n+1; k++) {
    for (int i = 1; i < 401; i++) {
      for (int j = 1; j < 401; j++) {
        if (k == n) {
          t[i][j] = std::min(table1[i][j], table2[i][j]);
          continue;
