void init_costs()
{
  for (int32_t j = 0; j < MAX_N * MAX_A; j++) {
    for (int32_t k = 0; k < MAX_N * MAX_B; k++) {
      costs[0][j][k] = COST_MAX;
    }
  }
  costs[0][0][0] = 0;
}

