    for (int32_t a = 0; a <= N * MAX_A; a++) {
      for (int32_t b = 0; b <= N * MAX_B; b++) {
        costs[i][a][b] = costs[i - 1][a][b];
        if ((a - inputs[i - 1].a) >= 0 && (b - inputs[i - 1].b) >= 0) {
          costs[i][a][b] = min(costs[i - 1][a][b], costs[i - 1][a - inputs[i - 1].a][b - inputs[i - 1].b] + inputs[i - 1].c);
        }
      }
