const ll INF = numeric_limits<int>::max();
const ll LINF = numeric_limits<ll>::max();
const ll mod = 1000 * 1000 * 1000 + 7;



void solve() {
    int n, p, q;
    cin >> n >> p >> q;
    vector<int> a(n), b(n), c(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i] >> c[i];
    }
    vector<vector<int> > d(500, vector<int>(500, INF));
    d[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int id1 = d.size() - 1; id1 >= 0; --id1) {
            for (int id2 = d.size() - 1; id2 >= 0; --id2) {
                if (d[id1][id2] == INF)
                    continue;
                int x = id1 + a[i], y = id2 + b[i];
                d[x][y] = min(d[x][y], d[id1][id2] + c[i]);
            }
        }
    }
    int res = INF;
    for (int i = 1; i < 500; ++i) {
        for (int j = 1; j < 500; ++j) {
            if (i * q == j * p) {
                res = min(res, d[i][j]);
            }
        }
    }
    if (res == INF)
        res = -1;
    cout << res << endl;
}


