#define MAX 40
#define INF INT32_MAX

int N, Ma, Mb;
int A[MAX];
int B[MAX];
int C[MAX];

int dfs( int i, int a, int b, int c )
{
	if( i >= N ) {
		return INF;
	}
	int res = INF;
	if( a * Mb == b * Ma && a && b ) {
		res = c;
	}
	int res1 = dfs( i + 1, a, b, c );
	int res2 = dfs( i + 1, a + A[i], b + B[i], c + C[i] );
	res = min( res, min( res1, res2 ) );
	return res;
}

