         for(int k=0; k<401; k++){
            memo[i][j][k]=inf;
         }
      }
   }
   int mi=inf;
   for(int k=1; max(k*A, k*B)<=40*10; k++){
      mi=min(mi, rec(0, k*A, k*B));
