int dp[41][500][500]; // dp[i][j][k] := cost to make j and k by using until i th item
int a[40];
int b[40];
int c[40];

signed main() {
    int n, ma, mb; cin >> n >> ma >> mb;

    int sa, sb;
    sa = 0;
    sb = 0;

    REP(i, n) {
        cin >> a[i] >> b[i] >> c[i];
        sa += a[i];
        sb += b[i];
    }

    REP(i, n+1) {
        REP(j, 500) {
            REP(k, 500) {
                if (j == 0 && k == 0) {
                    dp[i][j][k] = 0;
                } else {
                    dp[i][j][k] = INF;
                }
            }
        }
    }

    dp[0][0][0] = 0;

    REP(i, n) {
        REP(j, sa) {
            REP(k, sb) {
                if (dp[i][j][k] != INF) {
                    dp[i+1][j+a[i]][k+b[i]] = min(dp[i+1][j+a[i]][k+b[i]], dp[i][j][k] + c[i]);
                    dp[i+1][j][k] = min(dp[i][j][k], dp[i+1][j][k]);
                }
            }
        }
    }

    int ans = INF;

    for(int i = 1; i * ma <= sa && i * mb <= sb; i++) {
        if (dp[n][i*ma][i*mb] != INF) {
            ans = min(ans, dp[n][i*ma][i*mb]);
            cout << i << " " << i*ma << " " << i*mb << " " << dp[n][i*ma][i*mb] << endl;
        }
    }

    if(ans == INF){
        print(-1);
    } else {
        print(ans);
    }

    return 0;
}

