          a += get<0>(med2[i]);
          b += get<1>(med2[i]);
          c += get<2>(med2[i]);
        }
      }
      int ratio = a * Mb - b * Ma;
      if (ratio == 0) chmin(res, c);
      else if (cost2.count(ratio) == 0) cost2[ratio] = c;
      else chmin(cost2[ratio], c);
    }
  }

  for (auto itr=cost1.begin(); itr!=cost1.end(); ++itr) {
    int a = itr->first, b = itr->second;
    if (cost2.count(-a) == 0) continue;
    chmin(res, cost2[-a] + b);
  }

  print(int(res));

}

