using namespace std;
typedef long long ll;
int main(){
  int n,ma,mb;
  cin>>n>>ma>>mb;
  int a[n],b[n],c[n];
  for(int i=0;i<n;i++) cin>>a[i]>>b[i]>>c[i];
  int k=n/2,INF=1<<20;
  int dp[2][500][500];
  for(int i=0;i<500;i++)
    for(int j=0;j<500;j++)
      dp[0][i][j]=dp[1][i][j]=INF;
  for(int i=0;i<(1<<k);i++){
    int ta=0,tb=0,tc=0;
    for(int j=0;j<k;j++){
      if(i>>j&1){
	ta+=a[j];tb+=b[j];tc+=c[j];
      }
    }
    //cout<<ta<<" "<<tb<<" "<<tc<<endl;
    dp[0][ta][tb]=min(dp[0][ta][tb],tc);
  }
  for(int i=0;i<(1<<(n-k));i++){
    int ta=0,tb=0,tc=0;
    for(int j=k;j<n;j++){
      if(i>>(j-k)&1){
	ta+=a[j];tb+=b[j];tc+=c[j];
      }
    }
    //cout<<ta<<" "<<tb<<" "<<tc<<endl;
    dp[1][ta][tb]=min(dp[1][ta][tb],tc);
  }
  int ans=INF;
  for(int i=0;i<500;i++){
    for(int j=0;j<500;j++){
      if(dp[0][i][j]==INF) continue;
      for(int x=0;x<500;x++){
	if(i+x==0) continue;
	if((mb*(i+x)-ma*j)<0||(mb*(i+x)-ma*j)%ma) continue;
	int y=(mb*(i+x)-ma*j)/ma;
	if(y>=500) continue;
	//cout<<i+x<<" "<<j+y<<":"<<dp[0][i][j]+dp[1][x][y]<<endl;
	ans=min(ans,dp[0][i][j]+dp[1][x][y]);
      }
    }
  }
  cout<<(ans<INF?ans:-1)<<endl;
  return 0;
}

