using namespace std;

int n;
int A;
int B;
int AA[45];
int BB[45];
int cost[45];
int dp[45][405][405];

int go(int idx , int a , int b){
    if(b != 0){
        double aaa = a;
        double bbb = b;
        double ccc = A;
        double ddd = B;
        if(aaa / bbb == ccc / ddd)
            return 0;
    }
    if(idx > n)
        return 1e5;
    if(dp[idx][a][b] != -1)
        return dp[idx][a][b];
    int best = go(idx + 1 , a , b);
    best = cost[idx] + go(idx + 1 , a + AA[idx] , b + BB[idx]);
    return dp[idx][a][b] = best;
}

int main(){
    scanf("%d%d%d" , &n , &A , &B);
    memset(dp , -1 , sizeof dp);
    for(int i = 1; i <= n; i++){
        scanf("%d%d%d" , &AA[i] , &BB[i] , &cost[i]);
    }
    int ans = go(1 , 0 , 0);
    if(ans >= 1e5){
        puts("-1");
        return 0;
    }
    printf("%d\n" , ans);
}

