/* 2倍しても桁溢れしない最大数

   almost_max<uint64_t>() とか
*/
template<typename T>
constexpr T almost_max() {
    return std::numeric_limits<T>::max() / 2 - 1;
}

int main()
{
    int N, Ma, Mb;
    std::cin >> N >> Ma >> Mb;

    struct E {
        int a;
        int b;
        int c;
    };

    std::vector<E> e;
    for (size_t i = 0; i < N; ++i) {
        E t;
        std::cin >> t.a >> t.b >> t.c;
        e.push_back(t);
    }

    #include <boost/multi_array.hpp>

    boost::multi_array<int, 3> memo(boost::extents[N][N*10+1][N*10+1]);
    std::fill(memo.data(), memo.data() + memo.num_elements(), almost_max<int>());


    // 現在a, b, cであって、i以降を選択した時に 比がMa, Mbになる最小の価格
    auto f = [&e, &memo, N, Ma, Mb](auto F, int i, int a, int b) -> int {
        int ret = 0;
        if (i == N) {
            return almost_max<int>();
        }
        if (memo[i][a][b] != almost_max<int>()) {
            return memo[i][a][b];
        }
        if ((a + e[i].a) * Mb == (b + e[i].b) * Ma) {
            ret = e[i].c;
        }
        else {
            ret = std::min(F(F, i+1, a, b),
                           F(F, i+1, a + e[i].a, b + e[i].b) + e[i].c);
        }

        return memo[i][a][b] = ret;
    };

    auto ret = f(f, 0, 0, 0);
    if (ret == almost_max<int>()) {
        std::cout << -1 << std::endl;
    }
    else {
        std::cout << ret << std::endl;
    }

    return 0;
}

