using namespace std;

int main()
{
    int64_t N, Ma, Mb;
    std::cin >> N >> Ma >> Mb;

    struct Med {
        int64_t a;
        int64_t b;
        int64_t c;
    };

    std::vector<Med> med;
    for (decltype(N) i = 0; i < N; ++i) {
        Med t;
        std::cin >> t.a >> t.b >> t.c;
        med.push_back(t);
    }

    constexpr int64_t maxCost = 40*100*2;

    boost::multi_array<int64_t, 3> memo(boost::extents[10*40+1][10*40+1][N+1]);
    std::fill(memo.data(), memo.data() + memo.num_elements(), maxCost);

    auto f = [&memo, &med, N, Ma, Mb, maxCost](auto F, int64_t ma, int64_t mb, int64_t n ) -> int64_t {
        if (memo[ma][mb][n] != maxCost) {
            return memo[ma][mb][n];
        }

        if (n == N) {
            return maxCost;
        }

        if (ma != 0 && mb != 0 && ma*Mb == mb*Ma) {
            memo[ma][mb][n] = 0;
        }
        else {
            memo[ma][mb][n] = std::min(F(F, ma, mb, n+1),
                                       F(F, ma+med[n].a, mb+med[n].b, n+1) + med[n].c);
        }
        return memo[ma][mb][n];
    };

    auto c = f(f, 0, 0, 0);

    if (c == maxCost) {
        c = -1;
    }
    std::cout << c << std::endl;

    return 0;
}

