struct WarshallFloyd {
    const int n;
    vector<vector<ll>> d;
    WarshallFloyd(int _n) : n(_n), d(_n, vector<ll>(_n)) {
        rep(i, n) rep(j, n) { d[i][j] = (i == j ? 0 : INF); }
    }
    // directed
    void setDist(int i, int j, ll c) { d[i][j] = c; }
    int getDist(int i, int j) { return d[i][j]; }
    void calc() {
        rep(k, n) rep(i, n) rep(j, n) {
            if (d[i][j] > d[i][k] + d[k][j]) {
                d[i][j] = d[i][k] + d[k][j];
            }
        }
    }
};

ll N, M, K, A[40], B[40], C[40], DP[500][500][41], res = inf;
signed main() {
    cin >> N >> M >> K;
    rep(i, 500) rep(j, 500) rep(k, N + 1) DP[i][j][k] = inf;
    DP[0][0][0] = 0;
    rep(i, N) {
        cin >> A[i] >> B[i] >> C[i];
        rep(j, 500) rep(k, 500) DP[j][k][i + 1] = DP[j][k][i];
        rep(j, 500 - A[i]) rep(k, 500 - B[i]) {
            if (DP[j][k][i] == inf) continue;
            DP[j + A[i]][k + B[i]][i + 1] =
                min(DP[j + A[i]][k + B[i]][i + 1], DP[j][k][i] + C[i]);
        }
    }
    rep(i, 500) {
        ll MA = M * (i + 1), MB = K * (i + 1);
        if (MA >= 500 || MB >= 500) continue;
        rep(j, N + 1) res = min(res, DP[MA][MB][j]);
    }
    cout << (res >= inf ? -1 : res) << endl;
}

