int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n,ma,mb; cin>>n>>ma>>mb;
  constexpr int MAX = 400;
  constexpr int INF = 1e9;
  array<array<int,MAX+1>,MAX+1> dp{};
  for (auto& v:dp) for (auto& vv:v) vv=INF;
  dp[0][0] = 0;
  for (int i = 0; i < n; i++) {
    int a,b,c; cin>>a>>b>>c;
    for (int j = MAX; j >= 0; j--) {
      for (int k = MAX; k >= 0; k--) {
        if (j-a<0 or k-b<0)
          continue;
        dp[j][k] = min(dp[j][k], dp[j-a][k-b]+c);
      }
    }
  }
  int mma = ma, mmb = mb;
  int ans = INF;
  while (max(mma,mmb) <= MAX) {
    ans = min(ans, dp[mma][mmb]);
    mma+=ma;
    mmb+=mb;
  }
  cout << (ans != INF ? ans : -1) << endl;

  return 0;
}

