int a[41], b[41], c[41];
int memo[41][410][410];
int N, M_a, M_b;
int ans = 100000000;
void solve(int deep, int aa, int bb, int cost){
  if(deep == N){
    // cout << aa << "," << bb << " = " << cost << endl;
    if(aa == 0 && bb == 0)return;
    if(bb*M_a == aa*M_b){
      ans = min(ans, cost);
    }
    return;
  }
  if(memo[deep][aa][bb] < cost)return;
  memo[deep][aa][bb] = cost;
  solve(deep+1, aa, bb, cost);
  solve(deep+1, aa+a[deep], bb+b[deep], cost+c[deep]);
}

int main(void){
  cin >> N >> M_a >> M_b;
  fill_n(**memo, 41*410*410, 1000000);
  for(int i = 0; i < N; i++){
    cin >> a[i] >> b[i] >> c[i];
  }
  solve(0,0,0,0);
  cout << ((ans==100000000)?-1:ans) << endl;
  return 0;
}

