void update(int a, int b, int c, int N) {


	//この薬品をすでに使っているセルを管理する必要あり
	bool used[600][600];
	for (int i = 0; i < 500; i++) {
		for (int j = 0; j < 500; j++) {
			used[i][j] = false;
		}
	}

	if(dp[a + a][b + b] > dp[a][b]+c){
		dp[a + a][b + b] = dp[a][b] + c;
		used[a + a][b + b] = true;
	}
	if (dp[a][b] > c) {
		dp[a][b] = c;
		used[a][b] = true;

	}

	for (int i = 0; i < 500; i++) {
		for (int j = 0; j < 500; j++) {
			if (i == a && j == b) continue;
			if (dp[i][j] != LL_HALFMAX && used[i+a][j+b] == false) {
				//dp[i + a][j + b] = min(dp[i][j] + c, dp[i + a][j + b]);
				//もし金額が定義されてて、そこに薬品を追加してセルの最安値を更新できるなら、usedを立ててセルの価格を更新
				if (dp[i + a][j + b] > dp[i][j] + c) {
					used[i + a][j + b] = true;
					dp[i + a][j + b] = dp[i][j] + c;
				}
			}
		}
	}
}

