int b[N_MAX];
int c[N_MAX];

int dp[N_MAX + 1][AN_MAX + 1][BN_MAX + 1];

void solve() {
  fill(dp[0][0], dp[N][AN_MAX + 1], INF);
  dp[0][0][0] = 0;
  REP(i, N) FOR(ca, 0, AN_MAX) FOR(cb, 0, BN_MAX) {
    dp[i + 1][ca][cb] = min(dp[i + 1][ca][cb], dp[i][ca][cb]);
    if (ca >= a[i] && cb >= b[i]) {
      dp[i + 1][ca][cb] = min(dp[i + 1][ca][cb], dp[i][ca - a[i]][cb - b[i]] + c[i]);
    }
  }
  int ans = INF;
  FOR(ca, 0, AN_MAX) FOR(cb, 0, BN_MAX) {
    if (ca == 0 && cb == 0) continue;
    if (ca * Mb != cb * Ma) continue;
    ans = min(ans, dp[N][ca][cb]);
  }
  if (ans < INF) printf("%d\n", ans);
  else puts("-1");
}

void input() {
  scanf("%d%d%d", &N, &Ma, &Mb);
  REP(i, N) scanf("%d%d%d", a + i, b + i, c + i);
}

int main() {
  input();
  solve();
  return 0;
}

