int N, MA, MB;

int cost(int n, int ma, int mb){
	if (n == -1 and (ma != MA or mb != MB)){
		return 40000;
	}
	if (ma == MA and mb == MB){
		return 0;
	}
	int ans = dp[n][ma][mb];
	if (ans == NIL){
		int na = ma + ch[n].a, nb = mb + ch[n].b;
		int g = gcd(na, nb);
		na /= g; nb /= g;
		ans = min(cost(n - 1, ma, mb), cost(n - 1, na, nb) + ch[n].c); 
	}
	return ans;
}

