        }
        if(am*Mb==bm*Ma&&min>cm) min=cm;
        in[SN-1]++;
        while(in[SN-1]>=N){
            for(int i=SN-1;i>0;i--){
                if(in[i]>N-1){
                    in[i-1]++;
                    in[i]=0;
                }
            }        
            for(int i=1;i<SN;i++){
                if(in[i]<in[i-1])in[i]=in[i-1]+1;
            }
            if(in[0]+SN>N)break;
        }
        if(in[0]+SN>N)break;
    }
    mi=Calc(a,b,c,N,Ma,Mb,SN+1);
    if(mi<min) return mi;
    else return min; 
}

