#define MAX 40
#define INF (INT32_MAX/2)

int N, Ma, Mb;
int A[MAX];
int B[MAX];
int C[MAX];

int memo[MAX + 1][10 * MAX +1][10 * MAX +1];

int dfs( int i, int a, int b )
{
	if( a * Mb == b * Ma && a && b ) {
		return 0;
	}
	if( i >= N ) {
		return INF;
	}
	if( memo[i][a][b] >= 0 ) {
		return memo[i][a][b];
	}
	int res1 = dfs( i + 1, a, b );
	int res2 = dfs( i + 1, a + A[i], b + B[i] ) + C[i];
	int res = min( res1, res2 );
	memo[i][a][b] = res;
	return res;
}

int main() {
	cin >> N >> Ma >> Mb;
	for( int i = 0; i < N; i++ ) {
		cin >> A[i] >> B[i] >> C[i];
	}

	memset( memo, -1, sizeof( memo ) );
	int ans = dfs( 0, 0, 0 );

	if( ans >= INF ) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}

	return 0;
}

