/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */
const int MAX_N = 40;
const int MAX_A = 10 * MAX_N;
const int MAX_B = 10 * MAX_N;
int dp[MAX_N + 1][MAX_A + 1][MAX_B + 1];

signed main() {
    // dp[i+1][a][b] : i番目までのitemでaグラム/bグラムになるための最小コスト
    // i番目のitemを選ばない場合 dp[i+1][a][b] = min(dp[i+1][a][b], dp[i][a][b])
    // i番目のitemを選ぶ場合 dp[i+1][a][b] = min(dp[i+1][a][b], dp[i][a - cost[i]][b - cost[i]])

    int N, ma, mb;
    cin >> N >> ma >> mb;

    int A[N];
    int B[N];
    int C[N];
    for (int i = 0; i < N; i++) cin >> A[i] >> B[i] >> C[i];

    for (int i = 0; i < MAX_N + 1; i++) {
        for (int a = 0; a < MAX_A + 1; a++) {
            for (int b = 0; b < MAX_B + 1; b++) {
                dp[i][a][b] = INF;
            }
        }
    }
    dp[0][0][0] = 0;

    for (int i = 0; i < N; i++) {
        for (int a = 0; a < MAX_A + 1; a++) {
            for (int b = 0; b < MAX_B + 1; b++) {
                dp[i+1][a][b] = min(dp[i+1][a][b], dp[i][a][b]);
                if (a - A[i] >= 0 && b - B[i] >= 0) {
                    dp[i+1][a][b] = min(dp[i+1][a][b], dp[i][a - A[i]][b - B[i]] + C[i]);
                }
            }
        }
    }

    int ret = INF;
    for (int a = 1; a < MAX_A + 1; a++) {
        for (int b = 1; b < MAX_B + 1; b++) {
            if (ma * b == mb * a) {
                ret = min(ret, dp[N][a][b]);
            }
        }
    }

    if (ret == INF) ret = -1;

    cout << ret << endl;
}

