int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, ma, mb;
    cin >> n >> ma >> mb;

    int a[n], b[n], c[n];
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i] >> c[i];
    }

    int half_n = n / 2;
    int min_cost = INF;
    vector<pair<int, int>> p_ab;
  	p_ab.emplace_back(-10 * 10, INF);
    p_ab.emplace_back(10 * 10, INF);
    for (int i = 1; i < 1 << half_n; ++i) {
        int sum_ab = 0;
        int sum_c = 0;
        for (int j = 0; j < half_n; ++j) {
            if (i >> j & 1) {
                sum_ab += a[j] * mb - b[j] * ma;
                sum_c += c[j];
            }
        }
        if (sum_ab == 0) {
            min_cost = min(min_cost, sum_c);
        } else {
            p_ab.emplace_back(sum_ab, sum_c);
        }
    }
    sort(p_ab.begin(), p_ab.end());

    int m = 1;
    for (int i = 0; i < half_n; ++i) {
        if (p_ab[m - 1].second < p_ab[i].second) {
            p_ab[m++] = p_ab[i];
        }
    }

    for (int i = 1; i < 1 << (n - half_n); ++i) {
        int sum_ab = 0;
        int sum_c = 0;
        for (int j = 0; j < n - half_n; ++j) {
            if (i >> j & 1) {
                sum_ab += - a[half_n + j] * mb + b[half_n + j] * ma;
                sum_c += c[half_n + j];
            }
        }
        if (sum_ab == 0) {
            min_cost = min(min_cost, sum_c);
        } else if (!p_ab.empty() && sum_c < min_cost) {
            auto rest_ab = lower_bound(p_ab.begin(), p_ab.end(), make_pair(sum_ab, INF)) - 1;
            if (rest_ab->first == sum_ab) {
                min_cost = min(min_cost, rest_ab->second + sum_c);
            }
        }
    }

    if (min_cost == INF) {
        cout << -1 << '\n';
    } else {
        cout << min_cost << '\n';
    }


    return 0;
}

