int main(void){
	int N,Ma,Mb;
	cin >> N >> Ma >> Mb;
	vector<int> a(N),b(N),c(N);
	for(int i=0;i<N;i++){
		cin >> a[i] >> b[i] >> c[i];
	}

	vector<int> v;
	for(int i=0;i<N;i++)
		v.push_back(Ma*b[i] - Mb*a[i]);

	vector<int> v1(v.begin(),v.begin()+N/2);
	vector<int> v2(v.begin()+N/2,v.end());

	map<int,int> mp1;
	for(int i=0;i<(1<<v1.size());i++){
		int sum = 0,cost = 0;
		for(int j=0;j<v1.size();j++){
			if((i<<j) & 1){
				sum += v1[j];
				cost += c[j];
			}
		}
		if(mp1.find(sum) == mp1.end())mp1[sum] = cost;
		else mp1[sum] = min(mp1[sum],cost);
	}
	map<int,int> mp2;
	for(int i=1;i<(1<<v2.size());i++){
		int sum = 0,cost = 0;
		for(int j=0;j<v2.size();j++){
			if((i<<j) & 1){
				sum += v2[j];
				cost += c[j + N/2];
			}
		}
		if(mp2.find(sum) == mp2.end())mp2[sum] = cost;
		else mp2[sum] = min(mp2[sum],cost);
	}

	int ret = 1e9;
	for(auto it=mp1.begin();it!=mp1.end();it++){
		if( mp2.find(-(it->first)) == mp2.end() ) continue;
		ret = min(ret, mp2[(-it->first)]+it->second);
	}

	if(ret == 1e9)cout << -1 << endl;
	else cout << ret << endl;
