int dp[41][401][401]; // dp[i][a][b] : i番目までの溶液で、(a,b)となる最小のコスト
int a[41], b[41], c[41];

int main() {
	int N, Ma, Mb;
	scanf("%d%d%d", &N, &Ma, &Mb);
	for (int i = 1; i <= N; i++) scanf("%d%d%d", &a[i], &b[i], &c[i]);

	for (int A = 0; A <= 400; A++) {
		for (int B = 0; B <= 400; B++) {
			if (A == 0 && B == 0) dp[0][0][0] = 0;
			else dp[0][A][B] = INF; // 無理
		}
	}

	for (int i = 1; i <= N; i++) {
		for (int A = 0; A <= 400; A++) {
			for (int B = 0; B <= 400; B++) {

				if (A >= a[i] && B >= b[i]) dp[i][A][B] = min(dp[i - 1][A][B], dp[i - 1][A - a[i]][B - b[i]] + c[i]);
				else dp[i][A][B] = dp[i - 1][A][B];

			}
		}
	}

	int ans = INF;

	for (int A = 1; A <= 400; A++) {
		for (int B = 1; B <= 400; B++) {

			if (A*Mb == B * Ma) ans = min(ans, dp[N][A][B]);

		}
	}

	if (ans >= INF / 10) cout << -1 << endl;
	else  cout << ans << endl;


	return 0;
}

