int gcd(int a,int b){
	int t = a;
	if(b<a) t = b;
	int g;
	for(g=t;g>0;g--){
		if(a%g==0 && b%g==0){
			break;
		}
	}
	return g;
}


int main(){
	int N,Ma,Mb;
	int a[40],b[40],c[40];

	scanf("%d %d %d", &N, &Ma, &Mb);
	for(int i=0;i<N;i++){
		scanf("%d %d %d", &a[i],&b[i],&c[i]);
	}

	if(N==1){
		if(a[0]*Mb == b[0]*Ma){
			printf("%d\n", c[0]);
		}else{
			printf("-1\n");
		}
	}else{
		int ans = 100000;
		bool found = false;

		for(int i=0;i<N;i++){
			for(int j=i+1;j<N;j++){
				int a1 = a[i];
				int a2 = a[j];
				int b1 = b[i];
				int b2 = b[j];
				if(Ma*b1==Mb*a1){
					found = true;
					if(ans > c[i]) ans = c[i];
				}
				if(Ma*b2==Mb*a2){
					found = true;
					if(ans > c[j]) ans = c[j];
				}
				if(a1*b2==b1*a2){
					if(Ma*b1==Mb*a1){
						found = true;
						ans = min(c[i],c[j]);
					}else{
						ans = -1;
					}
				}
				int n1 = Ma*b1-Mb*a1;
				int n2 = Mb*a2-Ma*b2;
				if(n1>0&&n2>0){
					found = true;
					int g = gcd(n1,n2);
					int k1 = n2/g;
					int k2 = n1/g;
					int tmp = k1*c[i] + k2*c[j];
					if(ans > tmp) ans = tmp;
				}
				if(n1<0&&n2<0){
					found = true;
					int g = gcd(-n1,-n2);
					int k1 = -n2/g;
					int k2 = -n1/g;
					int tmp = k1*c[i] + k2*c[j];
					if(ans > tmp) ans = tmp;
				}
			}
		}
		printf("%d\n", ans);
	}

	return 0;
}

