struct Pack {
    int a, b, c;
};

int n, m, ma, mb, a[N], b[N];
vector<Pack> package;

void find_all_combination(int a[]){
    for(int mask=1; mask < (1 << 10); mask++){
        if(__builtin_popcount(mask) == 1) continue;

        vector<int> chose;
        for(int i=0; i<10; i++)
            if(BIT(mask,i)) chose.push_back(i+1);

        int amount = 0, cost = 0;
        for(int i : chose){
            if(a[i] == INF){
                cost = INF;
                break;
            }
            cost += a[i];
            amount += i;
        }

        a[amount] = min(a[amount], cost);
    }
}

