#define REP(i,n) for (int i=0;i<(n);++i)
template<class T> inline void chmin(T &a, T b){if(a>=b)a=b;}
template<class T> inline void chmax(T &a, T b){if(a<=b)a=b;}
typedef long long ll;
const int INF = 1e9;

int N,Ma,Mb;
int A[50],B[50],C[50];
// dp[i][j][k] : i番目まで使った時、maがj,mbがkの場合の最小値
int dp[50][500][500];

int main()
{
    cin >> N >> Ma >> Mb;
    REP(i,N) cin >> A[i] >> B[i] >> C[i];

    // 初期化
    REP(i,11) REP(a,401) REP(b,401) dp[i][a][b] = INF;
    //

    // 初期値　：　何も使ってないときはコスト０
    dp[0][0][0] = 0;
    // 可能なa,bを全て調査
    REP(i,N){
        REP(a,401){
            REP(b,401){
                // 使わない
                chmin(dp[i+1][a][b],dp[i][a][b]);
                // 使う
                chmin(dp[i+1][a+A[i]][b+B[i]],dp[i][a][b] + C[i]);
            }
        }
    }
    // a, bは1から(dp[n][0][0]には何も使わない時の値0が入ってる)
    int ans = INF;
    for(int a = 1; a < 401; ++a){
        for(int b = 1; b < 401; ++b){
