int gcd(int a , int b)
{
	if(a==0 && b==0) return 1;
	if(a==b) return a;
	if(a ==0 || b==0) return max(a,b);
	if(a<b) swap(a,b);

	if(a%b==0) return b;
	else return gcd(a%b , b);
}

int rec(int x , int one , int two)
{
	if(x==n)
	{
		int potato = gcd(one,two);
		one = one/potato;
		two = two/potato;

		if(one == r1 && two == r2) return 0;
		else return 1e9;
	}

	if(dp[x][one][two]!=-1) return dp[x][one][two];

	int ret = 0;
	ret = min( rec(x+1 , one + m1[x] , two + m2[x]) + cost[x] , rec(x+1 , one , two) );

	return dp[x][one][two] = ret;
}


