class st
{
public:
	int f;
	int s;
	int m;

	st() {
		f = s = m;
	}
	st(int a, int b, int c) {
		f = a;
		s = b;
		m = c;
	}
};

int main()
{
	int n, ma, mb;
	cin >> n >> ma >> mb;
	st dp[n+1][n];

	int a[n+1];
	int b[n+1];
	int c[n+1];

	for (int i = 1; i <= n; i++) {
		cin >> a[i] >> b[i] >> c[i];
	}

	int cost = INF;
	for (int i = 0; i < n+1; i++) {
		for (int j = 1; j <= n; j++) {
			if (i==0) {
				dp[i][j] = st(a[j],b[j],c[j]);
			} else if (i==j) {
				continue;
			} else {
				st tmp = dp[i-1][j];
				dp[i][j] = st(tmp.f+a[i], tmp.s+b[i], tmp.m+c[i]);
			}
//			cout << "i:" << i << "... "  << dp[i][j].f << " " << dp[i][j].s <<  " " << dp[i][j].m << "\n";
