int dp_cost[MAX_N][MAX_VAL][MAX_VAL];

int main(int argc, char **argv) {
    std::cin >> N >> Ma >> Mb;

    for (int i = 1; i <= N; i++) {
        std::cin >> a[i] >> b[i] >> c[i];
    }

    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= MAX_V * N; j++) {
            for (int k = 0; k <= MAX_V * N; k++) {
                dp_cost[i][j][k] = MAX_C * MAX_N;
            }
        }
    }

    dp_cost[0][0][0] = 0;

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= MAX_V * N; j++) {
            for (int k = 0; k <= MAX_V * N; k++) {
                dp_cost[i][j][k] = std::min(dp_cost[i][j][k], dp_cost[i-1][j][k]);
                if (j + a[i] <= MAX_V * N && k + b[i] <= MAX_V * N) {
                    dp_cost[i][j+a[i]][k+b[i]] = std::min(dp_cost[i][j+a[i]][k+b[i]], dp_cost[i-1][j][k] + c[i]);
                    //if (dp_cost[i][j+a[i]][k+b[i]] < MAX_C * MAX_N) {
