                }
            }
        }
    }

    int ret = MAX_C * MAX_N;
    for (int i = 1; i * Ma <= MAX_V * N && i * Mb <= MAX_V * N; i++) {
        ret = std::min(ret, dp_cost[N][i*Ma][i*Mb]);
    }

    if (ret == MAX_C * MAX_N) {
        std::cout << -1 << std::endl;
    } else {
        std::cout << ret << std::endl;
    }

    return 0;
}

