pi vmax(vi v) {
	int n = size(v);
	int MAX = 0;
	int pos = 0;
	rep(i, n) {
		if (MAX < v[i])pos = i;
		MAX = max(MAX, v[i]);
	}
	return { MAX,pos };
}

pi vmin(vi v) {
	int n = size(v);
	int MIN = INF;
	int pos = 0;
	rep(i, n) {
		if (MIN > v[i])pos = i;
		MIN = min(MIN, v[i]);
	}
	return { MIN,pos };
}

