typedef long long ll;
using namespace std;
typedef pair<int, int> pii;
const int maxn = 1e3 + 10;
int a[450][450];
bool can[450][450];
int n, ma, mb;
void solve() {
    cin >> n >> ma >> mb;
    int x, y, z;
    while(n--) {
        int t1, t2, t3;
        cin >> t1 >> t2 >> t3;
        //cin >> x >> y >> z;
        for (int k = 1; k * t1 <= 400 && k * t2 <= 400; k++) {
            x = k * t1; y = k * t2; z = k * t3;
            if(!can[x][y] || a[x][y] > z) {
                can[x][y] = 1;
                a[x][y] = z;
            }
            for (int i = 1; i <= 400; i++) {
                for (int j = 1; j <= 400; j++) {
                    if(!can[i][j]) continue;
                    int tx = x + i;
                    int ty = y + j;
                    //int d = __gcd(tx, ty);
                    //tx /= d; ty /= ty;
                    if(tx > 400 || ty > 400) continue;
                    if(!can[tx][ty] || a[tx][ty] > z + a[i][j]) {
                        can[tx][ty] = 1;
                        a[tx][ty] = z + a[i][j];
                    }
                }
            }
        }

    }
    bool f = 0;
    int res = 400000;
    for (int i = 1; ma * i <= 400 && mb * i <= 400; i++) {
        int x = i *ma, y = i * mb;
        if(can[x][y]) {
            f = 1;
            res = min(res, a[x][y]);
        }
    }
    //if(can[ma][mb]) cout << a[ma][mb] << endl;
    //else cout << -1 << endl;
    if(f) cout << res << endl;
    else cout << -1 << endl;
}
int main() {
   // freopen("test.in", "r", stdin);
    //freopen("test.out", "w", stdout);
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    solve();
    return 0;
}

