int main(void)
{
    int n, ma, mb;
    cin >> n >> ma >> mb;
    bool swapped = false;
    if (ma > mb) {
        int temp = mb;
        mb = ma;
        ma = temp;
        swapped = true;
    }
    vector<ti3> v;
    if (swapped) {
        for (size_t i = 0; i < n; ++i) {
            int b, a, c;
            cin >> b >> a >> c;
            v.emplace_back(a,b,c);
        }
