            int a, b, c;
            cin >> a >> b >> c;
            v.emplace_back(a,b,c);
        }
    }
    int min_sc = 114514;
    for (size_t num_use = 1; num_use <= n; ++num_use) {
        vector<int> used;
        int sa = 0;
        int sb = 0;
        int sc = 0;
        for (size_t i = 0; i < num_use; ++i) {
            used.push_back(i);
            ti3 j = v[i];
            sa += get<0>(j);
            sb += get<1>(j);
            sc += get<2>(j);
        }

        bool stay = true;
        while(stay)
        {
            if (sa*mb == sb*ma)
            {
                if (min_sc > sc)
                {
                    min_sc = sc;
                }
                break;
            }

            bool* defer = new bool[num_use];
            for (size_t i = 0; i < num_use; ++i) {
                defer[i] = false;
            }
            for (size_t i = 1; i <= num_use; ++i) {
                int k = num_use - i;
                ti3 j = v[used[k]];
                sa -= get<0>(j);
                sb -= get<1>(j);
                sc -= get<2>(j);
                if (used[k] == n - i) {
                    defer[k] = true;
                } else {
                    ++used[k];
                    ti3 jj = v[used[k]];
                    sa += get<0>(j);
                    sb += get<1>(j);
                    sc += get<2>(j);
                    break;
                }
            }
            int relocate = 0;
            for (size_t i = 0; i < num_use; ++i) {
                if (defer[i]) {
                    if (i == 0) {
                        stay = false;
                        break;
                    } else {
                        relocate = used[i-1]+1;
                    }
                }
            }
        }
    }

    if (min_sc == 114514) {
