template <typename T>
vector<vector<T>> alloc_double_vec(size_t rows, size_t cols, T init) {
    vector<vector<T>> ret;
    vector<T> ret_elem;
    ret_elem.resize(cols, init);
    ret.resize(rows, ret_elem);
    return ret;
}

int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    struct Item {
        int param;
        int cost;
    };
    vector<Item> items0;
    vector<Item> items1;
    vector<Item> items2;
    for (int i = 0; i < N; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        int param = b * Ma - a * Mb;
        if (param > 0) {
            items0.push_back(Item{param, c});
        } else if (param < 0) {
            items1.push_back(Item{-param, c});
        } else {
            items2.push_back(Item{param, c});
        }
    }
    int min_cost = numeric_limits<int>::max();
    for (auto item : items2) {
        min_cost = min(min_cost, item.cost);
    }
    vector<vector<int>> dp0 = alloc_double_vec(items0.size()+1, 40001, numeric_limits<int>::max());
    vector<vector<int>> dp1 = alloc_double_vec(items1.size()+1, 40001, numeric_limits<int>::max());
    // dpi[i][p] = インデックスi-1までの薬品を使用してパラメータの和をpにするための最小コスト
    using items_dp_t = pair<vector<Item>&, vector<vector<int>>&>;
    for (items_dp_t items_dp_pair : {items_dp_t(items0, dp0), items_dp_t(items1, dp1)}) {
        vector<Item>& items = items_dp_pair.first;
        vector<vector<int>>& dp = items_dp_pair.second;
        for (int i = 0; i < dp.size(); i++) {
            for (int p = 0; p < 40001; p++) {
                if (i == 0) {
                    if (p == 0) {
                        dp[i][p] = 0;
                    } else {
                        dp[i][p] = numeric_limits<int>::max();
                    }
                } else {
                    if (p-items[i-1].param >= 0) {
                        if (dp[i-1][p-items[i-1].param] == numeric_limits<int>::max()) {
                            dp[i][p] = dp[i-1][p];
                        } else {
                            dp[i][p] = min(dp[i-1][p], items[i-1].cost + dp[i-1][p-items[i-1].param]);
                        }
                    } else {
                        dp[i][p] = dp[i-1][p];
                    }
                }
            }
        }
    }
    for (int p = 1; p < 40001; p++) {
        if (dp0[items0.size()][p] == numeric_limits<int>::max() || dp1[items1.size()][p] == numeric_limits<int>::max()) {
            continue;
        }
        min_cost = min(min_cost, dp0[items0.size()][p] + dp1[items1.size()][p]);
    }
    if (min_cost == numeric_limits<int>::max()) {
        cout << -1 << endl;
    } else {
        cout << min_cost << endl;
    }
}

