			}
		}
	}

	p[0][0][0] = 0;

	REP(i,N-1){
		REP(at,401){
			REP(bt,401){
				if(p[i][at][bt] == SURP) continue;
				p[i+1][at][bt] = min(p[i+1][at][bt],p[i][at][bt]);
				p[i+1][at+a[i]][bt+b[i]] = min(p[i+1][at+a[i]][bt+b[i]],p[i][at][bt] + c[i]);
 			}
		}
	}

	int pp = 1;
	int tmp = SURP;

	while(true){
		if(Ma * pp >= 401 || Mb * pp >= 401) break;
		if(tmp >  p[N-1][Ma * pp][Mb * pp]) tmp = p[N-1][Ma * pp][Mb * pp];
    	pp++;
	}
	if (tmp == SURP) tmp = -1;
	cout << tmp <<endl;
	return 0;
}

