struct Material
{
  unsigned a, b, c;
  Material(unsigned a = 0, unsigned b = 0, unsigned c = 0)
    : a(a), b(b), c(c) {}
  bool operator==(const Material &m) const {
    return a == m.a && b == m.b && c == m.c;
  }
  bool operator<(const Material &m) const {
    return (c == m.c) ? (
      (b == m.b) ? a < m.a : b < m.b
    ) : c < m.c;
  }
  Material operator+(const Material &m) const {
    return Material(a + m.a, b + m.b, c + m.c);
  }
};

std::istream& operator>>(std::istream &is, Material &m)
{
  is >> m.a >> m.b >> m.c;
  return is;
}

inline bool satisfy(unsigned Ma, unsigned Mb, unsigned a, unsigned b)
{
  if(a == 0 || b == 0) return false;

  unsigned Ta = a / Ma, Sa = a % Ma;
  unsigned Tb = b / Mb, Sb = b % Mb;
  return (Ta == Tb) && (Sa == 0) && (Sb == 0);
}

inline bool satisfy(unsigned Ma, unsigned Mb, const Material& m)
{
  return satisfy(Ma, Mb, m.a, m.b);
}

long search(
  unsigned N, unsigned Ma, unsigned Mb,
  const std::vector<Material> &m
)
{
  std::vector< std::set<Material> > dp(N + 1);
  dp[0].emplace(0, 0, 0);

  N_TIMES(n, N) {
    for (Material p : dp[n]) {
      //std::cerr << '(' << p.a << ',' << p.b << ',' << p.c << ')' << std::endl;
      dp[n + 1].insert(Material(p));
      dp[n + 1].insert(p + m[n]);
    }
  }

  long ret = -1;

  for (Material p : dp[N]) {
    if (!satisfy(Ma, Mb, p)) continue;

    if (ret > 0) {
      ret = std::min(static_cast<long>(p.c), ret);
    } else {
      ret = static_cast<long>(p.c);
    }
  }

  return ret;
}

