      for (int k = 1; k <= MAXAB; k++) {
        dp[i][j][k] = dp[i-1][j][k];
        if (j - a[i] >= 0 && k - b[i] >= 0)
          dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j - a[i]][k - b[i]] + c[i]);
      }
    }
  }

  int ans = INF;

  for (int i = 1; i <= MAXAB; i++) {
    for (int j = 1; j <= MAXAB; j++) {
      if (A * i == B * j) {
        ans = min(ans, dp[n][i][j]);
      }
    }
  }

  cout << (ans == INF ? -1 : ans) << endl;
  return 0;
}

