        int a, b, p;
        cin >> a >> b >> p;
        items[i] = {a, b, p};
    }
    //N<=40, a,b<=10なので、最大400gしか買えない
    //i=買ったaの量、j=買ったbの量、値＝お値段とする
    const int MAX = 450;
