static const int INF = 100005;//4000より大きい数

int dp[50][500][500];

void MakeDp(int N, int a[], int b[], int c[]) {

	for (int i = 0;i < 402;i++) {//k=0の層をINFで埋める
		for (int j = 0;j < 402;j++) {
			dp[0][i][j] = INF;
		}
	}
	dp[0][0][0] = 0;//重さX，Y0はコスト0で数0で作れる

	int dia, top;
	for (int k = 1;k <= N;k++) {
		for (int i = 0;i < 402;i++) {
			for (int j = 0;j < 402;j++) {
				if (i - a[k] >= 0 && j - b[k] >= 0) dia = dp[k - 1][i - a[k]][j - b[k]] + c[k];
				else dia = INF;
				top = dp[k - 1][i][j];
				dp[k][i][j] = min(dia, top);
			}
		}
	}

}

int SolveDp(int N, int Ma, int Mb) {
	int cnt = 0;
	int ans = INF;
	int roopN = 400 / max(Ma, Mb);
	for (int i = 0;i < roopN;i++) {
		cnt++;
		ans = min(ans, dp[N][Ma*cnt][Mb*cnt]);
		//cout << ans<< endl;
	}

	return (ans == INF ? -1 : ans);
}

