void chmin(int& a, int b){
    a = min(a, b);
}

int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

int main(){
    int N, Ma, Mb, a[40], b[40], c[40];
    cin >> N >> Ma >> Mb;
    for(int i=0; i<N; i++) cin >> a[i] >> b[i] >> c[i];

    // OFFSETはsが負になることを防ぐために足す値
    const int OFFSET = 2000, INF = 1e9;

    // C[g][s] = グループgの選び方（1つ以上）で Mb*sumA - Ma*sumB + OFFSET = s となるときの最小コスト
    int C[2][4001];
    for(int g=0; g<2; g++) for(int s=0; s<=4000; s++) C[g][s] = INF;

    // グループgに属するのはインデックス [start[g], term[g]) の範囲のものとする
    int start[2] = {0, N/2}, term[2] = {N/2, N};

    for(int g=0; g<2; g++){
        int sz = term[g] - start[g];
        // 全列挙。1つ以上選ぶのでbits=0を見ない
        for(int bits=1; bits<(1<<sz); bits++){
            int s = OFFSET, cost = 0;
            for(int i=0; i<sz; i++) if(nth_bit(bits, i)){
                s += Mb * a[i+start[g]] - Ma * b[i+start[g]];
                cost += c[i+start[g]];
            }
            chmin(C[g][s], cost);
        }
    }

    int ans = min(C[0][0], C[1][0]);
    for(int s=0; s<=4000; s++) chmin(ans, C[0][s] + C[1][2*OFFSET-s]);
    if(ans >= INF) ans = -1;
    cout << ans << endl;
    return 0;
}

