struct Med
{
	int a, b, c;
};

int N, Ma,Mb;
std::vector<Med>  vMed;

int ans = INT_MAX;

int eval(int seek,Med sum)
{
	if (seek == N)
		return -1;

	if (!(sum.a ==0 && sum.b == 0) && sum.a*Mb == sum.b*Ma)
		return sum.c;

	int ans_0 = eval(seek + 1, sum);

	Med sum2 = sum;

	sum2.a += vMed[seek].a;
	sum2.b += vMed[seek].b;
	sum2.c += vMed[seek].c;

	int ans_1 = eval(seek + 1, sum2);

	if (ans_0 == -1 && ans_1 == -1)
		return -1;
	else if (ans_0 == -1)
		return ans_1;
	else if (ans_1 == -1)
		return ans_0;
	else return std::min(ans_0, ans_1);

}

