using namespace std;

#define FOR(i,a,b) for(int i=(int)(a);i<(int)(b);i++)
#define RFOR(i,a,b) for(int i=(int)(b)-1;i>=(int)(a);i--)
#define REP(i,n) FOR(i,0,n)
#define RREP(i,n) RFOR(i,0,n)
#define LL long long
#define INF INT_MAX

const double EPS = 1e-14;
const double PI  = acos(-1.0);


LL dp[41][101][101];

struct Mat {
  int a;
  int b;
  int c;
};

int main(){
  int n, ma, mb;
  cin >> n >> ma >> mb;

  vector<Mat> v(n);
  int a, b, c;
  REP (i, n) {
    cin >> a >> b >> c;
    v[i] = {a, b, c};
  }

  REP (i, 41) REP (j, 101) REP (k, 101) {
    if (j == 0 || k == 0) dp[i][j][k] = 0;
    else dp[i][j][k] = INF;
  }
  FOR (i, 1, n + 1) {
    REP (j, 101) {
      REP (k, 101) {
        int l = 1;
        int al = v[i - 1].a * l;
        int bl = v[i - 1].b * l;
        while (al <= 100 && bl <= 100) {
          al = v[i - 1].a * l;
          bl = v[i - 1].b * l;
          if (0 == j - al && 0 == k - bl) {
            dp[i][j][k] = min(dp[i - 1][j][k], (LL)(v[i - 1].c * l));
          } else if (0 < j - al && 0 < k - bl && dp[i - 1][j - al][k - bl] != INF) {
            dp[i][j][k] = min(dp[i - 1][j][k], dp[i - 1][j - al][k - bl] + v[i - 1].c * l);
          } else {
            dp[i][j][k] = min(dp[i - 1][j][k], dp[i][j][k]);
          }
          l++;
        }
      }
    }
  }

  LL ans = INF;
  FOR (i, 1, 101) {
    FOR (j, 1, 101) {
      if (i / ma == j / mb && i % ma == j % mb) {
        ans = min(ans, dp[n][i][j]);
      }
    }
  }

  if (ans == INF) cout << -1 << endl;
  else cout << ans << endl;
}

