			tot_A /= d;
			tot_B /= d;
			if (tot_A == a && tot_B == b)
				return 0;
		}
		return 1e9;
	}
	int &ret = DP[idx][tot_A][tot_B];
	if (ret != -1)
		return ret;
	ret = 1e9;
	ret = min(ret, solve(idx + 1, tot_A + x[idx], tot_B + y[idx]) + c[idx]);
	ret = min(ret, solve(idx + 1, tot_A, tot_B));
	return ret;
}
