VVLL Tenkai(VVLL const& ls) {
	VVLL ans;
	LL i, j, k;
	N_Number n(2, ls.size());

	while (true)
	{
		LL a, b, c;
		a = b = c = 0;
		for (i = 0; i < n.getKeta(); i++) {
			if (n.getNumber(i) == 1) {
				a += ls[i][0];
				b += ls[i][1];
				c += ls[i][2];
			}
		}

		ans.push_back(VLL({ a,b,c }));

