using namespace std;

int main()
{
    int N, MA, MB;
    cin >> N >> MA >> MB;

    for (int i = 0; i < N; i++)
    {
        cin >> a[i] >> b[i] >> c[i];
    }

    int asum = 0;
    int bsum = 0;
    for (int i = 0; i < N; i++)
    {
        asum += a[i];
        bsum += b[i];
    }

    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j <= asum; j++)
        {
            for (int k = 0; k <= bsum; k++)
            {
                eg[i][j][k] = false;
                dp[i][j][k] = CMAX;

                if (i == 0)
                {
                    if (j == 0 && k == 0)
                    {
                        dp[i][j][k] = 0;
                        eg[i][j][k] = true;
                    }
                    else if (j == a[i] && k == b[i])
                    {
                        dp[i][j][k] = c[i];
                        eg[i][j][k] = true;
                    }
                    continue;
                }

                if (eg[i - 1][j][k])
                {
                    dp[i][j][k] = dp[i - 1][j][k];
                    eg[i][j][k] = true;
                }
                if (j - a[i] >= 0 && k - b[i] >= 0 && eg[i - 1][j - a[i]][k - b[i]])
                {
                    dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j - a[i]][k - b[i]] + c[i]);
                    eg[i][j][k] = true;
                }
            }
        }
    }

    int result = CMAX;
    bool exists = false;
    for (int fac = 1; fac * MA <= asum && fac * MB <= bsum; fac++)
    {
        if (eg[N - 1][fac * MA][fac * MB])
        {
            result = min(result, dp[N - 1][fac * MA][fac * MB]);
            exists = true;
        }
    }

    cout << (exists ? result : -1) << endl;

    return 0;
}

