int memo[1000][1000];

int dfs(int i, int A, int B, int cost) {
    if (i == N) {
        if (cost == 0 || Ma / Mb != double(A) / double(B)) {
            return INF;
        } else {
            return cost;
        }
    }
    if (memo[A][B] != 0) {
        return memo[A][B];
    }

    int ans = min(dfs(i + 1, A + a[i], B + b[i], cost + c[i]),
                  dfs(i + 1, A, B, cost));

    return memo[A][B] = ans;
}

