int a[max_n], b[max_n], c[max_n];
int dp[max_n + 1][max_n * max_k + 1][max_n * max_k + 1];

signed solve()
{
	int n, ma, mb;
	cin >> n >> ma >> mb;
	REP(i, n) { cin >> a[i] >> b[i] >> c[i]; }
	REP(i, n + 1) REP(j, max_n * max_k + 1) REP(k, max_n * max_k + 1) dp[i][j][k] = inf;

	dp[0][0][0] = 0;
	REP(i, n)
	{
		REP(j, max_n * max_k + 1)
		{
			REP(k, max_n * max_k + 1)
			{
				if (dp[i][j][k] == inf) continue;
				// 足さない場合
				dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);
				// 足す場合
				dp[i + 1][j + a[i]][k + b[i]] = min(dp[i + 1][j + a[i]][k + a[i]], dp[i][j][k] + c[i]);
			}
		}
	}

	int ans = inf;
	FOR(j, 1, max_n * max_k + 1)
	{
		FOR(k, 1, max_n * max_k + 1)
		{
			if (j * mb == k * ma)
				ans = min(ans, dp[n][j][k]);
		}
	}

	if (ans == inf)
		print(-1);
	else
		print(ans);
	return 0;
}

