	if (P == 0) return 1;
	if (P % 2 == 0) {
		ll t = RepeatSquaring(N, P / 2, MO);
		return t * t % MO;
	}
	return N * RepeatSquaring(N, P - 1, MO);
}

ll gyakugen(ll numb, ll MO) {
	return RepeatSquaring(numb, MO - 2, MO);
