        reps(ii, 1, sz(dp[i])) {
            reps(iii, 1, sz(dp[i][ii])) {
                if (((double)Ma / Mb) == ((double)ii / iii)) {
                    ans = min(ans, dp[i][ii][iii]);
                }
            }
        }
    }

    cout << ((ans == UNDEFINED) ? -1 : ans) << endl;
    return 0;
}

