			rep(j,mx-off) {
				if(i & (1 << j)) {
					ab += in[off+j].fi;
					c += in[off+j].se;
				}
			}
			pii p(ab,c);
			if(k)
				vv.push_back(p);
			else
				v.push_back(p);
		}
	}
	sort(all(vv));
	sort(all(v));
	const int INF = 1e9;
	int res = INF;
	rep(i,v.size()) {
		int indx;
		indx = upper_bound(all(vv), pii(-v[i].fi, -1)) - vv.begin();
		if(indx == 0) indx++;
		if(indx >= vv.size() || v[i].fi+vv[indx].fi) continue;
		res = min(res, vv[indx].se + v[i].se);
	}

	if(res == INF)
		cout << -1 << endl;
	else
		cout << res << endl;
	return 0;
}

