int n, Ma, Mb; LL ans = inf, f[2][N][N]; double lim;

//inline double abs(double x) {return x <= -eps ? -x : x;}
//template <class T> inline T max(T a, T b) {return a > b ? a : b;}
//template <class T> inline T min(T a, T b) {return a < b ? a : b;}
template <class T> inline void in(T &x) {
	x = 0; LL f = 1; char ch = getchar();
	for (; ch<'0' || ch>'9';) {if (ch=='-') f=-1; ch = getchar();}
	for (; ch>='0' && ch<='9';) x = x*10 + ch-'0', ch = getchar();
	x *= f;
}

inline void init(int now) {
	for (int i = 0; i < N; ++i)
		for (int j = 0; j < N; ++j) f[now][i][j] = inf;
}

inline void work() {
	int a, b, now = 0, pre = 1; LL c;
	in(n), in(Ma), in(Mb); init(0), f[0][0][0] = 0;
	for (int l = 1; l <= n; ++l) {
		in(a), in(b), in(c);
		now ^= 1, pre = now^1, init(now);
		for (int i = 0; i < N; ++i)
			for (int j = 0; j < N; ++j) {
				if (f[pre][i][j] == inf) continue;
				f[now][i][j] = min(f[now][i][j], f[pre][i][j]);
				f[now][i+a][j+b] = min(f[now][i+a][j+b], f[pre][i][j] + c);
			}
	}
	double tmp; lim = ((double)Ma / (double)Mb);
	for (LL i = 0; i < N; ++i)
		for (LL j = 0; j < N; ++j) {
			tmp = ((double)i / (double)j);
			if (abs(tmp - lim) < eps) ans = min(ans, f[now][i][j]);
		}
	printf("%lld\n", ans);
}

