const int nmax = 40, abmax = 10, inf = 1e6;

int n, ma, mb;
int a[nmax], b[nmax], c[nmax];
int dp[nmax+1][nmax*abmax+1][nmax*abmax+1];

void solve() {
   for (int i = 0; i < n; i++) {
      for (int ca = 0; ca <= nmax*abmax; ca++) {
         for (int cb = 0; cb <= nmax*abmax; cb++) {
            chmin(dp[i+1][ca][cb], dp[i][ca][cb]);
            if (ca+a[i] <= nmax*abmax && cb+b[i] <= nmax*abmax) {
               chmin(dp[i+1][ca+a[i]][cb+b[i]], dp[i][ca][cb]+c[i]);
            }
         }
      }
   }

   int ans = inf;
   for (int ca = 1; ca <= nmax*abmax; ca++) {
      for (int cb = 1; cb <= nmax*abmax; cb++) {
         if (ca*mb==cb*ma) {
            chmin(ans, dp[n][ca][cb]);
         }
      }
   }

   if (ans == inf) ans = -1;
   cout << ans << endl;
}

