int N,Ma,Mb;
int a[41];
int b[41];
int c[41];



void pat( vector<int>& a0, vector<int>& b0, vector<int>& c0, int n0, vector<pair<int,int> >& v0, vector<int> ind )
{
  if( SIZ(ind) == n0 )
    {
      int cst = 0;
      int val = 0;

      REP(i,n0)
	{

	  if( ind[i] )
	    {
	      cst += c0[i];
	      val += a0[i] * Mb - b0[i] * Ma;
	    }

	}

      v0.push_back(make_pair(val,cst));
      return;
    }

  REP(j,2)
    {
      vector<int> temp = ind;
      temp.push_back(j);
      pat(a0,b0,c0,n0,v0,temp);
    }
}




int main()
{
  IOS; /* making cin faster */
  SCAND3(N,Ma,Mb);
  REP(i,N)
    {
      SCAND3(a[i],b[i],c[i]);
    }

  int n0 = N/2;
  int n1 = N - n0;

  vector<int> a0(n0), b0(n0), c0(n0);
  vector<int> a1(n1), b1(n1), c1(n1);

  REP(i,n0)
    {
      a0[i] = a[i];
      b0[i] = b[i];
      c0[i] = c[i];

    }

  REP(i,n1)
    {
      a1[i] = a[i+n0];
      b1[i] = b[i+n0];
      c1[i] = c[i+n0];

    }

  vector<pair<int,int> > v0, v1;
  vector<int> ind;
  pat(a0,b0,c0,n0,v0,ind);
  pat(a1,b1,c1,n1,v1,ind);


  sort(ALL(v0));
  sort(ALL(v1));


  int mn = INF;

  REP(i,SIZ(v0))
    {
      int val0 = v0[i].first;
      int cost0 = v0[i].second;

      auto it = lower_bound(ALL(v1),make_pair(-val0,0));

      if( cost0 == 0 and it->second == 0 and it != v1.end() )
	{
	  ++ it;
	}

      if( it != v1.end() )
	{
	  if( it->first == -val0 and ( cost0 != 0 or it->second != 0 ) )
	    {
	      mn = min( mn, cost0 + it->second ); 
	    }
	}
    }

  if( mn == INF )
    {
      PRINTD(-1);
    }
  else
    {
      PRINTD(mn);
    }


}

