#define rep(i, n) for(int i = 0; i < n; i++)

using namespace std;

typedef struct {
  int a;
  int b;
  int c;
} med;

int main()
{
  int N, Ma, Mb;
  cin >> N >> Ma >> Mb;

  int amax = 0, bmax = 0;

  vector<med> meds(N);
  rep(i, N) {
    cin >> meds[i].a >> meds[i].b >> meds[i].c;
    amax += meds[i].a;
    bmax += meds[i].b;
  }

  vector< vector<int> > cost(amax + 1);
  rep(i, amax + 1)
    cost[i].resize(bmax + 1);

  cost[0][0] = 0;
  rep(i, amax + 1) rep(j, bmax + 1) {
    if(i == 0 && j == 0) cost[i][j] = 0;
    else {
      int c = -1;
      rep(k, N) {
	int a = i - meds[k].a;
	int b = j - meds[k].b;
	if(a >= 0 && b >= 0 && cost[a][b] >= 0) {
	  if(c == -1) c = cost[a][b] + meds[k].c;
	  else c = min(c, cost[a][b] + meds[k].c);
	}
      }
      cost[i][j] = c;
    }
  }

  int m = -1;
  for(int i = 1; Ma * i <= amax && Mb * i <= bmax; i++) {
    if(cost[Ma * i][Mb * i] != -1) {
      if(m == -1) m = cost[Ma * i][Mb * i];
      else m = min(m, cost[Ma * i][Mb * i]);
    }
  }
  cout << m << endl;
  return 0;
}

