using namespace std;

const int MaxN = 44, MaxC = 0x3f3f3f3f;

int dp[444][444];
int a[MaxN], b[MaxN], c[MaxN];

int n;

int main( void )
{
  int ma, mb;
  while (scanf("%d %d %d", &n, &ma, &mb) != EOF)
  {
    int res = MaxC;
    memset (dp, MaxC, sizeof dp);
    for (int i = 0; i < n; i++)
      scanf("%d %d %d", &a[i], &b[i], &c[i]);
    dp[0][0] = 0;
    for (int i = 0; i < n; i++)
      for (int j = 443; j >= a[i]; j--)
        for (int k = 443; k >= b[i]; k--)
        {
          dp[j][k] = min(dp[j][k], dp[j-a[i]][k-b[i]] + c[i]);
          if(j % ma == 0 && k % mb == 0 && j / ma == k / mb)
            res = min(res, dp[j][k]);
        }




    if (res >= MaxC)
      res = -1;
    printf("%d\n", res);
  }
  return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define INF 100000
int dp[44][444][444];
int main(){
  int n,ma,mb;
  int a[44],b[44],c[44];
  cin>>n>>ma>>mb;
  for(int i=0;i<n;i++)cin>>a[i]>>b[i]>>c[i];

  fill_n(**dp,44*444*444,INF);
  dp[0][0][0]=0;
  int ans=INF;

  for(int i=0;i<n;i++){
    for(int j=0;j<444;j++){
      for(int k=0;k<444;k++){
	if(dp[i][j][k]==INF)continue;
	dp[i+1][j][k]=min(dp[i+1][j][k],dp[i][j][k]);
	dp[i+1][j+a[i]][k+b[i]]=min(dp[i+1][j+a[i]][k+b[i]],dp[i][j][k]+c[i]);
      }
    }
  }

  for(int i=1;i<444;i++)
    for(int j=1;j<444;j++)
      if(ma*j==mb*i)ans=min(ans,dp[n][i][j]);

  if(ans==INF)cout<<-1<<endl;
  else cout<<ans<<endl;

  return 0;
}

#include<bits/stdc++.h>
using namespace std;

static const int INF=1e9;

int main(){
    int N,ma,mb;
    cin >> N >> ma >> mb;
    int a[N],b[N],c[N];
    for(int i=0;i<N;i++){
        cin >> a[i] >> b[i] >> c[i];
    }
    int dp[N+1][401][401];
    for(int i=0;i<=N;i++){
        for(int s=0;s<=400;s++){
            for(int t=0;t<=400;t++){
                dp[i][s][t]=INF;
            }
        }
    }
    dp[0][0][0]=0;
    for(int i=0;i<N;i++){
        for(int s=0;s<=400;s++){
            for(int t=0;t<=400;t++){
                if(s+a[i]<=400&&t+b[i]<=400){
                    dp[i+1][s+a[i]][t+b[i]]=min(dp[i+1][s+a[i]][t+b[i]],dp[i][s][t]+c[i]);
                }
                dp[i+1][s][t]=min(dp[i+1][s][t],dp[i][s][t]);
            }
        }
    }
    int ans=INF;
    for(int i=1;i<=400;i++){
        for(int j=1;j<=400;j++){
            //cout << dp[N][i][j] << " ";
            if(i*mb==j*ma){
                ans=min(ans,dp[N][i][j]);
            }
        }
        //cout << endl;
    }
    if(ans==INF){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }

}

#include <iostream>
