using namespace std;

#define MAX_N 40
pair<int,int> target[MAX_N];
int ans=MOD,n,ma,mb,rbs;

int bs(int begin, int end, int x){
  int left=begin,right=end-1,mid;
  if(x<target[left].first || x>target[right].first) return -1;
  while(left<=right){
    mid = (left+right)/2;
    if(x<target[mid].first) right = mid-1;
    else left = mid+1;
  }
  if(x==target[right].first) return right;
  else return -1;
}

void dfs(int sum,int val,int k){
    if(bs(k+1,n,-sum)!=-1) ans = min(ans,val+target[bs(k+1,n,-sum)].second);
    if(k<n-2){
        ++k;
        dfs(sum,val,k);
        dfs(sum+target[k].first,val+target[k].second,k);
    }
}

void solve(){
    dfs(0,0,0);
    dfs(target[0].first,target[0].second,0);
}

int main(){
    scanf("%d %d %d",&n,&ma,&mb);
    REP(i,n){
        int a,b;
        scanf("%d %d %d",&a,&b,&target[i].second);
        target[i].first = ma*b - mb*a;
    }
    sort(target,target+n);
    solve();
    if(ans!=MOD) printf("%d\n",ans);
    else printf("-1\n");
    return 0;
}

