int bs(int begin, int end, int x){
  int left=begin,right=end-1,mid;
  if(x<ps[left].first || x>ps[right].first) return -1;
  while(left<=right){
    mid = (left+right)/2;
    if(x<ps[mid].first) right = mid-1;
    else left = mid+1;
  }
  if(x==ps[right].first) return right;
  else return -1;
}

int main(){
    int ans=MOD,n,ma,mb;

    scanf("%d %d %d",&n,&ma,&mb);
