#include <iostream>
using namespace std;


int N,Ma,Mb;
const int inf = 1000000;

int A[40], B[40], C[40];
int dp[41][400][400];


int solve(){
	int ans = inf;
	for(int i=0; i<N+1; i++){
		for(int a=0; a<=N*10; a++){
			for(int b=0; b<=N*10; b++){
				dp[i][a][b] = inf;
			}
		}
	}
	dp[0][0][0] = 0;

	for(int i=1; i<N+1; i++){
		for(int a=0; a<=10*N; a++){
			for(int b=0; b<=10*N; b++){
				if(dp[i-1][a][b] == inf) continue;
				dp[i][a][b] = min(dp[i][a][b], dp[i-1][a][b]);
				dp[i][a+A[i-1]][b+B[i-1]] = min(dp[i][a+A[i-1]][b+B[i-1]] ,dp[i-1][a][b]+C[i-1]);
			}
		}
	}

	for(int n=1; n*Ma<=10*N && n*Mb<=10*N; n++){
		ans = min(ans, dp[N][n*Ma][n*Mb]);
	}

	if(ans >= inf) cout << -1 << endl;
	else cout << ans << endl;
	return 0;
}



