	for(int i = 1; i <= 410; ++i){
		for(int j = 1; j <= 410; ++j){
			ll x = i, y = j;
			ll gcd = __gcd(x, y);
			x /= gcd, y /= gcd;
			g[i][j] = mp(x, y);
		}
	}

	for(ll i = 0; i < n; ++i){
		int p = g[a[i]][b[i]].F, q = g[a[i]][b[i]].S;
		if(dp[p][q] > c[i]){
			dp[p][q] = c[i];
			mask[p][q] = (1LL << i);
		}		
		for(int x = 1; x <= 400; ++x){
			for(int y = 1; y <= 400; ++y){
				int u = x + a[i], v = y + b[i];
				int l = g[u][v].F, r = g[u][v].S;
				if((mask[x][y] & (1LL << i)) == 0 && 
					dp[x][y] + c[i] < dp[l][r]){
						dp[l][r] = dp[x][y] + c[i];
						mask[l][r] = (mask[x][y] | (1LL << i));
					}	
			}
		}
	}

	cout << ((dp[ma][mb] == inf) ? (-1) : (dp[ma][mb])) << '\n';
}




