#include <bits/stdc++.h>
using namespace std;
#define rep(i,n) for (int i=0; i<(int)(n); i++)

int main() {
  int N, Ma, Mb;
  cin >> N >> Ma >> Mb;
  int med[N][3];  // med[i][2] = cost of i
  rep(i,N) rep(j,3) cin >> med[i][j];

  int dif[N];  // [target] some sum of dif = 0
  rep(i,N) {
    med[i][0] *= Mb;
    med[i][1] *= Ma;
    dif[i] = med[i][0] - med[i][1];
  }

  map<int, int> dps;
  dps[0] = 0;
  queue<int> check;
  check.push(0);
  priority_queue<int, vector<int>, greater<int>> ans;

  rep(i,N) {
    int num = check.size();
    int d = dif[i];
    queue<int> dps_q;

    rep(j,num) {  // keep value before update
      int p = check.front();
      check.pop();
      check.push(p);
      dps_q.push(dps[p]);
    }

    rep(j,num) {
      int p = check.front();
      check.pop();
      check.push(p);

      if (!dps.count(p+d)) {  // for the first time
        check.push(p+d);
        dps[p+d] = med[i][2];
      }
      else if (p+d == 0) {  // some sum of dif = 0
        ans.push(dps_q.front() + med[i][2]);
      }
      else if (dps_q.front() + med[i][2] < dps[p+d]) {  // less cost
        dps[p+d] = dps_q.front() + med[i][2];
      }
      dps_q.pop();
    }
  }
  if (ans.empty()) {
    cout << -1 << endl;
    return 0;
  }
  cout << ans.top() << endl;
  return 0;
}

