		std::cin >> drag[i].c;
	}

	long int num = 0;
	int keta;
	double m = ma / mb;
	Drag mix;
	int min = -1;
	while(next_choice(&drag, &num, &keta)){
		mix = drag_mix(drag, min, keta);
		if (mix.exist && (double)mix.a / mix.b == m)
			if(min == -1 || mix.c < min)
				min = mix.c;
	};

	std::cout << min;
}

