void solve(int pos, int as, int bs, int cs) {
	if (pos == N) {
		if (as == 0 && bs == 0) return;
		int r = gcd(as, bs);
		as /= r, bs /= r;
		if (as == X && bs == Y) ret = min(ret, cs);
		return;
	}
	if (vis[pos][as][bs]) return;
	solve(pos + 1, as, bs, cs);
	solve(pos + 1, as + a[pos], bs + b[pos], cs + c[pos]);
}
