int gcdmemo[400][400] = {};
int gcd(int a, int b){
	if(gcdmemo[a][b] != -1)return gcdmemo[a][b];
	return gcdmemo[a][b] = (b == 0 ? a : gcd(b, a % b));
}

signed main(){
	int n, ma, mb;
	cin >> n >> ma >> mb;
	vector <pair <pair <int, int>, int>> vpp(n);
	rep(i, n){
		int a, b, c;
		cin >> a >> b >> c;
		vpp[i] = make_pair(make_pair(a, b), c);
	}

	map <pair <int, int>, int> dp[n + 1];
	rep(i, 401)rep(j, 401)gcdmemo[i][j] = -1;
	rep(k, n + 1)rep(i, 401)rep(j, 401)
		dp[k][make_pair(i, j)] = INF;
	dp[0][make_pair(0, 0)] = 0;
	rep(i, vpp.size()){
		rep(j, 401)rep(k, 401){
			if(dp[i][make_pair(j, k)] == INF)continue;
			int adda = j + vpp[i].first.first, addb = k + vpp[i].first.second;
			int va = gcd(adda, addb);
			if(va != 0)adda /= va, addb /= va;
			dp[i + 1][make_pair(adda, addb)] = min(dp[i][make_pair(adda, addb)], dp[i][make_pair(j, k)] + vpp[i].second);
