    // dp[i][A][B] = 0..i-1????????????A?A g, ???B?B g?????????
    auto dp = make_matrix<i64, 3>({N + 1, N * 10 + 1, N * 10 + 1}, -1);
    REP (i, N + 1) {
        dp[i][0][0] = 0;
    }

    REP (i, N) {
        /*
         * ??i??????
         * -> dp[i + 1][A][B] = min(dp[i][A][B], dp[i][A-a_i][B-b_i] + c_i)
         */
        auto a = get<0>(abcs[i]);
        auto b = get<1>(abcs[i]);
        auto c = get<2>(abcs[i]);
        FOR (A, a, N * 10 + 1) {
            FOR (B, b, N * 10 + 1) {
                if (dp[i][A][B] != -1) {
                    dp[i + 1][A][B] = dp[i][A][B];
                }
                if (dp[i][A - a][B - b] != -1) {
                    if (dp[i + 1][A][B] == -1) {
                        dp[i + 1][A][B] = dp[i][A - a][B - b] + c;
                    } else {
                        dp[i + 1][A][B] = std::min(dp[i + 1][A][B], dp[i][A - a][B - b] + c);
                    }
                }
            }
        }
