#include <iostream>
#include <algorithm>
using namespace std;

struct yakuhin {
  int a;
  int b;
  int c;
};

class Less{
public:
  bool operator()(const struct yakuhin& left, const struct yakuhin& right){
    return (left.a==right.a)?(left.b<right.b):(left.a<right.a);
  }
};

struct yakuhin zenhan[1048576];
struct yakuhin kouhan[1048576];

int main(){
  int n,Ma,Mb;
  cin >> n >> Ma >> Mb;
  struct yakuhin y[40];
  if(Ma>=Mb){
    for(int i=0;i<n;i++){
      cin >> y[i].a >> y[i].b >> y[i].c;
    }
  }else{
    for(int i=0;i<n;i++){
      cin >> y[i].b >> y[i].a >> y[i].c;
    }
    int tmp;
    tmp=Ma;
    Ma=Mb;
    Mb=tmp;
  }
  for(int i=0;i<(1<<((n+1)/2));i++){
    zenhan[i].a = zenhan[i].b = zenhan[i].c = 0;
    for(int j=0;j<(n+1)/2;j++){
      if(i&(1<<j)){
        zenhan[i].a += y[j].a;
        zenhan[i].b += y[j].b;
        zenhan[i].c += y[j].c;
      }
    }
  }
  for(int i=0;i<(1<<(n/2));i++){
    kouhan[i].a = kouhan[i].b = kouhan[i].c = 0;
    for(int j=0;j<n/2;j++){
      if(i&(1<<j)){
        kouhan[i].a += y[j+(n+1)/2].a;
        kouhan[i].b += y[j+(n+1)/2].b;
        kouhan[i].c += y[j+(n+1)/2].c;
      }
    }
  }

  sort(zenhan,zenhan+(1<<((n+1)/2)),Less());
  sort(kouhan,kouhan+(1<<(n/2)),Less());

  int ans=1000000000;
  int k;
  for(int i=1;i<=10*n/Ma;i++){
    k=(1<<(n/2))-1;
    for(int j=0;j<(1<<((n+1)/2));j++){
      if(zenhan[j].a>Ma*i) break;
      if(zenhan[j].a+kouhan[k].a<Ma*i) continue;
      while(zenhan[j].a+kouhan[k].a>Ma*i){
        k--;
        if(k<0) break;
      }
      if(k<0) break;
      if(zenhan[j].a+kouhan[k].a==Ma*i){
        if(zenhan[j].b>Mb*i||zenhan[j].b+kouhan[k].b<Mb*i) continue;
        while(zenhan[j].b+kouhan[k].b>Mb*i){
          k--;
          if(zenhan[j].a+kouhan[k].a!=Ma*i||k<0) break;
        }
        if(k<0) break;
        if(zenhan[j].a+kouhan[k].a==Ma*i&&zenhan[j].b+kouhan[k].b==Mb*i){
          ans=((zenhan[j].c+kouhan[k].c<ans)?(zenhan[j].c+kouhan[k].c):ans);
        }
      }
    }
  }

  if(ans==1000000000) cout << -1 << endl;
  else cout << ans << endl;


  return 0;
}

