int dp[401][401];
int main() {
    for(int i = 0; i < 401; i++) {
        for (int j = 0; j < 401; j++) {
            dp[i][j] = INF;
        }
    }
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    vector<int> A, B, C;
    for (int i = 0; i < N; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        A.push_back(a);
        B.push_back(b);
        C.push_back(c);
    }
    dp[0][0] = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 400; j >= 0; j--) {
            for (int k = 400; k >= 0; k--) {
                if (j + A[i] >= 400 || k + B[i] >= 400) continue;
                dp[j + A[i]][k + B[i]] = min(dp[j + A[i]][k + B[i]], dp[j][k] + C[i]);
            }
        }
    }

    int g = gcd(Ma, Mb);
    Ma /= g;
    Mb /= g;
    int Ma_ = Ma;
    int Mb_ = Mb;

    int ans = INF;
    while(Ma < 401 && Mb < 401) {
        ans = min(ans, dp[Ma][Mb]);
        Ma += Ma_;
        Mb += Mb_;
    }
    if (ans == INF) {
        cout << "-1" << endl;
    } else {
        cout << ans << endl;
    }



    return 0;
}

