int search(int sumA, int sumB, int sumC, int st, int opt){
    if(sumC>=opt){return opt;}   
    if((sumA+a[st])*mb==(sumB+b[st])*ma){
        if(sumC+c[st]<opt){opt=sumC+c[st];}
        return min(opt, search(sumA, sumB, sumC, st+1, opt));
    }
    else{
        if(st==n-1){return opt;}
        else{
            opt=min(search(sumA, sumB, sumC, st+1, opt), opt);
            return min(opt, search(sumA+a[st], sumB+b[st], sumC+c[st], st+1, opt));
        }
    }
}
