		{
			if (A{ ma, mb, 0 } < a[i] || a[j] < A{ ma,mb,0 })
			{
				continue;
			}

			lint p = ma * a[i].b - mb * a[i].a;
			lint q = -ma * a[j].b + mb * a[j].a;

			if (p < 0 && q < 0)
			{
				p *= -1;
				q *= -1;
			}

			if (p <= 0 || q <= 0)
				continue;

			lint g = gcd(p, q);
