#define all(n) begin(n), end(n)
typedef long long ll;

template <class T>
bool chmin(T &a, const T &b)
{
    if (b < a)
    {
        a = b;
        return 1;
    }
    return 0;
}

int main()
{
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    int ans = 1e9;

    vector<tuple<int, int, int>> t1(N / 2), t2(N - N / 2); //前半と後半
    for (size_t i = 0; i < N; i++)
    {
        int a, b, c;
        cin >> a >> b >> c;
        if (i < N / 2)
            t1[i] = {a, b, c};
        else
        {
            t2[i - N / 2] = {a, b, c};
        }
    }
    vector<pair<int, int>> T2; //探す値を持っておく配列 後半の配列をbit全探索して入れていく
    for (int bit = 0; bit < (1 << t2.size()); bit++)
    {
        int a = 0, b = 0, c = 0;
        for (int i = 0; i < t2.size(); i++)
        {
            auto [A, B, C] = t2[i];
            if (bit & (1 << i))
            {
                a += A;
                b += B;
                c += C;
            }
        }
        int g=gcd(a,b);
        a/=g;
        b/=g;
        T2.push_back({b * Ma - a * Mb, c});
    }
    sort(all(T2)); //普通のpair<int,int>の順序で昇順ソート
    for (int bit = 0; bit < (1 << t1.size()); bit++)
    {
        int a = 0, b = 0, c = 0;
        for (size_t i = 0; i < t1.size(); i++)
        {
            auto [A, B, C] = t1[i];
            if (bit & (1 << i))
            {
                a += A;
                b += B;
                c += C;
            }
        }
        int g=gcd(a,b);
        a/=g;
        b/=g;
        int d = a * Mb - b * Ma; //このdの値がT2に入ってるか二分探索で調べる
        ll ok = T2.size() - 1, ng = -1;
        while (abs(ok - ng) > 1)
        {
            ll mid = (ok + ng) / 2;
            if (T2[mid].first >= d)
                ok = mid;
            else
                ng = mid;
        }
        //この時点でokは 「T2[i].second >= dを満たすようなiの集合」 の最小値になっているはず(あるいはその集合は空)
        if (T2[ok].first == d and c + T2[ok].second > 0) 
        {
                chmin(ans, c + T2[ok].second);
        }
    }
    if (ans != 1e9)
        cout << ans << endl;
    else
        cout << -1 << endl;
    return 0;
}

