/*

i-1番目まで調べて、物質aがAグラム、bがBグラムのときの最低価格をp[i][A][B]と置く。
A,Bは0から400まで、iは0から41まで

p[i][A][B] = 5000と置いておけば十分。

漸化式は、
p[i][A][B] = min(p[i-1][A-a[i-1]][B-b[i-1]] + c[i-1] , p[i-1][A][B])

p[0][0][0] = 0, 残りはp[0][A][B] = 5000。

*/
int a[40], b[40], c[40];

int p[41][401][401];
int memo[41][401][401];

int min(int i, int j){
	if(i<j){return i;}else{return j;}
}

int dp(int i,int A,int B){
	int PP;
	if(memo[i][A][B] == 1){
		return p[i][A][B];
	}
	if(A<0){return 5000;}
	if(B<0){return 5000;}

	PP = min(dp(i-1,A-a[i-1],B-b[i-1]) + c[i-1] , dp(i-1,A,B));
	memo[i][A][B] = 1;
	p[i][A][B] = PP;
	return PP;
}


int main() {
	int N,Ma,Mb,i,j,k,ans;
	scanf("%d %d %d",&N,&Ma,&Mb);
	for(i=0;i<N;i++){
		scanf("%d %d %d",&a[i],&b[i],&c[i]);
	}

	for(i=0;i<41;i++){
		for(j=0;j<401;j++){
			for(k=0;k<401;k++){
				memo[i][j][k] = 0;
				p[i][j][k] = 5000;
			}
		}
	}
	for(j=0;j<401;j++){
		for(k=0;k<401;k++){
			memo[0][j][k] = 1;
		}
	}
	p[0][0][0] = 0;

	ans = 5000;
	for(i=1;(i*Ma<=400) && (i*Mb<=400); i++){
		ans = min(ans, dp(N+1,Ma*i,Mb*i));
	}

	if(ans==5000){
		printf("-1\n");
	}else{
		printf("%d\n",ans);
	}
}

