const ll MOD = 1000000007ll;

int n, ma, mb;
int a[40], b[40], c[40];

int main() {
	cin >> n >> ma >> mb;
	REP(i, n) scanf("%d %d %d", a + i, b + i, c + i);

	vector<pii> sa;
	sa.push_back(pii(0,0));
	REP(i, 1 << (n / 2)) {
		int suma = 0, sumb = 0, sumc = 0;
		REP(j, n / 2) if (i >> j & 1) {
			suma += a[j];
			sumb += b[j];
			sumc += c[j];
		}
		sa.push_back(pii(suma * mb - sumb * ma, sumc));
	}
	sort(ALL(sa));

	int ans = INF;
	REP(i, 1 << (n - n / 2)) {
		int suma = 0, sumb = 0, sumc = 0;
		REP(j, n - n / 2) if (i >> j & 1) {
			suma += a[j + n / 2];
			sumb += b[j + n / 2];
			sumc += c[j + n / 2];
		}
		int diff = sumb * ma - suma * mb;

		vector<pii>::iterator it = lower_bound(ALL(sa), pii(diff, 0));
		if (it == sa.end()) continue;
		if (it->first != diff || it->second + sumc == 0) continue;

		chmin(ans, it->second + sumc);
	}
	if (ans == INF) ans = -1;

	cout << ans << endl;
	return 0;
}

