int dp[41][401][401];

int main(void){
    int n,ma,mb;
    cin >> n >> ma >> mb;
    int a[n],b[n],c[n];
    for(int i = 0;i < n;i++)cin >> a[i] >> b[i] >> c[i];

    for(int i = 0;i <= n;i++){
        for(int j = 0;j <= 400;j++){
            for(int l = 0;l <= 400;l++){
                dp[i][j][l] = 1e9;
            }
        }
    }
    dp[0][0][0] = 0;

    for(int i = 0;i < n;i++){
        for(int j = 0;j <= 400;j++){
            if(j < a[i])continue;
            for(int l = 0;l <= 400;l++){
                if(l < b[i])continue;
                dp[i+1][j][l] = min(dp[i][j][l],dp[i][j-a[i]][l-b[i]] + c[i]);
            }
        }
    }

    int alina = 1e9;
    if(ma >= mb){
        for(int i = ma;i <= 400;i += ma){
            int j = (i / ma) * mb;
            alina = min(alina,dp[n][i][j]);
        }
    } else {
        for(int i = mb;i <= 400;i += mb){
            int j = (i / mb) * ma;
            alina = min(alina,dp[n][j][i]);
        }
    }
    if(alina == 1e9)alina = -1;

    cout << alina << endl;
}

