void solve(){
    abc = vpl3(n);
    rep(i, n) in3(abc[i].e1, abc[i].e2.e1, abc[i].e2.e2);
    // minimize
    // sum ci
    // constraint
    // mb * sum ai = ma * sum bi

    rep(i, n + 1) rep(c1, n * 10 + 1) rep(c2, n * 10 + 1) dp[i][c1][c2] = -1;

    rep(i, n + 1) dp[i][0][0] = 0;
    For(i, 1, n + 1) revrep(c1, n * 10 + 1) revrep(c2, n * 10 + 1){
        ll a, b, c;
        a = abc[i - 1].e1; b = abc[i - 1].e2.e1; c = abc[i - 1].e2.e2;
        dp[i][c1][c2] = dp[i - 1][c1][c2];

        if (c1 + a > n * 10 && c2 + b > n * 10) continue;
        ll p1 = dp[i - 1][c1][c2]; ll p2 = dp[i - 1][c1 + a][c2 + b];
        if (p1 != -1 && p2 != -1) dp[i][c1 + a][c2 + b] = min(p1 + c, p2);
        else if (p1 != -1) dp[i][c1 + a][c2 + b] = p1 + c;
        else if (p2 != -1) dp[i][c1 + a][c2 + b] = p2;
    }

    answer = INF;
    For(i, 1, n + 1) For(c1, 1, n * 10 + 1) For(c2, 1, n * 10 + 1){
        if (mb * c1 != ma * c2 || dp[i][c1][c2] == -1) continue;
        answer = min(answer, dp[i][c1][c2]);
    }

    if (answer == INF) prl(-1);
    else prl(answer);

    // check negative MOD
