int n, ma, mb;
struct info{
    int a, b, c;
    bool operator < (const info &ot){
        if(a != ot.a) return a < ot.a;
        if(b != ot.b) return b < ot.b;
        return c < ot.c;
    }
};
vector<info> va, vb;
vector<info> sa, sb;

void generateFun(){
    int tot = (1 << va.size());
    for(int i=1; i<tot; i++){
        int aa = 0, bb = 0, cc = 0;
        for(int j=0; j<va.size(); j++)
            if(i & (1<<j))
                aa += va[j].a,
                bb += va[j].b,
                cc += va[j].c;
        sa.pb({aa, bb, cc});
    }

    tot = (1 << vb.size());
    for(int i=1; i<tot; i++){
        int aa = 0, bb = 0, cc = 0;
        for(int j=0; j<vb.size(); j++)
            if(i & (1<<j))
                aa += vb[j].a,
                bb += vb[j].b,
                cc += vb[j].c;
        sb.pb({aa, bb, cc});
    }
    sort(all(sb));
}

int main(){
    sfiii(n, ma, mb);
    for(int i=0; i<n; i++){
        int a, b, c;
        sfiii(a,b,c);
        if(i&1) va.pb({a, b, c});
        else vb.pb({a, b, c});
    }
    generateFun();

    int ans = INF;

    for(int i=0; i<sa.size(); i++){
        info u = sa[i];
        for(int k=1; k<401; k++){
            int na = ma*k, nb = mb*k;
            if(na<u.a || nb<u.b) continue;
            int ra = na-u.a, rb = nb-u.b;
            int lw = 0, hh = sb.size()-1, res = -1;
            while(lw<=hh){
                int mid = (lw+hh)/2;
                if(sb[mid].a<ra) lw = mid+1;
                else if(sb[mid].a>ra) hh = mid-1;
                else{
                    if(sb[mid].b<rb) lw = mid+1;
                    else if(sb[mid].b>rb) hh = mid-1;
                    else{
                        res = mid;
                        hh = mid-1;
                    }
                }
            }
            if(res != -1) ans = min(ans, u.c+sb[res].c);
        }
    }

    if(ans == INF) ans = -1;
    pfi(ans);

    return 0;
}

