#include <bits/stdc++.h>

using namespace std;

using ll = long long;

int Solve() {
    int n, ma, mb;
    cin >> n >> ma >> mb;

    vector<int> a(n), b(n), c(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i] >> b[i] >> c[i];

    const int MAX_C = 100 * 1000, MAX_A = 500, MAX_B = 500;
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(MAX_A,
                                   vector<int>(MAX_B, MAX_C)));
    dp[0][0][0] = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < MAX_A; ++j) {
            for (int k = 0; k < MAX_B; ++k) {
                if (MAX_C <= dp[i][j][k]) continue;

                dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);
                if (j + a[i] < MAX_A && k + b[i] < MAX_B)
                    dp[i + 1][j + a[i]][k + b[i]] = min(dp[i + 1][j + a[i]][k + b[i]],
                                                        dp[i][j][k] + c[i]);
            }
        }
    }

    int res = MAX_C;
    for (int i = 1; i < MAX_A; ++i) {
        for (int j = 1; j < MAX_B; ++j) {
            if (dp[n][i][j] < MAX_C && (i * mb == j * ma))
                res = min(res, dp[n][i][j]);
        }
    }

    return (res < MAX_C ? res : -1);
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cout << Solve() << endl;

    return 0;
}

