            if ((i >> j) & 1) {
                at += a[j + bg];
                bt += b[j + bg];
                ct += c[j + bg];
            }
        }
        if (!mp.count({at, bt}) || mp[{at, bt}] > ct) {
            mp[{at, bt}] = ct;
        }
    }
}

