    rep(i,50)rep(j,500)rep(k,500) dp[i][j][k]=INF;
    dp[0][0][0]=0;
    for(int i=1;i<=n;i++){
        rep(j,500)rep(k,500){
            dp[i][j][k]=dp[i-1][j][k];
            if(j-a[i-1]>=0&&k-b[i-1]>=0){
                dp[i][j][k]=min(dp[i][j][k],dp[i-1][j-a[i-1]][k-b[i-1]]+c[i-1]);
            }
        }
    }
    int ans=INF;
    for(int j=1;j*ma<500&&j*mb<500;j++){
        ans=min(ans,dp[n][j*ma][j*mb]);
    }
    cout<<(ans!=INF?ans:-1)<<endl;
    return 0;
}

