int main() {
	ll n, ma, mb;
	cin >> n >> ma >> mb;
	REP(i, 1, n) {
		ll x, y, z;
		cin >> x >> y >> z;
		ll v = x * mb - y * ma;
		d[i] = v;
		cost[i] = z;
	}
	ll n1 = n / 2;
	ll n2 = n - n1;
	ll n1_ = (1 << n1) - 1;
	ll n2_ = (1 << n2) - 1;
	REP(i, 0, n2_) {
		b[i] = cost2[i] = 0;
		REP(j, 0, n2 - 1) {
			if (((i >> j) & 1) == 1) {
				b[i] += d[j + 1 + n1];
				cost2[i] += cost[j + 1 + n1];
			}
		}
		ll t = m2[b[i]];
		if (t == 0) {
			m2[b[i]] = cost2[i];
		}
		else {
			m2[b[i]] = min(t, cost2[i]);
		}
	}
	REP(i, 0, n1_) {
		a[i] = cost1[i] = 0;
		REP(j, 0, n1 - 1) {
			if (((i >> j) & 1) == 1) {
				a[i] += d[j + 1];
				cost1[i] += cost[j + 1];
			}
		}
		a[i] *= -1;
		ll t = m1[a[i]];
		if (t == 0) {
			m1[a[i]] = cost1[i];
		}
		else {
			m1[a[i]] = min(t, cost1[i]);
		}
	}
	sort(a, a + n1_ + 1);
	sort(b, b + n2_ + 1);
	ll ans = 10000000000;
	REP(i, 0, n1_) {
		if (a[i] == 0) {
			if (m1[0] > 0 && m2[0] > 0) {
				ans = min(ans, min(m1[0], m2[0]));
			}
			else if(m1[0]>0||m2[0]>0){
				ans = min(ans, max(m1[0], m2[0]));
			}
		}
		else if (m2[a[i]] != 0) {
			ans = min(ans, m1[a[i]] + m2[a[i]]);
		}
	}
	if (ans == 10000000000) { ans = -1; }
	cout << ans << endl;
}

