vector<ll> bit2value(const vector<vector<ll>>& obj, const int i)
{
	const int N = obj.size();
	ll a = 0;
	ll b = 0;
	ll c = 0;

	REP(j, N) if (i&(1 << j)) {
		a += obj[j][0];
		b += obj[j][1];
		c += obj[j][2];
	}
	return { a,b,c };
}

map<ll, map<ll, ll>> make_half(const vector<vector<ll>>& obj)
{
	const int N = obj.size();
	map<ll, map<ll, ll>> res;

	REP(i, 1 << N) {
		auto sum = bit2value(obj, i);
		ll a = sum[0];
		ll b = sum[1];
		ll c = sum[2];

		if (res.find(a) == res.end()) {
			//res[a] = map<ll, ll>();
			res[a][b] = c;
		}
		else {
			if (res[a].find(b) == res[a].end()) {
				res[a][b] = c;
			}
			else {
				res[a][b] = min(res[a][b], c);
			}
		}
	}
	return res;
}


ll find_pair(map<ll, map<ll, ll>>& other, const vector<ll>& sum)
{
	ll cost = INF;
	ll a = sum[0];
	ll b = sum[1];
	ll c = sum[2];
	FOR(times, 1, 400 / Ma + 1)
	{
		ll obja = Ma * times;
		ll objb = Mb * times;
		ll resta = obja - a;
		ll restb = objb - b;
		if (resta < 0)continue;
		if (restb < 0)continue;

		if (other.find(resta) == other.end())continue;
		if (other[resta].find(restb) == other[resta].end())continue;
		cost = min(cost, other[resta][restb]);
	}
	return cost + c;
}


//計算
void calc()
{
	ll cost = INF;
	int rsiz = r.size();
	auto lhalf = make_half(l);

	REP(i, 1 << rsiz)
	{
		auto sum = bit2value(r, i);
		auto bestCost = find_pair(lhalf, sum);
		cost = min(cost, bestCost);
	}

	cout << (cost == INF ? -1 : cost) << endl;
}


