auto gcd = __gcd<lint>;

lint pow(lint num, lint e, lint MOD) {
    lint res = 1;
    lint cur_num = num;
    while (e) {
        if (e & 1) {
            res *= cur_num;
            res %= MOD;
        }
        cur_num *= cur_num;
        cur_num %= MOD;
        e >>= 1;
    }
    return res;
}

unordered_map<lint, lint> min_cost(const vec<lint>& a_list, const vec<lint>& b_list, const vec<lint>& c_list, lint Ma, lint Mb) {
    lint num_items = a_list.size();
    unordered_map<lint, lint> res;
    range(i, 1LL, (1LL << num_items)) {
        lint key = 0, cost = 0;
        range(s, 0, num_items) {
            if ((i >> s) & 1) {
                key += Ma * b_list.at(s) - Mb * a_list.at(s);
                cost += c_list.at(s);
            }
        }
        if (res.find(key) == res.end()) {
            res.emplace(key, cost);
        } else {
            res.at(key) = min(res.at(key), cost);
        }
    }
    return res;
}

