#define REP(i, n) for(int i=0; i<n; i++)
const int INF = 1000000;

int A[100];
int B[100];
int C[100];

int N, Ma, Mb;

map<int, int> ma;
map<int, int> mb;

void dfs(int s, int d, int aa, int bb, int cc, bool isA){
    if(s == d){
        if(cc == 0) return;
        int sum;
        if(isA){
            sum = -aa*Mb + bb*Ma;
            if(ma.find(sum) != ma.end()){
                int ccc = ma[sum];
                cc = min(cc, ccc);
            }
            ma[sum] = cc;
        }
        else{
            sum = aa*Mb - bb*Ma;
            if(mb.find(sum) != mb.end()){
                int ccc = mb[sum];
                cc = min(cc, ccc);
            }
            mb[sum] = cc;
        }
        return;
    }
    int a = A[s];
    int b = B[s];
    int c = C[s];
    dfs(s+1, d, aa, bb, cc, isA);
    dfs(s+1, d, aa+a, bb+b, cc+c, isA);
}

int main(){
    cin >> N >> Ma >> Mb;

    REP(i,N){
        int a, b, c;
        cin >> a >> b >> c;
        A[i] = a; 
        B[i] = b; 
        C[i] = c; 
    }

    dfs(0, N/2, 0, 0, 0, true);
    dfs(N/2, N, 0, 0, 0, false);

    int ans = INF;
    if(ma.find(0) != ma.end()){
        ans = min(ans, ma[0]);
    }
    if(mb.find(0) != mb.end()){
        ans = min(ans, mb[0]);
    }

    for(auto&& a : ma){
        int r = a.first;
        int c = a.second;
        if(mb.find(r) != mb.end()){
            ans = min(ans, c+mb[r]);
        }
    }

    if(ans == INF) ans = -1;
    cout << ans << endl;
    return 0;
}

