i64 N;
i64 MA, MB;
vector<i64> A;
vector<i64> B;
vector<i64> C;

void solve() {
    RD(N);
    RD(MA); RD(MB);

    A.resize(N);
    B.resize(N);
    C.resize(N);
    REP(i, N) {
        RD(A[i]);
        RD(B[i]);
        RD(C[i]);
    }

    static i64 dp[41][401][401];
    ARRAY_FILL(dp, INF);
    dp[0][0][0] = 0;

    FOR(i, 1, N+1) {
        i64 a = A[i-1];
        i64 b = B[i-1];
        i64 c = C[i-1];
        REP(j, 401) REP(k, 401) {
            i64 v = dp[i-1][j][k];
            if(j >= a && k >= b) {
                chmin(v, c + dp[i-1][j-a][k-b]);
            }
            dp[i][j][k] = v;
        }
    }

    i64 ans = INF;
    FOR(j, 1, 401) FOR(k, 1, 401) {
        if(j*MB == k*MA) {
            chmin(ans, dp[N][j][k]);
        }
    }

    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans == INF ? -1 : ans);
}

