long long INF = 1e18;
const int MOD = 1e9 + 7;

using namespace std;

#define MAX_N 40
pair<int,int> ps[1<<(MAX_N/2)];
int c[MAX_N],A[MAX_N];

int inline bs(int begin, int end, int x){
    int left=begin,right=end-1,mid;
    if(x<ps[left].first || x>ps[right].first) return -1;
    while(left<=right){
        mid = (left+right)/2;
        if(x<ps[mid].first) right = mid-1;
        else left = mid+1;
    }
    if(x==ps[right].first) return right;
    else return -1;
}

int main(){
    int ans=MOD,n,ma,mb;

    scanf("%d %d %d",&n,&ma,&mb);
    REP(i,n){
        int a,b;
        scanf("%d %d %d",&a,&b,&c+i);
        A[i] = ma*b - mb*a;
    }

    int n2 = n / 2;
    REP(i,1<<n2){
        int s=0,v=0;
        REP(j,n2){
            if(i>>j&1){
                s += A[i];
                v += c[i];
            }
        }
        ps[i] = make_pair(s,v);
    }

    ps[0] = ps[1];
    sort(ps,ps+(1<<n2));
    int m=1;
    FOR(i,1,1<<n2) if(ps[m-1].first != ps[i].first) ps[m++] = ps[i];

    REP(i,1<<(n-n2)){
        int s=0,v=0;
        REP(j,n-n2){
            if(i>>j&1){
                s += A[n2+j];
                v += c[n2+j];
            }
        }
        if(s!=0||v==0){
            if(bs(0,m,-s)!=-1) ans = min(ans,v+ps[bs(0,m,-s)].second);
        }else ans = min(ans,v);
    }

    if(ans!=MOD&&ans!=0) printf("%d\n",ans);
    else printf("-1\n");
    return 0;
}

