constexpr int MaxN = 40, MaxAmount = 10;
int n;
int A[MaxN], B[MaxN], C[MaxN];
int ma, mb;
int save[MaxN][MaxN * MaxAmount][MaxN * MaxAmount];

int Solve(int no, int a, int b) {
    if (save[no][a][b] != INF) {
        return save[no][a][b];
    } else if (no == n) {
        return INF;
    }

    int ans;
    if (a * b != 0 && a * mb == b * ma) {
        ans = 0;
    } else {
        ans = min(Solve(no + 1, a, b), Solve(no + 1, a + A[no], b + B[no]) + C[no]);
    }

    return save[no][a][b] = ans;
}

