#include <bits/stdc++.h>
#define inf 1000000000 //1E+9
using namespace std;	
typedef pair<pair<int,int>,int> PP;

bool operator<(PP &a, PP &b){return a.second<b.second;}
bool operator<(PP &a, int b){return a.second<b;}

int main(){
	int n,ma,mb;cin>>n>>ma>>mb;
	int a[n],b[n],c[n];	for(int i=0;i<n;i++)cin>>a[i]>>b[i]>>c[i];
	vector<PP> g1, g2; //group1(n=1,2,..,n/2); group2(n= n-(n/2)+1,...,n)
	PP p;
	int M=n/2;
	//making two available groups
	for(int i=1; i<pow(2,M); i++){
		p.first.first=0; p.first.second=0; p.second=0;
		for(int j=0; j<M; j++){
			if(i & (1<<j)){
				p.first.first+=a[j];	p.first.second+=b[j];	p.second+=c[j];
			}
		}
		g1.push_back(p);
	}
	for(int i=1; i<pow(2,n-M); i++){
		p.first.first=0; p.first.second=0; p.second=0;
		for(int j=0; j<n-M; j++){
			if(i & (1<<j)){
				p.first.first+=a[M+j];	p.first.second+=b[M+j];	p.second+=c[M+j];
			}
		}
		g2.push_back(p);
	}

	//genocide
	vector<PP> g_e;
	for(int i=0; i<g1.size(); i++){
		if(ma*g1[i].first.second == mb*g1[i].first.first)	g_e.push_back(g1[i]);
	}
	for(int i=0; i<g2.size(); i++){
		if(ma*g2[i].first.second == mb*g2[i].first.first)	g_e.push_back(g2[i]);
	}
	sort(g_e.begin(), g_e.end());	sort(g1.begin(), g1.end());	sort(g2.begin(), g2.end());
	int border = inf;
	if(g_e.size()){
		border=g_e[0].second;
		while(g1.size()){if(g1[g1.size()-1].second>border) g1.pop_back(); else break;}
		while(g2.size()){if(g2[g2.size()-1].second>border) g2.pop_back(); else break;}
	}

	//detail
	vector<PP> g1_a, g1_b, g2_a, g2_b;
	for(int i=0;i<g1.size();i++){
		if(ma*g1[i].first.second > mb*g1[i].first.first)g1_a.push_back(g1[i]);
		if(ma*g1[i].first.second < mb*g1[i].first.first)g1_b.push_back(g1[i]);
	}
	for(int i=0;i<g2.size();i++){
		if(ma*g2[i].first.second > mb*g2[i].first.first)g2_a.push_back(g2[i]);
		if(ma*g2[i].first.second < mb*g2[i].first.first)g2_b.push_back(g2[i]);
	}

	//last check
	int d, e, f;
	for(int i=0; i<g1_a.size(); i++){
	for(int j=0; j<g2_b.size(); j++){
		e = g1_a[i].first.first + g2_b[j].first.first;
		f = g1_a[i].first.second + g2_b[j].first.second;
		d = g1_a[i].second + g2_b[j].second;
		if(d>border) break;
		if(ma*f==mb*e)	border=min(border, d);
	}}
	for(int i=0; i<g1_b.size(); i++){
	for(int j=0; j<g2_a.size(); j++){
		e = g1_b[i].first.first + g2_a[j].first.first;
		f = g1_b[i].first.second + g2_a[j].first.second;
		d = g1_b[i].second + g2_a[j].second;
		if(d>border) break;
		if(ma*f==mb*e)	border=min(border, d);
	}}

	if(border==inf) cout<<-1<<endl;
	else cout<<border<<endl;

	return 0;
}

