		h=0; d=0; g=0;
		for(int j=n-1; j>=0; j--){
			if(k>=pow(2,j)){
				h+=a[j];
				d+=b[j];
				g+=c[j];
			}
		}
		e=h/ma; f=d/mb;
		if(e==f){
			if(cost>g && g!=0)  cost=g;
		}
	}

	if(cost==500000) cout << "-1" << endl;
	else cout << cost << endl;

	return 0;
}

