bool comp(P x, P y){
	return ((x.first == y.first)?(x.second < y.second):(x.first < y.first));
}

vector<P> v,u;

int find(ll x){
	int l = 0,r = u.l_ength(),m;
	while(r - l > 1){
		m = (l+r)/2;
		if(u[m].first < x){
			l = m;
		}else{
			r = m;
		}
	}
	return ((u[l].first < x)?r:l);
}

