#include<bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<ll,ll>;
const ll inf = numeric_limits<ll>::max()/3;

ll ma,mb;

struct item {
  ll a;ll b;ll c;
  bool operator< (const item &right) const{
    ll calcl = ma * b - mb * a;
    ll calcr = ma * right.b -  mb * right.a;
    if(calcl != calcr)
      return  calcl <  calcr;
    else
      return c < right.c;
  }
};

int main(void){
  int n;
  cin >> n >> ma >> mb;
  vector< item > items;
  for(int i = 0;i < n;++i){
    ll a,b,c;
    cin >> a >> b >> c;
    items.push_back((item){a,b,c});
  }
  ll res = inf;
  vector< item > half1;
  vector< item > half2;
  int h = n/2;
  for(int i = 1;i < (1 << h);++i){
    ll calcA = 0,calcB = 0,calcC = 0;
    for(int j = 0;j < h;++j){
      if(i & (1 << j)){
        calcA += items[j].a;
        calcB += items[j].b;
        calcC += items[j].c;
      }
    }
    if(calcA != 0 && calcB != 0 &&
       calcA * mb == calcB * ma){
      res = min(res, calcC);
    }
    half1.push_back((item){calcA,calcB,calcC});
  }

  for(int i = 1;i < (1 << (n-h));++i){
    ll calcA = 0,calcB = 0,calcC = 0;
    for(int j = h;j < n;++j){
      if(i & (1 << (j-h))){
        calcA += items[j].a;
        calcB += items[j].b;
        calcC += items[j].c;
      }
    }
    if(calcA != 0 && calcB != 0 &&
       calcA * mb == calcB * ma){
      res = min(res, calcC);
    }
    half2.push_back((item){calcA,calcB,calcC});
  }

  sort(half2.begin(),half2.end());
  vector< item > cand;
  for(item it : half2){
    if(!cand.empty()){
      item last = cand.back();
      ll calc1 = ma * last.b - mb * last.a;
      ll calc2 = ma * it.b - mb * it.a;
      if(calc1 == calc2)
        continue;
    }
    cand.push_back(it);
  }

  for(item it : half1){
    int l = 0,r = cand.size();
    ll target = -ma * it.b + mb * it.a;
    while(r - l > 1){
      int mid = (l+r)/2;
      ll calc = ma * cand[mid].b - mb * cand[mid].a;
      if(calc <= target){
        l = mid;
      }else{
        r = mid;
      }
    }
    ll calcA = it.a + cand[l].a;
    ll calcB = it.b + cand[l].b;
    if(calcA != 0 && calcB != 0 &&
       calcA * mb == calcB * ma){
      res = min(res,it.c + cand[l].c);
    }
  }
  if(res == inf){
    cout << "-1" << endl;
  }else{
    cout << res << endl;
  }
  return 0;
}

