#define INF 2147483600
#define fi first
#define se second

ll ans=0,ll ansc=0;
//あとiだけ入る.今のスコア. どこまで見たか
ll solve(int i, int j, int k, vector<pl> a){
	if(i==0){
		return j;
	}else if(i<0||k>=a.size()){
		return INF;
	}else if(ans<j){
		return INF;
	}else{
		ans = min(ans,min(solve(i,j,k+1,a),solve(i-a[k].fi,j+a[k].se,k+1,a)));
		return ans;
	}
}

int main(){
	ll n, ma, mb, temp1, temp2, temp3;
	cin>>n>>ma>>mb;
	//ans=0,INFになるならエラー
	vector<pl> a,b;
