// dp[i][j][k]: i個目までの薬品を使い、Aがjグラム、Bがkグラムの時の最小予算
int dp[41][401][401];
int a[41], b[41], c[41];

int main() {
	int N, Ma, Mb;
	cin >> N >> Ma >> Mb;

	int total_a = 0;
	int total_b = 0;
	for (int i=1; i<=N; i++) {
		cin >> a[i] >> b[i] >> c[i];
		total_a += a[i];
		total_b += b[i];
	}

	// INFで初期化
	for (int i=0; i<=N; i++) {
		for (int j=0; j<=total_a; j++) {
			for (int k=0; k<total_b; k++) {
				dp[i][j][k] = INF;
			}
		}
	}

	dp[0][0][0] = 0;

	for (int i=1; i<=N; i++) {
		for (int j=0; j<=total_a; j++) {
			for (int k=0; k<total_b; k++) {
				// i個目を使う場合
				int prev_j = j - a[i];
				int prev_k = k - b[i];
				if (prev_j < 0 || prev_k < 0) continue;
				if (dp[i-1][prev_j][prev_k] != INF) {
					dp[i][j][k] = min(dp[i][j][k], dp[i-1][prev_j][prev_k] + c[i]);
				}

				// i個目を使わない場合
				dp[i][j][k] = min(dp[i][j][k], dp[i-1][j][k]);
			}
		}
	}

	int min_cost = INF;
	for (int i=1; i<=N; i++) {
		for (int j=1; j<=total_a; j++) {
			for (int k=1; k<total_b; k++) {
				if (j * Mb == k * Ma) {
					min_cost = min(dp[i][j][k], min_cost);
				}
			}
		}
	}

	if (min_cost == INF) min_cost = -1;

	cout << min_cost << endl;

	return 0;
}

