    vector<int> ans;

    rep(i, n) {
        pair<int, int> p = make_pair(a[i], b[i]);

        for (auto iter = dp[i].begin(); iter != dp[i].end(); iter++) {
            pair<int, int> temp = iter->first;
            if (dp[i + 1][temp] == 0) {
                dp[i + 1][temp] = dp[i][temp];
            } else {
                dp[i + 1][temp] = min(dp[i][temp], dp[i + 1][temp]);
            }

            pair<int, int> new_pair =
                make_pair(temp.first + p.first, temp.second + p.second);

            if (dp[i + 1][new_pair] == 0) {
                dp[i + 1][new_pair] = dp[i][temp] + c[i];
            } else {
                dp[i + 1][new_pair] =
                    min(dp[i + 1][new_pair], dp[i][temp] + c[i]);
            }
        }
    }

    for (auto iter = dp[n].begin(); iter != dp[n].end(); iter++) {
        int a_weight = iter->first.first;
        int b_weight = iter->first.second;

        if (a_weight % ma == 0 && b_weight % mb == 0 &&
            a_weight / ma == b_weight / mb && a_weight != 0) {
            ans.push_back(iter->second);
        }
    }

    int result = pow(10, 9);
    rep(i, ans.size()) { result = min(result, ans[i]); }

    if (result == pow(10, 9)) {
        result = -1;
    }
    cout << result << endl;
    return 0;
}

