ll gcd(ll x, ll y) {
  if(x > y)
    return gcd(y, x);
  else if(x == 0)
    return y;
  else
    return gcd(y % x, x);
}
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n, ma, mb; cin >> n >> ma >> mb;
  vector<int> A(n), B(n), C(n);
  rep(i, n) cin >> A[i] >> B[i]>> C[i];
  int n1 = n/2, n2 = n-n1;
  vector<map<pair<ll, ll>, ll>> dp1(n1+1), dp2(n2+1);
  dp1[0][{0, 0}] = 0;
  dp2[0][{0, 0}] = 0;
  rep(i, n1) {
    for(auto ele: dp1[i]) {
      if(!dp1[i+1].count(ele.first)) dp1[i+1][ele.first] = longinf;
      dp1[i+1][ele.first] = min(ele.second, dp1[i+1][ele.first]);
      pair<ll, ll> nx = {ele.first.first+A[i], ele.first.second+B[i]};
      if(!dp1[i+1].count(nx)) dp1[i+1][nx] = longinf;
      dp1[i+1][nx] = min(ele.second+C[i], dp1[i+1][nx]);
    }
  }
  rep(i, n2) {
    for(auto ele: dp2[i]) {
      if(!dp2[i+1].count(ele.first)) dp2[i+1][ele.first] = longinf;
      dp2[i+1][ele.first] = min(ele.second, dp2[i+1][ele.first]);
      pair<ll, ll> nx = {ele.first.first+A[n1+i], ele.first.second+B[n1+i]};
      if(!dp2[i+1].count(nx)) dp2[i+1][nx] = longinf;
      dp2[i+1][nx] = min(ele.second+C[n1+i], dp2[i+1][nx]);
    }
  }
  for(auto ele: dp2[n2]) {
    ll g = gcd(ele.first.first, ele.first.second);
    if(g == 0) continue;
    pair<ll, ll> nx = {ele.first.first/g, ele.first.second/g};
    if(!dp2[n2].count({nx})) dp2[n2][nx] = longinf;
    dp2[n2][nx] = min(ele.second, dp2[n2][nx]);
  }
  ll ans = longinf;
  for(auto ele: dp1[n1]) {
    ll a = ele.first.first, b = ele.first.second;
    ll k = max((a+ma)/ma, (b+mb)/mb);
    ll x = ma*k-a, y = mb*k-b;
    if(!dp2[n2].count({x, y})) continue;
    ans = min(ele.second+dp2[n2][{x, y}], ans);
  }
  cout << (ans==longinf ? -1 : ans) << endk;
  return 0;
}

