        }
        memo[sum_d] = min(memo[sum_d], sum_c);
    }

    int res = INF;
    int L = N - m;
    REP(i, 1<<L){
        if(i==0)continue;
        int sum_d = 0;
        int sum_c = 0;
        REP(j, L){
            if((i>>j)&1){
                int k = m + j;
                sum_d += D[k];
                sum_c += c[k];
            }
        }
        if(memo.count(sum_d) == 0){
