            if(itr == back.end())continue;
            if(*itr != cur)continue;

            ans = min(ans, costfront[i.first][i.second] + costback[cur.first][cur.second]);
        }
    }

    cout << (ans == 1000000000 ? -1 : ans) << endl;
}

