// modint

template <std::uint_fast64_t Modulus> class modint {
  using u64 = std::uint_fast64_t;

public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};

map<pair<ll,ll>,ll> M;
vector<pair<pair<ll,ll>,ll>> V1,V2;
vector<pair<pair<ll,ll>,ll>> V;

void make1(vector<pair<pair<ll,ll>,ll>> &X){
  ll N=X.size();
  rep (bit,1<<N) {  // 0~2^N-1 までのbit 全探索
    ll a=0,b=0,c=0;
    rep (i, N){
      if (bit & (1<<i)) { // i が bit に入るかどうか
        a+=X[i].fr.fr;b+=X[i].fr.sc;c+=X[i].sc;
      }
    }
    //cout << a << " " << b << " " << c << endl;
    V.pb(mp(mp(a,b),c));
  }
}

void make2(vector<pair<pair<ll,ll>,ll>> &X){
  ll N=X.size();
  rep (bit,1<<N) {  // 0~2^N-1 までのbit 全探索
    ll a=0,b=0,c=0;
    rep (i, N){
      if (bit & (1<<i)) { // i が bit に入るかどうか
        a+=X[i].fr.fr;b+=X[i].fr.sc;c+=X[i].sc;
      }
    }
    if(M[mp(a,b)]==0){
      M[mp(a,b)]=c;
    }
    else{
      M[mp(a,b)]=min(c,M[mp(a,b)]);
    }
  }
}

