lli n, ma, mb;
lli a[41];
lli b[41];
lli c[41];
lli rec(lli use_cnt, lli cur_cnt, lli i, lli a_now, lli b_now, lli c_now) {
    if (use_cnt == cur_cnt) {
        if (a_now*mb == b_now*ma)
            return c_now;
        else
            return LLONG_MAX;
    }
    else if (use_cnt > cur_cnt + n - (i+1))
        return LLONG_MAX;

