    // i を使う
    ans = min(ans, rec(use_cnt, cur_cnt+1, i+1, a_now+a[i], b_now+b[i], c_now+c[i]));
    // i を使わない
    ans = min(ans, rec(use_cnt, cur_cnt, i+1, a_now, b_now, c_now));

    return ans;
}

