int go(int idx , int a , int b){
    if(b != 0){
        if(a / b == A / B)
            return 0;
    }
    if(idx > n)
        return 1e5;
    if(dp[idx][a][b] != -1)
        return dp[idx][a][b];
    int best = go(idx + 1 , a , b);
    best = cost[idx] + go(idx + 1 , a + AA[idx] , b + BB[idx]);
    return dp[idx][a][b] = best;
}

