  REP(i, 0, n) cin >> a[i] >> b[i] >> c[i];
  REPC(i, 0, nmax) {
    REPC(j, 0, abmax * nmax + 1) {
      REP(k, 0, nmax * abmax + 1) dp[i][j][k] = inf;
    }
  }
  dp[0][0][0] = 0;
  REPC(i, 0, n - 1) {
    REPC(j, 0, n * abmax + 1) {
      REP(k, 0, n * abmax + 1) {
        dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);
