const int INF = 2000000000;
using namespace std;

//i番目のビットを返す
bool getBit(int num, int i){
    return ((num & (1 << i)) != 0);
}

//i番目を1にする
int setBit(int num, int i){
    return num | (1 << i);
}

//i番目を0にする
int clearBit(int num, int i){
    int mask = ~(1 << i);
    return num & mask;
}

//i番目をvで置き換える
int updateBit(int num, int i, int v){
    int mask = ~(1 << i);
    return (num & mask) | (v << i);
}

const int MAX_N = 50;

int main(){
    int n, ma, mb;
    cin >> n >> ma >> mb;

    int a[MAX_N], b[MAX_N], c[MAX_N];
    rep(i,n) cin >> a[i] >> b[i] >> c[i];

    int m = n / 2;
    n-=m;

    //要素wをnとmに分け、それぞれで全列挙する
    map<pair<int, int>, int> x, y;
    rep(i,(1 << n)){
        pair<int, int> p = make_pair(0,0);
        int sum = 0;
        rep(j,n){
            if(getBit(i,j)){
                p.first += a[j];
                p.second += b[j];
                sum += c[j];
            }
        }
        x[p] = sum;
    }
    rep(i,(1 << m)){
        pair<int, int> p = make_pair(0,0);
        int sum = 0;
        rep(j,m){
            if(getBit(i,j)){
                p.first += a[n + j];
                p.second += b[n + j];
                sum += c[n + j];
            }
        }
        y[p] = sum;
    }

    int ans = INF;
    for(auto it:y){
        range(j,1,401){
            pair<int, int> p = make_pair(ma * j - it.first.first, mb * j - it.first.second);
            if(x.count(p)){
                ans = min(ans, x[p] + it.second);
            }
        }
    }
    cout << ((ans == INF) ?  -1 : ans ) << endl;
}

