template<typename T, typename F>
enable_if_t<rank<T>::value==0> ARRAY_FOREACH(T& e, F f)
{
    f(e);
}

template<typename Array, typename F>
enable_if_t<rank<Array>::value!=0> ARRAY_FOREACH(Array& ary, F f)
{
    for(auto& e : ary)
        ARRAY_FOREACH(e, f);
}

template<typename Array, typename U>
enable_if_t<rank<Array>::value!=0> ARRAY_FILL(Array& ary, const U& v)
{
    ARRAY_FOREACH(ary, [&v](auto& elem) { elem = v; });
}

int N;
int MA;
int MB;

int dp[2][401][401];

void solve()
{
    ARRAY_FILL(dp, INF);

    int cur = 0;
    int nex = 1;
    dp[cur][0][0] = 0;

    REP(_, N) {
        int a, b, c; RD(a); RD(b); RD(c);
        REP(i, 401) REP(j, 401) {
            if(dp[cur][i][j] == INF) continue;
            dp[nex][i  ][j  ] = dp[cur][i][j];
            dp[nex][i+a][j+b] = min(dp[cur][i+a][j+b], dp[cur][i][j] + c);
        }
        swap(cur, nex);
    }

    int ans = INF;
    for(int a=MA, b=MB; a<=400 && b<=400; a+=MA, b+=MB) {
        chmin(ans, dp[cur][a][b]);
    }

    if(ans == INF)
        ans = -1;
    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    RD(MA);
    RD(MB);

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

