using namespace std;


#define rep(i, a, b, k) for(__typeof(a) i = a;i < b;i += k)


#define endl '\n'


template<class T=int> inline T gcd(T x, T y) { if (!y) return x; return gcd(y, x%y); }


class Solution {
public:
    int ans = 5000;
    int a[41], b[41], c[41], n, ma, mb;

    void recur(int x, int asum, int bsum, int cost) {
        int g = gcd(asum, bsum);
        if (asum / g == ma and bsum / g == mb) ans = min(ans, cost);
        if (x == n) return;
        recur(x+1, asum+a[x+1], bsum+b[x+1], cost+c[x+1]);
        recur(x+1, asum, bsum, cost);
    }

    void solve(std::istream& in, std::ostream& out) {
        in >> n >> ma >> mb;
        rep(i, 1, n+1, 1) {
            in >> a[i] >> b[i] >> c[i];
        }
        recur(0, 0, 0, 0);
        if (ans == 5000) ans = -1;
        out << ans << endl;
    }
};

void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}


