    REP(i,N) {
        cin >> a[i] >> b[i] >> c[i];
        int g = gcd(a[i],b[i]);
        ar[a[i]/g][b[i]/g].insert(pp(p(c[i],g),p(a[i],b[i])));
    }

    // i,jの組み合わせを求める
    FOR(i,1,11)FOR(j,1,11){
        // if (gcd(i,j)!=1) continue;
        // printf("%d %d\n", i, j);
