                    int g1 = x.first.second;
                    int a2 = y.second.first;
                    int b2 = y.second.second;
                    int c2 = y.first.first;
                    int g2 = y.first.second;
                    int nc = c1 * g2 + c2 * g1;
                    int na = a1 * g2 + a2 * g1;
