ll gcd(ll a,ll b) {
  if (b == 0) 
    return a;

  return gcd(b,a % b);
}

int main(){
  cin >> n >> ma >> mb;

  a.resize(n);b.resize(n);c.resize(n);

  rep(i,n)cin >> a[i] >> b[i] >> c[i];

