struct seg{
    lint n=1;
    vec node;
    seg(lint size){
        while(n<size)n*=2;
        node.resize(2*n-1,0);
    }
    lint get(lint a,lint b,lint l=0,lint r=-1,lint k=0){
        if(r<0)r=n;
        if(r<=a||b<=l)return 0;
        if(a<=l&&r<=b)return node[k];
        return get(a,b,l,(l+r)/2,2*k+1)+get(a,b,(l+r)/2,r,2*k+2); 
    }
    void add(lint k,lint val){
        k+=n-1;
        node[k]+=val;
        while(k){
            k=(k-1)/2;
            node[k]+=val;
        }
    }
};
