using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

const int INF = 1000000000;
const int N_MAX = 40;
const int S_MAX = 1 << (N_MAX / 2);

typedef pair<int, int> P;

int N, Ma, Mb;
int a[N_MAX];
int b[N_MAX];
int c[N_MAX];

P ps[S_MAX];

void solve() {
  int n1 = N / 2;
  int S = 1 << n1;
  REP(i, S) {
    int at = 0, bt = 0, ct = 0;
    REP(j, n1) if (i >> j & 1) {
      at += a[j];
      bt += b[j];
      ct += c[j];
    }
    ps[i] = P(bt * Ma - at * Mb, ct);
  }
  sort(ps, ps + S);

  int ans = INF;
  int m = 1;
  // printf("ps[%d]: %d, %d\n", 0, ps[0].first, ps[0].second);
  FOR(i, 1, S - 1) {
    if (ps[i].first > ps[m - 1].first) {
      // printf("ps[%d]: %d, %d\n", m, ps[i].first, ps[i].second);
      ps[m++] = ps[i];
    } else if (ps[i].first == 0) {
      ans = min(ans, ps[i].second);
    }
  }

  int n2 = N - n1;
  REP(i, 1 << n2) {
    int at = 0, bt = 0, ct = 0;
    REP(j, n2) if (i >> j & 1) {
      at += a[n1 + j];
      bt += b[n1 + j];
      ct += c[n1 + j];
    }
    P p2 = P(at * Mb - bt * Ma, 0);
    P *p1 = lower_bound(ps, ps + m, p2);
    // printf("p2[%d]: %d, %d\n", i, p2.first, ct);
    // printf("p1[%d]: %d, %d\n", (int) (p1 - ps), p1->first, p1->second);
    if (p1 == ps + m || p1->first != p2.first) continue;
    if (p1->second + ct == 0) continue;
    ans = min(ans, p1->second + ct);
  }
  if (ans == INF) {
    puts("-1");
    return;
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d%d", &N, &Ma, &Mb);
  REP(i, N) scanf("%d%d%d", a + i, b + i, c + i);
}

int main() {
  input();
  solve();
  return 0;
}

