void f(int g, int a, int b, int n) {
    if(g >= ming) {
        return;
    }
    if(n == N) {
        if(Mb * (a + A[N - 1]) == Ma * (b + B[N - 1]) && g + C[N - 1] < ming) {
                ming = g + C[N - 1];
                return;
        }
    }
    else if(Mb * (a + A[n - 1]) == Ma * (b + B[n - 1]) && g + C[n - 1] < ming) {
            ming = g + C[n - 1];
            return;

    } else {
        f(g, a, b, n + 1);
        f(g + C[n - 1], a + A[n - 1], b + B[n - 1], n + 1);
    }
}

