	if(A<0){return 5000;}
	if(B<0){return 5000;}
	if(memo[i][A][B] == 1){
		return p[i][A][B];
	}
	PP = min(dp(i-1,A-a[i-1],B-b[i-1]) + c[i-1] , dp(i-1,A,B));
	memo[i][A][B] = 1;
	p[i][A][B] = PP;
	return PP;
}


