    cin >> a[i] >> b[i] >> c[i];
  }

  vector<Data> datas1;
  for(int i = 0; i < (1 << (N/2)); i++){
    Data d = Data();
    for(int j = 0; j < N/2; j++){
      if(((i>>j) & 1) == 1){
        d._a += a[j];d._b += b[j];d._c += c[j];
      }
    }
    datas1.push_back(d);
  }
  vector<Data> datas2;
  for(int i = 0; i < 1 << (N-(N/2)); i++){
    Data d = Data();
    for(int j = N-(N/2), l = 0; j <= N; j++,++l){
      if(((i>>l) & 1) == 1){
        d._a += a[j-1];d._b += b[j-1];d._c += c[j-1];
      }
    }
    datas2.push_back(d);
  }
  sort(datas2.begin(), datas2.end());
  int ans = 1000000000;
  for(int i = 0; i < datas1.size(); i++){
    Data d = datas1[i];
    int t1 = d._b * A;
    int t2 = B;
    //割り切れない時点で存在しない
    if(t1 % t2 != 0)continue;
    int want = t1/t2;
    if(want == 0)continue;
    //binary_search
    int l = 0;
    int r = datas2.size();
    while(l <= r){
      int mid = (l+r)/2;
      if(datas2[mid]._a == want){
        ans = min(ans, d._c + datas2[mid]._c);
        break;
      }else if(datas2[mid]._a < want){
        l = mid + 1;
      }else{
        r = mid - 1;
      }
    }
  }
  cout << ((ans==1000000000)?-1:ans) << endl;
  return 0;
}

