const int INF = (int)1e9, MAXN = 40, MAXAB = 10;
VI A, B, C;
int n, ma, mb;

bool chk(int d, int e) {
	if(d == 0 && e == 0) return false;
	int div = __gcd(d, e);
	return d / div == ma && e / div == mb;
}

int DP[MAXN + 1][MAXN * MAXAB + 1][MAXN * MAXAB + 1];
int minPrice(int i, int a, int b)
{
	if(i == n)
		return chk(a, b) ? 0 : INF;

	int& ret = DP[i][a][b];
	if(ret != -1)
		return ret;

	ret = INF;
	ret = min(minPrice(i + 1, a + A[i], b + B[i]) + C[i],
	 minPrice(i + 1, a, b));
	return ret;
}

int bottomUp()
{
	const int COMB = MAXN * MAXAB;
	for(int i = 0; i <= MAXN; ++i)
		for(int j = 0; j <= COMB; ++j)
			for(int k = 0; k <= COMB; ++k)
				DP[i][j][k] = INF;

	DP[0][0][0] = 0;
	for(int i = 0; i < n; ++i)
		for(int j = 0; j <= COMB; ++j)
			for(int k = 0; k <= COMB; ++k) {
				if(DP[i][j][k] == INF) continue;
				DP[i + 1][j][k] = min(DP[i + 1][j][k], DP[i][j][k]);
				DP[i + 1][j + A[i]][k + B[i]] = 
				min(DP[i + 1][j + A[i]][k + B[i]], DP[i][j][k] + C[i]);
			}
	int ans = INF;
	for(int i = 1; i <= COMB; ++i)
		for(int j = 1; j <= COMB; ++j)
			if(chk(i, j))
				ans = min(ans, DP[n][i][j]);
	return ans == INF ? -1 : ans;
}

