int memo[50][410][410];

int rec(int i, int ra, int rb) {
  if (memo[i][ra][rb] != -1) {
    return memo[i][ra][rb];
  }
  if (i == n) {
    return 10000;
  }
  if (ra != 0 && rb != 0 && ra * mb == rb * ma) {
    return 0;
  }
  return memo[i][ra][rb] = min(
    rec(i + 1, ra, rb),
    rec(i + 1, ra + a[i], rb + b[i]) + c[i]
  );
}

