int n, ma, mb;
vi A, B, C;

int memo[50][50];

int rec(int i, int a, int b, int c) {
    if (i==n) return INF;
    if (memo[a][b] != INF) return memo[a][b];
    else if (ma*(b+B[i])==mb*(a+A[i])) return memo[a+A[i]][b+B[i]] = c+C[i];
    else {
        return min(memo[a][b] = rec(i+1, a, b, c), memo[a+A[i]][b+B[i]] = rec(i+1, a+A[i], b+B[i], c+C[i]));
    }
    return INF;
}

