{
    rep(j, 50)
        rep(k, 50) memo[j][k] = INF;

    cin >> n >> ma >> mb;
    rep(i, n) {
        int a, b, c;
        cin >> a >> b >> c;
        A.push_back(a);
        B.push_back(b);
        C.push_back(c);
    }

    int res = rec(0, 0, 0, 0);
    int min_cost = INF;
    rep(i, 50)
        rep(j, 50) {
            if (memo[i][j] != 0)
                min_cost = min(min_cost, memo[i][j]);
        }


    if (res != INF && min_cost != INF) P (min_cost);
    else P(-1);

    return 0;
}

