ll bitcount(ll n) {
	ll cnt = 0;
	while (n > 0) {
		if (n & 1)cnt++;
		n = n >> 1;
	}
	return cnt;
}

int main()
{
	ll n, ma, mb; cin >> n >> ma >> mb;

	vector<ll> a, b, c;
	rep(i, 0, n) {
		ll A, B, C; cin >> A >> B >> C;
		a.push_back(A);
		b.push_back(B);
		c.push_back(C);
	}

	vector<pair<ll, pair<ll, ll>>> pre;
	rep(i, 0, 1 << n / 2) {
		ll a_sum = 0, b_sum = 0, c_sum = 0;
		rep(j, 0, n / 2) {
			if (i >> j & 1) {
				a_sum += a[j];
				b_sum += b[j];
				c_sum += c[j];
			}
		}
		pre.push_back(make_pair(c_sum, make_pair(a_sum, b_sum)));
	}

	map<pair<ll, ll>, ll> post;
	rep(i, 0, 1 << (n - n / 2)) {
		ll a_sum = 0, b_sum = 0, c_sum = 0;
		rep(j, 0, (n - n / 2)) {
			if (i >> j & 1) {
				a_sum += a[n / 2 + j];
				b_sum += b[n / 2 + j];
				c_sum += c[n / 2 + j];
			}
		}
		if (a_sum != 0 && b_sum != 0) {
			post[make_pair(a_sum, b_sum)] = c_sum;
		}
	}

	ll minV = 1e16;
	rep(i, 0, 1 << n / 2) {
		rep(m, 1, 15) {
			pair<ll, ll> key = make_pair(m*ma - pre[i].second.first, m*mb - pre[i].second.second);
			if (post.count(key) != 0) {
				minV = min(minV, post[key] + pre[i].first);
			}
		}
	}

	cout << ((minV == 1e16) ? -1 : minV) << endl;

	return 0;
}

