int solve(){
    int m=drugsA.size();
    vector<drug> dCA;
    int ans=INT_INF;
    for (int bit = 0; bit < (1<<m); bit++)
    {
        drug d;
        for (int j = 0; j < m; j++)
        {
            if((bit>>j)&1){
               d += drugsA[j];
            }
        }
        dCA.push_back(d);
    }


    m=drugsB.size();
    vector<drug> dCB;
    for (int bit = 0; bit < (1<<m); bit++)
    {
        drug d;
        for (int j = 0; j < m; j++)
        {
            if((bit>>j)&1){
               d += drugsB[j];
            }
        }
        dCB.push_back(d);
    }
    unordered_map<int, unordered_map<int,int> > memo;
    for(auto db:dCB){
        if(memo[db.a][db.b]==0) memo[db.a][db.b] = db.c;
        else memo[db.a][db.b] = min(memo[db.a][db.b],db.c);
    }

    for(auto d:dCA) {
        if(d.c==0) continue;
        if(Ma*d.b==Mb*d.a) ans = min(ans,d.c);
        else{
            for (int k = 1; k <= 10; k++)
