                if(x<0 || y<0) continue;
                if(memo[x][y]==0) continue;
                else ans = min(ans,d.c+memo[x][y]);
            }
        }
    }

    for(auto d:dCB) {
        if(d.c==0) continue;
        if(Ma*d.b==Mb*d.a) ans = min(ans,d.c);
    }

    if(ans==INT_INF) ans=-1;
    cout << ans << endl;
    return 0;
}   

