bool next_choice(std::vector<Drag> *d) {
	for(int i = 0; i < (*d).size(); ++i)
		if ((*d)[i].exist)
			(*d)[i].exist = false;
		else {
			(*d)[i].exist = true;
			return true;
		}
	return false;
}

Drag drag_mix(std::vector<Drag> d, int min) {
	Drag price = {0, 0, 0, 1};
	for (int i = 0; i < d.size(); ++i)
		if (d[i].exist) {
			price.a += d[i].a;
			price.b += d[i].b;
			price.c += d[i].c;
			if (price.c >= min && min != -1) {
				price.exist = 0;
				return price;
			}
		}
	return price;
}

