using namespace std;

int dp[50][500][500];

int main(){
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    vector<int> A(N), B(N), C(N);
    int sum_a = 0, sum_b = 0;
    for(int i=0;i<N;i++){
        cin >> A[i] >> B[i] >> C[i];
        sum_a += A[i];
        sum_b += B[i];
    }

    fill((int*)dp[0][0], (int*)dp[50][0],-1);
    dp[0][0][0] = 0;

    for(int i=0;i<N;i++){
        for(int a=0;a<=sum_a;a++){
            for(int b=0;b<=sum_b;b++){
                if(dp[i][a][b] == -1) continue;
                if(dp[i+1][a+A[i]][b+B[i]] == -1) dp[i+1][a+A[i]][b+B[i]] = dp[i][a][b] + C[i];
                dp[i+1][a+A[i]][b+B[i]] = min(dp[i+1][a+A[i]][b+B[i]], dp[i][a][b] + C[i]);
                dp[i+1][a][b] = dp[i][a][b];
            }
        }
    }

    int ans = 1e9;
    for(int a=1;a<=sum_a;a++){
        for(int b=1;b<=sum_b;b++){
            if(dp[N][a][b] == -1 || Ma*b != Mb*a) continue;

            ans = min(ans, dp[N][a][b]);
        }
    }
    if(ans == 1e9){
        cout << -1 << endl;
    }else{
        cout << ans << endl;
    }
    return 0;
}

