int gcd(int l, int r) {

  if (r > l) swap(l, r);
  int m = l - r;
  if ( l%m == 0 and r%m == 0 ) return m;
  else return gcd(r, m);

}

#define MAX 405
#define INF (1<<21)
typedef long long ll;

int N, Ma, Mb;
int a[55], b[55], c[55];

int main() {

  cin >> N >> Ma >> Mb;
  for (int i = 0; i < N; i++) {
    cin >> a[i] >> b[i] >> c[i];
  }

  vector<vector<vector<int> > > 
	dp(N+1, vector<vector<int> >(MAX, vector<int>(MAX, INF)));

  /*
  for (int i = 0; i < MAX; i++) {
    for (int j = 0; j < MAX; j++) {
      dp[0][i][j] = 0;
    }
  }

  for (int i = 1; i <= N; i++) {
    for (int j = 0; j < MAX; j++) {
      dp[i][0][j] = 0;
      dp[i][j][0] = 0;
    }
  }
  */
  dp[0][0][0] = 0;

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < MAX; j++) {
      for (int k = 0; k < MAX; k++) {
        if ( j+a[i] >= MAX || k+b[i] >= MAX ) continue;
        dp[i+1][j][k] = min(dp[i+1][j][k], dp[i][j][k]);
        dp[i+1][j+a[i]][k+b[i]] = min(dp[i+1][j+a[i]][k+b[i]], dp[i][j][k] + c[i]);
          // cout << dp[i][j][k] << endl;
      }
    }
  }

  int res = INF;
  for(int ma = Ma, mb = Mb; ma < MAX && mb < MAX; ma+=Ma, mb+=Mb) {
    res = min(res, dp[N][ma][mb]);
  }

  if( res == INF) res = -1;
  cout << res << endl;

  return 0;

}

