lli n, ma, mb, a[40], b[40], c[40], dp[401][401];

int main() {
  cin >> n >> ma >> mb;
  for (lli i=0; i<n; ++i) cin >> a[i] >> b[i] >> c[i];
  for (lli j=0; j<=400; ++j) {
    for (lli i=0; i<=400; ++i) {
      dp[j][i] = 1e10;
    }
  }
  dp[0][0] = 0;
  for (lli i=0; i<n; ++i) {
    for (lli xa=400; xa >= a[i]; --xa) {
      for (lli xb=400; xb >= b[i]; --xb) {
        dp[xa][xb] = min(dp[xa][xb], dp[xa-a[i]][xb-b[i]] + c[i]);
      }
    }
  }
  lli ans = 1e10;
  for (lli xa = ma, xb = mb; xa <= 400 && xb <= 400; xa += ma, xb += mb) {
    ans = min(ans, dp[xa][xb]);
  }
  cout << (ans < 1e10 ? ans : -1) << '\n';
  return 0;
}

