using namespace std;

struct drag
{
	int m, val;
};

int n;
int ma, mb;
int result;
vector<drag> v;

void calc(int cost, int i, int m)
{
	if (i == n)
	{
		if (m != 0)
			return;
		if (cost == 0)
			return;
		if (cost < result)
			result = cost;
	}
	else
	{
		if (cost >= result)
			return;
		//	次の製品がm = 0でもcostは高くなるのでx
		if (m == 0 && cost > 0)
		{
			result = cost;
			return;
		}

		if (m + v[i].m <= 0)
		{
			calc(cost + v[i].val, i + 1, m + v[i].m);
			calc(cost, i + 1, m);
		}
	}
}


int main()
{
	result = INT_MAX;
	cin >> n >> ma >> mb;
	v.resize(n);
	for (int i = 0; i < n; i++)
	{
		int a, b;
		cin >> a >> b >> v[i].val;
		v[i].m = a * mb - b * ma;
	}
	sort(v.begin(), v.end(), [](drag &l, drag &r) {return l.m < r.m; });
