using namespace std;

const int N = 44;
const int inf = 1e8;

int n, ma, mb, a[N], b[N], c[N];
int cache[44][404][404];
bool ready[44][404][404];

int dp(int k, int x, int y) {
    if (k == n) {
        if (x == 0 and y == 0) return inf;
        int g = __gcd(x, y);
        x /= g;
        y /= g;
        if (ma == x and mb == y) return 0;
        return inf;
    }

    if (ready[k][x][y]) return cache[k][x][y];
    ready[k][x][y] = true;
    int &rv = cache[k][x][y];
    rv = dp(k + 1, x, y);
    rv = min(rv, c[k] + dp(k + 1, x + a[k], y + b[k]));
    return rv;
}

int main() {
    cin >> n >> ma >> mb;
    for (int i = 0; i < n; ++i) cin >> a[i] >> b[i] >> c[i];
    int res = dp(0, 0, 0);
    printf("%d\n", res >= inf ? -1 : res);
}

