using namespace std;

int N;
int Ma, Mb;
vector<int> a, b, c;
int memo[50][500][500];

int dfs(int i, int A, int B, int cost) {
    if (i == N) {
        if (double(Ma) / double(Mb) == double(A) / double(B)) {
            return cost;
        } else {
            return INF;
        }
    }
    if (memo[i][A][B] != 0) {
        return memo[i][A][B];
    }

    int ans = min(dfs(i + 1, A + a[i], B + b[i], cost + c[i]),
                  dfs(i + 1, A, B, cost));

    return memo[i][A][B] = ans;
}

