  int med[N][3];  // med[i][2] = cost of i
  rep(i,N) rep(j,3) cin >> med[i][j];

  int dif[N];  // [target] some sum of dif = 0
  rep(i,N) {
    med[i][0] *= Mb;
    med[i][1] *= Ma;
    dif[i] = med[i][0] - med[i][1];
  }

  const int zero = 3960;
  map<int, int> dps;
  dps[zero] = 0;
  queue<int> check;
  check.push(zero);
  priority_queue<int, vector<int>, greater<int>> ans;

  rep(i,N) {
    int num = check.size();
    int &d = dif[i];
    rep(j,num) {
      int p = check.front();
      check.pop();
      check.push(p);

      if (!dps.count(p+d)) {  // for the first time
        check.push(p+d);
        dps[p+d] = med[i][2];
        continue;
      }
      if (p+d == zero) {  // some sum of dif = 0
        ans.push(dps[p] + med[i][2]);
        continue;
      }
      if (dps[p] + med[i][2] < dps[p+d]) {  // less cost
        dps[p+d] = dps[p] + med[i][2];
      }
    }
  }
  if (ans.empty()) {
    cout << -1 << endl;
    return 0;
  }
  cout << ans.top() << endl;
  return 0;
