const int N = 45;
int n, ma, mb;
int a[N], b[N], c[N];
int dp[N][N][N];

int solve (int i, int aa, int bb)
{
	if (aa >0 && bb >0)
		if (abs((double)aa / (double)bb - (double(ma) / double(mb))) <= 1e-9) {
			return 0;
		}
	if (i >= n) {
		return 1e9;
	}
	int &res = dp[i][aa][bb];
	if (res != -1)
		return res;
	int solve1 = 0, solve2 = 0;
	solve1 = solve(i+1, a[i]+aa, b[i]+bb)+c[i];
	solve2 = solve(i+1, aa, bb);
	return res = min(solve1, solve2);
}

