int const inf = 1<<29;

constexpr int max_n = 41;
constexpr int max_m = 500;
int dp[max_n][max_m][max_m];

int main() {
  int N, Ma, Mb; cin >> N >> Ma >> Mb;
  vector<int> a(N), b(N), c(N);
  rep(i, N) {
    cin >> a[i] >> b[i] >> c[i];
