int main() {
    ll n, ma, mb;
    cin >> n >> ma >> mb;
    constexpr ll amax = 400;
    constexpr ll amin = 1;
    constexpr ll bmax = 400;
    constexpr ll bmin = 1;
    array<array<ll, bmax+1>, amax+1> costs;
    for (auto &&i: boost::irange(0LL, amax+1)){
        for (auto &&j: boost::irange(0LL, bmax+1)){
            costs.at(i).at(j) = numeric_limits<ll>::max();
        }
    }
    costs.at(0).at(0) = 0;
    for (auto &&shohin: boost::irange(0LL, n)){
        ll a, b, c;
        cin >> a >> b >> c;
        for (auto &&i: boost::irange(0LL, amax+1)){
            for (auto &&j: boost::irange(0LL, bmax+1)){
                ll next_a = i+a;
                ll next_b = j+b;
                if (costs.at(i).at(j)!=numeric_limits<ll>::max() && next_a <= amax && next_b <= bmax){
                    costs.at(next_a).at(next_b) = min(costs.at(next_a).at(next_b), costs.at(i).at(j)+c);
                }
            }
        }
    }
    ll min_cost{numeric_limits<ll>::max()};
    for (auto &&i: boost::irange(0LL, amax+1)){
        for (auto &&j: boost::irange(0LL, bmax+1)){
            if (i == 0 || j == 0) continue;
            else {
                if (i * mb == j * ma){
                    min_cost = min(min_cost, costs.at(i).at(j));
                }
            }
        }
    }
    if (min_cost == numeric_limits<ll>::max()){
        min_cost = -1;
    }
    cout << min_cost;
