void build(int first,int last,vector<int>& a,vector<int>& b,vector<int>& c,map<P,int>& mp){

    int times = last - first;
    for(int i = 0;i < (1<<times);i++){

        int suma = 0,sumb = 0,cost = 0;
        for(int j = 0;j < times;j++){

            if((i>>j)&1){
                //選ぶ
                suma += a[first + j];
                sumb += b[first + j];
                cost += c[first + j];
            }
        }
        if(!mp.count({suma, sumb}) || mp[{suma, sumb}] > cost) {
            mp[{suma, sumb}] = cost;
        }
    }
}




