struct st{int a,b,c;};

map<pii,int> solve(vector<st> v){
	map<pii,int> mp;
	rep(i,1<<v.size()){
		int ta=0,tb=0,tc=0;
		int t = i;
		rep(j,v.size()){
			if(t%2==0){
				ta+=v[j].a;
				tb+=v[j].b;
				tc+=v[j].c;
			}
			t/=2;
		}
		if(mp.count(pii(ta,tb)))mp[pii(ta,tb)] = min(mp[pii(ta,tb)],tc);
		else mp[pii(ta,tb)] = tc;
	}
	return mp;
}

