const int INF = 1000000;

int main(){
	int N, p, q;
	cin >> N >> p >> q;
	int a[N], b[N], c[N], A[N];
	for(int i=0; i<N; i++){
		cin >> a[i] >> b[i] >> c[i];
		A[i] = q * a[i] - p * b[i];
	}
// dp[i][j] で、j-4000 を A[0] ～ A[i] でつくれるとき、最小予算
// つくれないとき、INF
	int dp[N][8000];
	for(int i=0; i<8000; i++){
		if(i - 4000 == A[0]) dp[0][i] = c[0];
		else dp[0][i] = INF;
	}
    dp[0][4000] = 0;
	for(int i=1; i<N; i++){
		for(int j=0; j<8000; j++){
			if(j - A[i] >= 0 && j - A[i] < 8000){
				dp[i][j] = min(dp[i-1][j], dp[i-1][j-A[i]] + c[i]);
				if(dp[i][j] > INF){
					dp[i][j] = INF;
				}
			}else{
				dp[i][j] = dp[i-1][j];
			}
		}
	}
	if(dp[N-1][4000] == INF) cout << -1 << endl;
	else cout << dp[N-1][4000] << endl;
	return 0;
}

