struct item{
    llong a, b, cost;
};

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    llong N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    vector<item> items(0);
    FOR(i, N){
        llong a, b, c;
        cin >> a >> b >> c;
        items.push_back({a, b, c});
    }

    vector<vector<vvecllong>> dp(N + 1, vector<vvecllong>(Ma, vvecllong(0)));

    FOR(i, Ma) {
        dp[0][i].push_back(vecllong(0));
    }

    FOR(i, N) {
        llong a = items[i].a;
        FOR(mod, Ma) {
            llong prevMod = (mod - a) % Ma;
            if(prevMod < 0) prevMod += Ma;
            FOR(j, dp[i][mod].size()) {
                dp[i + 1][mod].push_back(dp[i][mod][j]);
            }
            FOR(j, dp[i][prevMod].size()) {
                vecllong cp = dp[i][prevMod][j];
                cp.push_back(i);
                dp[i + 1][mod].push_back(cp);
            }
        }
    }

    llong ans = INF;
    FOR(i, dp[N][0].size()) {
        llong sumA = 0;
        llong sumB = 0;
        llong cost = 0;

        FOR(j, dp[N][0][i].size()) {
            sumA += items[dp[N][0][i][j]].a;
            sumB += items[dp[N][0][i][j]].b;
            cost += items[dp[N][0][i][j]].cost;
        }

        if(sumA * sumB > 0 and sumA * Mb == sumB * Ma) {
            ans = min(ans, cost);
        }
    }

    if(ans == INF) {
        cout << "-1" << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}

