    Mp[{0,0}] = 0;
    for(int bit = 0; bit < (1 << (N/2)); bit++) {
        int x = 0,y = 0,z = 0;
        for(int i = 0; i < N/2; i++) {
            if(1 & (bit >> i)) {
                x+=a[i];y+=b[i];z+=c[i];
            }
        }
        if(Mp.count({x,y})) {
            Mp[{x,y}] = min(Mp[{x,y}],z);
        }
        else {
            Mp[{x,y}] = z;
        }
    }
    int ans = INF;
    for(int bit = 0; bit < (1 << (N+1)/2); bit++) {
        int x = 0,y = 0,z = 0;
        for(int i = 0; i < (N+1)/2; i++) {
            if(1 & (bit >> i)) {
                x+=a[i+N/2];y+=b[i+N/2];z+=c[i+N/2];
            }
        }
        for(int i = 1; X*i <= mxa && Y*i <= mxb; i++) {
            if(Mp.count({X*i-x,Y*i-y})) {
                ans = min(ans,z+Mp[{X*i-x,Y*i-y}]);
            }
        }
    }
    if(ans == INF) {
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
}

