int N, X, Y, a[44], b[44], c[44], dp[44][444][444];
int solve(int pos, int as, int bs, int cs) {
	if (pos == N) {
		return (as != 0 && as * Y == bs * X ? cs : inf);
	}
	if (dp[pos][as][bs]) return dp[pos][as][bs] - 1;
	int lc = solve(pos + 1, as, bs, cs);
	int rc = solve(pos + 1, as + a[pos], bs + b[pos], cs + c[pos]);
	dp[pos][as][bs] = min(lc, rc) + 1;
	return min(lc, rc);
}
