        for (int b_i = 0; b_i < UB; b_i++) {
            dp[a_i][b_i] = INF;
        }
    }
    dp[0][0] = 0;

    for (int drug_i = 0; drug_i < n; drug_i++) {
        for (int a_amou = UB - 1; a_amou >= 0; a_amou--) {
            for (int b_amou = UB - 1; b_amou >= 0; b_amou--) {
                if (a_amou - a[drug_i] >= 0 && b_amou - b[drug_i] >= 0) {
                    dp[a_amou][b_amou] = min(dp[a_amou][b_amou],
                                             dp[a_amou - a[drug_i]][b_amou - b[drug_i]] + c[drug_i]);
                }
            }
        }
    }

    int ans = INF;
    for (int a_amou = 1; a_amou < UB; a_amou++) {
        for (int b_amou = 1; b_amou < UB; b_amou++) {
            if (a_amou * mb == b_amou * ma) {
                ans = min(ans, dp[a_amou][b_amou]);
            }
        }
    }

    if (ans >= INF) cout << -1 << endl;
    else cout << ans << endl;

    return 0;
}

