ll search(ll pos, vll& a, vll& b, vll& c, ll Ma, ll Mb, ll ma, ll mb, ll mc){
  if(pos>=a.size()) return -1;
  if(ma!=0 && mb!=0){
    ll k = ma/Ma;
    if(Ma*k==ma && Mb*k==mb){
      return mc;
    }
  }
  ll tmp1 = search(pos+1, a, b, c, Ma, Mb, ma, mb, mc);
  ll tmp2 = search(pos+1, a, b, c, Ma, Mb, ma+a[pos], mb+b[pos], mc+c[pos]);
  if(tmp1==-1) return tmp2;
  if(tmp2==-1) return tmp1;
  return min(tmp1, tmp2);
}

