// 使い回す集めるDP
// dp[j][h] =  
// ループがi回回っている時
//      j, hにループが着ているならばD[i][j][h]
//      j, hにループが着ていないならばD[i-1][j][h]
const ll J = 4010;
const ll H = 4010;
ll dp[J][H];

int main(void) {
    ll n, ma, mb;cin>>n>>ma>>mb;
    vll a(n), b(n), c(n);
    rep(i, n) {
        cin >> a[i] >> b[i] >> c[i];
    }

    rep(j, J) rep(h, H) {
        dp[j][h] = INF;
    }
    dp[0][0] = 0;
    repi(i, 1, n+1) {
        for (ll j = J-1; j>=0;j--) for(ll h=H-1;h>=0;h--) {
            if (j - a[i-1] >= 0 && h - b[i-1] >= 0) 
                chmin(dp[j][h], dp[j-a[i-1]][h-b[i-1]] + c[i-1]);
        }
    }
    ll ret = INF;
    repi(j, 1, J) repi(h, 1, H) if (h * ma == j * mb) {
        chmin(ret, dp[j][h]);
    }
    if (ret == INF) {
        cout << -1 << endl;
    } else { 
        cout << ret << endl;
    }

    return 0;
}

