ll dp[41][410][410];
ll gcd_table[410][410];

int main(int argc, char* argv[]) {
  ll n, ma, mb;
  cin >> n >> ma >> mb;
  vec<ll> a(n), b(n), c(n);
  for (int i = 0; i < n; i++) scanf("%lld %lld %lld", &a[i], &b[i], &c[i]);

  Fill(dp, LL_INF);
  dp[0][0][0] = 0;

  rep(i, 0, 410) rep(j, 0, 410) gcd_table[i][j] = gcd(i, j);
  rep(i, 0, n) rep(j, 0, 410) rep(k, 0, 410) {
    if (dp[i][j][k] == LL_INF) continue;
    chmin(dp[i + 1][j][k], dp[i][j][k]);
    chmin(dp[i + 1][j + a[i]][k + b[i]], dp[i][j][k] + c[i]);
  }

  ll ans = LL_INF;
  rep(i, 1, 401) rep(j, 1, 401) {
    if (dp[n][i][j] == LL_INF) continue;

    int ag = i, bg = j;
    while (gcd_table[ag][bg] != 1) {
      ll div = gcd_table[ag][bg];
      ag /= div, bg /= div;
    }

    if (ag != ma || bg != mb) continue;
    chmin(ans, dp[n][i][j]);
  }

  put(ans == LL_INF ? -1 : ans);
  return 0;
}

