template<class T> bool amin(T &a, const T &b) { if (b < a) { a = b; return 1; } return 0; }

ll solve() {
  int n = read<int>();
  int ma = read<int>();
  int mb = read<int>();

  int n1 = n / 2;
  int n2 = n - n1;

  int inf = 1e9;
  vvi F(444, vi(444, inf));

  {
    vi A(n1), B(n1), C(n1);
    rep(i, n1) {
      A[i] = read<int>();
      B[i] = read<int>();
      C[i] = read<int>();
    }
    rep(i, bit(n1)) {
      int aa = 0, bb = 0, cc = 0;
      rep(j, n1) {
        if ((bit(j) & i)) {
          aa += A[j];
          bb += B[j];
          cc += C[j];
        }
      }
      amin(F[aa][bb], cc);
    }
  }

  int ans = inf;
  {
    vi A(n2), B(n2), C(n2);
    rep(i, n2) {
      A[i] = read<int>();
      B[i] = read<int>();
      C[i] = read<int>();
    }
    rep(i, bit(n2)) {
      int aa = 0, bb = 0, cc = 0;
      rep(j, n2) {
        if ((bit(j) & i)) {
          aa += A[j];
          bb += B[j];
          cc += C[j];
        }
      }
      rep(x, 401) {
        int ay = mb * x + mb * aa - ma * bb;
        if (ay % ma == 0) {
          int y = ay / ma;
          if (y > 400) continue;
          int cand = F[x][y] + cc;
          if (aa + x != 0 && bb + y != 0) {
            ans = min(ans, cand);
          }
        }
      }
    }
  }
  if (ans == inf) return -1;
  return ans;
}
void Main() { cout << solve() << endl; }
