int main(void){
    int n, ma, mb;
    scanf("%d %d %d", &n, &ma, &mb);
    int ab[n], c[n];
    for(int i = 0;i < n;i++){
        int a, b;
        scanf("%d %d %d", &a, &b, &c[i]);
        ab[i] = b * ma - a * mb;
    }
    int dp[n][8000];
    for(int i = 0;i < n;i++){
        for(int j = 0;j < 8000;j++){
            dp[i][j] = mod;
        }
    }
    dp[0][4000] = mod-1;
    for(int i = 0;i < n;i++){
        for(int j = 0;j < 8000;j++){
            if(dp[i][j]==mod)continue;
            dp[i+1][j] = min(dp[i+1][j],dp[i][j]);
            if(j-ab[i]>=0&&j-ab[i]<8000)dp[i+1][j] = min(dp[i+1][j],dp[i][j-ab[i]]+c[i]);
        }
    }
    if(dp[n][4000] != mod)printf("%d\n", dp[n][4000]);
    else printf("-1\n");
    return 0;
}

