using namespace std;

int main() {
	int n, ma, mb;
	cin >> n >> ma >> mb;
	int dp[401][401];
	for (int i = 0; i < 401; ++i) {
		for (int j = 0; j < 401; ++j) {
			dp[i][j] = -1;
		}
	}
	dp[0][0] = 0;
	for (int i = 0; i < n; ++i) {
		int a, b, c;
		cin >> a >> b >> c;
		for (int j = 400; j >=0; ++j) {
			for (int k = 400; k >=0; ++k) {
				if (j + a > 400) continue;
				if (k + b > 400) continue;
				if (dp[j][k] == -1) continue;
				if (dp[j + a][k + b] == -1) {
					dp[j + a][k + b] = dp[j][k] + c;
				}
				else {
					dp[j + a][k + b] = min(dp[j][k] + c, dp[j+a][k+b]);
				}
			}
		}
	}
	int mincost = 100*50;
	int x = 1;
	while (x*ma <= 400 && x*mb <= 400) {
		if (dp[x*ma][x*mb] != -1) {
			mincost = min(mincost, dp[x*ma][x*mb]);
		}
		x++;
	}
	if (mincost == 100 * 50) cout << -1 << endl;
	else cout << mincost << endl;
	return 0;
}

