    DP[0][0][0] = 0;
    rep(i, N) {
        cin >> A[i] >> B[i] >> C[i];
        rep(j, 500 - A[i]) rep(k, 500 - B[i]) {
            DP[j + A[i]][k + B[i]][i + 1] =
                min(DP[j + A[i]][k + B[i]][i], DP[j][k][i] + C[i]);
        }
    }
    rep(i, 500) {
        ll MA = M * (i + 1), MB = K * (i + 1);
        rep(j, 40) res = min(res, DP[MA][MB][j]);
    }
    cout << (res == inf ? -1 : res) << endl;
}

