		for(int j = 1; j <= 410; ++j){
			ll x = i, y = j;
			ll gcd = __gcd(x, y);
			x /= gcd, y /= gcd;
			g[i][j] = mp(x, y);
		}
	}

	for(int i = 1; i <= 400; ++i){
		for(int j = 1; j <= 400; ++j){
			for(int k = 0; k < 40; ++k){
				if(i / __gcd(i, j) == a[k] && j / __gcd(i, j) == b[k]){
					if(dp[i][j] > c[k]){
						dp[i][j] = c[k];
						mask[i][j] = (1LL << k);
					}
				}
			}
		}
	}
	for(ll i = 0; i < n; ++i){
		for(int x = 400; x >= 1; --x){
			for(int y = 400; y >= 1; --y){
				int f = x, s = y;
				int l = f - a[i], r = s - b[i];
				if(l <= 0 || r <= 0) continue;
				if((mask[l][r] & (1LL << i)) == 0 && 
					dp[l][r] + c[i] < dp[f][s]){
						dp[f][s] = dp[l][r] + c[i];
						mask[f][s] = (mask[l][r] | (1LL << i));
					}	
			}
		}
	}

