		for(ll j = 1; j <= 400; ++j){
			if(i / __gcd(i, j) == ma && j / __gcd(i, j) == mb) ans = min(ans, dp[i][j]);
		}
	}
	cout << ((ans == inf) ? (-1) : (ans)) << '\n';
}




