#include <bits/stdc++.h>
#define REP(i,n) for(int i=0;i<n;++i)
#define SET(a,n) memset(a,n,sizeof(a))
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAX_M = 10, MAX_N = 40;

int N, A, B;
int a[MAX_N], b[MAX_N], c[MAX_N];
int dp[MAX_N + 1][MAX_M * MAX_N + 1][MAX_M * MAX_N + 1];

int rec(int i, int ca, int cb) {
  int res = INF;
  if (dp[i][ca][cb] < INF) return dp[i][ca][cb];

  if (i == N) {
    if (ca != 0 && cb != 0 && ca * B == cb * A) res = 0;
  } else {
    res = min(rec(i + 1, ca, cb), rec(i + 1, ca + a[i], cb + b[i]) + c[i]);
  }

  return dp[i][ca][cb] = res;
}

main() {
  int ans;
  cin >> N >> A >> B;
  REP(i, N) cin >> a[i] >> b[i] >> c[i];
  SET(dp, INF);

  ans = rec(0, 0, 0);
  cout << (ans < INF ? ans : -1) << endl;
}

