    if(b == 0) return a;
    return gcd(b, a%b);
}

int main(){
    ios::sync_with_stdio(false);
    cin >> N >> Ma >> Mb;

    REP(i,N) {
        cin >> a[i] >> b[i] >> c[i];
        int g = gcd(a[i],b[i]);
        ar[a[i]/g][b[i]/g].insert(pp(p(c[i],g),p(a[i],b[i])));
    }

    // i,jの組み合わせを求める
    FOR(i,1,11)FOR(j,1,11){
        // if (gcd(i,j)!=1) continue;
        // printf("%d %d\n", i, j);
        FOR(k,1,i) FOR(l,1,j) {
            // printf("%d %d %d %d\n", i-k, j-l, k, l);
            for(auto x: ar[i-k][j-l]) {
                for(auto y: ar[k][l]) {
                    int a1 = x.second.first;
                    int b1 = x.second.second;
                    int c1 = x.first.first;
                    int g1 = x.first.second;
                    int a2 = y.second.first;
                    int b2 = y.second.second;
                    int c2 = y.first.first;
                    int g2 = y.first.second;
                    int nc = c1 * g2 + c2 * g1;
                    int na = a1 * g2 + a2 * g1;
                    int nb = b1 * g2 + b2 * g1;
                    int ng = gcd(na,nb);
