void mul(ll &x, ll y){
	x *= y;
	if(x >= mod) x %= mod;
}

void add(ll &x, ll y){
	x += y;
	if(x >= mod) x -= mod;
	if(x < 0) x += mod;
}
ll bp(ll a, ll n){
	ll r = 1;
	while(n){
		if(n & 1) mul(r, a);
		mul(a, a);
		n >>= 1;
	}
	return r;
}

ll dp[415][415];
ll mask[415][415];
ll sum[415][415];
pll g[415][415];
ll a[41], b[41], c[41];
ll ma, mb, n;

void solve(){
	cin >> n >> ma >> mb;
	rep(i, 411) rep(j, 411) dp[i][j] = inf;
	for(ll i = 0; i < n; ++i){
		cin >> a[i] >> b[i] >> c[i];
	}
	for(int i = 1; i <= 410; ++i){
		for(int j = 1; j <= 410; ++j){
			ll x = i, y = j;
			ll gcd = __gcd(x, y);
			x /= gcd, y /= gcd;
			g[i][j] = mp(x, y);
		}
	}

	for(ll i = 0; i < n; ++i){
		int p = g[a[i]][b[i]].F, q = g[a[i]][b[i]].S;
		if(dp[p][q] > c[i]){
			dp[p][q] = c[i];
			mask[p][q] = (1LL << i);
		}		
		for(int x = 1; x <= 400; ++x){
			for(int y = 1; y <= 400; ++y){
				for(int j = 0; j < 40; ++j){
					int f = g[x][y].F, s = g[x][y].S;
					int u = f + a[j], v = s + b[j];
					int l = g[u][v].F, r = g[u][v].S;
					if(!(mask[f][s] & (1LL << j)) && 
							dp[f][s] + c[j] < dp[l][r]){
								dp[l][r] = dp[f][s] + c[j];
								mask[l][r] = mask[f][s] | (1LL << j);
							}
				}	
			}
		}
	}

	cout << ((dp[ma][mb] == inf) ? (-1) : (dp[ma][mb])) << '\n';
}




