    cin >> N >> Ma >> Mb;
    vector<int> a(N), b(N), c(N);
    for (int i = 0; i < N; i++) {
        cin >> a.at(i) >> b.at(i) >> c.at(i);
    }

    vector<P> A;
    for (int bit = 0; bit < (1 << (N / 2)); bit++) {
        int ma = 0;
        int mb = 0;
        int sum = 0;
        for (int i = 0; i < (N / 2); i++) {
            int mask = 1 << i;
            if (bit & mask) {
                ma += a[i];
                mb += b[i];
                sum += c[i];
            }
        }
        A.push_back(P(Ma * mb - ma * Mb, sum));
    }
    sort(A.begin(), A.end());

    int ans = INF;
    for (int bit = 0; bit < (1 << (N - N / 2)); bit++) {
        int ma = 0;
        int mb = 0;
        int sum = 0;
        for (int i = 0; i < (N - N / 2); i++) {
            int mask = 1 << i;
            if (bit & mask) {
                ma += a[i + N / 2];
                mb += b[i + N / 2];
                sum += c[i + N / 2];
            }
        }
        int C = ma * Mb - Ma * mb;

        auto it = lower_bound(ALL(A), P(C, 0));
