struct N {
  int a, b, c;
};

ll gcd(ll a, ll b) {
  if (a % b == 0) return b;
  return gcd(b, a % b);
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  int n, ma, mb;
  cin >> n >> ma >> mb;
  vector<N> ns(n);
  for (int i = 0; i < n; i++) cin >> ns[i].a >> ns[i].b >> ns[i].c;

  ll INF = (1LL << 60);
  if (n <= 20) {
    ll ans = INF;
    for (int i = 0; i < (1 << n); i++) {
      ll na = 0, nb = 0, cost = 0;
      for (int j = 0; j < n; j++) {
        if ((i >> j) & 1) {
          na += ns[j].a;
          nb += ns[j].b;
          cost += ns[j].c;
        }
      }
      if (na > 0 && nb > 0) {
        ll g = gcd(na, nb);
        if (na / g == ma && nb / g == mb) {
          ans = min(ans, cost);
        }
      }
    }
    if (ans == INF) {
      cout << -1 << endl;
    } else {
      cout << ans << endl;
    }
  } else {
    ll ans = INF;
    auto hs = [](int a, int b) {
      return a * 100000 + b;
    };
    map<ll, ll> mp;
    for (int i = 0; i < (1 << 20); i++) {
      ll a = 0, b = 0, c = 0;
      for (int j = 0; j < n; j++) {
        if ((i >> j) & 1) {
          a += ns[j].a;
          b += ns[j].b;
          c += ns[j].c;
        }
      }
      if (mp.find(hs(a, b)) == mp.end()) {
        mp[hs(a, b)] = c;
      } else {
        mp[hs(a, b)] = min(mp[hs(a, b)], c);
      }
    }
    int m = n - 20;
    for (int i = 0; i < (1 << m); i++) {
      ll a = 0, b = 0, c = 0;
      for (int j = 0; j < m; j++) {
        if ((i >> j) & 1) {
          a += ns[j].a;
          b += ns[j].b;
          c += ns[j].c;
        }
      }
      for (int j = 1; j < n; j++) {
        ll ga = j * ma - a;
        ll gb = j * mb - b;
        if (ga < 0 || gb < 0) continue;
        if (mp.find(hs(ga, gb)) != mp.end()) {
          ans = min(ans, c + mp[hs(ga, gb)]);
        }
      }
    }
    if (ans == INF) {
      cout << -1 << endl;
    } else {
      cout << ans << endl;
    }
  }

  return 0;
}

