//dp用配列準備
const int imax = 41;
const int jmax = 410;
const int kmax = 410;

int dp[imax][jmax][kmax];

int main() {

	int n, ma, mb; cin >> n >> ma >> mb;

	//dp初期化
	for (int i = 0; i < imax; i++) {
		for (int j = 0; j < jmax; j++) {
			for (int k = 0; k < kmax; k++) {
				dp[i][j][k] = INF;
			}
		}
	}

	dp[0][0][0] = 0;

	for (int i = 0; i < n; i++) {
		int a, b, c; cin >> a >> b >> c;
		for (int j = 0; j < jmax; j++) {
			for (int k = 0; k < kmax; k++) {
				if (dp[i][j][k] == INF)continue;

				dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);
				dp[i + 1][j+a][k+b] = min(dp[i + 1][j+a][k+b], dp[i][j][k]+c);
			}
		}
	}

	int ans = INF;

	for (int j = 1; j < jmax; j++) {
		for (int k = 1; k < kmax; k++) {
			if (j*mb == k * ma) {
				ans = min(ans, dp[n][j][k]);
			}
		}
	}

	if (ans == INF) {
		cout << "-1" << endl;
	}
	else {
		cout << ans << endl;
	}

	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define inf 5000
#define priMax 100
#define perMax 10
#define NMax 40

int Calc(int *a,int *b,int *c,int N,int Ma,int Mb,int SN,int **dat){
    int **sum;
    sum=new int**[SN*perMax+1];
    for(int i=0;i<=SN;i++)
        sum[i]=new int*[SN*perMax+1];
    for(int i=0;i<=SN*perMax;i++)
            for(int j=0;j<=N*perMax;j++)
                sum[i][j]=inf;

    sum[0][0]=0; 
    if(SN==0) return Calc(a,b,c,N,Ma,Mb,SN+1,sum);
    for(int an=0;an<=SN*perMax;an++)
        for(int bn=0;bn<=SN*perMax;bn++){
            sum[an][bn] = min(sum[an][bn],dat[an][bn]);
            sum[an+a[n]][bn+b[n]] = min(dat[an][bn]+c[n],sum[an+a[n]][bn+b[n]]);
        }
    if(SN!=N) return Calc(a,b,c,N,Ma,Mb,SN+1,sum);
    int res=inf;
    for(int an=0;an<=N*perMax;an++)
        for(int bn=0;bn<=N*perMax;bn++)
            if((an!=0||bn!=0)&&an*Mb==bn*Ma)res=min(sum[an][bn],res);
    if(res==inf) return -1;
    else return res;
}

int main(){
    int N,Ma,Mb;
    cin>>N;
    cin>>Ma;
    cin>>Mb;
    int a[N],b[N],c[N];
    for(int i=0;i<N;i++){
        cin>>a[i];
        cin>>b[i];
        cin>>c[i];
    }
    cout<<Calc(a,b,c,N,Ma,Mb,0,NULL)<<endl;
    return 0;
}

