using namespace std;
typedef long long ll;
typedef pair<int, int> P;

#define pi 3.141592653589793)
#define mod 1000000007

int N, Ma, Mb;

void solve() {
	cin >> N >> Ma >> Mb;
	vector<int> a(N), b(N), c(N);
	for (int i = 0; i < N; i++) cin >> a[i] >> b[i] >> c[i];

	map<P, int>x;
	for (int i = 0; i < (1 << (N / 2)); i++) {
		int ta = 0, tb = 0, tc = 0;
		for (int j = 0; j < N / 2; j++) {
			if (i&(1 << j) != 0) {
				ta += a[j];
				tb += b[j];
				tc += c[j];
			}
		}
		if (x.count(P(ta, tb)))
			x[P(ta, tb)] = min(x[P(ta, tb)], tc);
		else
			x[P(ta, tb)] = tc;
	}

	map<P, int>y;
	for (int i = 0; i < (1 << (N - N / 2)); i++) {
		int ta = 0, tb = 0, tc = 0;
		for (int j = 0; j < N - N / 2; j++) {
			if (i&(1 << j) != 0) {
				ta += a[j + N / 2];
				tb += b[j + N / 2];
				tc += c[j + N / 2];
			}
		}
		if (y.count(P(ta, tb)))
			y[P(ta, tb)] = min(y[P(ta, tb)], tc);
		else
			y[P(ta, tb)] = tc;
	}

	int ans = 1000000000;
	for (map < P, int>::iterator itr = x.begin(); itr != x.end(); itr++) {
		int ta = (*itr).first.first;	//*itrの要素はキーと値のペアである
		int tb = (*itr).first.second;
		for (int i = 1; i*max(Ma, Mb) < 405; i++) {
			if (y.count(P(i*Ma - ta, i*Mb - tb)))
				ans = min(ans, (*itr).second + y[P(i*Ma - ta, i*Mb - tb)]);
		}
	}
	if (ans < 1000000000) cout << ans << endl;
	else cout << -1 << endl;
}

int main() {
	solve();
	return 0;
}

