void oneCase () {
    int n, ma, mb;
    cin >> n >> ma >> mb;

    vector<int> a(n);
    vector<int> b(n);
    vector<int> c(n);

    for (int i = 0; i < n; ++i) {
        int x, y, z;
        cin >> x >> y >> z;

        a[i] = x;
        b[i] = y;
        c[i] = z;
    }

    auto maxWeight = n * 10;
    vector<vector<int>> dp(maxWeight + 1, vector<int>(maxWeight + 1, 1e9));

    for (int i = 0; i < n; ++i) {
        auto x = a[i];
        auto y = b[i];
        dp[x][y] = min(dp[x][y], c[i]);
        for (int l = 1; l <= maxWeight; ++l) {
            for (int r = 1; r <= maxWeight; ++r) {
                auto nx = x + l;
                auto ny = y + r;
                if ((nx > maxWeight) || (ny > maxWeight)) {
                    continue;
                }
                dp[nx][ny] = min(dp[nx][ny], dp[l][r] + dp[x][y]);
            }
        }

    }

    int best = 1e9;
    int x = 0;
    int y = 0;

    while (true) {
        x += ma;
        y += mb;
        if ((x >= dp.size()) || (y >= dp.size())) {
            break;
        }
        best = min(best, dp[x][y]);
    }
    if (best == 1e9) {
        best = -1;
    }
    cout << best << "\n";
}





