const int NIL = -1;

struct chem{
	int a, b, c;
};

vector<chem> ch;

int dp[40][100][100];

int gcd(int a, int b){
	if (b == 0) return a;
	return gcd(a, a % b);
}
int N, MA, MB;

int cost(int n, int ma, int mb){
	if (n == -1 and (ma != MA or mb != MB)){
		return 40000;
	}
	if (ma == MA and mb == MB){
		return 0;
	}
	int ans = dp[n][ma][mb];
	if (ans == NIL){
		int na = ma + ch[n].a, nb = mb + ch[n].b;
		int g = gcd(na, nb);
		na /= g; nb /= g;
		ans = min(cost(n - 1, ma, mb), cost(n - 1, na, nb) + ch[n].c); 
	}
	return ans;
}

int main(){
	ios_base::sync_with_stdio(false); cin.tie(NULL);
	cin >> N >> MA >> MB;	
	ch.resize(N);
	memset(dp, NIL, sizeof dp);
	int a, b, c;
	for (int i = 0; i < N; i++){
		cin >> a >> b >> c;
		ch[i] = {a, b, c};
	}
	assert(gcd(MA, MB) == 1);

	int ans = cost(N - 1, 0, 0);
	if (ans == 40000){
		ans = -1;
	}
	cout << ans << endl;

	return 0;
}

