#define MAX 50
int N,Ma,Mb,a[MAX],b[MAX],c[MAX];

int bf() {
  int mini = INT_MAX;
  REP(i,1,(1<<N)) {
    int sa = 0, sb = 0, sc = 0;
    rep(j,N) {
      if( (i>>j) & 1 ) {
	sa += a[j];
	sb += b[j];
	sc += c[j];
      }
    }
    int gcd = __gcd(sa,sb);
    sa /= gcd, sb /= gcd;
    if( sa == Ma && sb == Mb ) mini = min(mini,sc);
  }
  if( mini == INT_MAX ) mini = -1;
  return mini;
}

void compute() {
  map<ii,ll> dp,next;
  rep(i,N) {
    next.clear();
    next = dp;
    if( dp.count(ii(a[i],b[i])) == 0 ) {
      next[ii(a[i],b[i])] = c[i];
    } else {
      next[ii(a[i],b[i])] = min(dp[ii(a[i],b[i])],(ll)c[i]);
    }
    for(auto v : dp) {
      ii fir = v.first;
      ll sec = v.second;
      fir.first  += a[i];
      fir.second += b[i];
      //ll gcd = __gcd(fir.first,fir.second);
      //fir.first  /= gcd;
      //fir.second /= gcd;
      if( next.count(fir) ) next[fir] = min(next[fir],sec+(ll)c[i]);
      else                  next[fir] = sec + (ll)c[i];
    }
    dp = next;
  }
  ll mini = LLONG_MAX;
  for(auto v : dp) {
    ii fir = v.first;
    ll sec = v.second;
    ll gcd = __gcd(fir.first,fir.second);
    fir.first  /= gcd;
    fir.second /= gcd;
    if( fir.first == Ma && fir.second == Mb ) mini = min(mini,sec);
  }
  if( mini != LLONG_MAX ) cout << mini << endl;
  else puts("-1");
}

int main() {
  cin >> N >> Ma >> Mb;
  rep(i,N) cin >> a[i] >> b[i] >> c[i];
  compute();
  //cout << "Answer : " << bf() << endl;
  return 0;
}

