int minCost(vector<Drag>& drag, int k, int a, int b, int cost, int ma, int mb){
    if(k>=drag.size()){
        if(a==0 && b==0)
            return INT_MAX;
        int g = gcd(a, b);
        return (a/g==ma && b/g==mb) ? cost : INT_MAX;
    }
    return min(minCost(drag, k+1, a, b, cost, ma, mb), minCost(drag, k+1, a+drag[k].a, b+drag[k].b, cost+drag[k].c, ma, mb));
}
