const int INF = 1e9;

int f(int index, int a, int b){
    if(a<0 || b<0) return INF;
    if(index==-1){
        if(a==0 && b==0) return 0;
        else return INF;
    }
    if(dp[index][a][b] != -1) return dp[index][a][b];

    dp[index][a][b] = min(f(index-1, a, b), C[index]+f(index-1, a-A[index], b-B[index]));
