using namespace std;
typedef long long ll;
using P = pair<ll, ll>;

const int nmax = 40, abmax = 10, inf = 1000000;
int a[nmax], b[nmax], c[nmax];
int dp[nmax + 1][nmax*abmax + 1][nmax*abmax + 1];

int main() {

	int n, ma, mb;
	cin >> n >> ma >> mb;

	for (int i = 0; i < n; i++) {
		cin >> a[i] >> b[i] >> c[i];
	}

	for (int i = 0; i <= n; i++) {
		for (int ca = 0; ca <= nmax*abmax; ++ca) {
			for (int cb = 0; cb <= nmax*abmax; ++cb) {
				dp[i][ca][cb] = inf;
			}
		}
	}

	dp[0][0][0] = 0;


	//iを使ってi+1の状態を計算する。
	for (int i = 0; i < n; i++) {
		for (int ca = 0; ca <= nmax*abmax; ++ca) {
			for (int cb = 0; cb <= nmax*abmax; ++cb) {
				//iの段階で到達できないならi+1を加えることはできない。
				if (dp[i][ca][cb] == inf)continue;

				//****************注意!!!!!!!!!!****************
				//dp[i+1][ca][cb]=dp[i][ca][cb]としてWAくらいかけた
				//i+1のループ中、同じca,cbになることはあるぞ。
				dp[i + 1][ca][cb] = min(dp[i+1][ca][cb],dp[i][ca][cb]);

				//i+1を加える。当然Aの重さはa[i]増え、Bの重さはb[i]増える。
				//もともとdpテーブルに書いてあったコストと
				//[i][ca][cb]のコストにc[i]を足した
				//のうち小さい方をdpテーブルにメモする。
				dp[i + 1][ca+a[i]][cb+b[i]] = min(dp[i + 1][ca+a[i]][cb+b[i]], dp[i][ca][cb]+c[i]);
			}
		}
	}

	//最小値の更新なので、最大値で初期化。
	int ans = inf;

	//全てのアイテムを使える状態でのdpテーブルをca,cbで順番にみていく。
	//重さの比が指定されたものになってる要素だけに着目し、
	//最小値が更新できるなら更新する。
	for (int ca = 1; ca <= nmax*abmax; ++ca) {
		for (int cb = 1; cb <= nmax*abmax; ++cb) {
			if (ca*mb == cb*ma)ans = min(ans, dp[n][ca][cb]);
		}
	}

	//一度も更新が行われなかったので、作成不能。
	//-1を出力するために代入しておく。
	if (ans == inf)ans = -1;

	cout << ans << endl;

	return 0;
}

