void solve(int N, int M_a, int M_b, vi a, vi b, vi c) {
  if(N == 1) {
    COUT(a[0] * M_b == b[0] * M_a ? c[0] : -1);
    return;
  }
  int fn = N / 2;
  vvi f_costs(fn * 10 + 1, vi(fn * 10 + 1, INF));
  for (int bits_i = 0; bits_i < (1ll << fn); bits_i++) {
    int a_sum = 0, b_sum = 0, c_sum = 0;
    for (int bit = 0; bit < fn; bit++)
      if (bits_i & (1ll << bit)) {
        a_sum += a[bit];
        b_sum += b[bit];
        c_sum += c[bit];
      }
    amin(f_costs[a_sum][b_sum], c_sum);
  }
  int ln = N - fn;
  int ans = INF;
  for (int bits_i = 0; bits_i < (1ll << ln); bits_i++) {
    int a_sum = 0, b_sum = 0, c_sum = 0;
    for (int bit = 0; bit < ln; bit++)
      if (bits_i & (1ll << bit)) {
        a_sum += a[bit + fn];
        b_sum += b[bit + fn];
        c_sum += c[bit + fn];
      }
    for (int r = 1; max(M_a, M_b) * r <= N * 10; r++) {
      int ai = r * M_a - a_sum, bi = r * M_b - b_sum;
      if(ai < 0 || bi < 0 || ai >= fn * 10 || bi >= fn * 10)continue;
      amin(ans, c_sum + f_costs[ai][bi]);
    }
  }
  COUT(ans < INF ? ans : -1);
}


