    for( int i = 1; i <= N; ++i ){
        maxA += a[i];
        maxB += b[i];
    } 

    // dp[i][A][B]: i 番目までの薬品を選び終わった時に a の重さが A, b の重さが B になる
    //            　組み合わせを作るのに必要な最小のコスト
    int dp[41][401][401];

   for( int n = 0; n <= N; ++n ){ 
        for( int i = 0; i <= maxA; ++i ){
            for( int j = 0; j <= maxB; ++j ){
                dp[n][i][j] = INF;
            } 
        }
    }
    dp[0][0][0] = 0; 
    for( int n = 1; n <= N; ++n ){ 
        for( int i = 0; i <= maxA; ++i ){
            for( int j = 0; j <= maxB; ++j ){
                if( dp[n][i][j] == INF ) continue;
                dp[n][i][j] = min( dp[n][i][j], dp[n-1][i][j] );  // i 番目の薬品を買わない場合
                dp[n][i+a[n]][j+b[n]] = min( dp[n][i+a[n]][j+b[n]], dp[n-1][i][j] + c[i] );  // i 番目の薬品を買う場合
            } 
        }
    }

    int ans = INF;
    for( int i = 0; i <= maxA; ++i ){
        for( int j = 0; j <= maxB; ++j ){
            if( Ma*j == Mb*i ) ans = min( ans, dp[N][i][j] );
        }
    } 
    if( ans == INF ) cout << "-1" << endl;
    else cout << ans << endl;

    return 0;
}

