void solve() {
    ll N,MA,MB; cin >> N >> MA >> MB;
    vec a,b,c;
    ll suma=0, sumb=0;

    rep(i,N){
        ll _a,_b,_c;
        cin >> _a >> _b >> _c;
        a.push_back(_a);
        b.push_back(_b);
        c.push_back(_c);
        suma += _a;
        sumb += _b;
    }

    ll dp[N+1][suma + 1][sumb + 1];

    rep(i,N+1){
        rep(j, suma+1){
            rep(k, sumb+1){
                dp[i][j][k] = INF;
            }
        }
    }

    dp[0][0][0] = 0;

    for(int i=0; i < N; ++i){
        for(int ca = 0; ca <= suma; ++ca){
            for(int cb = 0; cb <= sumb; ++cb){
                if(dp[i][ca][cb] == INF) continue;
                dp[i+1][ca][cb] = min(dp[i+1][ca][cb], dp[i][ca][cb]);
                dp[i+1][ca+a[i]][cb+b[i]] = min(dp[i+1][ca+a[i]][cb+b[i]], dp[i][ca][cb]+c[i]);
            }
        }
    }

    ll ans = INF;
    for(int ca=1; ca <= suma; ++ca){
        for(int cb=1; cb <= sumb; ++cb){
            if(ca*MB==cb*MA) chmin(ans, dp[N][ca][cb]);
        }
    }
    if(ans==INF)ans=-1;

    cout << ans << endl;
}

