using namespace std;

int main() {
  int n, ma, mb;
  cin >> n >> ma >> mb;
  struct chemical{
    int a;
    int b;
    int c;
  };
  vector<chemical> chemis(n);
  for(int i = 0; i < n; i++)
  {
    int a, b, c;
    cin >> a >> b >> c;
    chemis[i] = {a, b, c};
  }
  ///半分全列挙を行う
  auto half_search = [&](uint range, uint offset, vector<vector<int>> &result)
  {
    for(uint i = 0; i < range; i++)
    {
      int a, b, c;
      a = b = c = 0;
      uint index = 0;
      for(uint j = 1; j <= i; j = j << 1)
      {
        if(j & i)
        {
          //そこのビットに1が立っている
          a += chemis[index + offset].a;
          b += chemis[index + offset].b;
          c += chemis[index + offset].c;
        }
        index++;
      }
      //解の範囲を超えるものは弾く
      if(a > 10 || b > 10) continue;
      result[a][b] = min(result[a][b], c);
    }
  };
  uint offset = (uint)(n / 2);
  const int max_num = 40 * 10;
  const int max_cost = 100 * 40 * 2;
  vector<vector<int>> result_before(max_num, vector<int>(max_num, max_cost));
  vector<vector<int>> result_after(max_num, vector<int>(max_num, max_cost));
  half_search((uint)(pow(2, offset)), 0, result_before);
  half_search((uint)(pow(2, n - offset)), offset, result_after);

  ///正しい比率を列挙
  vector<pair<int, int>> correct_rate;
  for(int i = 1; i <= max_num; i++)
  {
    int tempa = ma * i;
    int temob = mb * i;
    if(tempa <= max_num && temob <= max_num)
    {
      correct_rate.push_back({tempa, temob});
    }
  }
  ///結果をマージ
  int result = max_cost;
  for(int i = 0; i < max_num; i++)
  {
    for(int j = 0; j < max_num; j++)
    {
      for(auto e : correct_rate)
      {
        if(e.first - i < 0 || e.second - j < 0) continue;
        if(e.first - i >= max_num || e.second >= max_num) continue;
        result =  min(result, result_before[i][j] + result_after[e.first - i][e.second - j]);
      }
    }
  }
  if(result == max_cost)
  {
    cout << -1 << endl;
  }else{ 
    cout << result << endl;
  }
  return 0;
}

