const int INF = 1e9;
const ld EPS = 1e-8;
const int K = 500;

int state(int a, int b) {
  return a * K + b;
}

int main(){
  int N, MA, MB;
  cin >> N >> MA >> MB;
  vector<int> a(N), b(N), c(N);
  REP(i,N) cin >> a[i] >> b[i] >> c[i];

  vector<vector<int>> dp(N + 1, vector<int> (K * K, INF));
  dp[0][0] = 0;
  REP(i,N)REP(j,K * K) {
    if(dp[i][j] == INF) continue;
    dp[i + 1][j] = min(dp[i + 1][j], dp[i][j]);
    int tmp = state(j / K + a[i], j % K + b[i]);
    if(tmp < K * K) {
      dp[i + 1][tmp] = min(dp[i + 1][tmp], dp[i][j] + c[i]);
    }
  }

  int res = -1;
  for(int i = 1; state(MA * i, MB * i) < K * K; ++i) {
    if(dp[N][state(MA * i, MB * i)] < INF) {
      res = dp[N][state(MA * i, MB * i)];
      break;
    }
  }
  cout << res << endl;

  return 0;
}

