const long long int MOD = 1000000007;

int N,M;
int a, b;
int dp[40][401][401];
int num[40][2];
int cost[40];
int ans=1000000;

int main() {
	cin >> N>>a>>b;
	for (int i = 0; i < N; i++) {
		cin  >> num[i][0] >> num[i][1]>>cost[i];
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < 401; j++) {
			for (int k = 0; k < 401; k++) {
				dp[i][j][k] =1000000;
			}
		}
	}
	dp[0][num[0][0]][num[0][1]] = cost[0];
	for (int i = 1; i < N; i++) {
		for (int j = 1; j < N*10+1; j++) {
			for (int k = 1; k < N*10+1; k++) {
				if (j < num[i][0] || k < num[i][1]) {
					dp[i][j][k] = dp[i - 1][j][k];
				}
				else {
					dp[i][j][k] = min(dp[i - 1][j][k], dp[i - 1][j - num[i][0]][k - num[i][1]] + cost[i]);
				}
			}
		}
	}
	for (int i = 1; i < N*10+1; i++) {
		for (int j = 1; j < N*10+1; j++) {
			if (i%a == 0 && j%b == 0&&dp[N-1][i][j]!=1000000) {
				if (i / a == j / b) {
					//cout << i << " " << j << " " << dp[N - 1][i][j] << endl;
					ans = min(ans, dp[N - 1][i][j]);
				}
			}
		}
	}
	if (ans == 1000000)cout << "-1\n";
	else cout << ans << endl;
	return 0;
}

