struct pair_hash {
    template <class T1, class T2>
    std::size_t operator () (const std::pair<T1,T2> &p) const {
        auto h1 = std::hash<T1>{}(p.first);
        auto h2 = std::hash<T2>{}(p.second);
        return h1 ^ h2;
    }
};

int main() {
  ll N, Ma, Mb;
  cin >> N >> Ma >> Mb;
  vi a(N), b(N), c(N);
  for (ll i = 0; i < N; i++) {
    cin >> a[i] >> b[i] >> c[i];
  }

  unordered_map<ll, ll> m1, m2;
  m1[0] = 0;
  m2[0] = 0;

  for (ll i = 0; i < N / 2; i++) {
    for (auto p: m1) {
      ll x = p.first % 1000;
      ll y = p.first / 1000;
      m1[x + a[i] + 1000 * (y + b[i])] = p.second + c[i];
    }
  }

  for (ll i = N / 2; i < N; i++) {
    for (auto p: m2) {
      ll x = p.first % 1000;
      ll y = p.first / 1000;
      m2[x + a[i] + 1000 * (y + b[i])] = p.second + c[i];
    }
  }

  ll ans = (1ll << 32);

  for (ll i = 1; i <= 400; i++) {
    for (auto p: m1) {
      ll x = p.first % 1000;
      ll y = p.first / 1000;
      ll t = (Ma + 1000 * Mb) * i;
      auto it = m2.find(t - x - 1000 * y);
