		//	もうmが0になることがないときはスルー
		if (m + maxVal < 0)
			return;
		//	次の製品がm = 0でもcostは高くなるのでx
		if (m == 0 && cost > 0)
		{
			result = cost;
			return;
		}

		if (m + v[i].m <= 0)
		{
			calc(cost + v[i].val, i + 1, m + v[i].m);
			calc(cost, i + 1, m);
		}
	}
}

