void tap(int p)
{
	for (int i = 400; i >= 0; i--)
		for (int h = 400; h >= 0; h--)
			if (dp[i][h]!=inf)
				dp[i+T[p].a][h+T[p].b] = min(dp[i+T[p].a][h+T[p].b], dp[i][h]+T[p].c);
}

