		cin >> T[i].a >> T[i].b >> T[i].c;

	FOR (i, 0, 400)
		FOR (h, 0, 400)
			dp[i][h] = inf;

	dp[0][0] = 0;
	FOR (i, 1, n)
		tap(i);

	int mn = inf;
	FOR (i, 1, 400)
		FOR (h, 1, 400) {
			int gc = __gcd(i, h);
			if (dp[i][h]!=inf && i/gc==x && h/gc==y) {
				mn = min(mn, dp[i][h]);
			}
		}

	if (mn == inf)
		mn = -1;
	cout << mn;
}

