int mc[LIM][LIM];

using ll = long long;

int main() {
    cin >> N >> Ma >> Mb;
    for (int i = 0; i < N; ++i) {
        cin >> A[i] >> B[i] >> C[i];
    }

    for (int i = 0; i < LIM; ++i) fill(mc[i], mc[i]+LIM, INF);

    mc[0][0] = 0;
    for (int i = 0; i < N; ++i) {
        for (int x = LIM-1; x >= A[i]; --x) {
            for (int y = LIM-1; y >= B[i]; --y) {
                mc[x][y] = min(mc[x][y], mc[x-A[i]][y-B[i]] + C[i]);
