    for(int i = 0;i < n;i++){
        int a, b;
        scanf("%d %d %d", &a, &b, &c[i]);
        ab[i] = b * ma - a * mb;
    }
    int dp[n][8000];
    for(int i = 0;i < n;i++){
        for(int j = 0;j < 8000;j++){
            dp[i][j] = mod;
        }
    }
    dp[0][4000+ab[0]] = c[0];
    for(int i = 1;i < n;i++){
        for(int j = 0;j < 8000;j++){
            if(dp[i-1][j]!=mod || j == 4000){
                dp[i][j] = min(dp[i-1][j], dp[i][j]);
                int plus;
                if(dp[i-1][j] == mod)plus = c[i];
                else plus = dp[i-1][j] + c[i];
                if(j+ab[i]>=0&&j+ab[i]<8000)dp[i][j + ab[i]] = min(dp[i-1][j + ab[i]], plus);
            }
        }
    }
    if(dp[n-1][4000] != mod)printf("%d\n", dp[n-1][4000]);
    else printf("-1\n");
    return 0;
