int main()
{
    int N, Ma, Mb;
    scanf(" %d %d %d", &N, &Ma, &Mb);
    int a[N], b[N], c[N];
    for(int i=0; i<N; i++) scanf(" %d %d %d", &a[i], &b[i], &c[i]);

    int w[N], jmax = 8000;
    for(int i=0; i<N; i++) w[i] = a[i]*Mb - b[i]*Ma;
    std::vector<std::vector<int> > dp(N+1, std::vector<int>(jmax, 1e+9));
    for(int i=1; i<=N; i++){
        for(int j=0; j<jmax; j++){
            if(j - w[i-1] >= jmax || j - w[i-1] < 0) dp[i][j] = dp[i-1][j];
            else if(j == w[i-1]+4000){
                dp[i][j] = min(c[i-1], dp[i-1][j-w[i-1]] + c[i-1], dp[i-1][j]);
            }
            else dp[i][j] = min(dp[i-1][j-w[i-1]] + c[i-1], dp[i-1][j]);
        }
    }
    if(dp[N][4000] > 1e+8) std::cout << -1 << std::endl;
    else std::cout << dp[N][4000] << std::endl;
}

