void solve(long long N, long long M_a, long long M_b, std::vector<long long> a, std::vector<long long> b, std::vector<long long> c)
{
    for (int i = 0; i < 500; i++)
    {
        for (int j = 0; j < 500; j++)
        {
            dp[i][j] = INF;
        }
    }

    dp[0][0] = 0;
    for (int n = 0; n < N; n++)
    {
        ll tmp[500][500];
        memcpy(tmp,dp,sizeof(dp));
        for (int i = 0; i < 500; i++)
        {
            for (int j = 0; j < 500; j++)
            {
                if (dp[i][j] != INF && i + a[n] < 500 && j + b[n] < 500)
                {
                    tmp[i + a[n]][j + b[n]] = min(tmp[i + a[n]][j + b[n]], dp[i][j] + c[n]);
                }
            }
        }
        memcpy(dp,tmp,sizeof(tmp));
    }

    ll ma = M_a, mb = M_b;
    ll ans = INF;
    while (ma < 500 && mb < 500)
    {
        if (dp[ma][mb] != INF)
        {
            ans = min(ans, dp[ma][mb]);
        }
        ma += M_a;
        mb += M_b;
    }
    if (ans == INF)
    {
        cout << -1 << endl;
    }
    else
    {
