void solve(){
	cin >> n >> ma >> mb;
	rep(i, 411) rep(j, 411) dp[i][j] = inf;
	for(ll i = 0; i < n; ++i){
		cin >> a[i] >> b[i] >> c[i];
	}
	for(int i = 1; i <= 410; ++i){
		for(int j = 1; j <= 410; ++j){
			ll x = i, y = j;
			ll gcd = __gcd(x, y);
			x /= gcd, y /= gcd;
			g[i][j] = mp(x, y);
		}
	}
	for(int i = 0; i < n; ++i){
		int x = g[a[i]][b[i]].F, y = g[a[i]][b[i]].S;
		if(c[i] < dp[x][y]){
			dp[x][y] = c[i];
			mask[x][y] = (1LL << i);
		}
	}
	for(ll i = 0; i < n; ++i){
		for(int x = 1; x <= 400; ++x){
			for(int y = 1; y <= 400; ++y){
				int f = g[x][y].F, s = g[x][y].S;
				int u = f + a[i], v = s + b[i];
				int l = g[u][v].F, r = g[u][v].S;
