            for (int s = 0; s < 1 << i-20; s++) {
                v2[(1<<i-20) | s] = make_pair(v2[s].first + d[i], v2[s].second + c[i]);
                if (v2[(1<<i-20) | s].first == 0) ans = min(ans, v2[(1<<i-20) | s].second);
