using namespace std;

int N;
int Ma, Mb;
vector<int> a(50), b(50), c(50);
int memo[50][510][510];

int dfs(int i, int A, int B, int cost) {
    if (memo[i][A][B] != 0) {
        return memo[i][A][B];
    }
    if (i == N) {
        if (A == 0 || B == 0) return INF;
        if (double(Ma) / double(Mb) == double(A) / double(B)) {
            return cost;
        } else {
            return INF;
        }
    }
    int ans = min(dfs(i + 1, A + a[i], B + b[i], cost + c[i]),
                  dfs(i + 1, A, B, cost));
    return memo[i][A][B] = ans;
}

int main() {
    cin >> N >> Ma >> Mb;
    for (int i = 0; i < N; i++) {
        cin >> a[i] >> b[i] >> c[i];
    }

    int ans = dfs(0, 0, 0, 0);

    if (ans != INF) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
}

