{
    ios_base::sync_with_stdio(0);
    cin.tie(nullptr);
    int n, m_a, m_b;
    cin >> n >> m_a >> m_b;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 0;
    for (int i = 0; i < n; i++) {
        int a, b, c;
