    ll a = 0, b = 0, c = 0;
    for (ll j = 0; j < fn; ++j) {
      if ((i & (1 << j)) != 0) {
        vector<ll> temp = front.at(j);
        a += temp.at(0);
        b += temp.at(1);
        c += temp.at(2);
      }
    }
    fvec.at(a).at(b) = min(fvec.at(a).at(b), c);
  }
  for (ll i = 0; i < (1 << bn); ++i) {
    ll a = 0, b = 0, c = 0;
    for (ll j = 0; j < bn; ++j) {
      if ((i & (1 << j)) != 0) {
        vector<ll> temp = back.at(j);
        a += temp.at(0);
        b += temp.at(1);
        c += temp.at(2);
      }
    }
    bvec.at(a).at(b) = min(bvec.at(a).at(b), c);
  }
