        while ((cnt * ma <= 400) &&(cnt * mb <= 400)) {
          ans = min(ans, c + bvec.at(cnt * ma - i).at(cnt * mb - j));
          cnt += 1;
        }
      }
    }
  }
  if (ans == INF) {
    cout << -1 << "\n";
  }
  else {
    cout << ans << "\n";
  }
}

