void MixingExperiment() {
	const int mi = 401;

	int dp[2][mi][mi];
	for (size_t t = 0; t < 2; t++)
	{
		for (size_t i = 0; i < mi; i++)
		{
			for (size_t j = 0; j < mi; j++)
			{
				dp[t][i][j] = INF;
			}
		}
	}

	int n, ma, mb;
	cin >> n >> ma >> mb;
	dp[0][0][0] = 0;
	dp[1][0][0] = 0;
	for (size_t i = 0; i < n; i++)
	{
		int a, b, c;
		cin >> a >> b >> c;
		for (size_t j = 0; j <= 400; j++)
		{
			for (size_t k = 0; k <= 400; k++)
			{
				int next = (i + 1) % 2;
				int now = i % 2;
				if (a <= j && b <= k) {
					dp[next][j][k] = min(dp[now][j][k], dp[now][j - a][k - b] + c);
				}
				else {
					dp[next][j][k] = dp[now][j][k];
				}
			}
		}
	}

	int tma = ma;
	int tmb = mb;

	int res = INF;
	while (tma <= 400 && tmb <= 400)
	{
		res = min(dp[n % 2][tma][tmb], res);
		tma += ma;
		tmb += mb;
	}
	if (res == INF)
		cout << -1 << endl;
	else cout << res << endl;
}

