using namespace std;
typedef pair<int, int> ii;

int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    int a[40], b[40], c[40];
    for (int i = 0; i < N; i++) {
        cin >> a[i] >> b[i] >> c[i];
    }

    //半分前列挙用に連想配列を作成
    int sep = N / 2;
    map<ii, int> fh, lh;
    for (int bit = 0; bit < 1 << sep; bit++) {
        int sum_a = 0, sum_b = 0, sum_c = 0;
        for (int i = 0; i < sep; i++) {
            if (1 & (bit >> i)) {
                sum_a += a[i];
                sum_b += b[i];
                sum_c += c[i];
            }
        }
        auto it = fh.find(ii(sum_a, sum_b));
        if (it != fh.end()) {
            if (sum_c < it->second) it->second = sum_c;
        }
        else {
            fh.insert(make_pair(ii(sum_a, sum_b), sum_c));
        }

    }
    for (int bit = 0; bit < 1 << (N - sep); bit++) {
        int sum_a = 0, sum_b = 0, sum_c = 0;
        for (int i = 0; i < N - sep; i++) {
            if (1 & (bit >> i)) {
                sum_a += a[i + sep];
                sum_b += b[i + sep];
                sum_c += c[i + sep];
            }
        }
        auto it = lh.find(ii(sum_a, sum_b));
        if (it != lh.end()) {
            if (sum_c < it->second) it->second = sum_c;
        }
        else {
            lh.insert(make_pair(ii(sum_a, sum_b), sum_c));
        }
    }
    //前半の連想配列から必要なa,bを求め後半の連想配列を検索
    int max_la = 0, max_lb = 0;
    for (int i = sep; i < N; i++) {
        max_la += a[i];
        max_lb += b[i];
    }
    int ans = 1000000;
    for (auto it = fh.begin(); it != fh.end(); ++it) {
        int fa = it->first.first, fb = it->first.second;
        int fc = it->second;
        int x, y;
        for (int i = 1; ; i++) {
            x = Ma * i - fa;
            y = Mb * i - fb;
            if (x > max_la || y > max_lb) break;
            // auto result = lh.find(ii(x, y));
            for (auto result = lh.lower_bound(ii(x,y));
                result != lh.upper_bound(ii(x, y));
                ++result) {
                ans = min(ans, fc + result->second);
            }
            // if (result != lh.end()) {
            //     ans = min(ans, fc + result->second);
            // }
        }
    }
    if (ans == 1000000) ans = -1;
    cout << ans << endl;
}

