			}
		} 
	}
	int res=1e9;
	for(int j=ma;j<=400;j+=ma){
		int k=j/ma*mb;
		if(k>400)
			continue;
		res=min(res,dp[n+1][j][k]);
	}
	if(res==1e9)
		res=-1;
	cout<<res<<endl;
	return 0;
}

