        if ((i >> j) & 1) {
          na += ns[j].a;
          nb += ns[j].b;
          cost += ns[j].c;
        }
      }
      if (na > 0 && nb > 0) {
        ll g = gcd(na, nb);
        if (na / g == ma && nb / g == mb) {
          ans = min(ans, cost);
        }
      }
    }
    if (ans == INF) {
      cout << -1 << endl;
    } else {
      cout << ans << endl;
