                }else if(dp[j][k]!=0){
                    if(dp[j+a][k+b]==0) dp[j+a][k+b]=dp[j][k]+c;
                    else dp[j+a][k+b]=min(dp[j+a][k+b],dp[j][k]+c);
                }
            }
        }
    }
    int ans=1000000;
    for(int i=1;i<=C/max(A,B);i++){
        if(dp[A*i][B*i]!=0){
            ans=min(ans,dp[A*i][B*i]);
        }
    }
