        int v = hanbun[make_pair(a, b)];
        if (v == 0 || cost < v) {
            hanbun[make_pair(a, b)] = cost;
        }
        return;
    }
    enumerate1(idx + 1, a + itemsA[idx][0], b + itemsA[idx][1], cost + itemsA[idx][2]);
    enumerate1(idx + 1, a, b, cost);
}

int best = 1e8;
void enumerate2(int idx = 0, int a = 0, int b = 0, int cost = 0) {
    if (idx == itemsB.size()) {
        ll x, y;

        for (auto p : hanbun){
            int x = p.first.first;
            int y = p.first.second;
            if (a+x == 0 || b+y == 0) continue;
            int g = gcd(a+x, b+y);
            if ((a+x)/g == aa && (b+y)/g == bb){
                minset(best,p.second+cost);
            }
        }

        return;
    }

    enumerate2(idx + 1, a + itemsB[idx][0], b + itemsB[idx][1], cost + itemsB[idx][2]);
    enumerate2(idx + 1, a, b, cost);
}


int main() {

    scanner >> n >> aa >> bb;

    repeat(i, n) {
        ll a, b, c;
        scanner >> a >> b >> c;
        if (i<=n/2)
            itemsA.push_back({ a,b,c });
        else
            itemsB.push_back({ a,b,c });
    }

    if (n == 1) {
        auto item = itemsA[0];
        ll g = gcd(item[0], item[1]);
        if (item[0] / g == aa && item[1] / g == bb) {
            cout << item[2] << endl;
        }
        else {
            cout << -1 << endl;
        }
        return 0;
    }

    enumerate1();
    enumerate2();

    cout << (best > 1e7 ? -1 : best) << endl;


    return 0;
}

