void solve() {
	int N, Ma, Mb; cin >> N >> Ma >> Mb;
	REP(i, 401) REP(j, 401) dp[i][j] = inf;
	REP(i, 401) REP(j, 401) dp2[i][j] = inf;
	set<pii> memo;//a, b
	memo.insert(pii(0, 0));
	dp[0][0] = 0;
	REP(i, N) {
		int a, b, c; cin >> a >> b >> c;
		set<pii> s = memo;
		for (auto &p : s) {
			pii nxt(p.first + a, p.second + b); //a, b
			dp2[nxt.first][nxt.second] = min(dp[nxt.first][nxt.second], dp[p.first][p.second] + c);
			dp2[p.first][p.second] = min(dp2[p.first][p.second], dp[p.first][p.second]);
			memo.insert(nxt);
		}
		swap(dp2, dp);
	}

	int a = Ma, b = Mb;
	int res = inf;
	while(a <= 400 and b <= 400){
		res = min(res, dp[a][b]);
		a += Ma;
		b += Mb;
	}
	cout << (res == inf ? -1 : res) << endl;
}

