        for (int l = 1; l <= maxWeight; ++l) {
            for (int r = 1; r <= maxWeight; ++r) {
                auto nx = x + l;
                auto ny = y + r;
                if (nx > maxWeight or ny > maxWeight) {
                    continue;
                }
                dp[nx][ny] = min(dp[nx][ny], dp[l][r] + c[i]);
            }
        }
        dp[x][y] = min(dp[x][y], c[i]);
