using namespace std;
int N, A, B;
int a[50], b[50], c[50];
const int inf=1001001;

int gcd(int a, int b){
   if(a<b) swap(a, b);
   if(b==0) return a;
   else return gcd(b, a%b);
}

int main(){

   cin>> N>> A>> B;
   for(int i=0; i<N; i++){
      cin>> a[i]>> b[i]>> c[i];
   }

   int memo[500][500];
   for(int i=0; i<500; i++){
      for(int j=0; j<500; j++){
         memo[i][j]=inf;
      }
   }
   memo[0][0]=0;
   for(int k=0; k<N; k++){
      for(int i=0; i+a[k]<500; i++){
         for(int j=0; j+a[k]<500; j++){
            memo[i+a[k]][j+b[k]]=min(memo[i+a[k]][j+b[k]], memo[i][j]+c[k]);
         }
      }
   }

   int C=inf;
   for(int i=1; i<500; i++){
      for(int j=1; j<500; j++){
         int g=gcd(i, j);
         if(i/g==A&&j/g==B){
            C=min(C, memo[i][j]);
         }
      }
