using namespace std;
using namespace boost::adaptors;
using uint = unsigned int;
using ll = long long int;
using ull = unsigned long long int;

int main() {
    constexpr ll MAX = 401;
    array<ll, MAX*MAX> costs;
    costs.fill(numeric_limits<ll>::max());
    costs.at(0) = 0;
    ll N, ma, mb;
    cin >> N >> ma >> mb;
    vector<ll> as;
    vector<ll> bs;
    vector<ll> cs;
    for (auto &&i: boost::irange(0LL, N)){
        ll a, b, c;
        cin >> a >> b >> c;
        as.emplace_back(a);
        bs.emplace_back(b);
        cs.emplace_back(c);
    }

    auto index_to_ab = [MAX](ll index) -> pair<ll, ll>{
        return make_pair(index % MAX, index / MAX);
    };
    auto ab_to_index = [MAX](ll a, ll b) -> ll{
        return a + b * MAX;
    };

    for (auto &&i: boost::irange(0LL, N)){ // 40
        ll a, b, c;
        tie(a, b, c) = tie(as.at(i), bs.at(i), cs.at(i));
        for (auto &&index: boost::irange(0LL, MAX*MAX)){ // 1600
            if (costs.at(index) != numeric_limits<ll>::max()) {
                ll _a, _b;
                tie(_a, _b) = index_to_ab(index);
                if (_a + a > MAX - 1 || _b + b > MAX - 1) continue;
//                cout << _a << " " << _b << " " << ab_to_index(_a + a, _b + b) << endl;
                costs.at(ab_to_index(_a + a, _b + b)) = min(costs.at(ab_to_index(_a + a, _b + b)),
                                                            costs.at(index) + c);
            }
        }
    }
    ll minimum{numeric_limits<ll>::max()};
    for (auto &&index: boost::irange(0LL, MAX*MAX)){
        ll a, b;
        tie(a, b) = index_to_ab(index);
        if (a != 0 && b != 0 && costs.at(index)!= numeric_limits<ll>::max() && a*mb == b*ma){
            minimum = min(minimum, costs.at(index));
        }
    }
    if (minimum == numeric_limits<ll>::max()){
        minimum = -1;
    }
    cout << minimum;
    return 0;
}

