lint pow(lint num, lint e, lint MOD) {
    lint res = 1;
    lint cur_num = num;
    while (e) {
        if (e & 1) {
            res *= cur_num;
            res %= MOD;
        }
        cur_num *= cur_num;
        cur_num %= MOD;
        e >>= 1;
    }
    return res;
}

auto min_cost(const vec<lint>& a_list, const vec<lint>& b_list, const vec<lint>& c_list,
                lint Ma, lint Mb) {
    lint num_items = a_list.size();
    unordered_map<lint, lint> res;
    range(i, 1LL, (1LL << num_items)) {
        lint key = 0, cost = 0;
        range(s, 0, num_items) {
            if ((i >> s) & 1) {
                key += Ma * b_list[s] - Mb * a_list[s];
                cost += c_list[s];
            }
        }
        if (res.find(key) == res.end()) {
            res.emplace(key, cost);
        } else {
            res.at(key) = min(res.at(key), cost);
        }
    }
    return res;
}

int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);
    lint N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    lint n_fh = N / 2, n_sh = N - n_fh;
    vec<lint> a_fh(n_fh), b_fh(n_fh), c_fh(n_fh);
    vec<lint> a_sh(n_sh), b_sh(n_sh), c_sh(n_sh);
    range(i, 0, n_fh) {
        cin >> a_fh.at(i) >> b_fh.at(i) >> c_fh.at(i);
    }
    range(i, 0, n_sh) {
        cin >> a_sh.at(i) >> b_sh.at(i) >> c_sh.at(i);
    }
    auto min_cost_first_half = min_cost(a_fh, b_fh, c_fh, Ma, Mb);
    auto min_cost_second_half = min_cost(a_sh, b_sh, c_sh, Ma, Mb);
    lint res = (1LL << 61);
    if (min_cost_first_half.find(0) != min_cost_first_half.end())
        res = min(res, min_cost_first_half.at(0));
    if (min_cost_second_half.find(0) != min_cost_second_half.end())
        res = min(res, min_cost_second_half.at(0));
    for (const auto pair : min_cost_first_half) {
        lint key = pair.first, cost = pair.second;
        lint complement = -key;
        if (min_cost_second_half.find(complement) != min_cost_second_half.end()) {
            lint total_cost = cost + min_cost_second_half[complement];
            res = min(res, total_cost);
        }
    }
    cout << (res == (1LL << 61) ? -1 : res) << "\n";
}

