		}
	}

	for (int i = 0; i < N; i++) {
		int a, b, c;
		cin >> a >> b >> c;
		update(a, b, c, N);
	}

	int ans = LL_HALFMAX;
	for (int i = 0; i < 500; i++) {
		for (int j = 0; j < 500; j++) {
			double target = (double)Ma / (double)Mb;
			double now = (double)i / (double)j;
			if (abs(target - now) < 0.000001 && dp[i][j] < ans) {
				ans = dp[i][j];
			}

		}
	}

	if(ans <40000) cout << ans << "\n";
	else cout << "-1" << "\n";

	return 0;




}

