  for (ll i = 0; i < (1 << fn); ++i) {
    ll a = 0, b = 0, c = 0;
    for (ll j = 0; j < fn; ++j) {
      if ((i & (1 << j)) != 0) {
        vector<ll> temp = front.at(j);
        a += temp.at(0);
        b += temp.at(1);
        c += temp.at(2);
      }
    }
    fvec.at(a).at(b) = min(fvec.at(a).at(b), c);
  }
  for (ll i = 0; i < (1 << bn); ++i) {
    ll a = 0, b = 0, c = 0;
    for (ll j = 0; j < bn; ++j) {
      if ((i & (1 << j)) != 0) {
        vector<ll> temp = back.at(j);
        a += temp.at(0);
        b += temp.at(1);
        c += temp.at(2);
      }
    }
    bvec.at(a).at(b) = min(bvec.at(a).at(b), c);
  }
  ll ans = INF;
  for (ll i = 1; i < 401; ++i) {
    for (ll j = 1; j < 401; ++j) {
      if (fvec.at(i).at(j) != INF) {
        ll c = fvec.at(i).at(j);
        ll cnt = max((i + ma - 1) / ma, (j + mb - 1) / mb);
        while ((cnt * ma <= 400) && (cnt * mb <= 400)) {
          ans = min(ans, c + bvec.at(cnt * ma - i).at(cnt * mb - j));
          cnt += 1;
        }
      }
    }
  }
  if (ans == INF) {
    cout << -1 << "\n";
  }
  else {
    cout << ans << "\n";
  }
}

