        rep(j, 500 - A[i]) rep(k, 500 - B[i]) {
            if (DP[j][k][i] == inf) continue;
            DP[j + A[i]][k + B[i]][i + 1] =
                min({DP[j + A[i]][k + B[i]][i + 1], DP[j + A[i]][k + B[i]][i],
                     DP[j][k][i] + C[i]});
        }
    }
    rep(i, 500) {
        ll MA = M * (i + 1), MB = K * (i + 1);
        if (MA >= 500 || MB >= 500) continue;
        rep(j, N) res = min(res, DP[MA][MB][j]);
    }
    cout << (res == inf ? -1 : res) << endl;
}

