#include <bits/stdc++.h>
using namespace std;

const int NIL = -1;

struct chem{
	int a, b, c;
};

struct state{
	int n, ma, mb;
};

bool operator< (state me, state other){
		if (me.n == other.n){
			if (me.ma == other.ma){
				return me.mb < other.mb;
			}
			return me.ma < other.ma;
		}
		return me.n < other.n;
	}

vector<chem> ch;

map<state, int> dp;
int N, MA, MB;

int cost(int n, int ma, int mb){
	if (n == -1 and (ma != MA or mb != MB)){
		return 40000;
	}
	if (ma == MA and mb == MB){
		return 0;
	}
	state s{n, ma, mb};
	if (dp.find(s) != dp.end()){
		return dp[s];
	}
	else{
		int na = ma + ch[n].a, nb = mb + ch[n].b;
		int g = __gcd(na, nb);
		na /= g; nb /= g;
		int ans = min(cost(n - 1, ma, mb), cost(n - 1, na, nb) + ch[n].c);
		dp[s] = ans;
		return ans;
	}

}

int main(){
	ios_base::sync_with_stdio(false); cin.tie(NULL);
	cin >> N >> MA >> MB;	
	ch.resize(N);
	int a, b, c;
	for (int i = 0; i < N; i++){
		cin >> a >> b >> c;
		ch[i] = {a, b, c};
	}
	assert(__gcd(MA, MB) == 1);

	int ans = cost(N - 1, 0, 0);
	if (ans == 40000){
		ans = -1;
	}
	cout << ans << endl;

	return 0;
}

