struct Solution {
    int dfs(int n, int a, int b, int c) {
        if (memo[n][a][b]) return memo[n][a][b];
        if (a && b && Ma * b == Mb * a) return memo[n][a][b] = c;
        if (n == N) return  memo[n][a][b] = INF;
        return min(dfs(n + 1, a + A[n], b + B[n], c + C[n]), dfs(n + 1, a, b, c));
    }
    void solve(std::istream& in, std::ostream& out) {
        in >> N >> Ma >> Mb;
