void compute() {
  map<ii,ll> dp,next;
  rep(i,N) {
    next.clear();
    next = dp;
    if( dp.count(ii(a[i],b[i])) == 0 ) {
      next[ii(a[i],b[i])] = c[i];
    } else {
      next[ii(a[i],b[i])] = min(dp[ii(a[i],b[i])],(ll)c[i]);
    }
    for(auto v : dp) {
      ii fir = v.first;
      ll sec = v.second;
      fir.first  += a[i];
