      ll gcd = __gcd(fir.first,fir.second);
      fir.first  /= gcd;
      fir.second /= gcd;
      if( next.count(fir) ) next[fir] = min(next[fir],sec+(ll)c[i]);
      else                  next[fir] = sec + (ll)c[i];
    }
    dp = next;
  }
  if( dp.count(ii(Ma,Mb)) ) cout << dp[ii(Ma,Mb)] << endl;
  else puts("-1");
}

