        cin >> a[i] >> b[i] >> c[i];
    }
    for(int i = 0; i <= n; i++){
        for(int ca = 0; ca <= nmax*abmax; ca++){
            for(int cb = 0; cb <= nmax*abmax; cb++){
                dp[i][ca][cb] = inf;
            }
        }
    }

    dp[0][0][0] = 0;

    for(int i = 0; i < n; i++){
