void backtrack(int cnt, int aa, int bb, int costs) {
	if(cnt == (int)vv.size()) {
		if(aa == 0 && bb == 0) return;
		dp[aa][bb] = min(dp[aa][bb], costs);
		int gg = ggcd[aa][bb];
		if(!gg) return;
		aa /= gg, bb /= gg;
		if(aa == ma && bb == mb) ans = min(ans, costs);
		return;
	}
	for (int i = 0; i < (int)vv.size(); ++i) {
		if(vis[i]) {
			backtrack(cnt + 1, aa, bb, costs);
			continue;
		}
		vis[i] = 1;
		backtrack(cnt + 1, aa + vv[i].first.first, bb + vv[i].first.second, costs + vv[i].second);
		vis[i] = 0;
	}
}

void backtrack2(int cnt, int aa, int bb, int costs) {
	if(cnt == (int)vv2.size()) {
		if(aa == 0 && bb == 0) return;
		for (int i = 0; i <= 200; ++i) {
			int left = mb * (aa + i);
			int right = ma * bb;
			left -= right;
			if(left < 0 || left % ma != 0 || ma > left) continue;
			int yy = left /= ma;
			if(yy > 200) continue;
			ans = min(ans, costs + dp[i][yy]);
		}
		int gg = ggcd[aa][bb];
		if(!gg) return;
		aa /= gg, bb /= gg;
		if(aa == ma && bb == mb) ans = min(ans, costs);
		return;
	}
	for (int i = 0; i < (int)vv2.size(); ++i) {
		if(vis[i]) {
			backtrack2(cnt + 1, aa, bb, costs);
			continue;
		}
		vis[i] = 1;
		backtrack2(cnt + 1, aa + vv2[i].first.first, bb + vv2[i].first.second, costs + vv2[i].second);
		vis[i] = 0;
	}
}

