using namespace std;

int Gcd(int a, int b)
{
    if (b == 0) {
        return a;
    }
    return Gcd(b, a % b);
}

bool SameRatio(int a1, int b1, int a2, int b2)
{
    auto gcd1 = Gcd(a1, b1);
    auto gcd2 = Gcd(a2, b2);

    a1 /= gcd1;
    b1 /= gcd1;

    a2 /= gcd2;
    b2 /= gcd2;

    return a1 == a2 && b1 == b2;
}

int main()
{
    int n, ratio_a, ratio_b;
    cin >> n >> ratio_a >> ratio_b;

    constexpr int kInf = (1 << 25);
    const int kGramLimit = 10 * (n + 1);

    vector<vector<int>> min_cost(kGramLimit + 1, vector<int>(kGramLimit + 1, kInf));
    min_cost[0][0] = 0;

    for (auto i = 0; i < n; i += 1) {
        int grams_a, grams_b, cost;
        cin >> grams_a >> grams_b >> cost;

        for (auto a = kGramLimit - grams_a; a >= 0; a -= 1) {
            for (auto b = kGramLimit - grams_b; b >= 0; b -= 1) {
                auto next_a = a + grams_a;
                auto next_b = b + grams_b;
                min_cost[next_a][next_b] = min(min_cost[next_a][next_b],
                                               min_cost[a][b] + cost);
            }
        }
    }

    auto res = kInf;
    for (auto a = 1; a <= kGramLimit; a += 1) {
        for (auto b = 1; b <= kGramLimit; b += 1) {
            if (min_cost[a][b] < kInf && SameRatio(ratio_a, ratio_b, a, b)) {
                res = min(res, min_cost[a][b]);
            }
        }
    }

    if (res >= kInf) {
        res = -1;
    }

    cout << res << "\n";
    return 0;
}

