int main(){
    int N,MA,MB;cin >> N >>MA >> MB;
    vector<vector<int>> dp(10000,vector<int>(10000,-1));
    vector<vector<int>> vec;
    for(int a = 0;a < N;a++){
        int b,c,d;cin >> b >> c >> d;
        vec.push_back({b,c,d});
    }
    dp[0][0] = 0;
    function<int(int,int)> calc = [&](int i,int j)->int{
        if(dp[i][j] != -1)return dp[i][j];
        int ma = 1e9;
        for(int a = 0;a < N;a++){
            if(i - vec.at(a).at(0) >= 0 && j - vec.at(a).at(1) >= 0){
                if(calc(i-vec.at(a).at(0),j-vec.at(a).at(1)) != 1e9){
                    ma = min(ma,calc(i-vec.at(a).at(0),j-vec.at(a).at(1))+vec.at(a).at(2));
                }
            }
        }
        return dp[i][j] = ma;
    };
    int ans = 1e9;
    for(int a = 1;a*MA < 10000 && a*MB < 10000;a++){
        if(calc(a*MA,a*MB) != 1e9){
            ans = min(ans,calc(a*MA,a*MB));
        }
    }
    if(ans == 1e9){
        cout<<-1<<endl;
        return 0;
    }
    cout<<ans<<endl;
}

#include <bits/stdc++.h>

using namespace std;
using llong = long long;
using ldbl = long double;
using P = pair<llong, llong>;
using PP = pair<P,llong>;

#define BE(x) x.begin(), x.end()

const llong inf = llong(1e18)+7;
const llong mod = 1e9+7;

PP operator+(const PP &l, const PP &r){
	return PP(P(l.first.first+r.first.first,l.first.second+r.first.second), l.second+r.second);
}
P operator-(const P &l, const P &r){
	return P(l.first-r.first, l.second-r.second);
}

int main(){
	llong N, Ma, Mb;
	vector<PP> v;

	cin >> N >> Ma >> Mb;
	v.resize(N);
	for(int i = 0; i < N; i++)
		cin >> v[i].first.first >> v[i].first.second >> v[i].second;

	vector<PP> f,b;
	for(int i = 0; i < 1<<(N/2); i++){
		bitset<40> bs(i);
		PP sum = PP(P(0,0),0);
		for(int j = 0; j < N/2; j++)
			if(bs.test(j))
				sum = sum + v[j];
		f.push_back(sum);
	}
	for(int i = 0; i < 1<<(N-N/2); i++){
		bitset<40> bs(i);
		PP sum = PP(P(0,0),0);
		for(int j = 0; j < N-N/2; j++)
			if(bs.test(j))
				sum = sum + v[j+N/2];
		b.push_back(sum);
	}
	sort(BE(f)), sort(BE(b));

	llong ans = inf;
	for(int i = 0; i < f.size(); i++){
		PP now = f[i];
		// cerr << now.first.first << " " << now.first.second << endl;
		int tmA = now.first.first/Ma + (now.first.first%Ma > 0 ? 1 : 0);
		int tmB = now.first.second/Mb + (now.first.second%Mb > 0 ? 1 : 0);
		if(now.first.first == 0)
			tmA = 1;
		if(now.first.second == 0)
			tmB = 1;
		int tgA = Ma*max(tmA,tmB), tgB = Mb*max(tmA,tmB);

		// cerr << tgA << " " << tgB << endl << endl;
		for(int i = 0; i < 10; i++){
			int cA = tgA + Ma*i, cB = tgB + Mb*i;
			// cerr << cA << " " << cB << endl;
			auto it = lower_bound(BE(b), PP(P(cA, cB) - now.first, 0));
			if(it->first == P(cA,cB) - now.first)
				ans = min(ans, it->second + now.second);
		}
	}

	if(ans == inf)
		ans = -1;
	cout << ans << endl;

	return 0;
}

