const int MAX_N = 40, MAX_AB = 10, INF = (1<<20);

int a[MAX_N], b[MAX_N], c[MAX_N];
int dp[MAX_N + 1][MAX_N*MAX_AB + 1][MAX_N*MAX_AB + 1];

int main() {
	cin.tie(0); ios::sync_with_stdio(false);
	int N, Ma, Mb;
	cin >> N >> Ma >> Mb;
	for (int i = 0; i < N;i++) cin >> a[i] >> b[i] >> c[i];

	for (int i = 0; i <= N;i++) {
		for (int ca = 0; ca <= MAX_N*MAX_AB;ca++) {
			for (int cb = 0; cb <= MAX_N*MAX_AB;cb++) {
				dp[i][ca][cb] = INF;
			}
		}
	}
	dp[0][0][0] = 0;

	for (int i = 0; i < N;i++) {
		for (int j = 0; j <= MAX_N*MAX_AB;j++) {
			for (int k = 0; k <= MAX_N*MAX_AB;k++) {
				if (dp[i][j][k] == INF)continue;
				dp[i + 1][j + a[i]][k + b[i]] = min(dp[i + 1][j + a[i]][k + b[i]], dp[i][j][k] + c[i]);
				dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);
			}
		}
	}
	int ans = INF;
	for (int i = 1; i <= MAX_N*MAX_AB;i++) {
		for (int j = 1; j <= MAX_N*MAX_AB;j++) {
			if (i*Mb == j*Ma) {
				ans = min(ans, dp[N][i][j]);
			}
		}
	}
	if (ans == INF) ans = -1;
	cout << ans << endl;
}

