#define inf 500000

int Calc(int *a,int *b,int *c,int N,int Ma,int Mb,int SN){
    int in[SN];
    int min=inf,mi;
    int am,bm,cm;
    if(SN>N) return inf;
    for(int i=0;i<SN;i++){
        in[i]=i;
    }
    while(true){
        am=0;bm=0;cm=0;
        for(int i=0;i<SN;i++){
            am+=a[in[i]];
            bm+=b[in[i]];
            cm+=c[in[i]];
        }
        if(am*Mb==bm*Ma&&min>cm) min=cm;
        if(in[0]+SN>N)break;
        in[SN-1]++;
        for(int i=SN-1;i>0;i--){
            if(in[i]=N-1){
                in[i-1]++;
                in[i]=0;
            }
        }        
        for(int i=1;i<SN;i++){
            if(in[i]<in[i-1])in[i]=in[i-1]+1;
        }
    }
    mi=Calc(a,b,c,N,Ma,Mb,SN+1);
    if(mi<min) return mi;
    else return min; 
}

