        int a, b, c; cin >> a >> b >> c;
        for (int na = MAX - 1; na >= a; na--) {
            for (int nb = MAX - 1; nb >= b; nb--) {
                chmin(dp[na][nb], dp[na - a][nb - b] + c);
            }
        }
    }
    int ans = INF;
    for (int a = 1; a < MAX; a++) for (int b = 1; b < MAX; b++) {
        if (a * mb == b * ma) chmin(ans, dp[a][b]);
    }
