#include <cstdio>
#include <map>
#include <algorithm>
using namespace std;

typedef pair<int,int> ii;

struct Package {
    int a, b, c;

    ii to_pair(){
        return ii(a,b);
    }
};

int n, ma, mb;
vector<Package> pack;
map<ii,int> ratio;

bool same_ratio(ii ratio){
    int gcd = __gcd(ratio.first, ratio.second);
    return ii(ma, mb) == ii(ratio.first / gcd, ratio.second / gcd);
}

int main(){
    scanf("%d%d%d", &n ,&ma, &mb);
    for(int i=0; i<n; i++){
        int x, y, z; scanf("%d%d%d", &x, &y, &z);
        pack.push_back({x,y,z});
    }

    ratio[pack[0].to_pair()] = pack[0].c;
    for(int i=1; i<n; i++){
        map<ii,int> temp = ratio;
        for(map<ii,int>::iterator it = ratio.begin(); it != ratio.end(); it++){
            ii newRat = ii((it->first).first + pack[i].a, (it->first).second + pack[i].b);
            if(!temp[newRat]) temp[newRat] = it->second + pack[i].c;
            else temp[newRat] = min(temp[newRat], it->second + pack[i].c);
        }
        ratio = temp;
    }

    int ans = 1e9;
    for(map<ii,int>::iterator it = ratio.begin(); it != ratio.end(); it++)
        if(same_ratio(it->first)) ans = min(ans, it->second);

    printf("%d\n", ans == 1e9? -1:ans);
    return 0;
}

