const int N = 41;
const int G = 11;
const int INF = 228228228;
int dp[N][N * G][N * G];

inline ANDREIKKAA_RETURN_TYPE mainFunction(ANDREIKKAA_PARAMETERS)
{
	fill((int*)dp, (int*)dp + N * N * N * G * G, INF);
	dp[0][0][0] = 0;

	int n, ma, mb;
	cin >> n >> ma >> mb;

	for (int i = 1; i <= n; ++i)
	{
		int aa, bb, cc;
		cin >> aa >> bb >> cc;

		for (int j = 0; j < N * G; ++j)
		{
			for (int k = 0; k < N * G; ++k)
			{
				dp[i][j][k] = dp[i - 1][j][k];
				if (j >= aa && k >= bb)
				{
					if (dp[i - 1][j - aa][k - bb] + cc < dp[i][j][k])
					{
						dp[i][j][k] = dp[i - 1][j - aa][k - bb] + cc;
					}
				}
			}
		}
	}

	int ans = INF;
	for (int i = 1; max(ma, mb) * i < N * G; ++i)
	{
		ans = min(ans, dp[n][ma * i][mb * i]);
	}
	if (ans == INF)
		ans = -1;
	cout << ans << endl;
}

