class MaterialSet : public std::set<Material>
{
public:
  void update(const Material &m)
  {
    auto itr = find(m);
    if (itr != end()) {
      if (m.c < itr->c) {
        erase(itr);
        insert(m);
      }
    } else {
      insert(m);
    }
  }
};

inline bool satisfy(unsigned Ma, unsigned Mb, unsigned a, unsigned b)
{
  if(a == 0 || b == 0) return false;

  unsigned Ta = a / Ma, Sa = a % Ma;
  unsigned Tb = b / Mb, Sb = b % Mb;
  return (Ta == Tb) && (Sa == 0) && (Sb == 0);
}

inline bool satisfy(unsigned Ma, unsigned Mb, const Material& m)
{
  return satisfy(Ma, Mb, m.a, m.b);
}

long search(
  unsigned N, unsigned Ma, unsigned Mb,
  const std::vector<Material> &m
)
{
  std::vector<MaterialSet> dp(N + 1);
  dp[0].emplace(0, 0, 0);

  N_TIMES(n, N) {
    for (Material p : dp[n]) {
      dp[n + 1].update(p);
      dp[n + 1].update(p + m[n]);
    }
  }

  long ret = -1;

  for (Material p : dp[N]) {
    if (!satisfy(Ma, Mb, p)) continue;

    if (ret > 0) {
      ret = std::min(static_cast<long>(p.c), ret);
    } else {
      ret = static_cast<long>(p.c);
    }
  }

  return ret;
}

int main()
{
  unsigned N, Ma, Mb;
  std::cin >> N >> Ma >> Mb;

  std::vector<Material> m(N);
  N_TIMES(n, N) std::cin >> m[n];

  std::cout << search(N, Ma, Mb, m) << std::endl;

  return 0;
}

