    vector<pair<int, int>> p_ab;
    p_ab.emplace_back(-10 * 10 * 40, INF);
    p_ab.emplace_back(10 * 10 * 40, INF);
    for (int i = 1; i < 1 << half_n; ++i) {
        int sum_ab = 0;
        int sum_c = 0;
        for (int j = 0; j < half_n; ++j) {
            if (i >> j & 1) {
                sum_ab += a[j] * mb - b[j] * ma;
                sum_c += c[j];
            }
        }
        if (sum_ab == 0) {
            min_cost = min(min_cost, sum_c);
        } else {
            p_ab.emplace_back(sum_ab, sum_c);
        }
    }
    sort(p_ab.begin(), p_ab.end());

    int pre_ab = p_ab[0].first;
    int sub_min_cost = INF;
    int idx = 1;
    while (true) {
        if (p_ab.size() == idx) break;
        if (pre_ab == p_ab[idx].first) {
            sub_min_cost = min(sub_min_cost, p_ab[idx].second);
            p_ab[idx - 1].second = sub_min_cost;
            p_ab.erase(p_ab.begin() + idx);
        } else {
            pre_ab = p_ab[idx].first;
            sub_min_cost = p_ab[idx].second;
            idx++;
        }
    }

    for (int i = 1; i < 1 << (n - half_n); ++i) {
        int sum_ab = 0;
        int sum_c = 0;
        for (int j = 0; j < n - half_n; ++j) {
            if (i >> j & 1) {
                sum_ab += - a[half_n + j] * mb + b[half_n + j] * ma;
                sum_c += c[half_n + j];
            }
        }
        if (sum_ab == 0) {
            min_cost = min(min_cost, sum_c);
        } else if (sum_c < min_cost) {
            auto rest_ab = lower_bound(p_ab.begin(), p_ab.end(), make_pair(sum_ab, INF)) - 1;
            if (rest_ab->first == sum_ab) {
                min_cost = min(min_cost, rest_ab->second + sum_c);
            }
        }
    }

    if (min_cost == INF) {
        cout << -1 << '\n';
    } else {
        cout << min_cost << '\n';
    }


    return 0;
}

