    cin >> N >> Ma >> Mb;
    vector<ll> a(N), b(N), c(N);
    rep(i,N){
        cin >> a[i] >> b[i] >> c[i];
    }
    ll n1 = N/2;
    ll n2 = N - N/2;
    vector<vector<ll>> v(405, vector<ll>(405)), u(405, vector<ll>(405)); 
