    rep(i,(1LL << (n1))){
        ll suma = 0;
        ll sumb = 0;
        ll sumc = 0;
        rep(j,n1){
            if((i >> j) & 1LL){
                suma += a[j];
                sumb += b[j];
                sumc += c[j];
            }
        }
        v[suma][sumb] = sumc;
        vv.push_back({suma,sumb});
    }
    rep(i,(1LL << (n2))){
        ll suma = 0;
        ll sumb = 0;
        ll sumc = 0;
        REP(j,0,n2){
            if((i >> j) & 1LL){
                suma += a[j+n1];
                sumb += b[j+n1];
                sumc += c[j+n1];
            }
        }
        u[suma][sumb] = sumc;
        uu.push_back({suma,sumb});
    }
    ll ans = 1e18;
    rep(i, vv.size()){
        ll at = vv[i].fi;
