        rep(j,400){
            ll ca = ma - at;
            ll cb = mb - bt;
            if((0 <= ca && ca <= 400)){
                if((0 <= cb && cb <= 400)){
                    if(u[ca][cb] == 0 || v[at][bt] == 0) goto gt;
                    cmin(ans, u[ca][cb] + v[at][bt]);
                }
            }
            gt:
            ma += Ma;
            mb += Mb;
        }
    }
    if(ans == 1e18){
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
}

