int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N, ma, mb;
  cin >> N >> ma >> mb;
  ll fn = (N + 1) / 2, bn = N - fn;
  vector<vector<ll>> front;
  vector<vector<ll>> back;
  unordered_map<ll, ll> fm;
  unordered_map<ll, ll> bm;
  for (ll i = 0; i < N; ++i) {
    ll a, b, c;
    cin >> a >> b >> c;
    if (i < fn) {
      front.push_back({a, b, c});
    }
    else {
      back.push_back({a, b, c});
    }
  }
  for (ll i = 1; i < (1 << fn); ++i) {
    ll a = 0, b = 0, c = 0;
    for (ll j = 0; j < fn; ++j) {
      if ((i & (1 << j)) != 0) {
        vector<ll> temp = front.at(j);
        a += temp.at(0);
        b += temp.at(1);
        c += temp.at(2);
      }
    }
    ll num = mb * a - ma * b;
    auto itr = fm.find(num);
    if (itr == fm.end()) {
      fm[num] = c;
    }
    else {
      fm[num] = min(fm[num], c);
    }
  }
  for (ll i = 1; i < (1 << bn); ++i) {
    ll a = 0, b = 0, c = 0;
    for (ll j = 0; j < bn; ++j) {
      if ((i & (1 << j)) != 0) {
        vector<ll> temp = back.at(j);
        a += temp.at(0);
        b += temp.at(1);
        c += temp.at(2);
      }
    }
    ll num = ma * b - mb * a;
    auto itr = bm.find(num);
    if (itr == bm.end()) {
      bm[num] = c;
    }
    else {
      bm[num] = min(bm[num], c);
    }
  }
  ll ans = INF;
  auto itr = fm.find(0);
  if (itr != fm.end()) {
    ans = min(ans, itr->second);
  }
  auto itr2 = bm.find(0);
  if (itr2 != bm.end()) {
    ans = min(ans, itr2->second);
  }
  for (auto itr = fm.begin(); itr != fm.end(); ++itr) {
    auto temp_itr = bm.find(itr->first);
    if (temp_itr != bm.end()) {
      ans = min(ans, itr->second + temp_itr->second);
    }
  }
  if (ans == INF) {
    cout << -1 << "\n";
  }
  else {
    cout << ans << "\n";
  }
}

