bool is_valid(int ma, int mb, int Ma, int Mb)
{
    bool ret = false;
    if (ma > 0 && mb > 0)
    {
        if (ma % Ma == 0 && mb % Mb == 0)
        {
            if (ma / Ma == mb / Mb)
            {
                ret = true;
            }
        }
    }
    return ret;
}

int dfs(vector<int> &a, vector<int> &b, vector<int> &c, int idx, int n, int ma, int mb, int &Ma, int &Mb, int cost)
{
    if (is_valid(ma, mb, Ma, Mb))
    {
        return cost;
    }
    if (idx < n)
    {
        return min(dfs(a, b, c, idx + 1, n, ma + a[idx], mb + b[idx], Ma, Mb, cost + c[idx]),
                   dfs(a, b, c, idx + 1, n, ma, mb, Ma, Mb, cost));
    }
    return INT_MAX;
}

