struct Data {
    int a, b, c;
    Data(int a = 1, int b = 1, int c = 0) : a(a), b(b), c(c) {
        int g = __gcd(a, b);
        a /= g;
        b /= g;
    }
    bool operator<(const Data &rhs) const {
        int c = rhs.a;
        int d = rhs.b;
        return make_pair(a * d, c) < make_pair(c * b, rhs.c);
    }
};
int N, M[2];
