                sa+=vec[num+j].first.first;
                sb+=vec[num+j].first.second;
                sc+=vec[num+j].second;
            }
        }
        cost[sa][sb]=min(cost[sa][sb],sc);
    }
    int ans=1e9;
    for (auto p:vec1){
        int a=p.first.first;
        int c=p.first.second;
        int r=c%mb;
        int d=-r;
        while (d<201){
            d+=mb;
