typedef long long ll;

int a[40];
int b[40];
int c[40];

typedef pair<int, int> P;


int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N, Ma, Mb;
	cin >> N >> Ma >> Mb;

	for(int i = 0; i < N; i++) {
		cin >> a[i] >> b[i] >> c[i];
	}

	map<P, int> m;
	int n = (N / 2);
	for(int bit = 0; bit < 1 << n; bit++) {
		int sa = 0, sb = 0, sc = 0;
		for(int i = 0; i < n; i++) {
			if(bit >> i & 1) sa += a[i], sb += b[i], sc += c[i];
		}
		if(m.count({ sa, sb }) == 0 || m[{sa, sb}] > sc) {
			m[{sa, sb}] = sc;
		}
	}

	int ans = 1e9;
	for(int bit = 0; bit < 1 << (N - n); bit++) {
		int sa = 0, sb = 0, sc = 0;
		for(int i = 0; i < N - n; i++) {
			if(bit >> i & 1) sa += a[n + i], sb += b[n + i], sc += c[n + i];
		}
		for(int i = 1; i <= 100; i++) {
			int ra = Ma * i - sa, rb = Mb * i - sb;
			if(m.count({ ra, rb })) {
				ans = min(ans, sc + m[{ra, rb}]);
			}
		}
	}

	if(ans == 1e9) ans = -1;
	cout << ans << endl;
}

