	      val += a0[i] * Mb - b0[i] * Ma;
	    }

	}

      v0.push_back(make_pair(val,cst));
      return;
    }

  REP(j,2)
    {
      vector<int> temp = ind;
      temp.push_back(j);
      pat(a0,b0,c0,n0,v0,temp);
    }
}




