void solve(){
    int n, x, y;
    cin >> n >> x >> y;
    for (int i = 0; i < n; ++i) cin >> a[i] >> b[i] >> c[i];
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N * X; ++j) {
            for (int k = 0; k < N * Y; ++k) {
                dp[i][j][k] = mod;
            }
        }
    }
    for (int i = 0; i < n - 1; ++i) {
        dp[i][0][0] = 0;
        for (int j = 0; j < N - a[i]; ++j) {
            for (int k = 0; k < N - b[i]; ++k) {
