    cin.tie(NULL);
    cout.tie(NULL);

    cin >> N >> MA >> MB;
    REP(i, N) { cin >> A[i] >> B[i] >> C[i]; }

    REP(i, N + 1) REP(j, 500) REP(k, 500) { dp[i][j][k] = INF; }

    dp[0][0][0] = 0;
    REPS(i, N) {
        REP(j, 500) REP(k, 500) {
            if (j - A[i - 1] < 0) continue;
