int n, ma, mb;
int a[50], b[50], c[50];
int mini_cost = IINF;
int memo[50][500][500];

int dfs(int now, int type_a, int type_b){
    if(type_a < 0 || type_b < 0 || type_a >= 500 || type_b >= 500){
        return IINF + 5;
    }
    if(now == 0){
        return type_a == 0 && type_b == 0 ? 0 : IINF + 5;
    }
    if(memo[now][type_a][type_b] <= IINF){
        return memo[now][type_a][type_b];
    }
    memo[now][type_a][type_b] = IINF;
    return memo[now][type_a][type_b] = min(dfs(now-1, type_a, type_b), dfs(now-1, type_a - a[now-1], type_b - b[now-1]) + c[now-1]);
}

