            }
        }
    }
    rep(j, 500){
        rep(k, 500){
            if(j == 0 && k == 0){
                continue;
            }
            if(j * mb == k * ma){
                mini_cost = min(mini_cost, dfs(n, j, k));
            }
        }
    }
