using namespace std;

const int AB_MAX = 10;
const int INF    = 10000;

int main()
{
	int N, M_a, M_b;
	cin >> N >> M_a >> M_b;

	int A[N], B[N], C[N];
	for (int i = 0; i < N; i++)
		cin >> A[i] >> B[i] >> C[i];

	map < pair <int, int>, int > M;
	M[{0, 0}] = 0;

	for (int i = 0; i < N; i++)
	{
		vector < pair < pair <int, int>, int> > to_add;

		for(auto it: M)
		{
			pair <int, int> p = it.first;

			p.first += A[i];
			p.second += B[i];

			to_add.push_back({p, it.second + C[i]});
		}

		for (int i = 0; i < to_add.size(); i++)
		{
			pair <int, int> p = to_add[i].first;

			if (M.find(p) == M.end())
				M[p] = to_add[i].second;
			else
				M[p] = min(M[p], to_add[i].second);
		}
	}

	int ans = INF;

	for (int i = 1; i < N * AB_MAX; i++) {
		auto it = M.find({i * M_a, i * M_b});
		if (it != M.end())
			ans = min(ans, it->second);
	}

	if (ans != INF)
		cout << ans << endl;
	else
		cout << -1 << endl;

	return (0-0);
}

