const int inf = 1<<30;
const ll inf_l = 1LL<<61;
const int MAX = 20000;

int main() {
    int n, ma, mb; cin >> n >> ma >> mb;
    vint a_l, a_r, b_l, b_r, c_l, c_r;
    rep(i,n) {
        int a, b, c; cin >> a >> b >> c;
        if (i < n / 2) {
            a_l.push_back(a);
            b_l.push_back(b);
            c_l.push_back(c);
        } else {
            a_r.push_back(a);
            b_r.push_back(b);
            c_r.push_back(c);
        }
    }
    int n_l = a_l.size();
    int n_r = a_r.size();
    map<int,int> mp;
    int ans = inf;
    rep(i,1<<(n_l)) {
        int weight = 0, value = 0;
        rep(j,n_l) {
            if (i >> j & 1) {
                weight += ma * b_l[j] - mb * a_l[j];
                value += c_l[j];
            }
        }
        if (weight == 0 && value != 0) chmin(ans, value);
        if (!mp.count(weight)) mp[weight] = value;
        else if (weight != 0) chmin(mp[weight], value);
    }
    rep(i,1<<(n_r)) {
        int weight = 0, value = 0;
        rep(j,n_r) {
            if (i >> j & 1) {
                weight += mb * a_r[j] - ma * b_r[j];
                value += c_r[j];
            }
        }
        if (!mp.count(weight)) continue;
        if (weight == 0 && value != 0) chmin(ans, value);
        if (weight != 0) chmin(ans, mp[weight] + value);
    }
    printf("%d\n", ans == inf ? -1 : ans);
}

