#define INF 1000000000

int N, Ma, Mb;
int M[40][3];

int dp[50][500][500];

void solve() {
    for (int i = 0; i <= 40; i++) {
        for (int j = 0; j < 500; j++) {
            for (int k = 0; k < 500; k++) {
                dp[i][j][k] = INF;
            }
        }
    }

    dp[0][0][0] = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 500; j++) {
            for (int k = 0; k < 500; k++) {
                if (dp[i][j][k] == INF) continue;
                dp[i+1][j][k] = min(dp[i][j][k], dp[i+1][j][k]);
                dp[i+1][M[i][0]+j][M[i][1]+k] = min(dp[i+1][M[i][0]+j][M[i][1]+k], dp[i][j][k]+M[i][2]);  
            }
        }
    }

    int ans = INF;
    for (int i = 1; i < 500; i++) {
        for (int j = 1; j < 500; j++) {
            if(i*Mb==j*Ma) ans = min(ans, dp[N][i][j]);
        }
    }

    if(ans >= INF) cout << -1 << endl;
    else cout << ans << endl;
}

int main() {
    cin >> N >> Ma >> Mb;

    for (int i = 0; i < N; i++) {
        cin >> M[i][0] >> M[i][1] >> M[i][2];
    }

    solve();
}

