int gcd(int a, int b) {
    return (b == 0 ? a : gcd(b, a%b));
}

int dp[42][MAX_M][MAX_M];

int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    // init
    for (int i=0; i<42; i++) {
        for (int j=0; j<MAX_M; j++) {
            for (int k=0; k<MAX_M; k++) {
                dp[i][j][k] = INT_MAX;
            }
        }
    }
    dp[0][0][0] = 0;

    for (int i=0; i<N; i++) {
        int a, b, c;
        cin >> a >> b >> c;

        for (int j=0; j<MAX_M; j++) {
            for (int k=0; k<MAX_M; k++) {
                if (dp[i][j][k] != INT_MAX) {
                    // 薬品iを使わない
                    dp[i+1][j][k] = min(dp[i+1][j][k], dp[i][j][k]);
                    // 薬品iを使う
                    dp[i+1][j+a][k+b] = min(dp[i+1][j+a][k+b], dp[i][j][k] + c);
                }
            }
        }
    }

    int ans = INT_MAX;
    for (int i=1; i<MAX_M; i++) {
        for (int j=1; j<MAX_M; j++) {
            if (dp[N][i][j] != INT_MAX) {
                int g = gcd(i, j);
                if (i/g == Ma && j/g == Mb) {
                    ans = min(ans, dp[N][i][j]);
                }
            }
        }
    }

    cout << (ans == INT_MAX ? -1 : ans) << endl;

    return 0;
}

