struct drag
{
	int m, val;
};

int n;
int ma, mb;
int result;
vector<drag> v;

void calc(int cost, int i, int m)
{
	if (i == n)
	{
		if (m != 0)
			return;
		if (cost == 0)
			return;
		if (cost < result)
			result = cost;
	}
	else
	{
		if (cost >= result)
			return;
		if (m > 0)
			return;
		//	次の製品がm = 0でもcostは高くなるのでx
		if (m == 0 && cost > 0)
		{
			if (cost < result)
				result = cost;
			return;
		}

		//	use i
		calc(cost + v[i].val, i + 1, m + v[i].m);
		//	not use i
		calc(cost, i + 1, m);
	}
}


int main()
{
