using namespace std;
using ll = long long;
using ll1d = vector<ll>;
using ll2d = vector<ll1d>;
using ll3d = vector<ll2d>;

ll inf = ll(1e18);

void solve(istream &ccin = cin, ostream &ccout = cout) {
  ll n, ma, mb;
  ccin >> n >> ma >> mb;
  vector<ll> a(n), b(n), c(n);
  rep(i, n) {
    ccin >> a.at(i) >> b.at(i) >> c.at(i);
  }

  ll3d dp(n + 1, ll2d(402, ll1d(402, inf)));
  dp.at(0).at(0).at(0) = 0;
  REP(i, 1, n + 1) {
    REP(ia, 1, 402) {
      REP(ib, 1, 402) {
        if (ia >= a.at(i - 1) and ib >= b.at(i - 1)) {
          dp.at(i).at(ia).at(ib) = min(dp.at(i).at(ia).at(ib), c.at(i - 1)
              + dp.at(i - 1).at(ia - a.at(i - 1)).at(ib - b.at(i - 1)));
        }
      }
    }
  }
  ll cost = inf;
  ll range = min(400 / ma, 400 / mb);
  REP(j, 1, n) {
    REP(i, 1, range) {
      cost = min(cost, dp.at(j).at(i * ma).at(i * mb));
    }
  }

  if (cost == inf) {
    ccout << -1 << endl;
  } else {
    ccout << cost << endl;
  }
}

int main() {
  ios::sync_with_stdio(false);
  solve();
  return 0;
}

