int dp[1001][1001];

void rec(int v,int C,int D,int cost){
  if(v==n)return ;
  if(C>1001 || D>1001)return;
  if(dp[C][D]<cost)return;
  dp[C][D]=cost;
  rec(v+1,C,D,cost);
  rec(v+1,C+a[v],D+b[v],cost+c[v]);
}

int solve(){
  FOR(i,0,1001)FOR(j,0,1001)dp[i][j]=inf;
  rec(0,0,0,0);
  int ans=inf;
  FOR(i,1,100)ans=min(ans,dp[A*i][B*i]);
  if(ans==inf)return -1;
  return ans;
}

