    dp[0][0][0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int k = 0; k <= 400; k++) {
            for (int j = 0; j <= 400; j++) {
                dp[i][k][j] = min(dp[i][k][j],dp[i-1][k][j]);
                if (k - a[i-1] >= 0 and j - b[i-1] >= 0)
                    dp[i][k][j] = min(dp[i][k][j], dp[i-1][k - a[i-1]][j - b[i-1]] + c[i-1]);
            }
        }
    }
    int ans = INF;
    rep(i, 100) {
        if (i > 0 and i * ma <= 400 and i * mb <= 400 and
            dp[n][i * ma][i * mb] != INF)
            ans = min(ans, dp[n][i * ma][i * mb]);
    }
    if (ans != INF) {
        cout << ans << nn;
    } else {
        cout << -1 << nn;
    }

    return 0;
}

