}

int dp[MAX_N][MAX_N];

int main() {

    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    // init
    for (int i=0; i<MAX_N; i++) {
        for (int j=0; j<MAX_N; j++) {
            dp[i][j] = INT_MAX;
        }
    }

    queue<pair<int,int> > q;
    q.push( make_pair(0,0) );
    dp[0][0] = 0;

    for (int i=0; i<N; i++) {
        int a,b,c;
