            int nb = p.second;
            int nc = dp[p.first][p.second];
            pair<int,int> np = make_pair(na+a, nb+b);
            if (dp[np.first][np.second] > nc + c) {
                dp[np.first][np.second] = nc + c;
                nq.push( np );
