void search(ll now, ll e, ll num, ll as, ll bs, ll cs) {
  if (now == e) {
    d[num].push_back(P(mb * as - ma * bs, cs));
    return;
  }
  search(now+1, e, num, as, bs, cs);
  search(now+1, e, num, as + a[now], bs + b[now], cs + c[now]);
}

