#define DRUGS_NUM_MAX 40
#define TOTAL_COST_MAX DRUGS_NUM_MAX * 1000

using namespace std;

struct Drug {
    int a;
    int b;
    int cost;
};

int n;
int ma;
int mb;
Drug drugs[DRUGS_NUM_MAX];

int min(int a, int b) {
    if(a < b) return a;
    return b;
}

int gcd(int a, int b) {
    while(a != b) {
        if(a < b) b -= a;
        else a -= b;
    }
    return a;
}

int total_cost(vector<bool>& used_drugs) {
    int c = 0;
    for(int i=0; i<n; i++) {
        if(used_drugs[i])
            c += drugs[i].cost;
    }
    return c;
}

bool is_achieved(vector<bool>& used_drugs) {
    int a = 0, b = 0;
    for(int i=0; i<n; i++) {
        if(used_drugs[i]) {
            a += drugs[i].a;
            b += drugs[i].b;
        }
    }

    int g = gcd(a, b);
    a = a / g;
    b = b / g;

    return a == ma && b == mb;
}

vector<vector<bool>> dp;
vector<int> dpc;

int _solve(int d, vector<bool>& used_drugs) {
    used_drugs[d] = true;

    for(int i=0; i<dp.size(); i++) {
        bool ok = true;
        for(int j=0; j < dp[i].size(); j++) {
            if(dp[i][j] != used_drugs[j]) {
                ok = false;
            }
        }
        if(ok) return dpc[i];
    }

    int min_cost = TOTAL_COST_MAX;
    if(is_achieved(used_drugs)) min_cost = total_cost(used_drugs);

    for(int i=0; i<n; i++) {
        if(used_drugs[i] == true) {
            continue;
        }

        int c = _solve(i, used_drugs);
        if(c == -1) continue;
        min_cost = min(min_cost, c);
    }

    used_drugs[d] = false;
    dp.push_back(used_drugs);
    dpc.push_back(min_cost);

    if(min_cost == TOTAL_COST_MAX)
        return -1;
    else
        return min_cost;
}

int solve() {
    vector<bool> used_drugs;
    for(int i=0; i<n; i++) {
        used_drugs.push_back(false);
    }

    int min_cost = TOTAL_COST_MAX;
    for(int i=0; i<n; i++) {
        int c = _solve(i, used_drugs);
        min_cost = min(min_cost, c);
    }
    if(min_cost == TOTAL_COST_MAX) return -1;
    return min_cost;
}

int main() {
    cin >> n >> ma >> mb;
    int g = gcd(ma, mb);
    ma = ma / g;
    mb = mb / g;

    int a, b, cost;
    for(int i=0; i<n; i++) {
        cin >> a >> b >> cost;
        drugs[i].a = a;
        drugs[i].b = b;
        drugs[i].cost = cost;
    }

    cout << solve() << endl;
}

