void solve() {
    REP(i, MAX_M * MAX_N) {
        REP(j, MAX_M * MAX_N) {
            REP(n, MAX_N) {
                P[i][j][n] = INF;
            }
        }
    }
    P[0][0][0] = 0;
    REP(n, N) {
        REP(i, MAX_M * MAX_N) {
            REP(j, MAX_M * MAX_N) {
                if (i >= A[n] and j >= B[n]) {
                    P[i][j][n + 1] = min(P[i][j][n], P[i - A[n]][j - B[n]][n] + C[n]);
                } else {
                    P[i][j][n + 1] = P[i][j][n];
                }
            }
