int a[41], b[41], c[41];
int n, ma, mb;

int memo[41][410][410];

int helper(int pos, int ca, int cb){

    if(ca > 0 && ca * mb == cb * ma)
        return 0;

    if(pos == n)
        return -1;

    if(memo[pos][ca][cb] != 0)
        return memo[pos][ca][cb];

    int opt1 = helper(pos + 1, ca, cb);
    int opt2 = helper(pos + 1, ca + a[pos], cb + b[pos]);

    if(opt1 == -1 && opt2 == -1){
        memo[pos][ca][cb] = -1;
        return -1;
    }

    if(opt1 == -1){
        memo[pos][ca][cb] = opt2 + c[pos];
        return memo[pos][ca][cb];
    }

    if(opt2 == -1){
        memo[pos][ca][cb] = opt1;
        return opt1;
    }

    memo[pos][ca][cb] = min(opt1, opt2 + c[pos]);
    return memo[pos][ca][cb];

}

