    for(int i = 0; i < n; i++){
        cin >> a[i] >> b[i] >> c[i];
    }
    vector<vector<vector<int>>> dp(n,vector<vector<int>>(401,vector<int>(401,-1)));
    dp[0][0][0] = 0;
    dp[0][a[0]][b[0]] = c[0];
    for(int i = 1; i < n; i++){
        for(int j = 0; j < 401; j++){
            for(int k = 0; k < 401; k++){
                dp[i][j][k] = dp[i-1][j][k];
            }
        }

        for(int j = 0; j < 401; j++){
            for(int k = 0; k < 401; k++){
                if(j + a[i] < 401 && k + b[i] < 401 && dp[i][j][k] != -1){
                    if(dp[i][j+a[i]][k+b[i]] == -1 || dp[i][j+a[i]][k+b[i]] > dp[i][j][k] + c[i]){
                        dp[i][j+a[i]][k+b[i]] = dp[i][j][k] + c[i];
                    }
                }
            }
        }
    }

    int result = -1;

    for(int i = 1; i*ma < 401 && i*mb < 401; i++){
        if(dp[n-1][i*ma][i*mb] != -1){
            if(result < 0){
                result = dp[n-1][i*ma][i*mb];
            }else{
                if(dp[n-1][i*ma][i*mb] < result){
                    result = dp[n-1][i*ma][i*mb];
                }
            }
        }
    }

