    for(int i=0;i<N;i++){
        for(int j=0;j<=MAXN*abmax){
            for(int k=0;k<=MAXN*abmax){
                if(dp[i][j][k]==inf) continue;
                dp[i+1][j][k] = min(dp[i][j][k],dp[i+1][j][k]);
                dp[i+1][j+a[i]][k+b[i]] = min(dp[i+1][j][k],dp[i][j][k]+c[i]);
            }
        }
    }

    int ans=inf;
    for(int i=1;i<=MAXN*abmax; ++i){
        for(int j = 1;j<=MAXN*abmax;++j){
            if(i*Mb==j*Ma) ans = min(ans,dp[N][i][j]);
        }
