    int n,a,b;
    while(cin>>n>>a>>b){
        int x[40],y[40],z[40];
        for(int i=0;i<n;i++)
            cin>>x[i]>>y[i]>>z[i];
        solve(n,x,y,z,a,b);
    }
    return 0;
}

