        vector<ll> xi, ci;
        for (int i = 0; i < N; ++i) {
            ll a, b, c;
            cin >> a >> b >> c;
            ll x = a*mb - b*ma;
            xi.push_back(x);
            ci.push_back(c);
        }
        vector<ll> dp(4000, INF);
        for (int i = 0; i < xi.size(); ++i) {
            ll x = xi[i];
            ll c = ci[i];
            dp[x+2000] = min(dp[x+2000], c);
            auto size = min(dp.size()-x, dp.size());
            auto init = max(ll(0), -x);
            for (int j = init; j < size; ++j) {
                dp[j+x] = min(dp[j+x], dp[j] + c);
            }
        }
        if(dp[2000] == INF){ cout << -1 << endl; }
        else cout << dp[2000] << endl;
    }
}

