#include <bits/stdc++.h>
#define MAX 400
#define N 40
#define INF 1000000
using namespace std;
int memo[MAX+1][MAX+1][N+1];
struct package
{
	int a, b, c;
	package(){}
	package(int a, int b, int c):a(a),b(b),c(c){}
};
package packages[N+1];
int dp(int a, int b, int i)
{
	if(a<0 || b<0) return INF;
	if(a==0 && b==0) return 0;
	if(i<=0) return INF;
	if(memo[a][b][i]!=-1) return memo[a][b][i];

	return memo[a][b][i] = min(dp(a,b,i-1),packages[i].c+dp(a-packages[i].a,b-packages[i].b,i-1));
}
int main()
{
	ios_base::sync_with_stdio(false);
	std::cin.tie(NULL);
	std::cout.tie(NULL);

	memset(memo,-1,sizeof memo);

	int n, Ma, Mb; cin >> n >> Ma >> Mb;
	for(int i = 1; i <= n; i++)
	{
		int a, b, c; cin >> a >> b >> c;
		packages[i] = package(a,b,c);
	}
	int best = INF;
	for(int k = 1; k <= 40; k++)
		best = min(best,dp(Ma*k,Mb*k,n));
	cout<<(best>=INF ? -1 : best)<<endl;

	return 0;
}

