			total.pb(mp(0,0));
			rep(i,a.size()){
				temp1=total.size();
				rep(j,temp1){
					temp2=total[j].fi+a[i].fi;
					temp3=total[j].se+a[i].se;
					total.pb(mp(temp2,temp3));
				}
			}
			//全状態を列挙したらナップサック問題.
			FOR(i,1,total.size()){
				//total[i].fiになる詰め込み方.
				ans=min(ans,solve(total[i].fi,total[i].se,0,b));
			}
		}else{
			total.pb(mp(0,0));
			rep(i,b.size()){
				temp1=total.size();
				rep(j,temp1){
					temp2=total[j].fi+b[i].fi;
					temp3=total[j].se+b[i].se;
					total.pb(mp(temp2,temp3));
				}
			}
			FOR(i,1,total.size()){
				//total[i].fiになる詰め込み方.
				// dbg(ans);
				// dbg(solve(total[i].fi,total[i].se,0,a));
				ans=min(ans,solve(total[i].fi,total[i].se,0,a));
			}
		}
		if(ans==0){
			cout<<-1<<endl;
		}else{
			cout<<ans<<endl;
		}
	}
	return 0;
}

