int GCD(int a, int b) {
    if (b == 0) return a;
    else return GCD(b, a % b);
}

int main(int argc, char const *argv[])
{
	int n,p,q;cin>>n>>p>>q;
	rep(i,n) cin>>a[i]>>b[i]>>c[i];

	rep(i,11) {
		rep(j,11) {
			dp[i][j]=INT_MAX;
		}
	}

	dp[0][0]=0;

	rep(i,n) {
		rep(j,11) {
			rep(k,11) {
				if ((j==0&&k!=0)||(j!=0&&k==0)) continue;
				int g = GCD(j+a[i],k+b[i]);
				dp[(j+a[i])/g][(k+b[i])/g]=min(dp[(j+a[i])/g][(k+b[i])/g],dp[j][k]+c[i]);
			}
		}
	}

	if (dp[p][q]==INT_MAX) cout<<-1<<endl;
	else cout<<dp[p][q]<<endl;

	return 0;
}

