	vector<pl> total;
	vector<ll> c;
	rep(i,n){
		cin>>temp1>>temp2>>temp3;
		//数学的考察から式を単純に
		temp1=mb*temp1-ma*temp2;
		if(temp1>0){
			a.pb(mp(temp1,temp3));
		}else if(temp1<0){
			b.pb(mp(-1*temp1,temp3));
		}else{
			c.pb(temp3);
		}
	}
	if(c.size()!=0){
		sort(all(c));
		ansc=min(ansc,c[0]);
	}
	//2つに分けれた.
	if(a.size()==0||b.size()==0){
		if(ans==0){
			cout<<-1<<endl;
		}else{
			cout<<ans<<endl;
		}
	}else{
		ans=INF;
		sort(all(a));
		sort(all(b));
		if(a.size()<b.size()){
			//これで2^20まで落とせたのでループで全探索できる.
			total.pb(mp(0,0));
			rep(i,a.size()){
				temp1=total.size();
				rep(j,temp1){
					temp2=total[j].fi+a[i].fi;
					temp3=total[j].se+a[i].se;
					total.pb(mp(temp2,temp3));
				}
			}
			//全状態を列挙したらナップサック問題.
			FOR(i,1,total.size()){
				//total[i].fiになる詰め込み方.
				solve(total[i].fi,total[i].se,0,b);
			}
		}else{
