int bf() {
  int mini = INT_MAX;
  REP(i,1,(1<<N)) {
    int sa = 0, sb = 0, sc = 0;
    rep(j,N) {
      if( (i>>j) & 1 ) {
	sa += a[j];
	sb += b[j];
	sc += c[j];
      }
    }
    int gcd = __gcd(sa,sb);
