typedef struct _MedicineInfo{
    llong a;
    llong b;
    llong c;
}MedicineInfo;

int main(){
    llong N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    vector<MedicineInfo> Table(N+1);
    for(int i=1; i<=N; i++){
        cin >> Table[i].a >> Table[i].b >> Table[i].c;
    }
    llong MAX_SIZE = 500;
    vector<vector<vector<llong> > > dp(N+1, vector<vector<llong> >(MAX_SIZE+1, vector<llong>(MAX_SIZE+1,MOD)));
    dp[0][0][0] = 0;
    for(int i=1; i<=N; i++){
        for(int j=0; j<=MAX_SIZE; j++){
            for(int k=0; k<=MAX_SIZE; k++){
                if(j-Table[i].a<0){
                    dp[i][j][k] = dp[i-1][j][k];
                    continue;
                }
                if(k-Table[i].b<0){
                    dp[i][j][k] = dp[i-1][j][k];
                    continue;
                }
                dp[i][j][k] = min(dp[i-1][j][k], dp[i-1][j-Table[i].a][k-Table[i].b]+Table[i].c);
            }
        }
    }
    llong ans=MOD;
    for(int i=1; i<=MAX_SIZE; i++){
        for(int j=1; j<=MAX_SIZE; j++){
            if((Ma/Mb)==(i/j)){
                ans = min(ans, dp[N][i][j]);
            }
        }
    }
    if(ans==MOD){
        cout << -1 << endl;
        exit(0);
    }
    cout << ans << endl;
    return 0; 
}

