typedef struct {
	double a;
	double b;
	int c;
	int exist;
}Drag;

bool next_choice(std::vector<Drag> *d) {
	for(int i = 0; i < (*d).size(); ++i)
		if ((*d)[i].exist)
			(*d)[i].exist = false;
		else {
			(*d)[i].exist = true;
			return true;
		}
	return false;
}

Drag drag_mix(std::vector<Drag> d) {
	Drag price = {0, 0, 0, 1};
	for (int i = 0; i < d.size(); ++i)
		if (d[i].exist) {
			price.a += d[i].a;
			price.b += d[i].b;
			price.c += d[i].c;
		}
	return price;
}

int main() {
	int n;
	double ma, mb;
	std::cin >> n;
	std::cin >> ma;
	std::cin >> mb;

	std::vector<Drag> drag(n);
	for (int i = 0; i < n; ++i) {
		std::cin >> drag[i].a;
		std::cin >> drag[i].b;
		std::cin >> drag[i].c;
	}

	double m = ma / mb;
	Drag mix;
	int min = -1;
	while(next_choice(&drag)){
		mix = drag_mix(drag);
		if (mix.a / mix.b == m)
			if(min == -1 || mix.c < min)
				min = mix.c;
	};

	std::cout << min;
}

