int gcd(int x, int y){
	return y == 0 ? x : gcd(y, x%y);
}

int ma,mb;

bool cdekiru(pair<int,int> u, pair<int,int> r){
	int a = u.first + r.first, b = u.second + r.second;
	int g = gcd(a,b);
	if(ma == a/g && mb == b/g){
		return true;
	}
	else{return false;}
}

int main(){
	int n; cin >> n >> ma >> mb;
	vector<int> a(n), b(n), c(n);
	for(int i = 0; i < n; i++){
		cin >> a[i] >> b[i] >> c[i];
	}
	map<pair<int, int>, int> u,r;
	for(int i = 1; i < (1 << (int)((n+1)/2)); i++){
		int ta=0, tb=0, tc=0;
		for(int j = 0; j < n/2+1; j++){
			if((i & (1 << j)) != 0){
				ta += a[j]; tb += b[j];
				tc += c[j];
			}
		}
		int g = gcd(ta, tb);
		if(g != 0){
			ta /= g; tb /= g;
		}
		pair<int, int> p(ta,tb);
		if(u.find(p) != u.end()){
			u[p] = min(u[p], tc);
		}
		else{
			u[p] = tc;
		}
	}
	for(int i = 1; i < (1 << (n/2)); i++){
		int ta=0, tb=0, tc=0;
		for(int j = 0; j < n/2; j++){
			if((i & (1 << j)) != 0){
				ta += a[j]; tb += b[j];
				tc += c[j];
			}
		}
		int g = gcd(ta, tb);
		if(g != 0){
			ta /= g; tb /= g;
		}
		pair<int, int> p(ta,tb);
		if(r.find(p) != r.end()){
			r[p] = min(u[p], tc);
		}
		else{
			r[p] = tc;
		}
	}
	int ans = (int)1e8;
	for(auto itr = r.begin(); itr != r.end(); ++itr){
		if(ma == itr->first.first && mb == itr->first.second){
			ans = min(ans, itr->second);
		}
	}
	for(auto itr = u.begin(); itr != u.end(); ++itr){
		if(ma == itr->first.first && mb == itr->first.second){
			ans = min(ans, itr->second);
		}
		for(auto j = r.begin(); j != r.end(); ++j){
			if(cdekiru(itr->first,j->first)){
				ans = min(ans, itr->second+j->second);
			}
		}
	}
	if(ans == (int)1e8){ans = -1;}
	cout << ans << endl;

	return 0;
}

