		q.insert(ppo{x,y,z});
		return;
	}
	dfs(pos+1,x+a[pos],y+b[pos],z+c[pos]);
	dfs(pos+1,x,y,z);
}
void dd(int pos,int x,int y,int z){
	if(pos==n+1){
		for(int i=1;i<=8;i++){
			int ka=ma*i,kb=mb*i;
			auto it=q.lower_bound(ppo{ka-x,kb-y,0});
			if(it!=q.end()){
				int da=it->a+x;
				int db=it->b+y;
				if(da==ka&&db==kb){
					ans=min(ans,z+it->c);
				}
			}
		}
		return;
	}
	dd(pos+1,x+a[pos],y+b[pos],z+c[pos]);
	dd(pos+1,x,y,z);
}
