void search(int k)
{
    static vector<int> subset;

    if (k == N)
    {
        int mA = 0, mB = 0, cost = 0;
        for (int x : subset)
        {
            // cout << x << ' ';
            int a, b, c;
            tie(a, b, c) = items[x];
