            cost += c;
        }
        // cout << '\n';
        if (Ma * mB == Mb * mA && cost != 0 && mA != 0 && mB != 0)
            amount = min(amount, cost);
    }
    else
    {
        search(k + 1);
        subset.push_back(k);
        search(k + 1);
        subset.pop_back();
    }
}

