const int inf = 1e9;

int dp[50][1050][1050];

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    VI A(N);
    VI B(N);
    VI C(N);
    rep(i, N){
        cin >> A[i] >> B[i] >> C[i];
    }

    rep(i, 50){
      rep(j, 1050){
        rep(k, 1050){
          dp[i][j][k] = inf;
        }
      }
    }
    dp[0][0][0] = 0;
    // i番目の薬剤を選んだ結果をi+1に入れるとする
    rep(i, N){
      int a = A[i];
      int b = B[i];
      int c = C[i];
      rep(j, 1040){
        rep(k, 1040){
          if(dp[i][j][k]==inf) continue;
          // 選ばない場合
          dp[i+1][j][k] = dp[i][j][k];

          // 選ぶ場合
          chmin(dp[i+1][j+a][k+b], dp[i][j][k] + c);
        }
      }
    }

    int mi = inf;
    rep(a, 1050){
      rep(b, 1050){
        if(a==0 && b==0) continue;
        if(Ma * b == Mb * a){
          chmin(mi, dp[N][a][b]);
        }
      }
    }

    if(mi==inf){
      p(-1);
    }else{
      p(mi);
    }

    return 0;
}

