const int INF = 10000;

signed main() {
  int N, Ma, Mb;
  cin >> N >> Ma >> Mb;

  vector<int> a(N), b(N), c(N);

  REP(i, N) {
    cin >> a[i] >> b[i] >> c[i];
  }

  vector<vector<vector<int>>> dp(N+1, vector<vector<int>>(410, vector<int>(410, INF)));

  dp[0][0][0] = 0;

  REP(i, N) {
    REP(j, 410) {
      REP(k, 410) {
        int aa;
        if(j-a[i] < 0 || k-b[i] < 0) {
          aa = INF;
        } else {
          aa = dp[i][j-a[i]][k-b[i]];
        }

        dp[i+1][j][k] = min(aa + c[i], dp[i][j][k]);
      }
    }
  }

  int result = INF;

  FOR(n, 1, 410) {
    if(Ma * n >= 410 || Mb * n >= 410) {
      break;
    }
    result = min(result, dp[N][Ma * n][Mb * n]);
  }

  if(result >= INF) {
    result = -1;
  }

  cout << result << endl;
}

