const int INF = 1 << 29;

int N, Ma, Mb, A[40], B[40], C[40];

void dfs(int idx, int x, int y, int z, int end, vector< pair< pair< int, int >, int > > &odd)
{
  if(idx == end) {
    odd.emplace_back(make_pair(x, y), z);
  } else {
    dfs(idx + 1, x + A[idx], y + B[idx], z + C[idx], end, odd);
    dfs(idx + 1, x, y, z, end, odd);
  }
}

int main()
{
  cin >> N >> Ma >> Mb;

  vector< pair< int, int > > range;
  vector< pair< pair< int, int >, int > > a, b;
  for(int i = 1; i <= 400; i++) {
    int low = i * Mb;
    if(low % Ma != 0) continue;
    if(low / Ma > 400) continue;
    range.emplace_back(i, low / Ma);
  }
  for(int i = 0; i < N; i++) {
    cin >> A[i] >> B[i] >> C[i];
  }
  dfs(0, 0, 0, 0, N, a);
  dfs(0, 0, 0, 0, N, b);


  int call1[401][401], call2[401][401];
  fill_n(*call1, 401 * 401, INF);
  fill_n(*call2, 401 * 401, INF);
  call1[0][0] = 0;
  call2[0][0] = 0;
  for(auto &s : a) {
    auto &q = s.first;
    call1[q.first][q.second] = min(call1[q.first][q.second], s.second);
  }
  int ret = INF;
  for(auto &s : b) {
    auto &q = s.first;
    call2[q.first][q.second] = min(call2[q.first][q.second], s.second);
  }

  for(auto &s : range) {
    int sumA = s.first;
    int sumB = s.second;
    for(int j = 0; j <= sumA; j++) {
      for(int k = 0; k <= sumB; k++) {
        ret = min(ret, call1[j][k] + call2[sumA - j][sumB - k]);
      }
    }
  }
  if(ret == INF) cout << -1 << endl;
  else cout << ret << endl;
}

