using namespace std;

typedef struct {
  int a;
  int b;
  int c;
} med;

typedef struct {
  int c;
  vector< vector<int> > used_list;
} dp;

bool contains(vector<int> v, int n)
{
  rep(i, v.size()) {
    if(v[i] == n) return true;
  }
  return false;
}

int main()
{
  int N, Ma, Mb;
  cin >> N >> Ma >> Mb;

  int amax = 0, bmax = 0;

  vector<med> meds(N);
  rep(i, N) {
    cin >> meds[i].a >> meds[i].b >> meds[i].c;
    amax += meds[i].a;
    bmax += meds[i].b;
  }

  vector< vector<dp> > cost(amax + 1);
  rep(i, amax + 1)
    cost[i].resize(bmax + 1);

  rep(i, amax + 1) rep(j, bmax + 1) {
    if(i == 0 && j == 0) {
      cost[i][j].c = 0;
      vector<int> v;
      cost[i][j].used_list.push_back(v);
    }
    else {
      dp d;
      d.c = -1;
      rep(k, N) {
	int a = i - meds[k].a;
	int b = j - meds[k].b;
	if(a >= 0 && b >= 0 && cost[a][b].c >= 0) {
	  rep(l, cost[a][b].used_list.size()) {
	    if(!contains(cost[a][b].used_list[l], k)) {
	      int t = cost[a][b].c + meds[k].c;
	      if(d.c == -1 || t < d.c) {
		d.c = t;
		d.used_list.clear();
		d.used_list.push_back(cost[a][b].used_list[l]);
		d.used_list[0].push_back(k);
	      } else if(t == d.c) {
		d.used_list.push_back(cost[a][b].used_list[l]);
		d.used_list.back().push_back(k);
	      }
	    }
	  }
	}
      }
      cost[i][j] = d;
    }
  }

  int m = -1;
  for(int i = 1; Ma * i <= amax && Mb * i <= bmax; i++) {
    if(cost[Ma * i][Mb * i].c != -1) {
      if(m == -1) m = cost[Ma * i][Mb * i].c;
      else m = min(m, cost[Ma * i][Mb * i].c);
    }
  }
  cout << m << endl;
  return 0;
}

