const int INF = 10000000;
int n, ma, mb;
int a[45], b[45], c[45];
int dp[45][405][405];

int rec(int i, int  A, int B){
    if (dp[i][A][B] > 0){
        return dp[i][A][B];
    }

    if (A > 0 && B > 0 && ma*B == mb*A){
        return dp[i][A][B] = 0;
    }

    if (i == n){
        return INF;
    }

    int ret = INF;
    ret = min(ret, rec(i + 1, A, B));

    ret = min(ret, c[i] + rec(i + 1, A + a[i], B + b[i]));


    return dp[i][A][B] = ret;

}

int main(void){

    cin >> n >> ma >> mb;

    for (int i = 0; i < n; i++){
