            for (int k = 0; k <= 400; k++){
                dp[i][j][k] = -1;
            }
        }
    }

    int ans = rec(0, 0, 0);

    if (ans >= INF){
        cout << -1 << endl;
    }
    else{
        cout << ans << endl;
    }

}

