typedef struct {
	int a;
	int b;
	int c;
	int exist;
}Drag;

bool next_choice(std::vector<Drag> *d, long int *n, int *keta) {
	for(int i = 0; i < (*d).size(); ++i)
		if ((*d)[i].exist)
			(*d)[i].exist = false;
		else {
			(*d)[i].exist = true;
			(*n)++;
			if (i >= *keta)
				(*keta)++;
			return true;
		}
	return false;
}

Drag drag_mix(std::vector<Drag> d, std::vector<std::vector<Drag>> *v, int min, long int n, int keta) {
	int keta_tmp = keta - 1;
	Drag price = { d[keta_tmp].a, d[keta_tmp].b, d[keta_tmp].c, 1};

	long int num_tmp = n - ((long int)1 << keta_tmp);
	long int tmp = 1023;

	for (int i = 0; i < 4; ++i)
		if (keta_tmp > i * 10) {
			long int a_tmp = (num_tmp >> i * 10) & tmp;
			price.a += v->at(i).at(a_tmp).a;
			price.b += v->at(i).at(a_tmp).b;
			price.c += v->at(i).at(a_tmp).c;
		}
		else {
			int i_tmp = keta_tmp / 10;
			if (n % ((long int)1 << (i_tmp * 10)) == 0) {
				long int j_tmp = keta_tmp % 10;
				v->at(i_tmp).at(j_tmp).a = d[keta_tmp].a;
				v->at(i_tmp).at(j_tmp).b = d[keta_tmp].b;
				v->at(i_tmp).at(j_tmp).c = d[keta_tmp].c;
			}
			break;
		}

	return price;
}

int main() {
	int n;
	double ma, mb;
	std::cin >> n;
	std::cin >> ma;
	std::cin >> mb;

	std::vector<Drag> drag(n);
	for (int i = 0; i < n; ++i) {
		std::cin >> drag[i].a;
		std::cin >> drag[i].b;
		std::cin >> drag[i].c;
	}

	Drag zero = { 0, 0, 0, 1 };
	std::vector<std::vector<Drag>> v(4, std::vector<Drag>(1024));
	for (int i = 0; i < 4; ++i)
		v.at(i).at(0) = zero;

	long int num = 0;
	int keta = 0;
	double m = ma / mb;
	Drag mix;
	int min = -1;
	while(next_choice(&drag, &num, &keta)){
		mix = drag_mix(drag, &v, min, num, keta);
		if (mix.exist && (double)mix.a / mix.b == m)
			if(min == -1 || mix.c < min)
				min = mix.c;
	};

	std::cout << min;
}

