const int inf = 5000;
const int nmax = 40;
const int abmax = 10;
using namespace std;
int dp[nmax+1][nmax * abmax+1][nmax * abmax+1];

int main(){
  int n,ma,mb;

  cin >> n >> ma >> mb;
  vector<int> a(n),b(n),c(n);
  for(int i = 0; i < n; i++){
    cin >> a[i] >> b[i] >> c[i];
  }

  for(int i = 0; i < n+1; i++){
    for(int j = 0; j < nmax * abmax + 1; j++){
      for(int k = 0; k < nmax * abmax + 1; k++){
        dp[i][j][k] = inf;
      }
    }
  }
  dp[0][0][0] = 0;

  for(int i = 0; i < n; i++){
    for(int ca = 0; ca < nmax * abmax + 1; ca++){
      for(int cb = 0; cb < nmax * abmax + 1; cb++){
        if(dp[i][ca][cb] == inf) continue;
        // i番目を入れないとき
        dp[i+1][ca][cb] = min(dp[i+1][ca][cb], dp[i][ca][cb]);
        // i番目を入れるとき
        dp[i+1][ca + a[i]][cb + b[i]] = min(dp[i+1][ca + a[i]][cb + b[i]], dp[i+1][ca][cb] + c[i]);
      }
    }
  }

  int ans = inf;
  for(int ca = 1; ca < nmax * abmax + 1; ca++){
    for(int cb = 1; cb < nmax * abmax + 1; cb++){
      if(ca * mb == cb * ma){
        ans = min(ans, dp[n][ca][cb]);
      }
    }
  }

  if(ans == inf) ans = -1;
  cout << ans << endl;
  return 0;
}

