    REP(i, 1LL << (N - N2)) {
        ll sa = 0, sb = 0, sc = 0;
        REP(j, N)
        if(i >> j & 1) sa += a[N2 + j], sb += b[N2 + j], sc += c[N2 + j];
        if(memo2.count({sa, sb}))
            memo2[{sa, sb}] = min(memo2[{sa, sb}], sc);
        else
            memo2[{sa, sb}] = sc;
    }
    ll ans = LINF;
