	int list[N+1][amax+1][bmax+1];
	for(int i=0;i<N+1;i++){
		for(int a=0;a<amax+1;a++){
			for(int b=0;b<bmax+1;b++){
				list[i][a][b]=pmax;
			}
		}
	}

	//物質AもBもないのは何も買わず、コストも0
	for(int i=0;i<=N;i++){
		list[i][0][0]=0;
	}

	//動的計画法のメイン部分
	int a,b,p;
	for(int i=1;i<=N;i++){

		cin>>a>>b>>p;
		for(int anow=a;anow<=amax;anow++){
			for(int bnow=b;bnow<=bmax;bnow++){
				if( (list[i-1][anow-a][bnow-b]+p)<list[i-1][anow][bnow] ){
					list[i][anow][bnow]=list[i-1][anow-a][bnow-b]+p;
				}
				else list[i][anow][bnow]=list[i-1][anow][bnow];
			}
		}


	}


