    for(int i=0; i<N; i++)
        cin >> a[i] >> b[i] >> c[i];

    int N1 = N / 2;
    int N2 = N - N1;
    vector<pair<int, int>> G1(1 << N1), G2(1 << N2);
    G2.back() = pair<int, int>(0, 0);
    for(int i=0; i< 1<<N1; i++){
        int aa = 0, bb = 0, cc = 0;
        for(int j=0; j<N1; j++){
            if(i & 1<<j){
                aa += a[j];
                bb += b[j];
                cc += c[j];
            }
        }
        int tmp = aa * Mb - bb * Ma;
        G1[i] = pair<int, int>(tmp, cc);
    }
    for(int i=0; i< 1<<N2; i++){
        int aa = 0, bb = 0, cc = 0;
        for(int j=0; j<N2; j++){
            if(i & 1<<j){
                aa += a[j];
                bb += b[j];
                cc += c[j];
            }
        }
        int tmp = bb * Ma - aa * Mb;
        G2[i] = pair<int, int>(tmp, cc);
    }

