int main(void) {
	MYCP::DebugFlag = 0;

	LL i, j, k, n, m;
	LL ma, mb;
	cin >> n >> ma >> mb;

	VVLL ls(n, VLL(3));
	for (i = 0; i < n; i++)cin >> ls[i][0] >> ls[i][1] >> ls[i][2];

	LL mx = 500;

	vector<VVILL_TYPE> dp(n + 1, VVILL_TYPE(mx, VILL_TYPE(mx, ILL_TYPE::plus_inf())));

	dp[0][0][0] = 0;

	for (i = 1; i <= n; i++) {
		LL target = i - 1;

		for (j = 0; j < mx; j++) {
			for (k = 0; k < mx; k++) {
				LL a, b;
				a = j + ls[target][0];
				b = k + ls[target][1];

				dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j][k]);

				if (a < mx) {
					if (b < mx) {
						dp[i][a][b] = min(dp[i][a][b], dp[i - 1][j][k] + ls[target][2]);

						if (a == 1 && b == 2) {
							MYCP::DebugPrintf(dp[i][a][b].ToString());
						}
					}
				}
			}
		}
	}

	MYCP::DebugPrintf("aaa");

	MYCP::DebugPrintf(dp[n][1][2].ToString());
	MYCP::DebugPrintf(dp[n][3][3].ToString());
	MYCP::DebugPrintf(dp[n][6][6].ToString());

	auto ans = ILL_TYPE::plus_inf();
	for (i = 1; i < mx * 10; i++) {
		if (ma * i < mx && mb * i < mx) {
			ans = min(ans, dp[n][ma * i][mb * i]);
		}
	}

	if (ans == ILL_TYPE::plus_inf()) {
		cout << -1 << endl;
	}
	else
	{
		cout << ans.getN() << endl;
	}

	return 0;
}

