		for(int j = 0; j <= nmax*abmax; j++)
		{
			for(int k = 0; k <= nmax*abmax; k++)
			{
				dp[i][j][k] = inf;
			}
		}
	}


	//加える薬品数が0の場合は、物質Aも物質Bも重さは0
	dp[0][0][0] = 0;

	for(int i = 0; i < N; i++)
	{
		for(int j = 0; j <= nmax*abmax; j++)
