	{
		for(int j = 1; j <= nmax*abmax; j++)
		{
			if(i*Ma == j*Mb) ans = min(ans, dp[N][i][j]);
		}
	}

	if(ans == inf) ans = -1;
	cout << ans << endl;

	return 0;
}

