#define REP(i, n) for(int (i)=0;(i)<(n);(i)++)
#define MOD 1000000007

typedef long long ll;

using namespace std;

const int max_a = 10;
const int max_b = 10;
const int max_n = 40;
const int inf = 100000;
int a[max_n], b[max_n], c[max_n];
int dp[max_n + 1][max_n * max_a + 1][max_n * max_b + 1];

int main(){
    int N, M_a, M_b;
    cin >> N >> M_a >> M_b;
    REP(i, N) {
    	cin >> a[i] >> b[i] >> c[i];
    }

    REP(i, max_n + 1) {
	    REP(j, max_n * max_a + 1) {
	    	REP(k, max_n * max_b + 1) {
	    		dp[i][j][k] = inf;
	    	}
	    }
	}	

	// 初期条件
	dp[0][0][0] = 0;

	// dp[i + 1][j][k] : i 番目までの薬品を使って薬品a, bがj, k グラムになるときの最小コスト
    REP(i, N ) {
    	REP(j, max_n * max_a + 1) {
    		REP(k, max_n * max_b + 1) {
    			if (dp[i][j][k] == inf) {
    				continue;
    			}
    			else {
	    			dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);
	    			dp[i + 1][j + a[i]][k + b[i]] = min(dp[i + 1][j + a[i]][k + b[i]], dp[i][j][k] + c[i]);
    			}
    		}
    	}
    }

    int ans = inf;
    // a : b = M_a : M_b になる組み合わせの最小コストを求める
    for(int i = 1; i < max_n * max_a + 1; ++i) {
    	for(int j = 1; j < max_n * max_b + 1; ++j) {
    		if (i * M_b == j * M_a) ans = min(ans, dp[N][i][j]);
    	}
    }

    if (ans == inf) ans = -1;

    cout << ans << endl;
}

