int sol(int n, int x, int y) {
  if ( n < 0 && x == 0 && y == 0 ) return 0;
  if ( n < 0 ) return 1e8;
  if ( dp[n][x][y] != 1e7 ) return dp[n][x][y];

  if ( x - a[n] >= 0 && y-b[n] >= 0 ) {
    dp[n][x][y] = std::min( sol(n-1,x,y), sol(n-1,x-a[n],y-b[n])+c[n] );
  }
  else dp[n][x][y] = sol(n-1,x,y);
  return dp[n][x][y];
}

