using namespace std;

struct Mixed {
    long long a, b, c;
    static long long Ma, Mb;
    Mixed() : a(0), b(0), c(0) {}
    long long value() {
        return a * (Ma + Mb) - Ma * (a + b);
    }
    bool operator<(Mixed& rhs) {
        long long this_value = value();
        long long rhs_value = rhs.value();
        return (this_value != rhs_value ? this_value < rhs_value : this->c < rhs.c);
    }
    bool operator<(long long target) {
        long long this_value = value();
        return (this_value < target);
    }
};


//実体化
long long Mixed::Ma;
long long Mixed::Mb;

int main() {
    long long N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    Mixed::Ma = Ma;
    Mixed::Mb = Mb;

    vector<long long> a(N), b(N), c(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i] >> b[i] >> c[i];
    }

    long long ans = INT_MAX;

    //前半を列挙
    long long half_N = (N + 1) / 2;
    vector<Mixed> half1;
    for (int i = 0; i < (1 << half_N); i++) {
        Mixed tmp;
        for (int j = 0; j < half_N; j++) {
            if (i & (1 << j)) {
                //立っていたらカウント
                tmp.a += a[j];
                tmp.b += b[j];
                tmp.c += c[j];
            }
        }
        if (tmp.a * tmp.b != 0 && Ma * tmp.b == Mb * tmp.a) {
            ans = min(ans, tmp.c);
        }
        half1.push_back(tmp);
    }

    //後半を列挙
    long long another_half = N - half_N;
    vector<Mixed> half2;
    for (int i = 0; i < (1 << another_half); i++) {
        Mixed tmp;
        for (int j = 0; j < another_half; j++) {
            if (i & (1 << j)) {
                //立っていたらカウント
                tmp.a += a[j + half_N];
                tmp.b += b[j + half_N];
                tmp.c += c[j + half_N];
            }
        }
        if (tmp.a * tmp.b != 0 && Ma * tmp.b == Mb * tmp.a) {
            ans = min(ans, tmp.c);
        }
        half2.push_back(tmp);
    }

    //後半の方をソート
    sort(half2.begin(), half2.end());

    for (auto m : half1) {
        //mと合わせて比が正しくなるものをhalf2の中から2分探索
        long long need = -m.value();
        auto pair = lower_bound(half2.begin(), half2.end(), need);
        if (pair == half2.end()) {
            continue;
        }
        //最小が取れていないか
        for (auto itr = pair; ; itr--) {
            long long value = itr->value();
            if (value != need) {
                break;
            }

            //確認
            long long sum_a = m.a + itr->a;
            long long sum_b = m.b + itr->b;
            if (sum_a * sum_b == 0) {
                continue;
            }
            if (Ma * sum_b == Mb * sum_a) {
                ans = min(ans, m.c + itr->c);
            }

            if (itr == half2.begin()) {
                break;
            }
        }
    }
    if (ans == INT_MAX) {
        ans = -1;
    }

    cout << ans << endl;
}

