#define COST_MAX (40*100+1)
#define MIN(a,b)    ( ((a)<(b))?(a):(b) )

int main(){
    int N,Ma,Mb;
    int a[40],b[40],c[40],min_cost=COST_MAX;
    int Table[41][401][401];

    scanf("%d %d %d%*c",&N,&Ma,&Mb);
    for(int i=0;i<N;i++)
        scanf("%d %d %d%*c",a+i,b+i,c+i);

    for(int i=0;i<=40;i++){
        for(int j=0; j<=400; j++){
            for(int k=0; k<=400; k++){
                Table[i][j][k]=(j!=0 || k!=0)?COST_MAX:0;
            }
        }
    }
    for(int i=0;i<N;i++){
        for(int j=0; j<i*10+1; j++){
            for(int k=0; k<i*10+1; k++){
                if(Table[i][j][k]!=COST_MAX){
                    Table[i+1][j+a[i]][k+b[i]] =
                        MIN(Table[i][j+a[i]][k+b[i]], Table[i][j][k]+c[i]);
                }
            }
        }
    }

    for(int i=1; i*Ma<= 400 && i*Mb<= 400; i++){
        if(min_cost > Table[N][i*Ma][i*Mb])
            min_cost=Table[N][i*Ma][i*Mb];
    }
    printf("%d\n",(min_cost==COST_MAX)?(-1):min_cost);

    return 0;
}

