void calc(int cost, int i, int m)
{
	if (i == n)
	{
		if (m != 0)
			return;
		if (cost == 0)
			return;
		if (cost < result)
			result = cost;
	}
	else
	{
		if (cost >= result)
			return;
		//	use i
		calc(cost + v[i].val, i + 1, m + v[i].m);
		//	not use i
		calc(cost, i + 1, m);
	}
}


