int dp[41][401][401];

int main()
{
	int N, Ma, Mb;
	cin >> N >> Ma >> Mb;

	int a[41], b[41], c[41];
	for (auto i = 1; i <= N; ++i)
	{
		cin >> a[i] >> b[i] >> c[i];
	}

	for (auto i = 0; i <= N; ++i)
	{
		for (auto j = 0; j <= 400; j++)
		{
			for (auto k = 0; k <= 400; ++k)
			{
				dp[i][j][k] = INT_MAX;
			}
		}
	}
	dp[0][0][0] = 0;

	auto result = INT_MAX;
	for (auto i = 1; i <= N; ++i)
	{
		for (auto j = 1; j <= 400; ++j)
		{
			for (auto k = 1; k <= 400; ++k)
			{
				auto temp = INT_MAX;
				if (j >= a[i] && k >= b[i] && dp[i - 1][j - a[i]][k - b[i]] != INT_MAX)
				{
					temp = dp[i - 1][j - a[i]][k - b[i]] + c[i];
				}
				dp[i][j][k] = min(temp, dp[i - 1][j][k]);
				if (j * Mb == k * Ma)
				{
					result = min(result, dp[i][j][k]);
				}
			}
		}
	}

	if (result >= INT_MAX)
	{
		result = -1;
	}

	cout << result << endl;

	return 0;
}

