					dp[i+1][j][k]=min(dp[i][j-a[i]][k-b[i]]+c[i],dp[i+1][j][k]);
				}
			}
		}
	}
	int ans=INF;
	rep1(i,INF){
		if(i*Ma>asum||i*Mb>bsum) break;
		ans=min(ans,dp[N][i*Ma][i*Mb]);
	}
