typedef pair<int,int> Pii;
typedef pair<Pii,int> P;
typedef vector<int> vi;

vector < P > memo;
void calc(const vi &a,const vi &b,const vi &c, int prev, P p){
    if(prev == a.size()){
        return ;
    }
    p.fr.fr += a[prev];
    p.fr.sc += b[prev];
    p.sc    += c[prev];
    calc(a,b,c,prev+1,p);
    memo.pb(p);
    p.fr.fr -= a[prev];
    p.fr.sc -= b[prev];
    p.sc    -= c[prev];
    calc(a,b,c,prev+1,p);
    return ;
}
int main(){
    int N;
    cin >> N;
    int Ma,Mb;
    cin >> Ma >> Mb;
    vector < Pii > M;
    rep(i,50/min(Ma,Mb)){
        M.pb(mk(Ma*(i+1),Mb*(i+1)));
    }

    int a[50],b[50],c[50];
    vi a1,b1,c1;
    vi a2,b2,c2;
    rep(i,N){
        cin >> a[i] >> b[i] >> c[i];
        if(i < N/2){
            a1.pb(a[i]);
            b1.pb(b[i]);
            c1.pb(c[i]);
        }
        else{
            a2.pb(a[i]);
            b2.pb(b[i]);
            c2.pb(c[i]);
        }
    }
    P ini = mk(mk(0,0),0);
    memo.pb(ini);
    calc(a1,b1,c1,0,ini);
    vector < P > sum1 = memo;
    sort(sum1.begin(),sum1.end());
    memo.clear();
    memo.pb(ini);
    calc(a2,b2,c2,0,ini);
    vector < P > sum2 = memo;
    sort(sum2.begin(),sum2.end());
    map < Pii,int > tar;
    rep(i,sum2.size()){
        tar[mk(sum2[i].fr.fr,sum2[i].fr.sc)] = sum2[i].sc;
    }

    // puts("sum1");
    // rep(i,sum1.size()){
    //     cout << sum1[i].fr.fr << " " << sum1[i].fr.sc << " " << sum1[i].sc << "\n";
    // }

    // puts("sum2");
    // rep(i,sum2.size()){
    //     cout << sum2[i].fr.fr << " " << sum2[i].fr.sc << " " << sum2[i].sc << "\n";
    // }
    int ans = INF;
    rep(i,sum1.size()){
        rep(j,M.size()){
            Pii m = M[j];
            P p = sum1[i];
            if(m.fr < p.fr.fr && m.sc < p.fr.sc)break;
            if(m.fr < p.fr.fr || m.sc < p.fr.sc)continue;
            m.fr -= p.fr.fr;
            m.sc -= p.fr.sc;
            if(tar[m] != 0){
                ans = min(ans,sum1[i].sc + tar[m]);
            }
        }
        //cout << ans << endl;
    }
    if(ans == INF){
        ans = -1;
    }
    cout << ans << endl;

    return 0;
}

