    int res = rec(0, 0, 0, 0);
    int min_cost = INF;
    rep(i, 11)
        rep(j, 11) {
            if (memo[i][j] != 0)
                min_cost = min(min_cost, memo[i][j]);
        }


    if (res != INF) P (min_cost);
    else P(-1);

    return 0;
}

