const int inf = 1e9+7;

pair<int,int> simplify(int a, int b) {
	for (int i=2; i<=max(a,b); i++) {
		if (a%i==0 and b%i==0) {
			a/=i;
			b/=i;
		}
	}
	return {a,b};
}

