int main() {
  std::cin >> N >> Ma >> Mb;
  int ma = 0, mb = 0, mc = 0;
  for(int i = 0; i < N; ++i) {
    std::cin >> a[i] >> b[i] >> c[i];
    ma += a[i]; mb += b[i]; mc += c[i];
  }
  for(int i = 0; i <= N; ++i) for(int j = 0; j <= ma; ++j) {
    std::fill(dp[i][j], dp[i][j]+mb+1, INF);
  }
  dp[0][0][0] = 0;
  for(int i = 1; i <= N; ++i) for(int j = 0; j <= ma; ++j) {
    for(int k = 0; k <= mb; ++k) {
      int aa = a[i-1], bb = b[i-1], cc = c[i-1];
