    int n, ma, mb;
    cin >> n >> ma >> mb;

    vector<int> a(n);
    vector<int> b(n);
    vector<int> c(n);

    for (int i = 0; i < n; ++i) {
        int x, y, z;
        cin >> x >> y >> z;

        a[i] = x;
        b[i] = y;
        c[i] = z;
    }

    auto maxWeight = n * 20;
    vector<vector<int>> dp(maxWeight + 1, vector<int>(maxWeight + 1, 1e9));

    for (int i = 0; i < n; ++i) {
        auto x = a[i];
        auto y = b[i];
        for (int l = 1; l <= maxWeight - x; ++l) {
            for (int r = 1; r <= maxWeight - y; ++r) {
                dp[x + l][y + r] = min(dp[x + l][y + r], dp[l][r] + c[i]);
            }
        }
        dp[x][y] = min(dp[x][y], c[i]);
    }

    int best = 1e9;
    int x = 0;
    int y = 0;

    while (true) {
        x += ma;
        y += mb;
        if ((x >= dp.size()) || (y >= dp.size())) {
            break;
        }
        best = min(best, dp[x][y]);
    }
    if (best == 1e9) {
        best = -1;
    }
    cout << best << "\n";
}





int main() {
    int t = 1;
//    cin >> t;
    while (t > 0) {
        oneCase();
        --t;
    }

    return 0;
}

