void get_all_sum(vector<int> selected_chemicals, int* sum_a, int* sum_b, int* sum_c){
  for(int chemical : selected_chemicals){
    *sum_a += a[chemical];
    *sum_b += b[chemical];
    *sum_c += c[chemical];
  }
}

void comb(int current_chemical, vector<int> selected_chemicals){
  int sum_a=0, sum_b=0, sum_c=0;
  selected_chemicals.push_back(current_chemical);
  get_all_sum(selected_chemicals, &sum_a, &sum_b, &sum_c);
