      if(find(selected_chemicals.begin(), selected_chemicals.end(), i) == selected_chemicals.end()){
        comb(i, selected_chemicals);
      }
    }
  }
  else if(Ma*sum_b == Mb*sum_a && sum_c < min_cost){
    min_cost = sum_c;
  }
}

