                pii ni=mp((j+val[i+1].first)/div,(k+val[i+1].second)/div);
                cmin(dp[i+1][ni.first][ni.second],dp[i][j][k]+c[i+1]);
            }
        }
    }
    if(dp[n-1][comp.first][comp.second]==INF)return puts("-1")*0;
    else cout<<dp[n-1][comp.first][comp.second]<<endl;
}

