	{
		lint a, b, c;
		bool operator<(A o)
		{
			return this->b * o.a < o.b * this->a;
		}
	};
	vect<A> a(n);
	rep(i, n)
		cin >> a[i].a >> a[i].b >> a[i].c;

	sort(all(a));

	if (A{ ma, mb, 0 } < a[0] || a.back() < A{ ma,mb,0 })
	{
		cout << -1 << endl;
		ret;
	}

	lint ans = intmax;
	rep(i, n)
	{
		if (a[i].a * mb == a[i].b * ma)
		{
			ans = mmin(ans, a[i].c);
		}
	}

	rep(i, n)
	{
		repi(j, i + 1, n)
		{
			if (A{ ma, mb, 0 } < a[i] || a[j] < A{ ma,mb,0 })
			{
				continue;
			}

			lint p = ma * a[i].b - mb * a[i].a;
			lint q = -ma * a[j].b + mb * a[j].a;

			if (p < 0 && q < 0)
			{
				p *= -1;
				q *= -1;
			}

			if (p < 0 || q < 0)
				continue;

			lint g = gcd(p, q);
			p /= g;
			q /= g;

			ans = mmin(ans, p * a[j].c + q * a[i].c);
		}
	}

	cout << ans << endl;
	return 0;
