        continue;
      int s = ((t + b) / mb) * ma - a;
      if (s < 0 || s > 200)
        continue;
      if (ma * (b + t) == mb * (a + s)) {
        if (lt[s][t]) {
          ans = min(ans, lt[s][t] + c);
        }
      }
    }
  }
  if (ans == 1e9) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }
}

