using namespace std;

int main()
{
    int N, Ma, Mb;
    scanf("%d %d %d\n", &N, &Ma, &Mb);
    vector<tuple<int, int>> plus;
    vector<tuple<int, int>> minus;
    int plus_sum = 0;
    int minus_sum = 0;
    int result = INT_MAX;
    for (int i = 0; i < N; ++i){
        int ai, bi, ci;
        scanf("%d %d %d\n", &ai, &bi, &ci);
        int value = bi * Ma - ai * Mb;
        if (value > 0){
            plus.emplace_back(ci, value);
            plus_sum += value;
        }else if (value < 0){
            minus.emplace_back(ci, abs(value));
            minus_sum += abs(value);
        }else{
            result = min(ci, result);
        }
    }
    sort(plus.begin(), plus.end(), [](tuple<int, int>& l, tuple<int, int>& r){return get<1>(l) < get<1>(r);});
    sort(minus.begin(), minus.end(), [](tuple<int, int>& l, tuple<int, int>& r){return get<1>(l) < get<1>(r);});
    const int sum_max = min(plus_sum, minus_sum);
    vector<vector<int>> dp_plus(plus.size(), vector<int>(sum_max + 1, -1));
    vector<vector<int>> dp_minus(minus.size(), vector<int>(sum_max + 1, -1));
    function<int(int, int)> searchPlus = [&](int i, int sum){
        if (sum == 0) return 0;
        if (i >= plus.size() || sum < 0 || sum > sum_max) return INT_MAX;
        if (dp_plus[i][sum] != -1) return dp_plus[i][sum];
        int ret = INT_MAX;
        if (searchPlus(i + 1, sum) != INT_MAX) ret = min(searchPlus(i + 1, sum), ret);
        if (searchPlus(i + 1, sum - get<1>(plus[i])) != INT_MAX) ret = min(searchPlus(i + 1, sum - get<1>(plus[i])) + get<0>(plus[i]), ret);
        dp_plus[i][sum] = ret;
        return ret;
    };
    function<int(int, int)> searchMinus = [&](int i, int sum){
        if (sum == 0) return 0;
        if (i >= minus.size() || sum < 0 || sum > sum_max) return INT_MAX;
        if (dp_minus[i][sum] != -1) return dp_minus[i][sum];
        int ret = INT_MAX;
        if (searchMinus(i + 1, sum) != INT_MAX) ret = min(searchMinus(i + 1, sum), ret);
        if (searchMinus(i + 1, sum - get<1>(minus[i])) != INT_MAX) ret = min(searchMinus(i + 1, sum - get<1>(minus[i])) + get<0>(minus[i]), ret);
        dp_minus[i][sum] = ret;
        return ret;
    };
    for (int sum = 1; sum <= sum_max; ++sum){
        int cost_plus = searchPlus(0, sum);
        if (cost_plus == INT_MAX) continue;
        int cost_minus = searchMinus(0, sum);
        if (cost_minus == INT_MAX) continue;
        result = min(cost_plus + cost_minus, result);
    }
    if (result == INT_MAX){
        puts("-1");
    }else{
        printf("%d\n", result);
    }
}

