void solve()
{
	ll n,ma,mb;  cin >> n >> ma >> mb;
	vector<tuple<ll,ll,ll>> abc(n);
	rep(i,0,n-1){ ll a; ll b; ll c; cin>>a>>b>>c; abc[i]={a,b,c}; }


	ll m=min(20LL,n);
	ll mm=n-m;

	map<ll,ll> mp;

	ll ans=INF;
	rep(s,1,(1LL<<mm)-1){
		tll sm{0,0,0};
		rep(i,0,mm-1){
			if (!(s&(1LL<<i)))continue;

			ll ii = i+m;
			sm+=abc[ii];
		}

		ll a,b,c;  tie(a,b,c) = sm;
		ll v=ma*b-mb*a;
		if (v==0){
			chmin(ans,c);
			continue;
		}
		if (mp.count(v)==0 or c<mp[v]){
			mp[v]=c;
		}
	}

	rep(s,1,(1LL<<m)-1){
		tll sm{0,0,0};
		rep(i,0,m-1){
			if (!(s&(1LL<<i)))continue;

			sm+=abc[i];
		}

		ll a,b,c;  tie(a,b,c) = sm;
		ll v=ma*b-mb*a;
		if (v==0){
			chmin(ans,c);
			continue;
		}

		if (mp.count(-v)==1){
			ll c2=mp[v];
			chmin(ans,c+c2);
		}
	}
	if (ans==INF) ans=-1;
	cout << ans << '\n';
}


