	cin >> n >> ma >> mb;
	rep(i, 411) rep(j, 411) dp[i][j] = inf;
	for(ll i = 0; i < n; ++i){
		cin >> a[i] >> b[i] >> c[i];
		ll x = a[i], y = b[i], z = __gcd(a[i], b[i]);
		x /= z, y /= z;
		if(z < dp[x][y]){
			dp[x][y] = z;
			mask[x][y] = (1LL << i);
		}
	}
	set<pii> st;
