			x /= gcd, y /= gcd;
			g[i][j] = mp(x, y);
		}
	}
	for(ll i = 0; i < n; ++i){
		for(int x = 1; x <= 400; ++x){
			for(int y = 1; y <= 400; ++y){
				int u = x + a[i], v = y + a[i];
				int f = g[x][y].F, s = g[x][y].S;
				int l = g[u][v].F, r = g[u][v].S;
