					dp[f][s] + c[i] < dp[l][r]){
						dp[l][r] = dp[f][s] + c[i];
						mask[l][r] = (mask[f][s] + (1LL << i));
					}	
			}
		}
	}

	cout << (dp[ma][mb] == inf ? -1 : dp[ma][mb]) << '\n';
}




