void build(int bg, int en, vector<goods>& t, map<pii,int>& ans) {

	int m = en - bg;
	for (int i = 0; i < (1 << m); i++) {
		int aa = 0, bb = 0, cc = 0;

		for (int j = 0; j < m; j++) {
			if ((i >> j) & 1) {
				aa += t[bg + j].a;
				bb += t[bg + j].b;
				cc += t[bg + j].c;
			}
		}
		if (ans.count({ aa,bb }) == 0 || ans[{aa,bb}] > cc)
		{
			ans[{aa, bb}] = cc;
		}
	}
}

