template<class T=int> inline T gcd(T x, T y) { if (!y) return x; return gcd(y, x%y); }


class Solution {
public:
    int ans = 5000, dp[41][401][401];
    int a[41], b[41], c[41], n, ma, mb;

    void recur(int x, int asum, int bsum, int cost) {
        int g = gcd(asum, bsum);
        if (asum / g == ma and bsum / g == mb) {
            ans = min(ans, cost);
            if (dp[x][asum][bsum] < cost) return;
            dp[x][asum][bsum] = cost;
        }
        if (x == n) return;
        recur(x+1, asum+a[x+1], bsum+b[x+1], cost+c[x+1]);
        recur(x+1, asum, bsum, cost);
    }

    void solve(std::istream& in, std::ostream& out) {
        in >> n >> ma >> mb;
        rep(i, 1, n+1, 1) {
            in >> a[i] >> b[i] >> c[i];
        }
        rep(i, 0, 41, 1) rep(j, 0, 401, 1) rep(k, 0, 401, 1) dp[i][j][k] = 5000;
        recur(0, 0, 0, 0);
        if (ans == 5000) ans = -1;
        out << ans << endl;
    }
};

void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
