ll search(ll pos, vll& a, vll& b, vll& c, ll Ma, ll Mb, ll ma, ll mb, ll mc, ll c_sum){
  if(pos>=a.size()) return c_sum;
  if(ma!=0 && mb!=0){
    ll k = ma/Ma;
    if(Ma*k==ma && Mb*k==mb){
      return mc;
    }
  }
  ll tmp1 = search(pos+1, a, b, c, Ma, Mb, ma, mb, mc, c_sum);
  ll tmp2 = search(pos+1, a, b, c, Ma, Mb, ma+a[pos], mb+b[pos], mc+c[pos], c_sum);
  return min(tmp1, tmp2);
}

