int gcd(int a, int b){
    if(a == 0) return b;
    if(b == 0) return a;
    return __gcd(a, b);
}

int fun(int idx, int a, int b, int c){
    if(idx==n) return INF;
    int g = gcd(a, b);
    int aa = a/g, bb = b/g;
    int ans = INF;
    if(aa==ma && bb==mb) ans = c;
    ans = min(ans, fun(idx+1, a+vs[idx].a, b+vs[idx].b, c+vs[idx].c));
    ans = min(ans, fun(idx+1, a, b, c));
    return ans;
}

