            if (ans > sumc + pairs1[ok].second && sumc + pairs1[ok].second > 0) {
                ans = sumc + pairs1[ok].second;
            } 
        } 
    }

    if (ans == INFLL && ans1 == INFLL) {
        cout << -1 << endl;
