int dp[41][401][401];

int main(){

	int n,ma,mb;
	cin>>n>>ma>>mb;

	vector<int> a(n),b(n),c(n);
	for(int i=0;i<n;i++){
		cin>>a[i]>>b[i]>>c[i];
	}

	int N=n/2,M=n-N;
	int cost1[401][401],cost2[401][401];
	for(int i=0;i<401;i++){
		for(int j=0;j<401;j++) cost1[i][j]=cost2[i][j]=1e8;
	}

	for(int bit=0;bit<(1<<N);bit++){
		int a_sum=0,b_sum=0,c_sum=0;
		for(int i=0;i<N;i++){
			if( bit&(1<<i) ) a_sum+=a[i],b_sum+=b[i],c_sum+=c[i];
		}
		cost1[a_sum][b_sum]=min(cost1[a_sum][b_sum],c_sum);
	}

	for(int bit=0;bit<(1<<M);bit++){
		int a_sum=0,b_sum=0,c_sum=0;
		for(int i=0;i<M;i++){
			if( bit&(1<<i) ) a_sum+=a[N+i],b_sum+=b[N+i],c_sum+=c[N+i];
		}
		cost2[a_sum][b_sum]=min(cost2[a_sum][b_sum],c_sum);
	}

	int res=1e8;
	for(int i=1;i<=400;i++){
		int A=ma*i,B=mb*i;
		if(A>400 || B>400) break;

		for(int LA=0;LA<=400;LA++){
			int RA=A-LA;
			if(RA<0) break;
			for(int LB=0;LB<=400;LB++){
				int RB=B-LB;
				if(RB<0) break;
				res=min(res,cost1[LA][LB]+cost2[RA][RB]);
			}
		}

	}

	if(res==1e8) res=-1;
	cout<<res<<endl;


}

