struct PatternA {
	int a, b, c;
	PatternA(int a0, int b0, int c0) : a(a0), b(b0), c(c0) {}
	PatternA() : a(0), b(0), c(0) {}
	bool operator<(const PatternA& o) const {
		if (a * o.b == o.a * b) {
			return c < o.c;
		}
		else {
			return a*o.b < o.a*b;
		}
	}
};
struct PatternB {
	int a, b, c;
	PatternB(int a0, int b0, int c0) : a(a0), b(b0), c(c0) {}
	PatternB() : a(0), b(0), c(0) {}
	bool operator<(const PatternB& o) const {
		if (a * o.b == o.a * b) {
			return c < o.c;
		}
		else {
			return a*o.b > o.a*b;
		}
	}
};

int main()
{
	int n, ma, mb;
	int a[40], b[40], c[40];
	scanf("%d%d%d", &n, &ma, &mb);
	for (int i = 0; i < n; i++) {
		scanf("%d%d%d", &a[i], &b[i], &c[i]);
	}
	std::vector<PatternA> va;
	std::vector<PatternB> vb;
	int pan = std::min(20, n);
	int pbn = n - pan;
	for (int i = 1; i < (1<<pan); i++) {
		PatternA p;
		for (int j = 0; j < pan; j++) {
			if (i&(1 << j)) {
				p.a += a[j];
				p.b += b[j];
				p.c += c[j];
			}
		}
		va.push_back(p);
	}
	for (int i = 1; i < (1<<pbn); i++) {
		PatternB p;
		for (int j = 0; j < pan; j++) {
			if (i&(1 << j)) {
				p.a += a[j];
				p.b += b[j];
				p.c += c[j];
			}
		}
		vb.push_back(p);
	}
	std::sort(va.begin(), va.end());
	std::sort(vb.begin(), vb.end());
	int ia = 0;
	int ib = 0;
	int ret = INT_MAX;
	while (ia < (int)va.size() && ib < (int)vb.size()) {
		int aa = va[ia].a + vb[ib].a;
		int bb = va[ia].b + vb[ib].b;
		int cc = va[ia].c + vb[ib].c;
		if (aa * mb == bb * ma) {
			ret = std::min(ret, cc);
			ia++;
			continue;
		}
		if (aa * mb < bb * ma) {
			if (ia < (int)va.size() - 1) {
				ia++;
				continue;
			}
			else if (ib < (int)vb.size() - 1) {
				ib++;
				continue;
			}
			else {
				break;
			}
		} else  {
			if (ib < (int)vb.size() - 1) {
				ib++;
				continue;
			}
			else if (ia < (int)va.size() - 1) {
				ia++;
				continue;
			}
			else {
				break;
			}
		}
	}
	for (int i = 0; i < (int)va.size(); i++) {
		int aa = va[i].a;
		int bb = va[i].b;
		int cc = va[i].c;
		if (aa * mb == bb * ma) {
			ret = std::min(ret, cc);
			continue;
		}
	}
	for (int i = 0; i < (int)vb.size(); i++) {
		int aa = vb[i].a;
		int bb = vb[i].b;
		int cc = vb[i].c;
		if (aa * mb == bb * ma) {
			ret = std::min(ret, cc);
			continue;
		}
	}
	if (ret == INT_MAX) {
		ret = -1;
	}
	printf("%d\n", ret);
	return 0;
}

