//ビット全探索(n択m個)
void bit_tannsaku(long long int n,long long int m){
    long long int number[50]={1};
    for(int i=0;i<30;i++){
        number[i+1]=n*number[i];
    }
    for(int i=0;i<number[m];i++){
        atmp=0;
        btmp=0;
        costmp=0;
        for(int j=0;j<m;j++){
            long long int tmp=i;
            sousa(j,(tmp/number[j])%n);
        }
        num[atmp][btmp]=min(costmp,num[atmp][btmp]);
    }
}



