    for(int i = 0; i < n; ++i){
        cin >> c.at(i).at(0) >> c.at(i).at(1) >> c.at(i).at(2);
    }

    vector<vector<ll>> price(
        n * 10 + 1, vector<ll>(n * 10 + 1, numeric_limits<ll>::max()));
    price.at(0).at(0) = 0;
    for(int i = 0; i < n; ++i){
        for(int a = price.size() - 1; a >= 0; --a){
            for(int b = price.at(a).size() - 1; b >= 0; --b){
                if(price.at(a).at(b) == numeric_limits<ll>::max()){
                    continue;
                }
                price.at(a + c.at(i).at(0)).at(b + c.at(i).at(1)) = min(
                    price.at(a + c.at(i).at(0)).at(b + c.at(i).at(1)),
                    price.at(a).at(b) + c.at(i).at(2)
                );
            }
        }
    }

    ll ans = -1;
    for(int i = 1; i < price.size(); ++i){
        for(int j = 1; j < price.at(i).size(); ++j){
            if(price.at(i).at(j) == numeric_limits<ll>::max()){
                continue;
            }
            if(i % ma == 0 && j % mb == 0 && i / ma == j / mb){
                if(ans == -1){
                    ans = price.at(i).at(j);
                }else{
                    ans = min(ans, price.at(i).at(j));
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

