int n,ma,mb,a[45],b[45],c[45],dp[45][405][405];

int f(int idx,int num,int den){
	if(idx>n){
		if(num==0 or den==0) return (int)(1e5);
		int g=__gcd(num,den);
		num/=g;
		den/=g;
		if(num==ma and den==mb) return 0;
		return (int)(1e5);
	}
	if(dp[idx][num][den]!=-1) return dp[idx][num][den];
	int ans=1e5;
	ans=min(ans,c[idx]+f(idx+1,num+a[idx],den+b[idx]));
	ans=min(ans,f(idx+1,num,den));
	return dp[idx][num][den]=ans;
}

