int n, ma, mb;
int a[50], b[50], c[50];

int solve(int cos, int num, int aa, int bb){
    if(num == n){
        if(aa * mb == bb*ma){
            if(aa == 0 && bb == 0) return INT_INF;
            return cos;
        }
        else{
            return INT_INF;
        }
    }

    int mem1, mem2;
    mem1 = solve(cos+c[num], num+1, aa + a[num], bb+b[num]);
    mem2 = solve(cos, num+1, aa, bb);

    return min(mem1, mem2);
}

