#define INF (int)(1e9+7)

int dp[41][410][410], n, Ma, Mb;
int a[41], b[41], c[41];

int dfs(int x, int A, int B) {
    int tmp, ret = tmp = INF;

    if (dp[x][A][B] != 0) return dp[x][A][B];

    if ((double)A == (double)B * ((double)Ma / (double)Mb)) {
        return c[x];
    }

    for (int i = x+1; i < n; ++i) {
        ret = std::min(ret, dfs(i, A+a[i], B+b[i]) + c[x]);
    }

    return dp[x][A][B] = ret;
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);

    std::cin >> n >> Ma >> Mb;
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i] >> b[i] >> c[i];
    }
    int ans = INF;

    for (int i = 0; i < n; ++i) {
        ans = std::min(ans, dfs(i, a[i], b[i]));
    }

    if (ans != INF) std::cout << ans << std::endl;
    else std::cout << -1 << std::endl;

    return 0;
}

