struct drag {
    int a, b, c;
};

constexpr int INF = 1e9;

int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    vector<drag> v(N);
    for(int i=0; i<N; ++i) {
        cin >> v[i].a >> v[i].b >> v[i].c;
    }
    vector<vector<int>> tmp(401, vector<int>(401, INF));
    tmp[0][0] = 0;
    for(int i=0; i<1 << (N/2); ++i) {
        int x = 0, y=0, z=0;
        for(int j=0; j<N/2; ++j) {
            if(i & (1 << j)) {
                x += v[j].a;
                y += v[j].b;
                z += v[j].c;
            }
        }
        tmp[x][y] = min(tmp[x][y], z);
    }
    int res = INF;
    for(int i=0; i<1<<(N - N/2); ++i) {
        int x=0, y=0, z=0;
        for(int j=0; j<N - (N/2); ++j) {
            if(i & (1 << j)) {
                x += v[N/2 + j].a;
                y += v[N/2 + j].b;
                z += v[N/2 + j].c;
            }
        }
        for(int k=1; k*Ma <= 400 && k*Mb <= 400; ++k) {
            int Maa = k*Ma, Mbb = k*Mb;
            Maa -= x;
            Mbb -= y;
            if(Maa >= 0 && Mbb >= 0 && tmp[Maa][Mbb] != INF) {
                res = min(res, z + tmp[Maa][Mbb]);
            }
        }
    }
    if(res == INF) {
        cout << -1 << endl;
    } else {
        cout << res << endl;
    }
}

