const int maxn=45;

int n,ma,mb,a[maxn],b[maxn],c[maxn],pans=INF;
map<pair<int,int>,int> ans;

inline void mkfrac(int &fa,int &fb)
{
	if(fa==0||fb==0) return;

	int gcd=__gcd(fa,fb);
	fa/=gcd;
	fb/=gcd;
}

inline void sol(int k,int fa,int fb,int sum)
{
	// cerr<<k<<' '<<fa<<' '<<fb<<' '<<sum<<endl;

	int fra=fa,frb=fb;mkfrac(fra,frb);
	if(ans.find({fra,frb})!=ans.end()&&sum>ans[{fra,frb}]) return; else ans[{fra,frb}]=sum;

	if(k==n)
	{
		if(fra==ma&&frb==mb) pans=min(pans,sum);
		return;
	}

	sol(k+1,fa+a[k],fb+b[k],sum+c[k]);
	sol(k+1,fa,fb,sum);
}

int main()
{
	SF("%d%d%d",&n,&ma,&mb);
	rep(i,n) SF("%d%d%d",&a[i],&b[i],&c[i]);

	sol(0,0,0,0);

	PF("%d",pans==INF?-1:pans);

	return 0;
}
