int main()
{
	int n, ma, mb;
	cin >> n >> ma >> mb;

	for (int i = 0;i < n;i++) {
		cin >> a[i] >> b[i] >> c[i];
	}

	for (int i = 0;i <= max_n;i++) {
		for (int j = 0;j <= max_n * max_ab;j++) {
			for (int k = 0;k <= max_n * max_ab;k++) {
				dp[i][j][k] = INF;
			}
		}
	}

	for (int i = 0;i <= max_n;i++) dp[i][0][0] = 0;

	for (int i = 1;i <= n;i++) {
		for (int j = 1;j <= n * max_ab;j++) {
			for (int k = 1;k <= n * max_ab;k++) {
				if (a[i - 1] <= j && b[i - 1] <= k) {
					dp[i][j][k] = min(dp[i - 1][j][k], dp[i - 1][j - a[i - 1]][k - b[i - 1]] + c[i - 1]);
				}
				else dp[i][j][k] = dp[i - 1][j][k];
			}
		}
	}

	int min_cost = INF;
	for (int i = 1;i <= n * max_ab;i++) {
		for (int j = 1;j <= n * max_ab;j++) {
			if (i * mb == j * ma) min_cost = min(min_cost, dp[n][i][j]);
		}
	}

	if (min_cost == INF) cout << -1 << endl;
	else cout << min_cost << endl;

    return 0;
}

