struct S {
    int a, b, c;
};

int N, Ma, Mb;
vector<S> abc;
int ans = INT_MAX;

void dfs(int idx, int a, int b, int c) {
    if ((a > 0) && (b > 0)) {
        if (((double)Ma / Mb) == ((double)a / b)) {
            ans = min(ans, c);
        }
    }

    if (idx == N) {
        return;
    }

    if (c >= ans) {
        return;
    }

    dfs(idx + 1, a + abc[idx].a, b + abc[idx].b, c + abc[idx].c);
    dfs(idx + 1, a, b, c);
}

bool cmp(const S &a, const S &b) {
    return (a.c < b.c);
}

