const int MAX_N = 40;
const int MAX_A = 10;
const int INF = 1000;

int N, MA, MB;
int A[MAX_N], B[MAX_N], C[MAX_N];
int dp[MAX_N + 1][MAX_N * MAX_A + 1][MAX_N * MAX_A + 1];

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> MA >> MB;

    int asum = 0;
    int bsum = 0;

    for (int i = 0; i < N; i++) {
        cin >> A[i] >> B[i] >> C[i];
        asum += A[i];
        bsum += B[i];
    }

    fill(dp[0][0], dp[N][0], INF);

    dp[0][A[0]][B[0]] = C[0];

    for (int i = 0; i < N - 1; i++) {
        for (int j = 0; j <= asum; j++) {
            for (int k = 0; k <= bsum; k++) {
                if (j >= A[i + 1] && k >= B[i + 1]) {
                    dp[i + 1][j][k] = min(dp[i][j][k], dp[i][j - A[i + 1]][k - B[i + 1]] + C[i + 1]);
                } else {
                    dp[i + 1][j][k] = dp[i][j][k];
                }
            }
        }
    }

    int ans = INF;

    for (int j = 1; j <= asum; j++) {
        for (int k = 1; k <= bsum; k++) {
            int cost = dp[N - 1][j][k];
            if (cost != INF && MB * j == MA * k) {
                ans = min(cost, ans);
            }
        }
    }

    if (ans == INF) {
        ans = -1;
    }

    cout << ans << "\n";

    return 0;
}

