//i番目のビットを返す
bool getBit(int num, int i){
    return ((num & (1 << i)) != 0);
}

//i番目を1にする
int setBit(int num, int i){
    return num | (1 << i);
}

//i番目を0にする
int clearBit(int num, int i){
    int mask = ~(1 << i);
    return num & mask;
}

//i番目をvで置き換える
int updateBit(int num, int i, int v){
    int mask = ~(1 << i);
    return (num & mask) | (v << i);
}

const int MAX_N = 50;

int main(){
    int n, ma, mb;
    cin >> n >> ma >> mb;

    int a[MAX_N], b[MAX_N], c[MAX_N];
    rep(i,n) cin >> a[i] >> b[i] >> c[i];

    int m = n / 2;
    n-=m;

    //要素wをnとmに分け、それぞれで全列挙する
    map<pair<int, int>, int> x, y;
    rep(i,(1 << n)){
        pair<int, int> p = make_pair(0,0);
        int sum = 0;
        rep(j,n){
            if(getBit(i,j)){
                p.first += a[j];
                p.second += b[j];
                sum += c[j];
            }
        }
        if(x.count(p)) x[p] = min(x[p], sum);
        else x[p] = sum;
    }
    rep(i,(1 << m)){
        pair<int, int> p = make_pair(0,0);
        int sum = 0;
        rep(j,m){
            if(getBit(i,j)){
                p.first += a[n + j];
                p.second += b[n + j];
                sum += c[n + j];
            }
        }
        if(y.count(p)) y[p] = min(y[p], sum);
        else y[p] = sum;
    }

    int ans = INF;
