vector<int> va(40), vb(40), vc(40);

void root_search(int idx, int sum_a, int sum_b, int sum_c, int ma, int mb, int n, int &ans)
{
	if (idx >= n)
		return;

	int a, b, c;
	if (idx > 0)
	{
		a = sum_a;
		b = sum_b;
		c = sum_c;
		if (c < ans)
		{
			if ((a / ma) * mb == b)
				ans = c;
			else
				root_search(idx + 1, a, b, c, ma, mb, n, ans);
		}
	}

	a = sum_a + va[idx];
	b = sum_b + vb[idx];
	c = sum_c + vc[idx];
	if (c < ans)
	{
		if ((a / ma) * mb == b)
			ans = c;
		else
			root_search(idx + 1, a, b, c, ma, mb, n, ans);
	}
}

