i64 N;
i64 MA, MB;
vector<i64> A;
vector<i64> B;
vector<i64> C;

i64 f(i64 i, i64 j, i64 k) {
    static i64  memo[41][401][401];
    static bool done[41][401][401] {};

    if(i == 0)
        return (j == 0 && k == 0) ? 0 : INF;

    if(!done[i][j][k]) {
        i64 a = A[i-1];
        i64 b = B[i-1];
        i64 c = C[i-1];
        i64 res = f(i-1, j, k);
        if(j >= a && k >= b)
            chmin(res, c + f(i-1, j-a, k-b));

        memo[i][j][k] = res;
        done[i][j][k] = true;
    }
    return memo[i][j][k];
}

void solve() {
    RD(N);
    RD(MA); RD(MB);

    A.resize(N);
    B.resize(N);
    C.resize(N);
    REP(i, N) {
        RD(A[i]);
        RD(B[i]);
        RD(C[i]);
    }

    i64 ans = INF;
    FOR(j, 1, 401) FOR(k, 1, 401) {
        if(j*MB == k*MA) {
            chmin(ans, f(N, j, k));
        }
    }

    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans == INF ? -1 : ans);
}

signed main() {


    solve();

    EXIT();
}

