struct drag
{
	int m, val;
};

int n;
int ma, mb;
int result;
int maxVal = INT_MAX;
vector<drag> v;

void calc(int cost, int i, int m)
{
	if (i == n)
	{
		if (m != 0)
			return;
		if (cost == 0)
			return;
		if (cost < result)
			result = cost;
	}
	else
	{
		if (cost >= result)
			return;
		//	もうmが0になることがないときはスルー
		if (m + maxVal < 0)
			return;
		//	次の製品がm = 0でもcostは高くなるのでx
		if (m == 0 && cost > 0)
		{
			result = cost;
			return;
		}

		if (m + v[i].m <= 0)
		{
			calc(cost + v[i].val, i + 1, m + v[i].m);
			calc(cost, i + 1, m);
		}
	}
}

int main()
{
	result = INT_MAX;
	maxVal = 0;
	cin >> n >> ma >> mb;
	int N = n;
	v.resize(n);
	int minusVal = 0;
	int minPlus = INT_MAX;
	for (int i = 0; i < n; i++)
	{
		int a, b;
		cin >> a >> b >> v[i].val;
		v[i].m = a * mb - b * ma;
		if (v[i].m > 0)
		{
			maxVal += v[i].m;
			if (minPlus > v[i].m)
				minPlus = v[i].m;
		}
		else if (v[i].m < 0)
			minusVal += v[i].m;
		//	0を除く
		else
		{
			if (v[i].val < result)
				result = v[i].val;
			i--;
			n--;
		}
	}

	if (minPlus + minusVal > 0 && result == INT_MAX)
	{
		printf("-1");
		return 0;
	}

	for (int i = n; i < N; i++)
		v[i].m = v[i].val = INT_MAX;

	sort(v.begin(), v.end(), [](const drag &l, const drag &r) {return l.m < r.m; });
	//stable_sort(v.begin(), v.end(), [](const drag &l, const drag &r) {return l.val < r.val; });



	calc(0, 0, 0);
	if (result == INT_MAX)
		result = -1;
	printf("%d", result);
	return 0;
}

