template<typename T>
struct fast_set{
	constexpr static int B=4;
	struct node{
		T val=0;
        bool b=0;
		node** ch=new node*[1<<B]();
	};
	using np=node*;
	np root=0,root2=0;
	T& operator[](int64_t k){
        if(k<0)return get(-k,root2);
        else return get(k,root);
    }
    bool count(int64_t k){
        if(k<0)return count(-k,root2);
        else return count(k,root);
    }
    vector<pair<int64_t,T>> out(){
        vector<pair<int64_t,T>>v;
        out(v,root2,0,-1);
        out(v,root,0,1);
        return v;
    }
	T& get(int64_t k,np& t){
		if(!t)t=new node();
		if(!k){
            t->b=1;
            return t->val;
        }
		return get(k>>B,t->ch[k&((1<<B)-1)]);
	}
    bool count(int64_t k,np& t){
        if(!t)return 0;
        if(!k)return t->b;
        else return count(k>>B,t->ch[k&((1<<B)-1)]);
    }
    void out(vector<pair<int64_t,T>>&v,np& t,int k,int f){
        if(!t)return;
        if(t->b)v.emplace_back(k,t->val);
        for(int i=0;i<(1<<B);++i){
            out(v,t->ch[i],(k<<B)+i*f,f);
        }
    }
};

int main() {
    int N, Ma, Mb; cin >> N >> Ma >> Mb;
    int A[41], B[41], C[41];
    rep(i,N) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        A[i] = a;
        B[i] = b;
        C[i] = c;
    }
    int H1 = N / 2;
    int H2 = N - H1;
    int mi = INT32_MAX;

    // (MbA0−MaB0)+(MbA1−MaB1)=0
    // MbA0 - MaB0 = MaB1 - MbA1

    fast_set<int> M1;
    for (int bit = 1; bit < pow(2,H1); bit++) {
        int a = 0, b = 0, c = 0;
        for (int i = 0; i < H1; i++) {
            if (bit & (1 << i)) {
                a += A[i];
                b += B[i];
                c += C[i];
            }
        }
        int s = Mb * a - Ma * b;
        if (M1[s] == 0) M1[s] = c; // Can't be zero
        else M1[s] = min(M1[s], c);
        if (s == 0) mi = min(mi, c);
    }

    fast_set<int> M2;
    for (int bit = 1; bit < pow(2,H2); bit++) {
        int a = 0, b = 0, c = 0;
        for (int i = 0; i < H2; i++) {
            if (bit & (1 << i)) {
                a += A[H1 + i];
                b += B[H1 + i];
                c += C[H1 + i];
            }
        }
        int s = Ma * b - Mb * a;
        if (M2[s] == 0) M2[s] = c;
        else M2[s] = min(M2[s], c);
        if (s == 0) mi = min(mi, c);
    }

    for (auto x : M1.out()) {
        if (M2.count(x.first)) {
            mi = min(mi, x.second + M2[x.first]);
        }
    }

    if (mi == INT32_MAX) {
        cout << -1 << endl;
    } else {
        cout << mi << endl;
    }
}

