#define rep(i,N) for(int i=0;i<N;++i)
typedef long long int LL;

int N, Ma, Mb, ans;
std::vector<int>a, b, c;
std::vector<std::pair<std::pair<int, int>, int>>res1, res2;

LL gcd(LL a, LL b)
{
	if (a < b) std::swap(a, b);
	LL r = a % b;
	while (r != 0)
	{
		a = b;
		b = r;
		r = a % b;
	}
	return b;
}

int main()
{
	in >> N >> Ma >> Mb;
	a.resize(N), b.resize(N), c.resize(N);
	rep(i, N) in >> a[i] >> b[i] >> c[i];
	rep(bit, (1 << (N / 2)))
	{
		int aa = 0, bb = 0, cc = 0;
		rep(k, N / 2)
		{
			if (bit&(1 << k))
			{
				aa += a[k];
				bb += b[k];
				cc += c[k];
			}
		}
		res1.push_back(std::make_pair(std::make_pair(aa, bb), cc));
	}
	rep(bit, (1 << (N - N / 2)))
	{
		int aa = 0, bb = 0, cc = 0;
		rep(k, N - N / 2)
		{
			if (bit&(1 << k))
			{
				aa += a[k + N / 2];
				bb += b[k + N / 2];
				cc += c[k + N / 2];
			}
		}
		res2.push_back(std::make_pair(std::make_pair(aa, bb), cc));
	}
	std::sort(res1.begin(), res1.end());
	std::sort(res2.begin(), res2.end());
	Ma *= 400; Mb *= 400;
	ans = 114514;
	for (auto i : res1)
	{
		int wantA = Ma / std::max(i.first.first, 1), wantB = Mb / std::max(i.first.second, 1);
		int tmp = gcd(wantA, wantB);
		wantA /= tmp; wantB /= tmp;
		for (int j = 1; j <= 400; ++j)
		{
			auto it = std::lower_bound(res2.begin(), res2.end(), std::make_pair(std::make_pair(wantA*j, wantB*j), 0));
			if (it != res2.end())
			{
				if ((*it).first.first == wantA * j && (*it).first.second == wantB * j) ans = std::min(ans, i.second + (*it).second);
			}
		}
	}
	out << (ans == 114514 ? -1 : ans) << std::endl;
	return 0;
}

