using namespace std;
using ll = long long;
ll inf = ll(1e18);
using ll1d = vector<ll>;
using ll2d = vector<ll1d>;
using ll3d = vector<ll2d>;

class Combination {
 public:
  vector<vector<ll>> dp;
  ll n;

  explicit Combination(ll n) {
    this->n = n;
    this->dp = vector<vector<ll>>(n + 1, vector<ll>(n + 1, 0));
    comb_table();
  }

  inline ll calc(ll n, ll r) {
    return dp[n][r];
  }

  void comb_table() {
    rep(i, n + 1) {
      rep(j, n + 1) {
        if (j == 0 or j == i) {
          dp[i][j] = 1LL;
        } else {
          if (i != 0)
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
        }
      }
    }
  }
};

void solve(istream &ccin = cin, ostream &ccout = cout) {

  ll n, a, b;
  ccin >> n >> a >> b;
  ll1d v(n);
  rep(i, n) {
    ccin >> v.at(i);
  }
  sort(v.rbegin(), v.rend());

  ll sum = 0;
  rep(i, a) {
    sum += v.at(i);
  }
  double mean = double(sum) / a;

  ccout << fixed;
  ccout << setprecision(6) << mean << endl;

  ll va_1 = v.at(a - 1);
  Combination cmb(51);
  ll cnt1 = 0, cnt2 = 0;
  rep(i, n) {
    if (v[i] == va_1) {
      ++cnt1;
      if (i < a) {
        ++cnt2;
      }

    }

  }

  ll ans = 0;
  if (a == cnt2) {
    REP(i, a, b + 1) {
      ans += cmb.calc(cnt1, i);
    }
  } else {
    ans += cmb.calc(cnt1, cnt2);
  }

  ccout << ans << endl;
}

int main() {
  ios::sync_with_stdio(false);
  solve();
  return 0;
}

