#include <bits/stdc++.h>
#define rep(i,n) for(int (i)=0;(i)<(int)(n);++(i))
using namespace std;
static const int32_t INF = 0x3F3F3F3F;
typedef vector<int32_t> vii;
int memo[40005];
int N, Ma, Mb;
vii A, B, C;
struct Solution {
    int dfs(int n, int a, int b, int c) {
        if (memo[c]) return memo[c];
        if (a && b && Ma * b == Mb * a) return c;
        if (n == N) return INF;
        return memo[c] = min(dfs(n + 1, a + A[n], b + B[n], c + C[n]), dfs(n + 1, a, b, c));
    }
    void solve(std::istream& in, std::ostream& out) {
        in >> N >> Ma >> Mb;
        memset(memo, 0, sizeof(memo));
        A.resize(N);
        B.resize(N);
        C.resize(N);
        rep(i, N) {
            in >> A[i] >> B[i] >> C[i];
        }
        int ans = dfs(0, 0, 0, 0);
        out << (ans == INF ? -1 : ans) << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
