ll dp[50][500][500];
void solve() {
    ll n, ma, mb;
    cin >> n >> ma >> mb;

    vec<tuple<ll, ll, ll>> abc(n);
    REP(i, n) {
        ll a, b, c;
        cin >> a >> b >> c;
        abc[i] = {a, b, c};
    }
    REP(i, 50) {
        REP(j, 500) {
            REP(k, 500) {
                dp[i][j][k] = INF;
            }
        }
    }
    dp[0][0][0] = 0;
    REP(i, n) {
        auto [a, b, c] = abc[i];
        REP(j, (n + 1) * 10) {
            REP(k, (n + 1) * 10) {
                if(dp[i][j][k] == INF)
