using namespace std;
int N, A, B;
int a[50], b[50], c[50];
const int inf=1001001;
int memo[41][401][401];

int rec(int i, int _a, int _b){

   if(memo[i][_a][_b]!=inf) return memo[i][_a][_b];
   if(_a==0&&_b==0) return 0;
   if(i==N) return inf;
   int ret=inf;
   ret=min(ret, rec(i+1, _a, _b));
   if(_a-a[i]>=0&&_b-b[i]>=0) ret=min(ret, rec(i+1, _a-a[i], _b-b[i])+c[i]);

   return memo[i][_a][_b]=ret;
}

int main(){

   cin>> N>> A>> B;
   int x=0, y=0;
   for(int i=0; i<N; i++){
      cin>> a[i]>> b[i]>> c[i];
      x+=a[i]; y+=b[i];
   }

   for(int i=0; i<41; i++){
      for(int j=0; j<401; j++){
         for(int k=0; k<401; k++){
            memo[i][j][k]=inf;
         }
      }
   }
   int mi=inf;
   for(int k=1; max(k*A, k*B)<=40*10; k++){
      if(k*A>x||k*B>y) continue;
      mi=min(mi, rec(0, k*A, k*B));
   }

   if(mi==inf){
      cout<< -1<< endl;
   }else{
      cout<< mi<< endl;
   }

   return 0;
}

