const int INF = (int)1e9;
int n, ma, mb;
struct chemical
{
	int a, b, price;
	bool operator < (chemical& rhs) {
		return price < rhs.price;
	}
};

bool chk(int d, int e) {
	int div = __gcd(d, e);
	return d / div == ma && e / div == mb;
}

vector<chemical> chems;
int DP[50][500][500];
int minPrice(int idx, int a, int b)
{
	if(chk(a, b))
		return chems[idx].price;

	int& ret = DP[idx][a][b];
	if(ret != INF)
		return ret;

	for(int i = idx + 1; i < n; ++i) {
		int nxta = a + chems[i].a, nxtb = b + chems[i].b;
		ret = min(ret, chems[idx].price + minPrice(i, nxta, nxtb));
	}
	return ret;
}

