int b[41]={};
int c[41]={};
int dp[401][401][41]={};
const int INF=1000000000;
int calc(int a1,int b1,int n1){
	int ans=INF;
	if(dp[a1][b1][n1]<INF)return dp[a1][b1][n1];
	if(n1==1){
		if(a1==a[1]&&b1==b[1])ans=c[1];
		return ans;
	}
	ans=calc(a1,b1,n1-1);
	if(a1>=a[n1]&&b1>=b[n1])ans=min(ans,calc(a1-a[n1],b1-b[n1],n1-1)+c[n1]);
	dp[a1][b1][n1]=ans;
	return ans;
}

int main() {

	cin>>N>>Ma>>Mb;
	for(int i=1;i<N+1;++i)cin>>a[i]>>b[i]>>c[i];
	for(int i=0;i<401;++i){
		for(int j=0;j<401;++j){
			for(int k=0;k<41;++k)dp[i][j][k]=INF;
		}
	}
	dp[0][0][0]=0;
	int total=INF;
	for(int i=1;i<401;++i){
		for(int j=1;j<401;++j){
			if(Ma*j==Mb*i)total=min(total,calc(i,j,N));
		}
	}
	if(total==INF){
		cout<<-1<<endl;
	}else{
		cout<<total<<endl;
	}
	return 0;
}

