int N, Ma, Mb, amount = INT_MAX;
vector<tuple<int, int, int>> items;

void search(int k)
{
    static vector<int> subset;

    if (k == N)
    {
        int mA = 0, mB = 0, cost = 0;
        for (int x : subset)
        {
            // cout << x << ' ';
            int a, b, c;
            tie(a, b, c) = items[x];
            // cout << a << ' ' << b << ' ' << c << '\n';
            mA += a;
            mB += b;
            cost += c;
        }
        // cout << '\n';
        if (Ma * mB == Mb * mA && cost != 0 && mA != 0 && mB != 0)
            amount = min(amount, cost);
    }
    else
    {
        search(k + 1);
        subset.push_back(k);
        search(k + 1);
        subset.pop_back();
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> N >> Ma >> Mb;

    for (int i = 0; i < N; ++i)
    {
        int a, b, c;
        cin >> a >> b >> c;
        items.push_back(make_tuple(a, b, c));
    }

    search(0);

    if (amount == INT_MAX)
        amount = -1;

    cout << amount << '\n';

    return 0;
}

