const ll inf = numeric_limits<ll>::max()/3;




struct item {
  ll a;ll b;ll c;
  bool operator< (const item &right) const{
    ll calcl = a * right.b;
    ll calcr = right.a * b;
    if(calcl != calcr)
      return  calcl <  calcr;
    else
      return c < right.c;
  }
};

int main(void){
  int n,ma,mb;
  cin >> n >> ma >> mb;
  vector< item > items;
  for(int i = 0;i < n;++i){
    ll a,b,c;
    cin >> a >> b >> c;
    items.push_back((item){a,b,c});
  }
  ll res = inf;
  vector< item > half1;
  vector< item > half2;
  int h = n/2;
  for(int i = 1;i < (1 << h);++i){
    ll calcA = 0,calcB = 0,calcC = 0;
    for(int j = 0;j < h;++j){
      if(i & (1 << j)){
        calcA += items[j].a;
        calcB += items[j].b;
        calcC += items[j].c;
      }
    }
    if(calcA != 0 && calcB != 0 &&
       calcA * mb == calcB * ma){
      res = min(res, calcC);
    }
    half1.push_back((item){calcA,calcB,calcC});
  }

  for(int i = 1;i < (1 << (n-h));++i){
    ll calcA = 0,calcB = 0,calcC = 0;
    for(int j = h;j < n;++j){
      if(i & (1 << (j-h))){
        calcA += items[j].a;
        calcB += items[j].b;
        calcC += items[j].c;
      }
    }
    if(calcA != 0 && calcB != 0 &&
       calcA * mb == calcB * ma){
      res = min(res, calcC);
    }
    half2.push_back((item){calcA,calcB,calcC});
  }

  sort(half2.begin(),half2.end());
  vector< item > cand;
  for(item it : half2){
    if(!cand.empty()){
      item last = cand.back();
      if(last.a * it.b == it.a * last.b)
        continue;
    }
    cand.push_back(it);
  }

  for(item it : half1){
    int l = 0,r = cand.size();
    while(r - l > 1){
      int mid = (l+r)/2;
      ll calcA = it.a + cand[mid].a;
      ll calcB = it.b + cand[mid].b;
      if(calcA * mb <= ma * calcB){
        l = mid;
      }else{
        r = mid;
      }
    }
    ll calcA = it.a + cand[l].a;
    ll calcB = it.b + cand[l].b;
    if(calcA != 0 && calcB != 0 &&
       calcA * mb == calcB * ma){
      res = min(res,it.c + cand[l].c);
    }
  }
  if(res == inf){
    cout << "-1" << endl;
  }else{
    cout << res << endl;
  }
  return 0;
}

