struct Package {
	int a, b, c;
};


const int INF = 1e9 + 1;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, m1, m2;
	cin >> n >> m1 >> m2;
	vector<Package> p(n + 1);
	for (int i = 0; i < n; ++i) {
		cin >> p[i + 1].a >> p[i + 1].b >> p[i + 1].c;
	}

	vector<vector<vector<int>>> dp(n + 1);

	for (int i = 0; i <= n; ++i) {
		dp[i].resize(401);
		for (int j = 0; j < 401; ++j) {
			dp[i][j].resize(401, INF);
		}
	}

	dp[0][0][0] = 0;

	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j < 401; ++j) {
			for (int c = 1; c < 401; ++c) {
				dp[i][j][c] = min(dp[i][j][c], dp[i - 1][j][c]);
				if (j >= p[i].a && c >= p[i].b) dp[i][j][c] = min(dp[i][j][c], dp[i - 1][j - p[i].a][c - p[i].b] + p[i].c);
			}
		}
	}

	int ans = INF;
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j < 401; ++j) {
			for (int c = 1; c < 401; ++c) {
				if ((j / (__gcd(j, c)) == m1 && (c / __gcd(j, c)) == m2)) ans = min(ans, dp[i][j][c]); 
			}
		}
	}

	if (ans != INF) cout << ans << endl;
	else cout << -1 << endl;

	return 0;
}

