	return gcd(y, x % y);
}
int N, X, Y, a[44], b[44], c[44], ret; bool vis[44][444][444];
void solve(int pos, int as, int bs, int cs) {
	if (pos == N) {
		if (as == 0 && bs == 0) return;
		int r = gcd(as, bs);
		as /= r, bs /= r;
		if (as == X && bs == Y) ret = min(ret, cs);
