class st
{
public:
	ll f;
	ll s;
	ll m;

	st() {
		f = s = m;
	}
	st(ll a, ll b, ll c) {
		f = a;
		s = b;
		m = c;
	}
};

int main()
{
	ll n, ma, mb;
	cin >> n >> ma >> mb;
	st dp[n+1][n];

	ll a[n+1];
	ll b[n+1];
