	for (int i = 0; i < n+1; i++) {
		for (int j = 1; j <= n; j++) {
			if (i==0) {
				dp[i][j] = st(a[j],b[j],c[j]);
			} else if (i==j) {
				continue;
			} else {
				st tmp = dp[i-1][j];
				dp[i][j] = st(tmp.f+a[i], tmp.s+b[i], tmp.m+c[i]);
