int N, Ma, Mb;
int a[41], b[41], c[41];

struct Data {
  int now, type_a, type_b, cost;
  bool operator < ( const Data &d ) const {
    if( cost != d.cost ) return cost > d.cost;
    if( now  != d.now ) return now > d.now;
    if( type_a != d.type_a ) return type_a > d.type_a;
    return type_b > d.type_b;
  }
};

Data arr[41];
bool cmp(Data &a, Data &b) {
  return a.cost < b.cost;
}

bool used[41][401][410];
void compute() {
  priority_queue<Data> Q;
  Q.push((Data){0,0,0,0});
  used[0][0][0] = true;
  while( !Q.empty() ) {
    Data d = Q.top(); Q.pop();
    if( d.type_a * Mb == d.type_b * Ma && d.type_a != 0 ) {
      cout << d.cost << endl;
      return;
    }
    if( d.now >= N ) continue;
    // 使わない
    if( !used[d.now+1][d.type_a][d.type_b] ) {
      used[d.now+1][d.type_a][d.type_b] = true;
      Q.push((Data){d.now+1,d.type_a,d.type_b,d.cost});
    }
    if( !used[d.now+1][d.type_a+arr[d.now].type_a][d.type_b+arr[d.now].type_b] ) {
      used[d.now+1][d.type_a+arr[d.now].type_a][d.type_b+arr[d.now].type_b] = true;
      Q.push((Data){d.now+1,d.type_a+arr[d.now].type_a, d.type_b+arr[d.now].type_b,d.cost+arr[d.now].cost});
    }
  }
  puts("-1");
}

