int ans;

inline void check(int sa, int sb, int sc) {
	int t = __gcd(sa, sb);
	sa /= t;
	sb /= t;
	if (sa == ma && sb == mb) {
		if (ans == -1 || ans > sc) {
			ans = sc;
		}
	}
}

void go(int v, int k, int sa = 0, int sb = 0, int sc = 0) {
	if (v == k) {
		if (sa + sb == 0) return;
		check(sa, sb, sc);
		if (k == n) {
			int val = mb * sa - ma * sb;
			if (g.count(val)) {
				int t = g[val] + sc;
				if (ans == -1 || ans > t) {
					ans = t;
				}
			}
		} else {
			int val = ma * sb - mb * sa;
			if (g.count(val)) {
				g[val] = min(g[val], sc);
			} else {
				g[val] = sc;
			}
		}
		return;
	}
	go(v + 1, k, sa, sb, sc);
	go(v + 1, k, sa + a[v], sb + b[v], sc + c[v]);
}

