void solve() {
    i64 N; RD(N);
    i64 MA,MB; RD(MA); RD(MB);

    vector<i64> A(N);
    vector<i64> B(N);
    vector<i64> C(N);
    REP(i, N) {
        RD(A[i]);
        RD(B[i]);
        RD(C[i]);
    }

    static i64 dp[41][401][401];
    CARRAY_FILL(dp, INF);
    dp[0][0][0] = 0;
    FOR(i, 0, N) REP(j, 401) REP(k, 401) {
        if(dp[i][j][k] == INF) continue;

        i64 a = A[i];
        i64 b = B[i];
        i64 c = C[i];
        chmin(dp[i+1][j][k], dp[i][j][k]);
        chmin(dp[i+1][j+a][k+b], dp[i][j][k] + c);
    }

    i64 ans = INF;
    FOR(j, 1, 401) FOR(k, 1, 401) {
        if(j*MB != k*MA) continue;
        chmin(ans, dp[N][j][k]);
