ll dp[41][401][401];
ll solve(int n, int ai, int bi){
	if(dp[n][ai][bi] > 0) return dp[n][ai][bi];
	if(n == 0){
		if(ai == 0 && bi == 0){
			return dp[n][ai][bi] = 0;
		}
		else if(ai - a[0] == 0 && bi - b[0] == 0){
			return dp[n][ai][bi] = c[0];
		}
		else{
			return dp[n][ai][bi] = INT_MAX;
		}
	}
	else{
		if(ai - a[n] >= 0 && bi - b[n] >= 0){
			return dp[n][ai][bi] = min(solve(n-1, ai-a[n], bi - b[n]) + c[n], solve(n-1, ai, bi));
		}
		else{
			return dp[n][ai][bi] = solve(n-1, ai, bi);
		}
	}
