    vector<pair<int,int>> a(n);
    vector<int> cost(n);
    for(int i = 0; i < n; i++)cin >> a[i].first >> a[i].second >> cost[i];

    int m = n / 2;


    //半分全列挙
    vector<pair<int,int>> front, back;
    map<pair<int,int>,int> costfront, costback; //{i,j}の組を作る最小値

    for(int bit = 0; bit < (1 << m); bit++){
        pair<int,int> cur;
        int curcost = 0;
        for(int i = 0; i < m; i++){
            if(bit & (1 << i)){
                cur.first += a[i].first;
                cur.second += a[i].second;
                curcost += cost[i];
            }
        }
        front.push_back(cur);
        if(costfront.count(cur)){
            costfront[cur] = min(curcost, costfront[cur]);
        }else{
            costfront[cur] = curcost;
        }
    }
    sort(front.begin(), front.end());

    int t = n - m;//半分全列挙の後側
    for(int bit = 0; bit < (1 << t); bit++){
        pair<int,int> cur;
        int curcost = 0;
        for(int i = 0; i < t; i++){
            if(bit & (1 << i)){
                cur.first += a[i + m].first;
                cur.second += a[i + m].second;
                curcost += cost[i + m];
            }
        }
        back.push_back(cur);
        if(costback.count(cur)){
            costback[cur] = min(curcost, costback[cur]);
        }else{
            costback[cur] = curcost;
        }
    }
    sort(back.begin(), back.end());


    int ans = 1000000000;

    for(int cef = 1; cef < 500; cef++){
        int ma = MA * cef;
        int mb = MB * cef;

        for(auto i : front){
            pair<int,int> cur = {ma - i.first, mb - i.second};
            auto itr = lower_bound(back.begin(), back.end(), cur);
            if(itr == back.end())continue;
            if(*itr != cur)continue;

            ans = min(ans, costfront[i] + costback[cur]);
        }
    }

    cout << (ans == 1000000000 ? -1 : ans) << endl;
}

