            b1.pb(b[i]);
            c1.pb(c[i]);
        }
        else{
            a2.pb(a[i]);
            b2.pb(b[i]);
            c2.pb(c[i]);
        }
    }
    P ini = mk(mk(0,0),0);
    memo.pb(ini);
    calc(a1,b1,c1,0,ini);
    vector < P > sum1 = memo;
    sort(sum1.begin(),sum1.end());
    memo.clear();
    memo.pb(ini);
    calc(a2,b2,c2,0,ini);
    vector < P > sum2 = memo;
    sort(sum2.begin(),sum2.end());
    map < Pii,int > tar;
