typedef pair<int,int> ii;

struct Package {
    int a, b, c;

    ii to_pair(){
        return ii(a,b);
    }
};

int n, ma, mb, dp[509][509];
vector<Package> packs;

int main(){
    scanf("%d%d%d", &n ,&ma, &mb);
    for(int i=0; i<n; i++){
        int x, y, z; scanf("%d%d%d", &x, &y, &z);
        packs.push_back({x,y,z});
    }

    memset(dp, 63, sizeof dp);
    int ans = dp[0][0]; dp[0][0] = 0;
    for(Package pack : packs) {
        for(int i=0; i<=400; i++)
            for(int j=0; j<=400; j++)
                if(dp[i][j] == ans) continue;
                else dp[i + pack.a][j + pack.b] = min(dp[i + pack.a][j + pack.b], dp[i][j] + pack.c);
    }

    for(int i=1; i<=400; i++)
        for(int j=1; j<=400; j++)
            if(i * mb == j * ma) ans = min(ans, dp[i][j]);

    printf("%d\n", ans == 0x3f3f3f3f? -1:ans);
    return 0;
}

