int dp[11][405][405];
int n;

int solve(int pos, int x, int y) {
	if (x < 0 || y < 0) return 1e9;
	if (pos == n) {
		if (x == 0 && y == 0) return 0;
		return 1e9;
	}
	if (dp[pos][x][y] != -1) return dp[pos][x][y];
	int ans = min(solve(pos + 1, x - a[pos].first.first, y - a[pos].first.second) + a[pos].second, solve(pos + 1, x, y));
	return dp[pos][x][y] = ans;
} 

