int gcd(int a, int b) {
    if (a % b == 0) return b;
    gcd(b, a%b);
}

int calc(int nowA, int nowB, int nowCost, int nowIndex) {
    int ret = INF;
    if (nowIndex == n) return ret;
    nowA += a[nowIndex];
    nowB += b[nowIndex];
    nowCost += c[nowIndex];
    nowIndex++;
    int G = gcd(nowA, nowB);
    if (nowA/G == Ma && nowB/G == Mb) ret = nowCost;
    ret = min(calc(nowA, nowB, nowCost, nowIndex), ret);
    return ret;
}

