    cin >> N >> Ma >> Mb;
    vector<int> a(N), b(N), c(N);
    for(int i=0; i<N; i++)
        cin >> a[i] >> b[i] >> c[i];

    int N1 = N / 2;
    int N2 = N - N1;
    vector<pair<int, int>> G1((1 << N1) - 1), G2((1 << N2) - 1);
    for(int i=1; i< 1<<N1; i++){
        int aa = 0, bb = 0, cc = 0;
        for(int j=0; j<N1; j++){
            if(i & 1<<j){
                aa += a[j];
                bb += b[j];
                cc += c[j];
            }
        }
        int tmp = aa * Mb - bb * Ma;
        G1[i-1] = pair<int, int>(tmp, cc);
    }
    for(int i=1; i< 1<<N2; i++){
        int aa = 0, bb = 0, cc = 0;
        for(int j=0; j<N2; j++){
            if(i & 1<<j){
                aa += a[N1+j];
                bb += b[N1+j];
                cc += c[N1+j];
            }
        }
        int tmp = bb * Ma - aa * Mb;
        G2[i-1] = pair<int, int>(tmp, cc);
    }
    const int INF = 1000000000;
    int ans = INF;
    for(auto g : G1)
        if(g.first==0)
            ans = min(ans, g.second);
    for(auto g : G2)
        if(g.first==0)
            ans = min(ans, g.second);

    sort(G2.begin(), G2.end());
    for(int i=0; i<G1.size(); i++){
        pair<int, int> p = pair<int, int>(G1[i].first, 0);
        auto itr = lower_bound(G2.begin(), G2.end(), p);
        if(itr == G2.end() || G1[i].first != itr->first) continue;
        ans = min(ans, G1[i].second + itr->second);
    }
    if(ans == INF)
        cout << -1 << endl;
    else
        cout << ans << endl;

    return 0;
}

