using namespace std;

int main()
{
    int64_t N, Ma, Mb;
    std::cin >> N >> Ma >> Mb;

    struct D {
        int64_t a;
        int64_t b;
        int64_t c;
    };

    std::vector<D> d;
    for (decltype(N) i = 0; i < N; ++i) {
        int64_t a, b, c;
        std::cin >> a >> b >> c;
        d.push_back({a, b, c});
    }

    // dp[aの総量][bの総量][i個まで(i含む)]
    boost::multi_array<int64_t, 3> dp(boost::extents[N+1][10*N+1][10*N+1]);

    const int64_t INF = 40*N+1;
    std::fill(dp.data(), dp.data() + dp.num_elements(), INF);

    // 配るDP
    dp[0][0][0] = 0;

    #if 1
    for (int64_t i = 0; i < N; ++i) {
        for (int64_t a = 0; a <= 10*N; ++a) {
            for (int64_t b = 0; b <= 10*N; ++b) {
                if (dp[i][a][b] == INF) {
                    // 原点から届かない部分からは次に配らない
                    // この枝切りを入れないと、
                    // すでに a, b がmaxになっているところから先に配ろうとして、
                    // 範囲外アクセスとなる。
                    continue;
                }

                // 自分をいれる
                dp[i+1][a+d[i].a][b+d[i].b] = std::min(dp[i+1][a+d[i].a][b+d[i].b],
                                                       dp[i][a][b] + d[i].c);
                // 自分をいれない
                dp[i+1][a][b] = std::min(dp[i+1][a][b], dp[i][a][b]);
            }
        }
    }
    #endif
    #if 0
    // もらうDP
    for (int64_t i = 0; i < N; ++i) {
        for (int64_t a = 0; a <= 10*N; ++a) {
            for (int64_t b = 0; b <= 10*N; ++b) {
                if (a - d[i].a >= 0 && b - d[i].b >= 0) {
                    dp[i+1][a][b] = std::min(dp[i][a][b], dp[i][a - d[i].a][b - d[i].b] + d[i].c);
                }
                else {
                    dp[i+1][a][b] = dp[i][a][b];
                }
            }
        }
    }
    #endif
    int64_t ans = INF;
    for (int64_t a = 1; a <= 10*N; ++a) {
        for (int64_t b = 1; b <= 10*N; ++b) {
            if (Ma*b == Mb*a) {
                ans = min(ans, dp[N][a][b]);
            }
        }
    }
    if (ans == INF) {
        ans = -1;
    }
    std::cout << ans << std::endl;

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn=45;
const int zero=4000;
const int INF=0x3f3f3f3f;
int n,a[maxn],b[maxn],val[maxn],cost[maxn],dp1[zero*2+5],dp2[zero*2+5],ans;
void solve(int s)
{
	memset(dp1,-1,sizeof(dp1));
	dp1[val[s]+zero]=cost[s];
	for(int i=s+1;i<=n;i++)
	{
		memset(dp2,0x3f,sizeof(dp2));
		for(int j=0;j<=zero*2;j++)
		{
			if(dp1[j]!=-1) dp2[j]=dp1[j];
			int pre=j-val[i];
			if(0<=pre&&pre<=zero*2&&dp1[pre]!=-1)
				dp2[j]=min(dp2[j],dp1[pre]+cost[i]);
			if(dp2[j]==INF) dp2[j]=-1;
		}
		for(int j=0;j<=zero*2;j++)
			dp1[j]=dp2[j];
	}
	if(dp1[zero]!=-1)
		ans=min(ans,dp1[zero]);
}
void fl()
{
    freopen(".in","r",stdin);
    freopen(".out","w",stdout);
}
int main()
{
//	  fl();
	int Ma,Mb;
	scanf("%d%d%d",&n,&Ma,&Mb);
	memset(dp1,-1,sizeof(dp1));
	for(int i=1;i<=n;i++)
	{
		scanf("%d%d%d",&a[i],&b[i],&cost[i]);
		val[i]=b[i]*Ma-a[i]*Mb;
	}
	ans=INF;
	for(int i=1;i<=n;i++)
		solve(i);
	printf("%d\n",ans==INF?-1:ans);
	return 0;
}

