using namespace std;

void assign_if(int& a0, const int& a1) {
    if (a1 < a0) a0 = a1;
}

struct Chemicals {
    Chemicals& operator+=(const Chemicals& o) {
        a += o.a; b += o.b; c += o.c;
        return *this;
    }
    bool operator<(const Chemicals& o) const {
        return a != o.a ? a < o.a : b != o.b ? b < o.b : c < o.c;
    }
    int a, b, c;
};

Chemicals p[40];
Chemicals q[2][1 << 20];

int n, ma, mb;
int k[2], l;

void enumerate(int i, int i1, Chemicals o) {
    if (i < i1) {
        enumerate(i + 1, i1, o);
        o += p[i];
        enumerate(i + 1, i1, o);
    } else {
        int t = min(o.a / ma, o.b / mb);
        q[l][k[l]++] = { o.a - t * ma, o.b - t * mb, o.c };
    }
}

int main() {
    cin >> n >> ma >> mb;

    for (int i = 0; i < n; i++) {
        cin >> p[i].a >> p[i].b >> p[i].c;
    }

    int m[3] = { 0, n / 2, n };
    for (int i = 0; i < 2; i++) {
        k[l = i] = 0;
        enumerate(m[i], m[i + 1], { 0, 0, 0 });
    }

    auto end = q[1] + k[1];
    sort(q[1], end);
    end = unique(q[1] + 1, end, [&](const Chemicals& o0, const Chemicals& o1) {
        return o0.a == o1.a && o0.b == o1.b;
    });

    int r = 4001;
    for (int i = 0; i < k[0]; i++) {
        auto o = q[0][i];
        int t = max((o.a + ma - 1) / ma, (o.b + mb - 1) / mb);
        o = { t * ma - o.a, t * mb - o.b, 0 };
        auto it = lower_bound(q[1] + (i == 0), end, o);
        if (it == end) continue;
        if (it->a != o.a || it->b != o.b) continue;
        assign_if(r, q[0][i].c + it->c);
    }

    cout << (r < 4001 ? r : -1) << endl;

    return 0;
}

