using namespace std;

map<long long, long long> f(long long M_a, long long M_b, vector<long long> &a, vector<long long> &b, vector<long long> &c, int l, int r) {
	int n = r - l;
	map<long long, long long> res;
	for(int s = 1; s < 1 << n; ++s) {
		long long t = 0;
		long long u = 0;
		for(int i = 0; i < n; ++i) {
			if((s >> i) & 1) {
				t += M_a * b[i] - M_b * a[i];
				u += c[i];
			}
		}
		if (res.find(t) == res.end()) {
			res[t] = u;
		} else {
			res[t] = min(res[t], u);
		}
	}
	return res;
}

void solve(long long N, long long M_a, long long M_b, vector<long long> a, vector<long long> b, vector<long long> c){
	map<long long, long long> v = f(M_a, M_b, a, b, c, 0, N / 2);
	map<long long, long long> w = f(M_a, M_b, a, b, c, N / 2, N);
	long long res = N + 10;
	for(auto p : v) {
		if (w.find(-p.first) == w.end()) continue;
		res = min(res, p.second + w.find(-p.first) -> second);
	}
	for(auto p : v) {
		if (p.first == 0) {
			res = min(res, p.second);
		}
	}
	for(auto p : w) {
		if (p.first == 0) {
			res = min(res, p.second);
		}
	}

	cout << (res > N ? -1 : res) << endl;
}

int main(){	
	long long M_b;
	long long M_a;
	long long N;
	scanf("%lld",&N);
	vector<long long> c(N-1+1);
	vector<long long> b(N-1+1);
	vector<long long> a(N-1+1);
	scanf("%lld",&M_a);
	scanf("%lld",&M_b);
	for(int i = 0 ; i <= N-1 ; i++){
		scanf("%lld",&a[i]);
		scanf("%lld",&b[i]);
		scanf("%lld",&c[i]);
	}
	solve(N, M_a, M_b, a, b, c);
	return 0;
}

