ll N,Ma,Mb;
struct drug {
     ll a;
     ll b;
     ll c;
};
drug drugs[40];
ll dp[40][401][401];

int main() {
    std::cin >> N>>Ma>>Mb;
    for (int i = 0; i < N; i++) {
        std::cin >> drugs[i].a>>drugs[i].b>>drugs[i].c;
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= 400; j++) {
            for (int k = 0; k <= 400; k++) {
                if(j==0 && k==0){
                    dp[i][j][k]=0;
                }else{
                    dp[i][j][k]=40000;
                }
                if(i>0){
                    dp[i][j][k] = min(dp[i][j][k],dp[i-1][j][k]);
                }
                if(j-drugs[i].a>=0 && k-drugs[i].b>=0){
                    dp[i][j][k] = min(dp[i][j-drugs[i].a][k-drugs[i].b]+drugs[i].c, dp[i][j][k]);
                }
                if(i>0 && j-drugs[i].a>=0 && k-drugs[i].b>=0){
                    dp[i][j][k] = min(dp[i-1][j-drugs[i].a][k-drugs[i].b]+drugs[i].c, dp[i][j][k]);
                }
            }
        }
    }
    ll   ans=40000;
    for (int j = 1; j <= 400/(max(Ma,Mb)); j++) {
        ans = min(ans,dp[N-1][Ma*j][Mb*j]);
    }

    if(ans==40000){
        std::cout << -1 << std::endl;
    }else{
        std::cout << ans << std::endl;
    }
}

