int yosan[4500][4500];

bool solve() {
    REP (i,450) REP (j,450) yosan[i][j] = INF;
    yosan[0][0] = 0;
    int n,ma,mb; cin >> n >> ma >> mb;
    REP (i,n) {
        int a,b,c; cin >> a >> b >> c;
        REP (i,450) {
            REP (j,450) {
                if (i+a >= 450 || j+b >= 450) continue;
                chmin(yosan[i+a][j+b],yosan[i][j]+c);
            }
        }
    }
    int ans = INF;
    REP (i,450) {
        REP (j,450) {
            if (!i || !j) continue;
            if (i * mb == j * ma) {
                chmin(ans,yosan[i][j]);
            }
        }
    }
    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
}

