int a[50], b[50], c[50], n, ma, mb, opt;
int search(int sumA, int sumB, int sumC, int st){
    if(sumC>=opt) return 5000;
    if((sumA+a[st])*mb==(sumB+b[st])*ma){
        if(sumC+c[st]<opt) opt=sumC+c[st];
        return sumC+c[st];
    }
    else{
        if(st==n-1) return 5000;
        else return min(search(sumA, sumB, sumC, st+1), search(sumA+a[st], sumB+b[st], sumC+c[st], st+1));
    }   
}
int main(void){
    opt=5000;
    cin>>n>>ma>>mb;
    for(int i=0;i<n;i++) cin>>a[i]>>b[i]>>c[i];
    opt=min(search(0, 0, 0, 0), opt);
    if(opt>=5000||opt==0) opt=-1;
    cout<<opt<<endl;
}

