pi vmax(vi v) {
	int n = size(v);
	int MAX = 0;
	int pos = 0;
	rep(i, n) {
		if (MAX < v[i])pos = i;
		MAX = max(MAX, v[i]);
	}
	return { MAX,pos };
}

pi vmin(vi v) {
	int n = size(v);
	int MIN = INF;
	int pos = 0;
	rep(i, n) {
		if (MIN > v[i])pos = i;
		MIN = min(MIN, v[i]);
	}
	return { MIN,pos };
}

int vsum(vi v) {
	int n = size(v);
	int sum = 0;
	rep(i, n) {
		sum += v[i];
	}
	return sum;
}

int gcd(int a, int b) {
	if (b == 0) {
		swap(a, b);
	}
	int r;
	while ((r = a % b) != 0) {
		a = b;
		b = r;
	}
	return b;
}
int lcm(int a, int b) {
	return (a / gcd(a, b) * b);
}

bool is_square(int n) {
	if ((int)sqrt(n)*(int)sqrt(n) == n) {
		return true;
	}
	else {
		return false;
	}
}


bool is_prime(int n) {
	if (n <= 1) {
		return true;
	}
	else {
		for (int i = 2; i*i <= n; i++) {
			if (n % i == 0) {
				return false;
			}
		}
	}
	return true;
}

void dec_num(int n, vi &v) {
	int a = 2;
	v.push_back(1);
	v.push_back(n);
	while (a*a <= n) {
		if (n%a == 0) {
			v.push_back(a);
			v.push_back(n / a);

		}
		a++;
	}
	sort(all(v));
}


