const int inf = 40 * 100 + 23;

const int MAXN = 45;
const int MAXS = 410;

int A[MAXN][MAXS][MAXS];

int main()
{
    cin.tie(0);
    ios_base::sync_with_stdio(false);

    int n, ma, mb;
    cin >> n >> ma >> mb;

    for (int i = 0; i < MAXN; i++)
        for (int j = 0; j < MAXS; j++)
            for (int k =0 ; k < MAXS; k++)
                A[i][j][k] = inf;

    A[0][0][0] = 0;

    for (int i = 0; i < n; i++) {
        int ca, cb, c;
        cin >> ca >> cb >> c;
        for (int cur_ca = 0; cur_ca < MAXS; cur_ca++) {
            for (int cur_cb = 0; cur_cb < MAXS; cur_cb++) {
                if (A[i][cur_ca][cur_cb] == inf) {
                    continue;
                }

                A[i + 1][cur_ca + ca][cur_cb + cb] = min(
                    A[i + 1][cur_ca + ca][cur_cb + cb],
                    A[i][cur_ca][cur_cb] + c
                );
                A[i + 1][cur_ca][cur_cb] = min(
                    A[i + 1][cur_ca][cur_cb],
                    A[i][cur_ca][cur_cb]
                                           );
            }
        }
    }

    int best_ans = inf;
    for (int mul = 1; mul < MAXS; mul++) {
        int ca = mul * ma;
        int cb = mul * mb;
        if (ca >= MAXS or cb >= MAXS) {
            continue;
        }
        best_ans = min(best_ans, A[n][ca][cb]);
    }
    if (best_ans >= inf) {
        cout << -1 << endl;
    } else {
        cout << best_ans;
    }
}

