            dp[i][ca][cb] = min(dp[i][ca][cb] , dp[i-1][ca][cb]);
            if (ca >= a[i] && cb >= b[i]) {
               chmin(dp[i][ca][cb], dp[i-1][ca-a[i]][cb-b[i]] + c[i]);
            }
         }
      }
   }

   int ans = inf;
