  tmp1 = dp[i-1][ca][cb]; //drug iを入れない場合
  if(ca-drugs[i].a >= 0 && cb-drugs[i].b >=0){
    tmp2 = dp[i-1][ca-drugs[i].a][cb-drugs[i].b] + drugs[i].c;
  }
  if(tmp1 <= tmp2) return tmp1;
  else return tmp2;
}

