    for(int i = 0; i < n; ++i){
        cin >> a[i] >> b[i] >> c[i];
    }

    // dpテーブルの初期化
    for(int i = 0; i <= 40; ++i){
        for(int j = 0; j <= 400; ++j){
            for(int k = 0; k <= 400; ++k){
                dp[i][j][k] = INF;
            }
        }
    }
    dp[0][0][0] = 0;

    int budget = INF;
    for(int i = 0; i < n; ++i){
        for(int j = 0; j <= 400; ++j){
            for(int k = 0; k <= 400; ++k){
                if(dp[i][j][k] == INF)      continue;
                // 薬品iを入れない場合
                dp[i+1][j][k] = min(dp[i+1][j][k], dp[i][j][k]);

                // (j,k)が比の条件(ma:mb)を満たしていれば、budgetと比較する
                if((j != 0 && k != 0) && j*mb == k*ma){
                    budget = min(budget, dp[i+1][j][k]);
