        for(j=0; j+a[i]<404; j++) {
            for(k=0; k+b[i]<404; k++) {
                dp[i+1][j+a[i]][k+b[i]]=min(dp[i][j+a[i]][k+b[i]], dp[i][j][k]+c[i]);
            }
        }
    }

    ll ans=INF;
    for(i=1; i*max(A, B)<404; i++) {
        ans=min(ans, dp[N][i*A][i*B]);
    }

    if(ans==INF) pr(-1);
    else pr(ans);

}

