void oneCase () {
    int n, ma, mb;
    cin >> n >> ma >> mb;
    vector<int> a(n);
    vector<int> b(n);
    vector<int> c(n);
    for (int i = 0; i < n; ++i) {
        int x, y, z;
        cin >> x >> y >> z;
        a[i] = x;
        b[i] = y;
        c[i] = z;
    }
    auto sz = n * 10 + 10;
    vector<vector<int>> dp(sz + 1, vector<int>(sz + 1, 1e9));

    for (int i = 0; i < n; ++i) {
        auto x = a[i];
        auto y = b[i];
        for (int l = 1; l <= sz; ++l) {
            for (int r = 1; r <= sz; ++r) {
                auto nx = x + l;
                auto ny = y + r;
                auto d = gcd(nx, ny);
                nx /= d;
                ny /= d;
                if (nx > sz or ny > sz) {
                    continue;
                }
                dp[nx][ny] = min(dp[nx][ny], dp[l][r] + c[i]);
            }
        }
        dp[x][y] = min(dp[x][y], c[i]);
    }



    auto best = dp[ma][mb] == 1e9 ? -1 : dp[ma][mb];
    cout << best << "\n";
}





