using u64 = unsigned long long;
#define REP(i, n) for (int i = 0; (i64)(i) < (i64)(n); ++i)

const int INF = 1 << 30;

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N, ma, mb;
  cin >> N >> ma >> mb;

  int mincost = INF;
  vector<tuple<int, int>> x_minus, x_plus;
  REP(i, N) {
    int a, b, c;
    cin >> a >> b >> c;
    int x = a * mb - ma * b;
    if (x == 0) {
      if (mincost > c) {
        mincost = c;
        // cerr << "x = 0, cost = " << c << endl;
      }
    } else if (x < 0) {
      x_minus.emplace_back(c, -x);
    } else {
      x_plus.emplace_back(c, x);
    }
  }

  // dp_*[i] := mincost of total weight i.
  const int XMAX = 1000;
  vector<int> dp_plus(XMAX + 1, INF), dp_minus(XMAX + 1, INF);
  dp_plus[0] = dp_minus[0] = 0;
  REP(i, x_plus.size()) {
    int ci = get<0>(x_plus[i]);
    int xi = get<1>(x_plus[i]);
    for (int w = XMAX - xi; w >= 0; --w) {
      dp_plus[w + xi] = min(dp_plus[w + xi], dp_plus[w] + ci);
    }
  }
  REP(i, x_minus.size()) {
    int ci = get<0>(x_minus[i]);
    int xi = get<1>(x_minus[i]);
    for (int w = XMAX - xi; w >= 0; --w) {
      dp_minus[w + xi] = min(dp_minus[w + xi], dp_minus[w] + ci);
    }
  }
  REP(w, XMAX) {
    int wp = dp_plus[w + 1], wm = dp_minus[w + 1];
    if (wp != INF && wm != INF && mincost > wp + wm) {
      //   cerr << "Found: weight = " << (wp + wm) << " (" << wp << " + " << wm
      //        << ")\n";
      mincost = wp + wm;
    }
  }
  cout << (mincost == INF ? -1 : mincost) << endl;
}

