typedef vector<int> vi;

vector < P > memo;
void calc(const vi &a,const vi &b,const vi &c, int prev, P p){
    if(prev == a.size()){
        return ;
    }
    p.fr.fr += a[prev];
    p.fr.sc += b[prev];
    p.sc    += c[prev];
    calc(a,b,c,prev+1,p);
    memo.pb(p);
    p.fr.fr -= a[prev];
    p.fr.sc -= b[prev];
    p.sc    -= c[prev];
    calc(a,b,c,prev+1,p);
    return ;
}
