            c2.pb(c[i]);
        }
    }
    P ini = mk(mk(0,0),0);
    memo.pb(ini);
    calc(a1,b1,c1,0,ini);
    vector < P > sum1 = memo;
    sort(sum1.begin(),sum1.end());
    memo.clear();
