const int INF = 1e9;
int n, ma, mb;
int a[45];
int b[45];
int c[45];
int dp[45][405][405];
int solve(int pos, int remA, int remB) {
	if(pos == n) {
		bool flag = ((remA * mb) == (remB * ma));
		flag = flag && !(remA%ma);
		flag = flag && !(remB%mb);
		flag = flag && (remA != 0) && (remB != 0);
		if(flag) {
			return 0;
		} else {
			return INF;
		} 
	}

	int& ret = dp[pos][remA][remB];
	if(ret != -1) return ret;
	ret = INF;

	ret = min(ret, solve(pos+1, remA+a[pos], remB+b[pos]) + c[pos]);
	ret = min(ret, solve(pos+1, remA, remB));
	return ret;
}

