					dp[i][a + A[i]][b + B[i]] = min(dp[i][a + A[i]][b + B[i]], dp[i - 1][a][b] + C[i]);
					dp[i][a][b] = dp[i - 1][a][b];
				}
			}
		}
	}

	ll ans = INF;
	repe(j, 1, M) {
		repe(k, 1, M) {
			if (dp[n][j][k] == INF) {
				continue;
			}

			ll g = gcd(j, k);
			if (j == ma * g &&  k == mb * g) {
				//if (j * mb != k * ma) continue;
				ans = min(ans, dp[n][j][k]);
			}
		}
	}
	if (ans < INF) cout << ans << endl;
	else cout << -1 << endl;

	return 0;
}

