int n, ma, mb;
int a[40], b[40], c[40];
int dp[41][401][401];

int gcd(int a, int b) {
	if (b == 0) return a;
	return gcd(b, a % b);
}

int main() {
	cin >> n >> ma >> mb;
	REP(i, n) scanf("%d %d %d", a + i, b + i, c + i);

	fill(dp[0][0], dp[41][0], INF);
	dp[0][0][0] = 0;

	REP(i, n) {
		REP(j, 401) REP(k, 401) {
			chmin(dp[i + 1][j][k], dp[i][j][k]);

			if (j + a[i] > 400 || k + b[i] > 400) continue;
			if (dp[i][j][k] == INF) continue;

			chmin(dp[i + 1][j + a[i]][k + b[i]], dp[i][j][k] + c[i]);
		}
	}

	int ans = INF;
	FOR(i, 1, 401) FOR(j, 1, 401) {
		int g = gcd(i, j);

		if (i / g == ma && j / g == mb) chmin(ans, dp[n][i][j]);

	}
	if (ans == INF) ans = -1;

	cout << ans << endl;

	return 0;
}

