int inf=(1<<31)-1;
void dfs(int cur,int cnt,int num,int sum)
{
    if(sum&&cnt&&num)
    {
        int pos=__gcd(cnt,num);
        if(cnt/pos==x&&num/pos==y)
        {
            inf=min(inf,sum);
            return;
        }
        else if(cnt/pos>x||num/pos>y)
        {
            return;
        }
    }
    for(int i=cur; i<=n; i++)
    {
        dfs(i+1,cnt+a[i],num+b[i],sum+c[i]);
    }
}
