int n,a[44],b[44],c[44],sa,sb,ma,mb,ans=1e9,dp[444][444];
int main()
{
	cin>>n>>ma>>mb;
	memset(dp,-1,sizeof(dp));
	for(int i=0;i<n;i++)
	{
		cin>>a[i]>>b[i]>>c[i];
		sa+=a[i];
		sb+=b[i];
		dp[a[i]][b[i]]=c[i];
	}
	for(int i=1;i<=400;i++)
	{
		for(int j=1;j<=400;j++)
		{
			for(int k=0;k<n;k++)
			{
				if(i<=a[k] || j<=b[k])
				{
					continue;
				}
				if(dp[i-a[k]][j-b[k]]==-1)
				{
					continue;
				}
				dp[i][j]=min(dp[i][j],dp[i-a[k]][j-b[k]]+c[k]);
			}
		}
	}
	for(int i=1;i<=400;i++)
	{
		int nma=ma*i,nmb=mb*i;
		if(nma>sa || nmb>sb)
		{
			break;
		}
		if(dp[nma][nmb]!=-1)
		{
			ans=min(ans,dp[nma][nmb]);
		}
	}
	if(ans==1e9)
	{
		cout<<-1<<endl;
	}
	else
	{
		cout<<ans<<endl;
	}
	return 0;
}

