// dp[i][ag][bg]: i 個目までを使えるときに、ag, bg を実現する最小コスト 
lli dp[41][401][401];
lli inf = 100000;

int main() {
    lli n, ma, mb;
    cin3(n, ma, mb);
    lli a[n];
    lli b[n];
    lli c[n];
    ncin3(n, a, b, c);

    REPE(i, 0, 40) {
        REP(ag, 0, 401) {
            REP(bg, 0, 401) {
                dp[i][ag][bg] = inf;
            }
        }
    }
    dp[0][0][0] = 0;

    REPE(i, 1, n) {
        REP(ag, 1, 401) {
            REP(bg, 1, 401) {
                if (ag - a[i-1] < 0 || bg - b[i-1] < 0) {
                    dp[i][ag][bg] = dp[i-1][ag][bg];
                }
                else {
                    dp[i][ag][bg] = min(dp[i-1][ag][bg], dp[i-1][ag-a[i-1]][bg-b[i-1]] + c[i-1]);
                }
            }
        }
    }

