    //         }
    //     }
    // }
    lli ans = inf;
    REP(ag, 1, 401) {
        REP(bg, 1, 401) {
            if (bg*ma == ag*mb) {
                ans = min(ans, dp[n][ag][bg]);
            }

        }
    }
    if (ans == inf)
        cout << -1 << endl;
    else
        cout << ans << endl;
}

