struct Package {
	int a, b, c;
};


const int INF = 1e9 + 1;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, m1, m2;
	cin >> n >> m1 >> m2;
	vector<Package> p(n + 1);
	for (int i = 0; i < n; ++i) {
		cin >> p[i + 1].a >> p[i + 1].b >> p[i + 1].c;
	}

	vector<vector<vector<Package>>> dp(n + 1);
	Package t;

	t.a = 0;
	t.b = 0;
	t.c = INF;
	for (int i = 0; i <= n; ++i) {
		dp[i].resize(401);
		for (int j = 0; j < 401; ++j) {
			dp[i][j].resize(401, t);
		}
	}

	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < 401; ++j) {
			dp[i][j][0].c = 0;
			dp[i][j][0].a = 0;
			dp[i][j][0].b = 0;
		}
	}

	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j < 401; ++j) {
			for (int c = 1; c < 401; ++c) {
				if (j >= p[i].a && c >= p[i].b && j - p[i].a == dp[i - 1][j - p[i].a][c - p[i].b].a && c - p[i].b == dp[i - 1][j - p[i].a][c - p[i].b].b && dp[i][j][c].c > dp[i - 1][j - p[i].a][c - p[i].b].c + p[i].c) {
					dp[i][j][c].a = dp[i - 1][j - p[i].a][c - p[i].b].a + p[i].a;	
					dp[i][j][c].b = dp[i - 1][j - p[i].a][c - p[i].b].b + p[i].b;
					dp[i][j][c].c = dp[i - 1][j - p[i].a][c - p[i].b].c + p[i].c;
				} 
			}
		}
	}

	int ans = INF;
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j < 401; ++j) {
			for (int c = 1; c < 401; ++c) {
				if ((j / (__gcd(j, c)) == m1 && (c / __gcd(j, c)) == m2)) ans = min(ans, dp[i][j][c].c); 
			}
		}
	}

	if (ans != INF) cout << ans << endl;
	else cout << -1 << endl;

	return 0;
}

