vector<int> a, b, c;
map<P, int> mp1;
map<P, int> mp2;
int N, Ma, Mb;

void dfs(int i, P sum, int cost)
{
  if (i > N / 2) {
    if (mp1.count(sum))
      mp1[sum] = min(mp1[sum], cost);
    else
      mp1[sum] = cost;
    return;
  }

  dfs(i + 1, make_pair(sum.FI, sum.SE), cost);
  dfs(i + 1, make_pair(sum.FI + a[i], sum.SE + b[i]), cost + c[i]);
}

void dfs2(int i, P sum, int cost)
{
  if (i == N) {
    if (mp2.count(sum))
      mp2[sum] = min(mp2[sum], cost);
    else
      mp2[sum] = cost;
    return;
  }
  dfs2(i + 1, make_pair(sum.FI, sum.SE), cost);
  dfs2(i + 1, make_pair(sum.FI + a[i], sum.SE + b[i]), cost + c[i]);
}

