                sa += A[N/2+j];
                sb += B[N/2+j];
                sc += C[N/2+j];
            }
        }

        S2.pb({{sa,sb},sc});
    }

    sort(all(S1));
    sort(all(S2));

    int ans = infi;


    rep(i,int(S1.size())){


        pair<pii,int> s;
        s.fi.fi = S1[i].fi.fi, s.fi.se = S1[i].fi.se, s.se = S1[i].se;

        if(s.se > ans) continue;

        int ma = Ma, mb = Mb;
        int an = infi;
        while (ma <= 400 && mb <= 400 && an == infi) {

            if(ma < s.fi.fi || mb < s.fi.se){
                ma += Ma,mb += Mb;
                continue;
            }
            int mma = ma - s.fi.fi;
            int mmb = mb - s.fi.se;
            pair<pii,int> cc = {{mma,mmb},0};

            auto itr = lower_bound(all(S2),cc);
            pair<pii,int> aaa = *itr;
            if(aaa.fi == cc.fi){
                an = aaa.se + s.se;
            }



            ma += Ma,mb += Mb;
        }

        chmin(ans,an);



    }

    if(ans == infi) cout << -1 << endl;
    else cout << ans << endl;



    return 0;
}

