typedef struct {
	int a;
	int b;
	int c;
	int exist;
}Drag;

bool next_choice(std::vector<Drag> *d, long int *n, int *keta) {
	for(int i = 0; i < (*d).size(); ++i)
		if ((*d)[i].exist)
			(*d)[i].exist = false;
		else {
			(*d)[i].exist = true;
			(*n)++;
			if (i >= *keta)
				(*keta)++;
			return true;
		}
	return false;
}

Drag drag_mix(std::vector<Drag> d, std::vector<std::vector<Drag>> *v, int min, long int n, int keta) {
	int keta_tmp = keta - 1;
	Drag price = { d[keta_tmp].a, d[keta_tmp].b, d[keta_tmp].c, 1};

	long int num_tmp = n - ((long int)1 << keta_tmp);
	long int tmp = 1023;

	for (int i = 0; i < 4; ++i)
		if (keta_tmp > i * 10) {
			long int a_tmp = (num_tmp >> i * 10) & tmp;
			price.a += v->at(i).at(a_tmp).a;
			price.b += v->at(i).at(a_tmp).b;
			price.c += v->at(i).at(a_tmp).c;
			if (min != -1 && price.c >= min) {
				price.exist = 0;
				return price;
			}
		}
		else {
			int i_tmp = keta_tmp / 10;
			long int k_tmp = (long int)1 << (i_tmp * 10);
			if (n % k_tmp == 0) {
				int j_tmp = n / k_tmp;
				int j_t = num_tmp / k_tmp;
				v->at(i_tmp).at(j_tmp).a = d[keta_tmp].a + v->at(i_tmp).at(j_t).a;
