#include <bits/stdc++.h>

#define REP(i,n) for (int i=0;i<(n);++i)

using namespace std;

using tri = tuple<int, int, int>;

template <class T, class U> void amin(T& x, U y) {if (x > y) x = y;}

constexpr int N_MAX = 40;
constexpr int A_MAX = 10;
constexpr int B_MAX = 10;
constexpr int C_MAX = 100;
constexpr int INF = INT_MAX;

template <class Iterator>
vector<vector<int>> bit(Iterator first, Iterator last) {
    int n = distance(first, last);
    vector<vector<int>> result(A_MAX * N_MAX / 2 + 1, vector<int>(B_MAX * N_MAX / 2 + 1, INF));
    REP(bit, 1 << n) {
        int a = 0, b = 0, c = 0;
        REP(i, n) {
            if (bit & 1 << i) {
                tri t = *(first + i);
                a += get<0>(t);
                b += get<1>(t);
                c += get<2>(t);
            }
        }
        amin(result[a][b], c);
    }
    return result;
}

int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    vector<tri> abc(N);
    REP(i, N) {
        int a, b, c;
        cin >> a >> b >> c;
        abc[i] = tri(a, b, c);
    }

    auto s1 = bit(abc.begin(), abc.begin() + N / 2);
    auto s2 = bit(abc.begin() + N / 2, abc.end());

    int result = INF;
    REP(a1, N_MAX / 2 + 1) REP(b1, N_MAX / 2 + 1) REP(a2, N_MAX / 2 + 1) {
        if ((a1 + a2) * Mb % Ma != 0) {
            continue;
        }
        int b2 = (a1 + a2) * Mb / Ma - b1;
        if (b2 < 0 || N_MAX / 2 < b2 || a1 + a2 == 0 && b1 + b2 == 0) {
            continue;
        }
        int c1 = s1[a1][b1];
        int c2 = s2[a2][b2];
        if (c1 != INF && c2 != INF) {
            amin(result, c1 + c2);
        }
    }
    if (result == INF) {
        cout << (-1) << endl;
    } else {
        cout << result << endl;
    }

    return 0;
}

