int opt(int i, int ca, int cb)
{
	int ra = ca/(__gcd(ca,cb) == 0?1:__gcd(ca,cb));
	int rb = cb/(__gcd(ca,cb) == 0?1:__gcd(ca,cb));
	if(ra == ma && rb == mb)
