	}
	if(dp[i][ca][cb]==-1)
	{
		dp[i][ca][cb] = min(opt(i+1,ra,rb),opt(i+1,ra+A[i],rb+B[i])+C[i]);
	}
	return dp[i][ca][cb];
}

