	ratio = ma / mb;
	for (int i = 0; i < n; i++)
	{
		cin >> x >> y >> z;
		m[((double)x / y)].push_back(z);
	}

	for (auto iter : m)
	{
		if (iter.first > ratio)
		{
			break;
		}
		vector <int> t = iter.second;
		if (iter.first == ratio)
		{
			for (int i = 0; i < t.size(); i++)
			{
				if (res > t[i])
				{
					res = t[i];
				}
			}
		}
		else
		{
			double d = (ratio / iter.first);
			for (int i = 0; i < t.size(); i++)
			{
				for (int j = 0; j < m[d].size(); j++)
				{
					if (res > t[i] + m[d][j])
					{
						res = t[i] + m[d][j];
					}
				}
			}
		}
	}

	if (res != 99999999)
