using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<int, pii> pipii;
typedef pair<double, double> pdd;

map<pii, int> dp;

void solve() {
  int n, ma, mb;
  cin >> n >> ma >> mb;
  while(n--) {
    int a, b, c;
    cin >> a >> b >> c;
    map<pii, int> ndp;
    ndp[{a, b}] = c;
    for(auto out2: dp) {
      pii out = out2.first;
      if(ndp.count(out)) ndp[out] = min(ndp[out], dp[out]);
      else ndp[out] = dp[out];
      if(ndp.count({out.first + a, out.second + b})) ndp[{out.first + a, out.second + b}] = min(ndp[{out.first + a, out.second + b}], dp[out] + c);
      else ndp[{out.first + a, out.second + b}] = dp[out] + c;
    }
    dp = ndp;
  }
  int ret = 1e9;
  for(auto out: dp) {
    pii key = out.first;
    if(key.first * mb == key.second * ma) {
      ret = min(ret, out.second);
    }
  }
  if(ret == 1e9) ret = -1;
  cout << ret << "\n";
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << " ";
    solve();
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  solve();
  // casesolve();
}

