void dfs(int pos,int x,int y,int z){
	if(pos==(n+1)/2){
		q.insert(ppo{x,y,z});
		return;
	}
	dfs(pos+1,x+a[pos],y+b[pos],z+c[pos]);
	dfs(pos+1,x,y,z);
}
void dd(int pos,int x,int y,int z){
	if(pos==n+1){
		for(int i=1;i<=5;i++){
			int ka=ma*i,kb=mb*i;
			auto it=q.lower_bound(ppo{ka-x,kb-y,0});
