int a[N_MAX], b[N_MAX], c[N_MAX];
vector<vector<vector<int>>> dp(N_MAX+1, vector<vector<int>>(C_MAX+1, vector<int>(C_MAX+1, -1)));

int dfs(int n, int x, int y) {
  // cout << n << x << y << endl;
  if (dp[n][x][y]!=-1) return dp[n][x][y];
  if (n==0) {
    if (x==0&y==0) return dp[n][x][y] = 0;
    else return dp[n][x][y] = INF;
  }
  int result = 0;
  if (x<a[n-1]||y<b[n-1]) return dp[n][x][y] = dfs(n-1, x, y);
  else result = min(dfs(n-1, x, y), dfs(n-1, x-a[n-1], y-b[n-1])+c[n-1]);
  return dp[n][x][y] = result;
}

int main() {
  int N, ma, mb; cin >> N >> ma >> mb;
  rep(i, N) cin >> a[i] >> b[i] >> c[i];
  int result = INF;
  for(int i=1; i*max(ma, mb)<=N*10; i++) {
    int tmp = dfs(N, i*ma, i*mb);
    if (tmp>=0) result = min(result, tmp);
  }

  // cout << dfs(3,1,2) << endl;
  if (result==INF) result=-1;
  cout << result << endl;
  return 0;
}

