VI A, B, C;


void solve() {
    REP(i, MAX_M * MAX_N) {
        REP(j, MAX_M * MAX_N) {
            REP(n, MAX_N) {
                P[i][j][n] = INF;
            }
        }
    }
    P[0][0][0] = 0;
    REP(n, N) {
        REP(i, MAX_M * MAX_N - MAX_M) {
            REP(j, MAX_M * MAX_N - MAX_M) {
                int new_i = i + A[n];
                int new_j = j + B[n];
                //cout << new_i << " " << new_j << endl;
                P[new_i][new_j][n + 1] = min(P[new_i][new_j][n], P[i][j][n] + C[n]);
