        int ma = Ma * i; int mb = Mb * i;
        if (ma >= MAX_M * MAX_N or mb >= MAX_M * MAX_N) {
            break;
        }
        //cout << ma << " " << mb << " " << P[ma][mb][N] << endl;
        ans = min(ans, P[ma][mb][N]);
    }
    if (ans == INF) {
        ans = -1;
    }
    cout << ans << endl;
}

