int solve (int i, int aa, int bb)
{
	if (aa >0 && bb >0)
		if (abs((double)aa / (double)bb - (double(ma) / double(mb))) <= 1e-9) {
			return 0;
		}
	if (i >= n) {
		return 1e9;
	}
