            }
        }
    }

    int ans = inf;
    for(int j=1; j<=400; ++j){
        for(int k=1; k<=400; ++k){
            if(Ma*k == Mb*j) ans = min(ans, dp[N][j][k]);
        }
    }

    if(ans == inf) cout << -1 << endl;
    else cout << ans << endl;

    return 0;
}

