        for(auto &t: pre) {
            ll x, cc;
            tie(x, cc) = t;
            x += a*mb - b*ma;
            mp[x] = min(mp.count(x) ? mp[x] : (ll)1e9, cc+c);
        }
    }

    map<ll,ll> mq;
    for(ll i=n/2; i<n; i++) {
        map<ll,ll> pre = mq;
        pre[0] = 0;

        ll a, b, c;
        tie(a, b, c) = v[i];
        for(auto &t: pre) {
            ll x, cc;
