#define MAX_N 100

ll N;
ll Ma, Mb;
ll A[MAX_N] = {};
ll B[MAX_N] = {};
ll C[MAX_N] = {};

ll dp[MAX_N][MAX_N][MAX_N] = {};

template <typename T> T gcd(T a, T b) { while (a) { b %= a; swap(a, b); } return b; }

// i を見ていて現在の比が a:b の時の最小を返す
ll dfs(ll i, ll a, ll b) {
    if(dp[i][a][b] != INF) { return dp[i][a][b]; }
    if(i >= N) {
        if(a != 0 && b != 0 && a == Ma && b == Mb) {
            dp[i][a][b] = 0;
            return 0;
        }
        dp[i][a][b] = -1;
        return -1;
    }

    ll next_a = a + A[i];
    ll next_b = b + B[i];
    ll gcd_val = gcd(next_a, next_b);
    next_a /= gcd_val;
    next_b /= gcd_val;

    // 足してもできるか不明
    // 足す場合
    ll cand1 = dfs(i+1, next_a, next_b);
    if(cand1 != -1) { cand1 += C[i]; }
    // 足さない場合
    ll cand2 = dfs(i+1, a, b);

    ll ret = -1;
    if(cand1 == -1 && cand2 == -1) { ret = -1; }
    else if(cand1 == -1) { ret = cand2; }
    else if(cand2 == -1) { ret = cand1; }
    else { ret = min(cand1, cand2); }
    dp[i][a][b] = ret;
    return ret;
}


