	cin >> n >> ma >> mb;
	v.resize(n);
	for (int i = 0; i < n; i++)
	{
		int a, b;
		cin >> a >> b >> v[i].val;
		v[i].m = a * mb - b * ma;
	}
	sort(v.begin(), v.end(), [](drag &l, drag &r) {return l.m < r.m; });
	calc(0, 0, 0);
	if (result == INT_MAX)
		result = -1;
	printf("%d", result);
	return 0;
}

