const ll INF = (ll)1e18;

ll N, Ma, Mb;
ll a_sum, b_sum;
vector<ll> a, b, c;
ll dp[50][500][500];

void init() {
  for (int i = 0; i <= N; i++) {
    for (int j = 0; j <= a_sum; j++) {
      for (int k = 0; k <= b_sum; k++) {
        dp[i][j][k] = INF;
      }
    }
  }
  dp[0][0][0] = 0;
}

void solve() {
  init();
  for (int i = 0; i < N; i++) {
    for (int ca = 0; ca <= a_sum; ca++) {
      for (int cb = 0; cb <= b_sum; cb++) {
        dp[i + 1][ca][cb] = min(dp[i][ca][cb], dp[i + 1][ca][cb]);
        dp[i + 1][ca + a[i]][cb + b[i]] =
            min(dp[i][ca][cb] + c[i], dp[i + 1][ca + a[i]][cb + b[i]]);
      }
    }
  }

  ll res = INF;
  for (int ca = 0; ca <= a_sum; ca++) {
    for (int cb = 0; cb <= b_sum; cb++) {
      if (Ma * cb == Mb * ca && ca != 0 && cb != 0 && dp[N][ca][cb] != INF) {
        res = min(res, dp[N][ca][cb]);
      }
    }
  }
