                if (dp[i+1][j][k] != inf && j+a[i] < size && k+b[i] < size) {
                    chmin(dp[i+1][j+a[i]][k+b[i]], dp[i+1][j][k] + c[i]);
                }
            }
        }
    }

    ll rate = 1;
    ll ans = inf;
    while (true) {
            if (Ma*rate >= size || Mb*rate >= size) {
            break;
        }

        if (dp[N][Ma*rate][Mb*rate] != inf) {
            chmin(ans, dp[N][Ma*rate][Mb*rate]);
        }
        rate++;
    }
    if (ans == inf) ans = -1;
    cout << ans << "\n";
}

