class info
{
	public:
	int num;
	int A,B,C;
	bool operator <(const info &rhs)
	{
		if(num==rhs.num)
			return C<rhs.C;
		return num<rhs.num;
	}
};

int main()
{
	int N;
	int a[50]={};
	int b[50]={};
	int c[50]={};
	int MA,MB;

	cin >> N >> MA >> MB;
	for(int i=0;i<N;i++)
		cin >> a[i] >> b[i] >> c[i];

	vector<info> f,s;
	for(int bit=0;bit<pow(2,N/2);bit++)
	{
		int x=bit;
		int A=0,B=0,C=0;
		for(int i=0;i<N/2;i++)
		{
			if(x%2==1)
			{
				A+=a[i];
				B+=b[i];
				C+=c[i];
			}
			x/=2;
		}
		f.push_back({MA*B-MB*A,A,B,C});
	}
	for(int bit=0;bit<pow(2,N-N/2);bit++)
	{
		int x=bit;
		int A=0,B=0,C=0;
		for(int i=0;i<N-N/2;i++)
		{
			if(x%2==1)
			{
				A+=a[i+N/2];
				B+=b[i+N/2];
				C+=c[i+N/2];
			}
			x/=2;
		}
		s.push_back({-(MA*B-MB*A),A,B,C});
	}

	sort(s.begin(),s.end());

	int ans=1e9;
	for(auto&& i:f)
	{
		auto itr=lower_bound(s.begin(),s.end(),i);
		if(itr==s.end())
			continue;
		if(itr->num!=i.num)
			continue;
		if(i.A+i.B+itr->A+itr->B==0)
			continue;
		ans=min(ans,i.C+itr->C);
	}

	if(ans==1e9)
		cout << -1;
	else
		cout << ans;
	cout << endl;
	return 0;
}

