inline void work() {
	int a, b, c, now = 0, pre = 1;
	in(n), in(Ma), in(Mb), memset(f[0], inf, sizeof f[0]);
	for (int l = 1; l <= n; ++l) {
		in(a), in(b), in(c);
		now ^= 1, pre = now^1;
		memset(f[now], inf, sizeof f[now]);
		f[pre][a][b] = min(f[pre][a][b], c);
		for (int i = 0; i < N; ++i)
			for (int j = 0; j < N; ++j) {
				if (f[pre][i][j] == inf) continue;
				f[now][i][j] = min(f[now][i][j], f[pre][i][j]);
