using namespace std;

struct Mixed {
    int a, b, c;
    static int Ma, Mb;
    Mixed() : a(0), b(0), c(0) {}
    bool operator<(Mixed& rhs) {
        int this_value = this->a * (Ma + Mb) - Ma * (this->a + this->b);
        int rhs_value = rhs.a * (Ma + Mb) - Ma * (rhs.a + rhs.b);
        return (this_value != rhs_value ? this_value < rhs_value : this->c < rhs.c);
    }
    bool operator<(int target) {
        int this_value = this->a * (Ma + Mb) - Ma * (this->a + this->b);
        return (this_value < target);
    }
};

int Mixed::Ma;
int Mixed::Mb;

int main() {
    int N, Ma, Mb;
    cin >> N >> Ma >> Mb;

    Mixed::Ma = Ma;
    Mixed::Mb = Mb;

    vector<int> a(N), b(N), c(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i] >> b[i] >> c[i];
    }

    int half_N = N / 2;
    //半分全列挙


    //前半を列挙
    vector<Mixed> half1;
    for (int i = 0; i < (1 << half_N); i++) {
        Mixed tmp;
        for (int j = 0; j < half_N; j++) {
            if (i & (1 << j)) {
                //立っていたらカウント
                tmp.a += a[j];
                tmp.b += b[j];
                tmp.c += c[j];
            }
        }
        half1.push_back(tmp);
    }

    //後半を列挙
    int another_half = N - half_N;
    vector<Mixed> half2;
    for (int i = 1; i < (1 << another_half); i++) {
        Mixed tmp;
        for (int j = 0; j < another_half; j++) {
            if (i & (1 << j)) {
                //立っていたらカウント
                tmp.a += a[j + half_N];
                tmp.b += b[j + half_N];
                tmp.c += c[j + half_N];
            }
        }
        half2.push_back(tmp);
    }

    //後半の方をソート
    sort(half2.begin(), half2.end(), [&](Mixed& lhs, Mixed& rhs) {
        int lhs_value = lhs.a * (Ma + Mb) - Ma * (lhs.a + lhs.b);
        int rhs_value = rhs.a * (Ma + Mb) - Ma * (rhs.a + rhs.b);
        return (lhs_value != rhs_value ? lhs_value < rhs_value : lhs.c < rhs.c);
    });

    int ans = INT_MAX;
    for (auto m : half1) {
        //mと合わせて比が正しくなるものをhalf2の中から2分探索
        int need = -(m.a * (Ma + Mb) - Ma * (m.a + m.b));
        auto pair = lower_bound(half2.begin(), half2.end(), need);
        //確認
        int sum_a = m.a + pair->a;
        int sum_b = m.b + pair->b;
        if (Ma * sum_b == Mb * sum_a) {
            ans = min(ans, m.c + pair->c);
        }
    }
    if (ans == INT_MAX) {
        ans = -1;
    }

    cout << ans << endl;
}

