// Matrix class.
    template<class T, int size_m, int size_n>
    struct Matrix {
        T val[size_m][size_n];

        Matrix() {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    val[i][j] = 0;
        }

        /**
         * \brief Matrix type casting for another matrix of the same dimension.
         */
        template<class U>
        Matrix(Matrix<U, size_m, size_n> mat) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    val[i][j] = mat.val[i][j];
        }

        /**
         * \brief Construct a matrix from a 2D array.
         */
        Matrix(T **arr) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    val[i][j] = arr[i][j];
        }

        /**
         * \brief Returns the reference to the cell (i, j) in the matrix.
         */
        T &operator()(const int i, const int j) { return val[i][j]; }

        /**
         * \brief Explicitly cast the matrix to Matrix<U>.
         */
        template<class U>
        const Matrix<U, size_m, size_n> convert() { return Matrix<U, size_m, size_n>(*this); }

        const Matrix operator+=(const Matrix<T, size_m, size_n> mat) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    (*this)(i, j) += mat(i, j);
        }

        const Matrix operator-=(const Matrix<T, size_m, size_n> mat) {
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    (*this)(i, j) -= mat(i, j);
        }

        const Matrix operator+(const Matrix<T, size_m, size_n> mat) {
            Matrix<T, size_m, size_n> res = *this;
            res += mat;
            return res;
        }

        const Matrix operator-(const Matrix<T, size_m, size_n> mat) {
            Matrix<T, size_m, size_n> res = *this;
            res -= mat;
            return res;
        }

        /**
         * \brief Matrix-matrix multiplication.
         */
        template<int size_p>
        Matrix<T, size_m, size_p> operator*(Matrix<T, size_n, size_p> mat) {
            Matrix<T, size_m, size_p> res;
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_p; j++)
                    for (int k = 0; k < size_n; k++)
                        res(i, j) += (*this)(i, k) * mat(k, j);
            return res;
        }

        /**
         * \brief Matrix-vector multiplication.
         */
        Vector<T, size_n> operator*(Vector<T, size_n> vec) {
            Vector<T, size_n> res;
            for (int i = 0; i < size_m; i++)
                for (int j = 0; j < size_n; j++)
                    res.val[j] += val[i][j] * vec[j];
            return res;
        }
    };

// Vector class.
    template<class T, int size>
    struct Vector {
        /**
         * Specialization for Vector of size 2.
         */
        template<class U>
        static const Vector<U, 2> vec2(U a, U b) {
            Vector<U, 2> vec;
            vec.val[0] = a, vec.val[1] = b;
            return vec;
        }

        /**
         * Specialization for Vector of size 3.
         */
        template<class U>
        static const Vector<U, 3> vec3(U a, U b, U c) {
            Vector<U, 3> vec;
            vec.val[0] = a, vec.val[1] = b, vec.val[2] = c;
            return vec;
        }

        T val[size];

        /**
         * \brief Empty vector constructor.
         */
        Vector() {
            for (int i = 0; i < size; i++)
                val[i] = 0;
        }

        /**
         * \brief Vector type casting for another vector of the same size.
         */
        template<class U>
        Vector(Vector<U, size> vec) {
            for (int i = 0; i < size; i++)
                val[i] = vec.val[i];
        }

        /**
         * \brief Constructing a vector from an array.
         */
        Vector(T *arr) {
            for (int i = 0; i < size; i++)
                val[i] = arr[i];
        }

        /**
         * \brief Explicitly cast the vector to Vector<U> with the same size.
         */
        template<class U>
        Vector<U, size> convert() { return Vector<U, size>(*this); }

        const Vector operator+(const Vector &vec) const {
            Vector v = *this;
            v += vec;
            return v;
        }

        const Vector operator-(const Vector &vec) const {
            Vector v = *this;
            v -= vec;
            return v;
        }

        const Vector operator*(const Vector &vec) const {
            Vector v = *this;
            v *= vec;
            return v;
        }

        const Vector operator/(const Vector &vec) const {
            Vector v = *this;
            v /= vec;
            return v;
        }

        const Vector operator+=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] += vec.val[i];
            return *this;
        }

        const Vector operator-=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] -= vec.val[i];
            return *this;
        }

        const Vector operator*=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] *= vec.val[i];
            return *this;
        }

        const Vector operator/=(const Vector &vec) {
            for (int i = 0; i < size; i++)
                val[i] /= vec.val[i];
            return *this;
        }

        /**
         * \brief Compute the dot product of two vectors.
         */
        const T dot(const Vector<T, size> vec) {
            T acc = 0;
            for (int i = 0; i < size; i++)
                acc += val[i] * vec.val[i];
