    struct Log2Table {
        vector<int> val;
        // Last value that we computed to.
        int pmax = 0;

        Log2Table() {
            val.resize(1);
            val[0] = -1;
        }

        int get(int n) {
            if (n >= val.size()) {
                eprintf("Error: request log2[%d] but is not computed yet\n", n);
                exit(1);
            }

            return val[n];
        }

        void require(int n) {
            if (n < pmax)
                return;
            val.resize(n + 1);

            for (int i = 0; i < 30; i++)
                for (int j = max(1 << i, pmax + 1); j < min(1 << (i + 1), n + 1); j++)
                    val[j] = i;

            pmax = n;
        }
    };

