long long memo[500][500][50];
long long N, MA, MB;
long long a[100];
long long b[100];
long long c[100];

int main(){
	cin >> N >> MA >> MB;
	for(long long i = 0; i < N; i++){
		cin >> a[i] >> b[i] >> c[i];
	}
	for(long long i = 0; i < 500; i++){
		for(long long j = 0; j < 500; j++){
			for(long long k = 0; k < 50; k++){
				memo[i][j][k] = INT_MAX;
			}
		}
	}

	memo[0][0][0] = 0;
	for(long long k = 0; k < N; k++){
		long long av = a[k];
		long long bv = b[k];
		long long cv = c[k];
		for(long long i = 499; i >= 0; i--){
			for(long long j = 499; j >= 0; j--){
				if(i + av < 500  && j + bv < 500){
					memo[i+av][j+bv][k+1] = min(memo[i+av][j+bv][k+1], min(memo[i+av][j+bv][k], memo[i][j][k] + cv));
				}
			}
		}
	}

	long long ans = INT_MAX;
	for(long long i = 1; i < 500; i++){
		for(long long j = 1; j < 500; j++){
			if(i%MA == 0 && j%MB == 0 && i/MA == j/MB)
				ans = min(ans, memo[i][j][N]);
		}
	}
	if(ans == INT_MAX){
		ans = -1;
	}
	cout << ans << endl;
}

