		std::cin >> drag[i].a;
		std::cin >> drag[i].b;
		std::cin >> drag[i].c;
	}

	std::vector<std::vector<Drag>> v(4, std::vector<Drag>(1024));

	long int num = 0;
	int keta = 0;
	double m = ma / mb;
	Drag mix;
	int min = -1;
	while(next_choice(&drag, &num, &keta)){
		mix = drag_mix(drag, min, keta);
		if (mix.exist && (double)mix.a / mix.b == m)
			if(min == -1 || mix.c < min)
				min = mix.c;
	};

	std::cout << min;
}

