map<P, int> make_p(vector<Solution> &v) {
    map<P, int> ans;
    int n = v.size();
    rep(i, 1 << n) {
        int a = 0, b = 0, c = 0;
        rep(j, n) if ((i >> j) & 1) {
                a += v[j].a;
                b += v[j].b;
                c += v[j].c;
            }
        P p(a, b);
        if (ans.find(p) == ans.end()) {
            ans[p] = c;
        } else {
            cmin(ans[p], c);
        }
    }
    return ans;
}

