	void dijkstra(int posStart) {
		val(posStart).dijk = 0;
		//
		bfs(posStart, [&](int now, int next, int w) {
			if (val(next).dijk == Dijk::MINVAL || val(next).dijk > val(now).dijk + w) {
				val(next).dijk = val(now).dijk + w;
				return true;
			}
			return false;
			});
