struct Data {
    int a, b, c;
    Data(int a = 1, int b = 1, int c = 0) : a(a), b(b), c(c) {
        int g = __gcd(a, b);
        a /= g;
        b /= g;
    }
    bool operator<(const Data &rhs) const {
        int c = rhs.a;
        int d = rhs.b;
        return make_pair(a * d, c) < make_pair(c * b, rhs.c);
    }
};
int N, M[2];
int a[50], b[50], c[50];
vector<int> s[2];
vector<Data> d[2];
int main() {
    cin >> N >> M[0] >> M[1];
    rep(i, N) cin >> a[i] >> b[i] >> c[i];
    rep(i, N) { s[i % 2].push_back(i); }
    assert(s[0].size() <= 20);
    assert(s[1].size() <= 20);
    rep(i, 2) rep(S, 1 << s[i].size()) {
        int A = 0, B = 0, C = 0;
        if (S == 0) continue;
        rep(j, s[i].size()) if (S >> j & 1) {
            A += a[s[i][j]];
            B += b[s[i][j]];
            C += c[s[i][j]];
        }
        d[i].push_back(Data(A, B, C));
    }
    rep(i, 2) sort(all(d[i]));
    const int INF = 1e8;
    int ans = INF;
    rep(i, d[0].size()) {
        Data t(M[0] * d[0][i].b, M[1] * d[0][i].a, 0);
        int idx = lower_bound(all(d[1]), t) - d[1].begin();
        if (idx == d[1].size()) continue;
        int A = d[0][i].a * d[1][idx].a;
        int B = d[0][i].b * d[1][idx].b;
        int G = __gcd(A, B);
        A /= G;
        B /= G;
        if (M[0] == A && M[1] == B) {
            ans = min(ans, d[0][i].c + d[1][idx].c);
        }
    }
    if (ans == INF) ans = -1;
    cout << ans << endl;

    return 0;
}

