void solve(long long N, long long M_a, long long M_b, std::vector<long long> a,
           std::vector<long long> b, std::vector<long long> c) {
  ll MAXDRAG = 401;
  ll INF = 1e8;

  vector<vector<vector<ll>>> dp(
      N + 1, vector<vector<ll>>(MAXDRAG, vector<ll>(MAXDRAG, INF)));

  dp[0][0][0] = 0;

  for (ll n = 1; n <= N; n++) {
    rep(ai, MAXDRAG) {
      rep(bi, MAXDRAG) {
        // 選ばない場合
        dp[n][ai][bi] = dp[n - 1][ai][bi];

        // 選ぶかもしれない場合
        if (ai - a[n - 1] >= 0 && ai - a[n - 1] < MAXDRAG &&
            bi - b[n - 1] >= 0 && bi - b[n - 1] < MAXDRAG) {
          dp[n][ai][bi] =
              min(dp[n][ai][bi],
                  dp[n - 1][ai - a[n - 1]][bi - b[n - 1]] + c[n - 1]);
        }
      }
    }
  }

  ll cost = INF;
  ll i = 1;
  ll ma = M_a;
  ll mb = M_b;
  while (ma < MAXDRAG && mb < MAXDRAG) {
    cost = min(cost, dp[N][ma][mb]);
    i++;
    ma = M_a * i;
    mb = M_b * i;
  }
  if (cost == INF) {
    print(-1);
  } else {
    print(cost);
  }
}

int main() {
  long long N;
  scanf("%lld", &N);
  long long M_a;
  scanf("%lld", &M_a);
  long long M_b;
  scanf("%lld", &M_b);
  std::vector<long long> a(N);
  std::vector<long long> b(N);
  std::vector<long long> c(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &a[i]);
    scanf("%lld", &b[i]);
    scanf("%lld", &c[i]);
  }
  solve(N, M_a, M_b, std::move(a), std::move(b), std::move(c));
  return 0;
}

