    }

    rep(j,num) {
      int p = check.front();
      check.pop();
      check.push(p);

      if (p+d == 0) {  // some sum of dif = 0
        ans.push(dps_q.front() + med[i][2]);
      }
      else if (!dps.count(p+d)) {  // for the first time
        check.push(p+d);
        dps[p+d] = dps_q.front() + med[i][2];
      }
      else if (dps_q.front() + med[i][2] < dps[p+d]) {  // less cost
        dps[p+d] = dps_q.front() + med[i][2];
      }
      dps_q.pop();
    }
  }
  if (ans.empty()) {
    cout << -1 << endl;
    return 0;
  }
  cout << ans.top() << endl;
  return 0;
}

