    cin >> a[i] >> b[i] >> c[i];
  }

  for(int i = 0; i < N; i++){
    for(int j = 0; j <= 400; j++){
      for(int k = 0; k <= 400; k++){
        dp[i][j][k] = INT_MAX;
      }
    }
  }

  dp[0][0][0] = 0;
  dp[0][a[0]][b[0]] = c[0];

  for(int i = 1; i < N; i++){
    for(int j = 0; j <= 400; j++){
