        dp[i][j][k] = min(dp[i][j][k], dp[i - 1][j][k]);
        if(j >= a[i] && k >= b[i] && dp[i - 1][j - a[i]][k - b[i]] != INT_MAX){
          dp[i][j][k] = min(dp[i][j][k], c[i] + dp[i - 1][j - a[i]][k - b[i]]);
        }
      }
    }
  }

  int ans = INT_MAX;
  for(int i = 1; i <= 400; i++){
    for(int j = 1; j <= 400; j++){
      if(i % M_a == 0 && j % M_b == 0 && i / M_a == j / M_b){
        ans = min(ans, dp[N - 1][i][j]);
      }
    }
