int main() {
  ll N, Ma, Mb;
  cin >> N >> Ma >> Mb;
  vi a(N), b(N), c(N);
  for (ll i = 0; i < N; i++) {
    cin >> a[i] >> b[i] >> c[i];
  }
  unordered_map<ll, ll> m1, m2;
  m1[0] = 0;
  m2[0] = 0;
  for (ll i = 0; i < N / 2; i++) {
    vpii v;
    for (auto p: m1) {
      v.push_back(p);
    }
    for (auto p: v) {
      ll j = (p.first / 10000 + a[i]) * 10000 + p.first % 10000 + b[i];
      ll k = p.second + c[i];
      if (m1.find(j) == m1.end()) {
        m1[j] = k;
      } else {
        m1[j] = min(m1[j], k);
      }
    }
  }
  for (ll i = N / 2; i < N; i++) {
    vpii v;
    for (auto p: m2) {
      v.push_back(p);
    }
    for (auto p: v) {
      ll j = (p.first / 10000 + a[i]) * 10000 + p.first % 10000 + b[i];
      ll k = p.second + c[i];
      if (m2.find(j) == m2.end()) {
        m2[j] = k;
      } else {
        m2[j] = min(m2[j], k);
      }
    }
  }

  ll ans = (1ll << 32);
  for (ll i = 1; i <= 400; i++) {
    ll t = (Ma * 10000 + Mb) * i;
    for (auto p: m1) {
      if (m2.find(t - p.first) != m2.end()) {
        ans = min(ans, m2[t - p.first] + p.second);
      }
    }
  }

  if (ans == (1ll << 32)) {
    cout << -1 << endl;
  } else {
    cout << ans << endl;
  }
}

