#pragma warning(disable : 4996)

#define MAX_N 40

int N, MA, MB;

int A[MAX_N+1];
int B[MAX_N+1];
int C[MAX_N+1];

int DP[MAX_N+1][MAX_N * 10+1][MAX_N * 10+1];

int INF = 10000;

int min(int a, int b) {
	if (a < b) return a;
	return b;
}

int main(void) {
	scanf("%d %d %d", &N, &MA, &MB);
	for (int i = 0; i < N; ++i) {
		scanf("%d %d %d", &A[i+1], &B[i+1], &C[i+1]);
	}
	for (int i = 0; i < N+1; ++i) {
		for (int j = 0; j <= N * 10; ++j) {
			for (int k = 0; k <= N * 10; ++k) {
				DP[i][j][k] = INF;
			}
		}
	}


	for (int i = 1; i < N+1; ++i) {
		for (int j = 1; j <= N * 10; ++j) {
			for (int k = 1; k <= N * 10; ++k) {
				int prev = DP[i-1][j][k];
				int now = INF;
				if ((j - A[i] >= 0) && (k - B[i] >= 0)) {
					int base = DP[i - 1][j - A[i]][k - B[i]];
					if ((base == INF) && (j == A[i]) && (k == B[i])) {
						now = C[i];
					}
					else if (base == INF) {
						now = INF;
					}
					else {
						now = base + C[i];
					}
				}
				DP[i][j][k] = min(prev, now);
			}
		}
	}

	int minC = INF;

	for (int i = 1; i <= N * 10; ++i) {
		for (int j = 1; j <= N * 10; ++j) {
			if (MB*i == MA * j) {
				if (DP[N][i][j] < minC) {
					minC = DP[N][i][j];
				}
			}
		}
	}
	if (minC == INF) {
		printf("-1");
	}
	else {
		printf("%d", minC);
	}

	return 0;
}

