    for (int i = 0; i < n; ++i) {
        auto x = a[i];
        auto y = b[i];
        for (int l = 1; l <= sz; ++l) {
            for (int r = 1; r <= sz; ++r) {
                auto nx = x + l;
                auto ny = y + r;
                auto d = gcd(nx, ny);
                nx /= d;
                ny /= d;
                if (nx > sz or ny > sz) {
                    continue;
                }
                dp[nx][ny] = min(dp[nx][ny], dp[l][r] + c[i]);
            }
        }
        dp[x][y] = min(dp[x][y], c[i]);
    }
    int best = 1e9;
    int x = 0;
