vector<int> bit2value(const vector<vector<int>>& obj, const int i)
{
	const int N = obj.size();
	int a = 0;
	int b = 0;
	int c = 0;

	REP(j, N) if (i&(1 << j)) {
		a += obj[j][0];
		b += obj[j][1];
		c += obj[j][2];
	}
	return { a,b,c };
}

map<int, map<int, int>> make_half(const vector<vector<int>>& obj)
{
	const int N = obj.size();
	map<int, map<int, int>> res;

	REP(i, 1 << N) {
		auto sum = bit2value(obj, i);
		int a = sum[0];
		int b = sum[1];
		int c = sum[2];

		if (res[a].find(b) == res[a].end()) {
			res[a][b] = c;
		}
		else {
			res[a][b] = min(res[a][b], c);
		}
	}
	return res;
}


int find_pair(map<int, map<int, int>>& other, const vector<int>& sum)
{
	int cost = INF;
	int a = sum[0];
	int b = sum[1];
	int c = sum[2];
	FOR(times, 1, suma / Ma + 1)
	{
		ll obja = Ma * times;
		ll objb = Mb * times;
		ll resta = obja - a;
		ll restb = objb - b;
		if (resta < 0)continue;
		if (restb < 0)continue;

		//if (other.find(resta) == other.end())continue;
		if (other[resta].find(restb) == other[resta].end())continue;
		cost = min(cost, other[resta][restb]);
	}
	return cost + c;
}


