        int g = __gcd(a, b);
        a /= g;
        b /= g;
    }
    bool operator<(const Data &rhs) const {
        int c = rhs.a;
        int d = rhs.b;
        return make_tuple(a, b, c) < make_tuple(c, d, rhs.c);
        return make_pair(a * d, c) < make_pair(c * b, rhs.c);
    }
    bool operator==(const Data &rhs) const {
        return make_tuple(a, b, c) == make_tuple(rhs.a, rhs.b, rhs.c);
    }
};
