// 単一始点最短経路問題を解くアルゴリズム．負辺があるとやり直しが発生し，最悪負のループがあると終了しないため，ベルマンフォードを使う．下の実装は優先度付きキューを使用．
// 密なグラフではO(n2)の実装(graph/dijkstra-matrix.cc) を使うべき．負辺は計算量に影響し，最悪無限ループ．
// 計算量O((E+V)logV)
vector<Weight> dijkstra_sparse(const Graph &g, int s){
	const Weight INF = numeric_limits<Weight>::max()/8;
	using state = tuple<Weight,int>;
	priority_queue<state> q;
	vector<Weight> dist(g.size(),INF);
	dist[s] = 0;
	q.emplace(0,s);
	while(q.size()){
		Weight d;
		int v;
		tie(d, v) = q.top();
		q.pop();
		d *= -1;
		/* if(v == t) return d; */
		if(dist[v] < d) continue;
		for(auto &e : g[v]){
			if (dist[e.dst] > dist[v] + e.weight){
				dist[e.dst] = dist[v] + e.weight;
				q.emplace(-dist[e.dst], e.dst);
			}
		}
	}
	return dist;
}

// ヒープを使わないダイクストラ法．密（E∝V^2）なグラフではこっちの方が高速．
// 計算量O(V^2)
std::vector<Weight> dijkstra_dense(const Graph &g, int s) {
	static const Weight INF = std::numeric_limits<Weight>::max() / 8;
	const size_t n = g.size();
	Matrix m(n, Array(n, INF));
	for (const Edges &es : g)
		for (const Edge &e : es) m[e.src][e.dst] = std::min(m[e.src][e.dst], e.weight);
	std::vector<Weight> d(n, INF);
	std::vector<int> used(n);
	d[s] = 0;
	while (1) {
		int v = -1;
		for (size_t j = 0; j < n; j++)
			if (!used[j] && (v == -1 || d[j] < d[v])) v = j;
		if (v == -1) break;
		used[v] = true;
		/* if(v == t) return d[v]; */
		for (const Edge &e : g[v]) {
			int u = e.dst;
			d[u] = std::min(d[u], d[v] + m[v][u]);
		}
	}
	return d;
}

// O(V^3)
Matrix WarshallFloyd(const Graph &g) {
	auto const INF = numeric_limits<Weight>::max()/8;
	int n = g.size();
	Matrix d(n,Array(n,INF));
	rep(i,n) d[i][i]=0;
	rep(i, n) for(auto &e: g[i]) d[e.src][e.dst] = min(d[e.src][e.dst],e.weight);
	rep(k,n) rep(i,n) rep(j,n)
		if(d[i][k]!=INF && d[k][j]!=INF) d[i][j] = min(d[i][j],d[i][k]+d[k][j]);
	return d;
}

