int dp[MAX_N + 1][MAX_N * MAX_AB + 1][MAX_N * MAX_AB + 1];

int main(void) {
    cin >> N >> Ma >> Mb;
    for (int i = 0; i < N; ++i) {
        cin >> a[i] >> b[i] >> c[i];
    }

