                dp[i][ca][cb] = INF;
            }
        }
    }

    dp[0][0][0] = 0;
    for (int i = 0; i < N; ++i) {
        for (int ca = 0; ca <= MAX_N * MAX_AB; ++ca) {
            for (int cb = 0; cb <= MAX_N * MAX_AB; ++cb) {
                if (dp[i][ca][cb] == INF) continue;
                dp[i + 1][ca][cb] = min(dp[i + 1][ca][cb], dp[i][ca][cb]);
