#include <iostream>
#include <vector>
#define MAX 5000
using namespace std ;

vector<int> a, b, c;
int n, ma, mb, opt;
int search(int sumA, int sumB, int sumC, int st){
    if(sumC>=opt){return MAX;}   
    if((sumA+a[st])*mb==(sumB+b[st])*ma){
        if(sumC+c[st]<opt){opt=sumC+c[st];}
        return sumC+c[st];
    }
    else{
        if(st==n-1){return MAX;}
        else{
            int x=search(sumA, sumB, sumC, st+1);
            int y=search(sumA+a[st], sumB+b[st], sumC+c[st], st+1);
            return min(x,y);
        }
    }
}
int main(void){
    opt=MAX;
    cin>>n>>ma>>mb;
    int ai,bi,ci;
    for(int i=0;i<n;i++){
        cin>>ai>>bi>>ci;
        a.push_back(ai);
        b.push_back(bi);
        c.push_back(ci);
    }
    if(search(0,0,0,0)>=MAX) opt=-1;
    cout<<opt<<endl;
}

