int main() {

    int N,Ma,Mb;
    scanf("%d %d %d", &N, &Ma, &Mb);

    int* mat;
    int mat_s = N*10 + 1;
    mat = (int*)malloc(sizeof(int)*mat_s*mat_s);
    for(int i=0;i<mat_s*mat_s;i++) {
        mat[i] = INF;
    }

    int* a_v = (int*)malloc(sizeof(int)*N);
    int* b_v = (int*)malloc(sizeof(int)*N);
    int* c  = (int*)malloc(sizeof(int)*N);

    for(int i=0;i<N;i++) {
        scanf("%d %d %d", &a_v[i], &b_v[i], &c[i]);
        mat[a_v[i]*mat_s + b_v[i]] = c[i];
    }

    for(int a=0;a<mat_s;a++) {
        for(int b=0;b<mat_s;b++) {
            for(int i=0;i<N;i++) {
                if(a - a_v[i] > 0 && b - b_v[i] > 0) {
                    if(mat[a*mat_s + b] > mat[(a - a_v[i])*mat_s + (b - b_v[i])] + c[i]) {
                        mat[a*mat_s + b] = mat[(a - a_v[i])*mat_s + (b - b_v[i])] + c[i];
                    }
                }
            }
        }
    }
    int res = INF;
    for(int i=1;(Ma*i<mat_s && Mb*i<mat_s);i++) {
        if(res > mat[(Ma*i)*mat_s + Mb*i]) {
//          printf("%d %d\n", Ma*i,Mb*i);
            res = mat[(Ma*i)*mat_s + Mb*i];
        }
    }

    if(res == INF) {
        printf("%d\n", -1);
    } else {
        printf("%d\n", res);
    }

    return 0;
}

