using namespace std;

const int INF = 0x3f3f3f3f;
const int MAX_M = 10, MAX_N = 40;

int N, A, B, asum, bsum, cmin;
int a[MAX_N], b[MAX_N], c[MAX_N];
int dp[MAX_N + 1][MAX_M * MAX_N + 1][MAX_M * MAX_N + 1];

main() {
  cin >> N >> A >> B;
  REP(i, N) cin >> a[i] >> b[i] >> c[i];

  REP(i, N) asum += a[i];
  REP(i, N) bsum += b[i];

  REP(ca, asum + 1) REP(cb, bsum + 1) {
    dp[0][ca][cb] = INF;
  }
  dp[0][0][0] = 0;
  REP(i, N) REP(ca, asum + 1) REP(cb, bsum + 1) {
    if (ca >= a[i] && cb >= b[i]) {
      dp[i + 1][ca][cb] = min(dp[i][ca][cb], dp[i][ca - a[i]][cb - b[i]] + c[i]);
    } else {
      dp[i + 1][ca][cb] = dp[i][ca][cb];
    }
  }
  cmin = INF;
  REP(ca, asum + 1) REP(cb, bsum + 1) {
    if (ca == 0 && cb == 0) continue;
    if (ca * B == cb * A && dp[N][ca][cb] < cmin) cmin = dp[N][ca][cb];
  }

  cout << (cmin < INF ? cmin : -1) << endl;
}

