using namespace std;

const int NMax = 40;
const int abMax = 10;
const int cMax = 100;

const int INF = cMax * NMax + 1;

const int abNMax = abMax * NMax;

array<int, NMax> a;
array<int, NMax> b;
array<int, NMax> c;

array<array<array<int, abNMax + 1>, abNMax + 1>, NMax + 1> dp;

int main()
{
    int N, Ma, Mb;
    if (scanf("%d%d%d", &N, &Ma, &Mb) < 3) return 0;

    // 0-indexed
    for (int i = 0; i < N; i++)
    {
        if (scanf("%d%d%d", &a[i], &b[i], &c[i]) < 3) return 0;
    }

    // none dp[0][0][0] = 0;
    for (int i = 0; i <= N; i++)
    {
        for (int j = 0; j <= abNMax; j++)
        {
            for (int k = 0; k <= abNMax; k++)
            {
                dp[i][j][k] = INF;
            }
        }
    }

    // none
    dp[0][0][0] = 0;

    // update dp[i + 1]
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j <= abNMax; j++)
        {
            for (int k = 0; k <= abNMax; k++)
            {
                if (dp[i][j][k] == INF) continue;

                // not select
                dp[i + 1][j][k]
                    = min(dp[i][j][k], dp[i + 1][j][k]);

                // select
                dp[i + 1][j + a[i]][k + b[i]]
                    = min(
                        dp[i][j][k] + c[i],
                        dp[i + 1][j + a[i]][k + b[i]]);
            }
        }
    }

    int ans = INF;
    for (int i = 1; i < abNMax; i++)
    {
        for (int j = 1; j < abNMax; j++)
        {
            if (i * Mb == j * Ma) ans = min(ans, dp[N][i][j]);
        }
    }

    if (ans == INF) printf("%d\n", -1);
    else printf("%d\n", ans);

    return 0;
}

