int N, Ma, Mb, a, b, c;
vector<vector<int>> v;
map<tuple<int, int, int>, LL> memo;

LL dfs(int i, int a, int b) {
	if (a != 0 && b != 0) {
		int d = max(Ma, a) / min(Ma, a);
		if (Ma * d == a && Mb * d == b) {
			return 0;
		}
		if (a * d == Ma && b * d == Mb) {
			return 0;
		}

	}

	if (i == N) {
		return 1e10;
	}

	if (memo.find(make_tuple( i, a, b)) != memo.end()) {
		return memo[{i, a, b}];
	}

	LL ans = dfs(i + 1, a + v[i][0], b + v[i][1]) + v[i][2];
	ans = min(ans, dfs(i + 1, a, b));

	return memo[make_tuple(i, a, b)] = ans;

}


