int n,ma,mb;
struct Medicine
{
  int a,b,c,value;
  Medicine() {}
  Medicine(int a, int b, int c) : a(a),b(b),c(c) {
    value = ma*b-mb*a;
  }
  void compute_value() {
    value = ma*b-mb*a;
  }
};

int main() {
  std::cin >> n >> ma >> mb;
  std::vector<Medicine> med(n);
  rep(i,n) {
    std::cin >> med[i].a >> med[i].b >> med[i].c;
    med[i].compute_value();
  }
  std::vector<Medicine> positive;
  std::vector<Medicine> negative;
  std::vector<Medicine> zero;
  for(auto m:med) {
    if(m.value>0) positive.push_back(m);
    else if(m.value<0) negative.push_back(m);
    else zero.push_back(m);
  }
  int mincost = INF;
  for(auto m:zero) mincost = std::min(mincost,m.c);
  std::map<int,int> pmap;
  std::map<int,int> nmap;
  pmap[0] = 0;
  nmap[0] = 0;
  for(auto i:positive) {
    for(auto e:pmap) {
      if(pmap.find(e.first+i.value)!=pmap.end())
        pmap[e.first+i.value] = std::min(pmap[e.first+i.value],pmap[e.first]+i.c);
      else 
        pmap[e.first+i.value] = pmap[e.first]+i.c;
    }
  }
  for(auto i:negative) {
    for(auto e:nmap) {
      if(nmap.find(e.first-i.value)!=nmap.end())
        nmap[e.first-i.value] = std::min(nmap[e.first-i.value],nmap[e.first]+i.c);
      else 
        nmap[e.first-i.value] = nmap[e.first]+i.c;
    }
  }
  for(auto e:pmap) {
    if(!e.first) continue;
    if(nmap.find(e.first)!=nmap.end())
    mincost = std::min(nmap[e.first]+e.second,mincost);
  }
  if (mincost == INF) mincost = -1;
  std::cout << mincost << ENDL;
  return 0;
}

