const int INF = 1e9;
const ll LLINF = 1e18;
const ll MOD = (ll)1e9 + 7;

int memo[45][405][405];

int rec(int ix, int a, int b, int c, int& Ma, int& Mb,
        vector<int>& A, vector<int>& B, vector<int>& C)
{
  if (a > 0 and a * Mb == b * Ma) { return c; }
  int n = A.size();
  if (ix == n) { return -1; }
  if (memo[ix][a][b] != 0) {
    return memo[ix][a][b];
  }
  int val1 = rec(ix + 1, a + A[ix], b + B[ix], c + C[ix], Ma, Mb, A, B, C);
  int val2 = rec(ix + 1, a, b, c, Ma, Mb, A, B, C);
  if (val1 == -1) { return memo[ix][a][b] = val2; }
  if (val2 == -1) { return memo[ix][a][b] = val1; }
  return memo[ix][a][b] = min(val1, val2);
}

int main()
{
  int N, Ma, Mb; scanf("%d %d %d", &N, &Ma, &Mb);
  vector<int> A(N), B(N), C(N);
  for (int i = 0; i < N; ++i) {
    scanf("%d %d %d", &A[i], &B[i], &C[i]);
  }

  int ans = rec(0, 0, 0, 0, Ma, Mb, A, B, C);
  printf("%d\n", ans);
  return 0;
}

