const int mxN = 40, mxX = 400;
int a[mxN], b[mxN], c[mxN];
int n, ma, mb;
int dp[mxN + 1][mxX][mxX][2];

void solve() {
    read(n, ma, mb);

    FOR(n) read(a[i], b[i], c[i]);

    FOR(j, mxX) {
        FOR(k, mxX) {
            dp[0][j][k][0] = 1e9;
            dp[0][j][k][1] = 1e9;
        }
    }
    dp[0][0][0][0] = 0;

    FOR(i, 1, n + 1) {
        FOR(j, mxX) {
            FOR(k, mxX) {
                dp[i][j][k][1] = 1e9;
                dp[i][j][k][0] = min(dp[i - 1][j][k][0], dp[i - 1][j][k][1]);
                if (a[i - 1] <= j && b[i - 1] <= k) {
                    dp[i][j][k][1] = c[i - 1] + min(dp[i - 1][j - a[i - 1]][k - b[i - 1]][0],
                                                    dp[i - 1][j - a[i - 1]][k - b[i - 1]][1]);
                }


            }
        }
    }

    int ans = 1e9;
    FOR(j, mxX) {
        FOR(k, mxX) {
            if (j % ma || k % mb || j / ma != k / mb) {
                continue;
            }
            if (dp[n][j][k][0]) {
                ans = min(ans, dp[n][j][k][0]);
            }
            if (dp[n][j][k][1]) {
                ans = min(ans, dp[n][j][k][1]);
            }


        }
    }

    print(ans==1e9?-1:ans);
}

