struct Item {
	unsigned int a;
	unsigned int b;
	size_t price;

	Item() = default;

	Item(unsigned int a, unsigned int b, size_t p) : a(a), b(b), price(p) {}
};

void traverse(size_t& min_price, const size_t N, const size_t Ma, const size_t Mb, const std::vector<Item>&,
              size_t next_min_item, size_t now_price, int a, int b);

int main() {
	size_t N, Ma, Mb;
	std::cin >> N >> Ma >> Mb;

	std::vector<Item> items;
	items.reserve(N);

	for (size_t i = 0; i < N; ++i) {
		unsigned int a, b, price;
		std::cin >> a >> b >> price;
		items.emplace_back(a, b, price);
	}

	size_t min_price = std::numeric_limits<size_t>::max();
	traverse(min_price, N, Ma, Mb, items, 0, 0, 0, 0);
	if (min_price == std::numeric_limits<size_t>::max()) {
		std::cout << -1 << std::endl;
	} else {
		std::cout << min_price << std::endl;
	}
}

void traverse(size_t& min_price, const size_t N, const size_t Ma, const size_t Mb, const std::vector<Item>& items,
              size_t next_min_item, size_t now_price, int a, int b) {
#if 0
	std::cerr << min_price << ',' << now_price << ',' << next_min_item << ',' << now_price << ',' << a << ',' << b
			  << std::endl;
#endif
	if (min_price <= now_price) {
		return;
	} else if (a != 0 && b != 0 && a % Ma == 0 && b % Mb == 0 && a / Ma == b / Mb) {
		min_price = now_price;
		return;
	} else if (next_min_item == N) {
		return;
	}

	traverse(min_price, N, Ma, Mb, items, next_min_item + 1, now_price, a, b);
	const Item& item = items[next_min_item];
	traverse(min_price, N, Ma, Mb, items, next_min_item + 1, now_price + item.price, a + item.a, b + item.b);
}

