int main(void) {
	int n, ma, mb;
	cin >> n >> ma >> mb;
	for (int i = 0; i < n; i++) {
		cin >> a[i] >> b[i] >> c[i];
	}

	for (int i = 0; i <= n; i++) {
		for (int j = 0; j <= nmax * abmax; j++) {
			for (int k = 0; k <= nmax * abmax; k++) {
				dp[i][j][k] = INF;
			}
		}
	}
	dp[0][0][0] = 0;

	for (int i = 0; i < n; i++) {
		for (int ca = 0; ca <= nmax * abmax; ca++) {
			for (int cb = 0; cb <= nmax * abmax; cb++) {
				if (dp[i][ca][cb] == INF) continue;

				dp[i + 1][ca][cb] = min(dp[i + 1][ca][cb], dp[i][ca][cb]);
