int main () {

    ll n,ma,mb; cin >>n>>ma>>mb;
    vector<ll> a(n); vector<ll> b(n); vector<ll> c(n);
    rep(i,n) cin >> a[i] >> b[i] >> c[i];

    ll n1 = n/2;
    vector<P> pairs1((1<<n1));

    for (ll s = 0; s < (1<<n1); s++) {
        ll suma = 0;
        ll sumb = 0;
        ll sumc = 0;
        for (ll i = 0; i < n1; i++) {
            if (s & (1<<i)) {
                suma += a[i];
                sumb += b[i];
                sumc += c[i];
            }
        }
        pairs1[s] = P((ma+mb)*suma - ma*(suma+sumb), sumc);
    }

    sort(pairs1.begin(), pairs1.end());

    ll ans = INFLL;
    for (ll s = 0; s < (1<<(n-n1)); s++) {
        ll suma = 0;
        ll sumb = 0;
        ll sumc = 0;
        for (ll i = 0; i < (n-n1); i++) {
            if (s & (1<<i)) {
                suma += a[n1 + i];
                sumb += b[n1 + i];
                sumc += c[n1 + i];
            }
        }
        ll m = ma*(suma+sumb) - (ma+mb)*suma;
        ll ok = (1<<n1);
        ll ng = -1;
        while (abs(ng-ok)>1) {
            ll mid = (ok+ng)/2;
            if (m <= pairs1[mid].first) {
                ok = mid;
            } else {
                ng = mid;
            } 
        }
        if (m == pairs1[ok].first && (pairs1[ok].first != 0 || m != 0)) {
            if (ans > sumc + pairs1[ok].second) {
                ans = sumc + pairs1[ok].second;
            } 
        } 
    }

    if (ans == INFLL) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    } 

    return 0;
}

