int f(int kinds, int a_total, int b_total)
{
    if (kinds == 0) return dp[kinds][a_total][b_total];
    if (checked[kinds][a_total][b_total]) return dp[kinds][a_total][b_total];

    int ret = 20000000;
    ret = min(ret, f(kinds-1, a_total, b_total));

    if (kinds == 1 && a_total == 1 && b_total == 2) {
        debug_printf("-- x0\n");
    }
    if (kinds == 2 && a_total == 3 && b_total == 3) {
        debug_printf("-- x1\n");
    }
    if (kinds == 1 && a_total == 3 && b_total == 3) {
        debug_printf("-- x2\n");
    }

    int lastidx = kinds - 1;

    ll a = get<0>(abclist[lastidx]);
    ll b = get<1>(abclist[lastidx]);
    ll c = get<2>(abclist[lastidx]);
    if (a_total >= a && b_total >= b) {
        ret = min(ret, f(kinds - 1, a_total - a, b_total - b) + (int)c);
    }

    if (kinds == 1 && a_total == 1 && b_total == 2) {
        debug_printf("-- x0 ret=%d\n", ret);
    }
    if (kinds == 2 && a_total == 3 && b_total == 3) {
        debug_printf("-- x1 ret=%d\n", ret);
    }
    if (kinds == 1 && a_total == 3 && b_total == 3) {
        debug_printf("-- x2 ret=%d\n", ret);
    }

    checked[kinds][a_total][b_total] = true;
    return dp[kinds][a_total][b_total] = ret;
}

