// (a+x) : (b+y) = bb : aa を満たすx,yを探す
void calc_satisfy(ll a, ll b, ll& out_x, ll& out_y) {
    out_x = 0;
    out_y = 0;
    if (a == 0) {
        a += 1;
        out_x += 1;
    }
    if (b == 0) {
        b += 1;
        out_y += 1;
    }
    ll g = gcd(a, b);
    while (a / g != aa || b / g != bb) {
        double l = (double)a / (double)b;
        double r = aa / bb;
        if (l < r) {
            out_x++;
            a++;
        }
        else {
            out_y++;
            b++;
        }
        g = gcd(a, b);
    }
}

