const int MAX_AB = 500;
const int INF = 99999999;

int dp[MAX_AB][MAX_AB];

int main(void) {
    for (int i = 0; i < MAX_AB; i++) {
        for (int j = 0; j < MAX_AB; j++) {
            dp[i][j] = INF;
        }
    }

    int N, Ma, Mb; cin >> N >> Ma >> Mb;
    for (int i = 0; i < N; i++) {
        int a, b, c; cin >> a >> b >> c;
        for (int j = 0; j < MAX_AB-a; j++) {
            for (int k = 0; k < MAX_AB-b; k++) {
                if (j == a && k == b) {
                    if (dp[a][b] != INF) {
                        dp[j+a][k+b] = min(dp[j+a][k+b], dp[j][k]+c);
                        dp[a][b] = min(dp[a][b], c);
                    } else {
                        dp[a][b] = c;
                    }
                }

                if (dp[j][k] != INF) {
                    dp[j+a][k+b] = min(dp[j+a][k+b], dp[j][k]+c);
                }
            }
        }
    }

    int ans = INF;
    int pos_a = Ma;
    int pos_b = Mb;
    while (pos_a < MAX_AB && pos_b < MAX_AB) {
        ans = min(ans, dp[pos_a][pos_b]);
        pos_a += Ma;
        pos_b += Mb;
    }

    if (ans != INF) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }

    return 0;
}

