int solve(int i, int sa, int sb)
{
	if( sa < 0 ) return INF;
	if( sb < 0 ) return INF;

	int& ans = dp[i][sa][sb];

	if( ans != -1 ) return ans;

	if( i == 0 )
	{
		if( sa == 0 && sb == 0 ) return ans = 0;
		return ans = INF;
	}

	ans = solve( i - 1 , sa - a[i] , sb - b[i] ) + c[i];
	ans = min( ans , solve( i - 1 , sa , sb ) );

	return ans;
}

