int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, Ma, Mb;
    cin >> N >> Ma >> Mb;
    vector<int> a(N), b(N), c(N);

    REP(i,N) cin >> a[i] >> b[i] >> c[i];
    map<pair<int,int>, int> mp;
    REP(i, 1<<(N/2)){
        int sumA=0, sumB=0, sumC=0;
        REP(j,N/2){
            if((i>>j) & 1){
                sumA += a[j];
                sumB += b[j];
                sumC += c[j];
            }
        }
        if(mp[{sumA, sumB}] > 0){
            chmin(mp[{sumA, sumB}], sumC);
        }
        else mp[{sumA, sumB}] = sumC;
    }
    map<pair<int,int>, int> mp2;
    REP(i, 1<<(N-N/2)){
        int sumA=0, sumB=0, sumC=0;
        REP(j,N-N/2){
            if((i>>j) & 1){
                sumA += a[j+N/2];
                sumB += b[j+N/2];
                sumC += c[j+N/2];
            }
        }
        if(mp2[{sumA, sumB}] > 0){
            chmin(mp2[{sumA, sumB}], sumC);
        }
        else mp2[{sumA, sumB}] = sumC;
    }

    int ans = INF;
    for(auto x : mp){
        int sumA = x.first.first;
        int sumB = x.first.second;
        for(int i=1;i*max(Ma,Mb)<405;i++){
            if(mp2[{i*Ma-sumA, i*Mb-sumB}] > 0) chmin(ans, x.second + mp2[{i*Ma-sumA, i*Mb-sumB}]);
        }
    }
    if(ans == INF) ans = -1;
    cout << ans << endl;
}

