int N,Ma,Mb;
int A[50],B[50],C[50];
int G[410][410][410];

int gcd(int a, int b){
	if(a%b == 0) return b;
	else gcd(b,a%b);
}

int main(){
	while(cin >> N >> Ma >> Mb){
		for(int i=1;i<N+1;i++){
			cin >> A[i] >> B[i] >> C[i];
		}
		for(int i=1;i<N+1;i++){
			for(int j=1;j<401;j++){
				for(int k=1;k<401;k++){
					G[i][j][k] = -1;
				}
			}
		}
		G[1][A[1]][B[1]] = C[1];
		for(int i=2;i<N+1;i++){
			for(int j=1;j<401;j++){
				for(int k=1;k<401;k++){
					if(G[i-1][j][k]!=-1){
						if(G[i][j+A[i]][k+B[i]] == -1) G[i][j+A[i]][k+B[i]] = G[i-1][j][k] + C[i];
						else G[i][j+A[i]][k+B[i]] = min(G[i-1][j][k] + C[i] , G[i][j+A[i]][k+B[i]]);
					}
				}
			}
			if(G[i-1][A[i]][B[i]] == -1) G[i][A[i]][B[i]] = C[i];
			else G[i][A[i]][B[i]] = min(C[i],G[i-1][A[i]][B[i]]);
		}
		int ans = 4001;
		for(int i=1;i<N+1;i++){
			for(int j=1;j<401;j++){
				for(int k=1;k<401;k++){
					int a = gcd(j,k);
					if(Ma == j/a && Mb == k/a && G[i][j][k] != -1) ans = min(ans,G[i][j][k]);
				}
			}
		}
		if(ans != 4001) cout << ans << endl;
		else cout << -1 << endl;
	}
}

