    for (int i = 0; i <= N; ++i)
    {
        for (int j = 0; j <= SUMMAX; ++j)
        {
            for (int k = 0; k <= SUMMAX; ++k)
            {
                if (j == 0 && k == 0) dp[i][j][k] = 0;
                else dp[i][j][k] = INF;
            }
        }
