int main(void){
    long N,Ma,Mb;
    cin>>N>>Ma>>Mb;
    vector<long> a(N),b(N),c(N);
    long A=0,B=0,M=0;

    for(int i=0;i<N;i++){
        cin>>a.at(i)>>b.at(i)>>c.at(i);
        //if(check) cout<<a.at(i)<<b.at(i)<<c.at(i)<<endl;
        if(a.at(i)*Mb>b.at(i)*Ma) A++;
        else if(a.at(i)*Mb<b.at(i)*Ma) B++;
        else M++;
    }
    //if(check) cout<<A<<B<<M<<endl;
    if(A==N || B==N){
        cout<<-1<<endl;
        return 0;
    }

    typedef pair<long,pair<long,long>> P;
    priority_queue<P,vector<P>,greater<P>> que;
    for(int i=0;i<N;i++) que.push(make_pair(c.at(i),make_pair(a.at(i),b.at(i))));

    while(true){
        P p=que.top();
        que.pop();
        long cost=p.first,Sa=p.second.first,Sb=p.second.second;
        if(check) cout<<"cost:"<<cost<<" Sa:"<<Sa<<" Sb:"<<Sb<<endl;
