	for (i = 1; i < dp.size(); i++) {
		LL target = i - 1;

		for (j = 0; j < mx; j++) {
			for (k = 0; k < mx; k++) {
				LL a, b;
				a = k + ls[target][0];
				b = j + ls[target][1];

				if (a < mx) {
					if (b < mx) {
						dp[i][a][b] = min(dp[i][a][b], dp[i - 1][j][k] + ls[target][2]);
					}
				}
			}
		}
	}

	if (dp[n][ma][mb] == ILL_TYPE::plus_inf()) {
		cout << -1 << endl;
		return 0;
	}

	cout << dp[n][ma][mb].getN() << endl;

	return 0;
}

