int comb_mod(int n, int k) {
	if (n < k)return 0;
	if (n < 0 || k < 0)return 0;
	return fac[n] * (facinv[k] * facinv[n - k] % MOD) % MOD;
}

//x^n (mod p)
int pow_mod(int x, int n, int p) {
	if (n == 0)return 1;
	int res = pow_mod(x*x%p, n / 2, p);
	if (n % 2 == 1)res = res * x % p;
	return res;
}

class UF {
public:

	vi par;
	vi rank;

	UF(int n) {
		par.resize(n, -1);
		rank.resize(n, 0);
	}

	int root(int x) {
		if (par[x] == -1)return x;
		return par[x] = root(par[x]);
	}

	//xの集合の位数
	int order(int x) {
		return -par[root(x)];
	}

	//xとyを併合
	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) {
			return;
		}

		if (rank[x] < rank[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (rank[x] == rank[y])rank[x]++;
		}
	}

	//xとyが同じ集合にあるか
	bool is_same(int x, int y) {
		return root(x) == root(y);
	}
};

class SegmentTree {
private:
	int n;
	vi node;
	int size;
	int init; //クエリによって決定

public:

	//SegmentTree s(vi(n,INF))とか書く
	SegmentTree(vi v) {
		this->size = size(v);

		n = 1;
		init = v[0];
		while (n < size)n *= 2;
		node.resize(2 * n - 1, init);

		rep(i, size) {
			node[i + n - 1] = v[i];
		}

		for (int i = n - 2; i >= 0; i--) {
			node[i] = min(node[2 * i + 1], node[2 * i + 2]); //右辺はクエリによって定義
		}
	}

	////////////////////////////////////////////////////////////////////////////////////////////////////
	//																								  //
	// 以下の関数はあくまで更新クエリと区間内最小値クエリのものであって、問題によって変える必要がある //
	//																								  //
	////////////////////////////////////////////////////////////////////////////////////////////////////

	//node[x]の値をvalに更新
	void update(int x, int val) {
		x += (n - 1);

		node[x] = val;
		while (x > 0) {
			x = (x - 1) / 2;
			node[x] = min(node[2 * x + 1], node[2 * x + 2]); //右辺はクエリによって定義
		}
	}

	//区間[a,b)内の最小値を返す
	///b未満だから！
	int getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		if (r <= a || b <= l)return init;
		if (a <= l && r <= b)return node[k];

		int L = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
		int R = getmin(a, b, 2 * k + 2, (l + r) / 2, r);

		return min(L, R); //クエリによって定義
	}
};

