#define ll long long
#define maxn 40
#define maxa 10
#define maxx 5000

int d[maxn + 1][maxa * maxn + maxa + 2][maxa * maxn + maxa + 2];
int a[maxn + 1], b[maxn + 1], c[maxn + 1];

int main() {
    int n, aa, bb, rez = maxx;
    scanf("%d%d%d", &n, &aa, &bb);

    for (int i = 1; i <= n; i++) {
        scanf("%d%d%d", &a[i], &b[i], &c[i]);
    }

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= maxn * maxa; j++) {
            for (int k = 0; k <= maxn * maxa; k++) {
                d[i][j][k] = maxx;
            }
        }
    }

    d[0][0][0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= maxn * maxa; j++) {
            for (int k = 0; k <= maxn * maxa; k++) {
                if (d[i - 1][j][k] != maxx) {
                    d[i][j][k] = d[i - 1][j][k];
                    d[i][j + a[i]][k + b[i]] = std::min(d[i][j + a[i]][k + b[i]], d[i - 1][j][k] + c[i]);
                }
            }
        }
    }
    for (int i = 1; i <= maxn * maxa; i++) {
        for (int j = 1; j <= maxn * maxa; j++) {
            if (aa * j == bb * i)
                rez = std::min(rez, d[n][i][j]);
        }
    }
    if(rez != maxx)
        printf("%d", rez);
    else
        printf("-1");
    return 0;
}

