#include <bits/stdc++.h>
using namespace std;

int main() {
  int N, Ma, Mb;
  cin >> N >> Ma >> Mb;
  vector<int> a(N), b(N), c(N);
  for (int i = 0; i < N; ++i)
    cin >> a[i] >> b[i] >> c[i];

  int max_a = 0, max_b = 0;
  for (int i = 0; i < N; ++i)
    max_a += a[i], max_b += b[i];

  vector<vector<vector<int>>> dp(
      N + 1,
      vector<vector<int>>(max_a + 1, vector<int>(max_b + 1, 1000000001)));
  for (int i = 0; i <= N; ++i)
    dp[i][0][0] = 0;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j <= max_a - a[i]; ++j) {
      for (int k = 0; k <= max_b - b[i]; ++k) {
        if (dp[i][j][k] != 1000000001)
          dp[i + 1][j + a[i]][k + b[i]] =
              min(dp[i + 1][j + a[i]][k + b[i]], dp[i][j][k] + c[i]);

        dp[i + 1][j + a[i]][k + b[i]] =
            min(dp[i + 1][j + a[i]][k + b[i]], dp[i][j + a[i]][k + b[i]]);
      }
    }
  }

  int ans = 1000000001;
  for (int i = 1; i <= N; ++i)
    for (int j = 1; j <= max_a; ++j)
      for (int k = 1; k <= max_b; ++k)
        if (Mb * j == Ma * k)
          ans = min(ans, dp[i][j][k]);

  if (ans != 1000000001)
    cout << ans << endl;
  else
    cout << -1 << endl;
}

