int dp[40][401][401];
int num[40][2];
int cost[40];
int ans=1000000;

int main() {
	cin >> N>>a>>b;
	for (int i = 0; i < N; i++) {
		cin  >> num[i][0] >> num[i][1]>>cost[i];
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < 401; j++) {
			for (int k = 0; k < 401; k++) {
				dp[i][j][k] =1000000;
			}
		}
	}
	dp[0][0][0] = 0;
	dp[0][num[0][0]][num[0][1]] = cost[0];
	for (int i = 1; i < N; i++) {
		for (int j = 0; j < N*10+1; j++) {
			for (int k = 0; k < N*10+1; k++) {
				if (dp[i - 1][j][k] != 1000000) {
					//cout <<i<<" "<< j << " " << k << endl;
					dp[i][j + num[i][0]][k + num[i][1]] = min(dp[i][j + num[i][0]][k + num[i][1]], dp[i - 1][j][k] + cost[i]);
					dp[i][j][k] = dp[i - 1][j][k];
				}
			}
		}
	}
	for (int i = 1; i < 401; i++) {
		for (int j = 1; j < 401; j++) {
			if (i%a == 0 && j%b == 0&&dp[N-1][i][j]!=1000000) {
				if (i / a == j / b) {
				//	cout << i << " " << j << " " << dp[N-1][i][j] << endl;
					ans = min(ans, dp[N - 1][i][j]);
				}
			}
		}
	}
	if (ans == 1000000)cout << "-1\n";
	else cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>
#define INF 1e9
using namespace std;
int N;
double Ma, Mb;
vector<double> a, b;
vector<int> c;
int memo[1000][1000];
int dfs(int i, int A, int B, int cost) {
    if (i == N) {
        if (Ma / Mb != double(A) / double(B)) {
            return INF;
        } else {
            return cost;
        }
    }
    if (memo[A][B] != 0) {
        return memo[A][B];
    }

    int ans = min(dfs(i + 1, A + a[i], B + b[i], cost + c[i]),
                  dfs(i + 1, A, B, cost));

    return memo[A][B] = ans;
}

int main() {
    cin >> N >> Ma >> Mb;
    a.resize(N);
    b.resize(N);
    c.resize(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i] >> b[i] >> c[i];
    }
    int ans = dfs(0, 0, 0, 0);
    if (ans != INF) {
        cout << ans << endl;
    } else {
        cout << -1 << endl;
    }
}

