  }
  m2[0] = INF;                                  //////////////////////////
  REP(i, 1, 1 << g_2) {
    int bit = i, med = 0, cost = 0;
    REP(j, g_1, N) {
      if (bit & 1) {
        med += M_b * AB[j].first;
        med -= M_a * AB[j].second;
        cost += C[j];
      }
      bit >>= 1;
    }
    if (m2.count(med)) chmin(m2[med], cost);    //////////////////////////
