int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N,Mb,Ma; cin >> N >> Ma >> Mb;
    vector<int> a(N),b(N),c(N);
    rep(i,N) cin >> a[i] >> b[i] >> c[i];

    int M = N/2;
    vector<pair<int, int>> left(1 << M),right(1 << (N-M));
    for (int tmp = 0; tmp < (1 << M); tmp++) {
        bitset<20> s(tmp);
        int C = 0;
        int val = 0;
        rep(i,M) {
            if (s.test(i)) {
                val += (a[i]*Mb - b[i]*Ma);
                C += c[i];
                left[tmp] = make_pair(val,C);
            }
        }
    }
    for (int tmp = 0; tmp < (1 << (N-M)); tmp++) {
        bitset<20> s(tmp);
        int C = 0;
        int val = 0;
        rep(i,(N-M)) {
            if (s.test(i)) {
                val += (a[M+i]*Mb - b[M+i]*Ma);
                C += c[M+i];
                right[tmp] = make_pair(val,C);
            }
        }
    }
    sort(all(left)); sort(all(right));
    rep (i,(1 << M)-1) {
        if (left[i].second == 0) continue;
        if (left[i+1].first == left[i].first) {
            left[i+1].second = left[i].second;
        }
    }
    rep (i,(1 << (N-M))-1) {
        if (right[i].second == 0) continue;
        if (right[i+1].first == right[i].first) {
            right[i+1].second = right[i].second;
        }
    }
    int ans = INF;
    for (auto i : left) {
        auto it = lower_bound(all(right),make_pair(-i.first,-1));
        if (it == right.end()) continue;
        if (i.second+it->second == 0) it++;
        if (it == right.end()) continue;
        if (it->first != -i.first) continue;
        chmin(ans,i.second+it->second);
    }

    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

