int solve(int a,int b,int c,int d,int p,int q,int *x,int *y){
  int det=a*d-b*c;
  int s=d*p-b*q;
  int t=-c*p+a*q;
  if(det==0 || s*det<0 || t*det<0) return 0;
  *x=s*det;
  *y=t*det;
  return 1;
}

int gcd(int a,int b){
  int r=a%b;
  while(r>0){
    a=b;
    b=r;
    r=a%b;
  }
  return b;
}

void run(void){
  int n,ma,mb;
  scanf("%d%d%d",&n,&ma,&mb);
  int a[40],b[40],c[40];
  int i,j;
  for(i=0;i<n;i++) scanf("%d%d%d",a+i,b+i,c+i);
  int min=-1;
  for(i=0;i<n;i++){
    for(j=i+1;j<n;j++){
      int s,t;
      if(!solve(a[i],a[j],b[i],b[j],ma,mb,&s,&t)) continue;
      int g=gcd(s,t);
      s/=g;
      t/=g;
      if(min==-1 || min>c[i]*s+c[j]*t) min=c[i]*s+c[j]*t;
    }
  }
  printf("%d\n",min);
}

