    amax += a[i];
    bmax += b[i];
  }

  for(i = 0; i < N; i++) {
    for(ca = 0; ca <= amax; ca++) {
      for(cb = 0; cb <= bmax; cb++) {
	dp[i][ca][cb] = inf;
      }
