	  tmp1 = dp[i-1][ca-a[i]][cb-b[i]] + c[i];
	} else {
	  tmp1 = inf;
	}
	// iをいれない
	tmp2 = dp[i-1][ca][cb];
	if(tmp1 < tmp2) {
	  dp[i][ca][cb] = tmp1;
	} else {
	  dp[i][ca][cb] = tmp2;
	}
      }
    }
  }
  ans = inf;
  flag = -1;
