void sort_func(int *A, int *B, int *C, double *D, int left, int right, int *tmp_A, int *tmp_B, int *tmp_C, double *tmp_D){

	if(right - left > 1){

		int i, j, k, half = (left + right) / 2;

    sort_func(A, B, C, D, left, half, tmp_A,  tmp_B, tmp_C, tmp_D);
    sort_func(A, B, C, D, half, right, tmp_A,  tmp_B, tmp_C, tmp_D);

    	for(i = left; i < right; i++){
			tmp_A[i] = A[i];
			tmp_B[i] = B[i];
			tmp_C[i] = C[i];
			tmp_D[i] = D[i];
		}

		for(i = left, j = left, k = half; i < right; i++){
			if(k == right){
				A[i] = tmp_A[j];
				B[i] = tmp_B[j];
				C[i] = tmp_C[j];
				D[i] = tmp_D[j];
                j++;
			}
			else if(tmp_A[j] <= tmp_A[k] && j < half){
				A[i] = tmp_A[j];
				B[i] = tmp_B[j];
				C[i] = tmp_C[j];
				D[i] = tmp_D[j];
				j++;
			}
			else{
				A[i] = tmp_A[k];
				B[i] = tmp_B[k];
				C[i] = tmp_C[k];
				D[i] = tmp_D[k];
				k++;
			}
		}

    }

}

