	int *tmp_A = (int *)malloc(sizeof(int) * N);
	int *tmp_B = (int *)malloc(sizeof(int) * N);
	int *tmp_C = (int *)malloc(sizeof(int) * N);
	double *tmp_D = (double *)malloc(sizeof(double) * N);

	sort_func(A, B, C, D, 0, N, tmp_A, tmp_B, tmp_C, tmp_D);
	free(tmp_A);
    free(tmp_B);
    free(tmp_C);
    free(tmp_D);

}

