void run(void){
  int n,ma,mb;
  scanf("%d%d%d",&n,&ma,&mb);
  int l=400;
  int *dp=(int *)malloc(sizeof(int)*(l+1)*(l+1));
  const int inf=1000000;
  int i,j;
  for(i=0;i<=l;i++) for(j=0;j<=l;j++) dp[POS(i,j)]=inf;
