        for(int j = 0;j < 8000;j++){
            if(dp[i-1][j]!=mod || j == 4000){
                //i番目は使わない
                dp[i][j] = min(dp[i-1][j], dp[i][j]);
                int plus;
                if(j==4000)plus = c[i];
                else plus = dp[i-1][j] + c[i];
                //i番目を使う
                dp[i][j + ab[i]] = min(dp[i][j + ab[i]], plus);
            }
        }
    }
    //n-1番目のコストが更新されていればそれを出力
    if(dp[n-1][4000] != mod)printf("%d\n", dp[n-1][4000]);
