struct prod {
    int diff;
    int cost;
};

#define NUM_MAX 40
// 99*40
#define DIFF_MAX 5000
#define INF 0x01010101

struct pair {
    int x;
    int y;
};

int main(void) {
    int num = get_int();
    int ma, mb;
    static struct prod prods[NUM_MAX];
    get_int2(&ma, &mb);

    int i;
    for(i = 0; i < num; i++) {
        int a, b, cost;
        get_int3(&a, &b, &cost);
        // max: 10*10-1*1
        int diff = a*mb - b*ma;
        prods[i] = (struct prod){diff, cost};
    }

    static int dp[NUM_MAX+1][DIFF_MAX*2+1];
    memset(dp, 0x01, sizeof(int)*NUM_MAX*(DIFF_MAX*2+1));
    int offset = DIFF_MAX;
    int j;
    int ans = INF;
    int idx;
    for(j = 0; j < num; j++) {
        dp[1][offset+prods[j].diff] = prods[j].cost;
        for(i = 2, idx = 1; idx <= num; idx++) {
            if(idx-1 == j) continue;
            struct prod p = prods[i-1];
            int val = p.diff;
            for(j = 0; j <= DIFF_MAX*2; j++) {
                // stay
                dp[i][j] = dp[i-1][j];
                // choose
                if(j-val >= 0 && j-val <= DIFF_MAX*2) {
                    dp[i][j] = min(dp[i][j], dp[i-1][j-val]+p.cost);
                }
            }
            i++;
        }
#ifdef DEBUG
        printf("%d\n", dp[num][offset]);
#endif
        ans = min(ans, dp[num][offset]);
    }
    if(ans >= INF) ans = -1;
    printf("%d\n", ans);
    return 0;
}

