#define MAX 230000
#define SFT 9
#define MSK 511
#define INF 0x5ffffff
int dp[MAX+5];
int N;

int main()
{
	int i, Ma, Mb;
	int ma, ans;

	N = in(), Ma = in(), Mb = in();
	ans = INF, ma = 0;
	for (i = 0; i < MAX; ++i) dp[i] = INF;
	dp[0] = 0;
	while (N--) {
		int a = in(), b = in(), c = in();
		for (i = ma; i >= 0; --i) if (dp[i] < INF) {
			int x = dp[i] + c;
			int aa = (i >> SFT) + a, bb = (i & MSK) + b;
			if (aa*Mb == bb*Ma && ans > x) ans = x;
			int k = (aa << SFT) | bb;
			if (k > ma) ma = k;
			if (dp[k] > x) dp[k] = x;
		}
	}
	if (ans < INF) printf("%d\n", ans);
	else puts("-1");
	return 0;
}

