#define INF 100000000

int N, Ma, Mb;
int a[1000];
int b[1000];
int c[1000];

int memo[50][500][500];

int search(int pos, int cur_a, int cur_b) {
	int ret = INF;
	int candidate;
	if (cur_a > 0 && cur_b > 0 && cur_a * Mb == cur_b * Ma) return 0; /* 条件を満たした */
	if (pos >= N) return ret; /* もう入れる薬品が無い */
	if (memo[pos][cur_a][cur_b]) return ~memo[pos][cur_a][cur_b];

	/* 買う */
	candidate = search(pos + 1, cur_a + a[pos], cur_b + b[pos]) + c[pos];
	if (candidate < ret) ret = candidate;
	/* 買わない */
	candidate = search(pos + 1, cur_a, cur_b);
	if (candidate < ret) ret = candidate;

	return ~(memo[pos][cur_a][cur_b] = ~ret);
}

