#define POS(i,j) ((i)*(l+1)+(j))

void run(void){
  int n,ma,mb;
  scanf("%d%d%d",&n,&ma,&mb);
  int l=1000;
  int *dp=(int *)malloc(sizeof(int)*(l+1)*(l+1));
  const int inf=1000000;
  int i,j;
  for(i=0;i<=l;i++) for(j=0;j<=l;j++) dp[POS(i,j)]=inf;
  dp[POS(0,0)]=0;
  while(n--){
    int a,b,c;
    scanf("%d%d%d",&a,&b,&c);
    for(i=0;i+a<=l;i++){
      for(j=0;j+b<=l;j++){
	if(dp[POS(i,j)]==inf) continue;
	dp[POS(i+a,j+b)]=MIN(dp[POS(i+a,j+b)],dp[POS(i,j)]+c);
      }
    }
  }
  int min=-1;
  for(i=1;i*ma<=l && i*mb<=l;i++){
    if(dp[POS(i*ma,i*mb)]==inf) continue;
    min=(min==-1?dp[POS(i*ma,i*mb)]:MIN(min,dp[POS(i*ma,i*mb)]));
  }
  printf("%d\n",min);
}

