typedef struct { int ab, a, b, c; } T;
T tbl[45]; int N;

void Qsort(T *a, int l, int r) {
	int i, j; int m; T t;

	i = l, j = r, m = a[(l+r) >> 1].ab;
	while (1) {
		while (a[i].ab > m) i++;
		while (m > a[j].ab) j--;
		if (i >= j)	break;
		t = a[i], a[i] = a[j], a[j] = t;
		i++, j--;
	}
	if (l+1 < i) Qsort(a, l, i-1);
	if (j+1 < r) Qsort(a, j+1, r);
}

