#define inf 4001

int main(void)
{
  int N;
  int Ma, Mb;
  int a[41], b[41], c[41];
  static int dp[41][401][401];
  int i, ca, cb;
  int amax = 0;
  int bmax = 0;
  int ans;
  int tmp1;
  int tmp2;

  scanf("%d %d %d", &N, &Ma, &Mb);
  for(i = 0; i < N; i++) {
    scanf("%d %d %d", &a[i], &b[i], &c[i]);
    amax += a[i];
    bmax += b[i];
  }

  for(i = 0; i < N; i++) {
    for(ca = 0; ca <= amax; ca++) {
      for(cb = 0; cb <= bmax; cb++) {
	dp[i][ca][cb] = inf;
      }
    }
  }  
  dp[0][a[0]][b[0]] = c[0];
  dp[0][0][0] = 0;

  for(i = 1; i < N; i++) {
    for(ca = 0; ca <= amax; ca++) {
      for(cb = 0; cb <= bmax; cb++) {
	// iを入れる
	if(ca >= a[i] && cb >= b[i]) {
	  tmp1 = dp[i-1][ca-a[i]][cb-b[i]] + c[i];
	} else {
	  tmp1 = inf;
	}
	// iをいれない
	tmp2 = dp[i-1][ca][cb];
	if(tmp1 < tmp2) {
	  dp[i][ca][cb] = tmp1;
	} else {
	  dp[i][ca][cb] = tmp2;
	}
      }
    }
  }

  ans = inf;
  for(ca = 0; ca <= amax; ca++) {
    for(cb = 0; cb <= bmax; cb++) {
      if(ca*Mb == cb*Ma && dp[N-1][ca][cb] != 0) {
	if(ans > dp[N-1][ca][cb]) {
	  ans = dp[N-1][ca][cb];
	}
      }
    }
  }
  if(ans == inf) {
    printf("%d\n", -1);
  } else {
    printf("%d\n", ans);
  }
  return 0;
}

