private var meds: List<Med> = emptyList()

private const val FILLED_WITH_ONE: Long = 0L.inv()
fun createBitMask(length: Int): Long = FILLED_WITH_ONE.shl(length).inv()

fun main(vararg args: String) {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val input: IntArray = br.readLine().split(" ").map { it.toInt() }.toIntArray()
    val n = input[0]
    val ma = input[1]
    val mb = input[2]

    meds = (0 until n).map { Med(br.readLine().split(" ").map{ it.toInt() }.toIntArray()) }

    var minimumPrice: Int? = null

    for (i in 0L..(FILLED_WITH_ONE and createBitMask(n))) {
        var bitLen = 0
        var tmp = i
        while (tmp != 0L) {
            tmp = tmp ushr 1
            bitLen++
        }
        val med = getCompositedMed(i, bitLen, minimumPrice)

        if (med == null || med == Med.MED_ZERO) continue

        val gcd = gcd(med.a, med.b)
        if (med.a / gcd == ma && med.b / gcd == mb &&
            minimumPrice?.let { it > med.price } ?: true) {
            minimumPrice = med.price
        }
    }
    println(minimumPrice ?: -1)
}

private val CACHE = mutableMapOf<Long, Med>()
fun getCompositedMed(flag: Long, length: Int, limit: Int?): Med? {
    var sum = Med.MED_ZERO
    var i = length
    while (i > 0) {
        if (limit?.let { it < sum.price } ?: false) {
            return null
        }
        val masked = flag and createBitMask(i)
        if (CACHE.containsKey(masked)) {
            sum += CACHE[masked]!!
            break
        }
        if (masked ushr (i - 1) == 1L) {
            sum += meds[i - 1]
        }
        i--
    }
    CACHE[flag and createBitMask(length)] = sum
    return sum
}

tailrec fun gcd(m: Int, n: Int): Int = if (m > n) {
    gcd(n, m)
} else if (0 == m) {
    n
} else {
    gcd(m, n % m)
}

data class Med(val a: Int, val b: Int, val price: Int) {
    companion object {
        val MED_ZERO = Med(0, 0, 0)
    }
    constructor(inputs: IntArray) : this(inputs[0], inputs[1], inputs[2])
    infix operator fun plus(med: Med): Med = Med(this.a + med.a, this.b + med.b,
                                                 this.price + med.price)
}

fun main(args: Array<String>) {
    var (n, ma, mb) = readLine()!!.split(' ').map(String::toInt)
    val abcList =
            (1..n).map {
                val (a, b, c) = readLine()!!.split(' ').map(String::toInt)
                Triple(a, b, c)
            }
    val totalA = abcList.map { it.first }.sum()
    val totalB = abcList.map { it.second }.sum()
    val okList = mutableListOf<Pair<Int, Int>>()
    var i = 1
    while (true) {
        if (i * ma > totalA || i * mb > totalB) break
        okList.add(Pair(i * ma, i * mb))
        i++
    }

    val dp = Array(501) { IntArray(501) { Int.MAX_VALUE / 2 } }
    for (abc in abcList) {
        val (a, b, c) = abc
        for (j in 1..400) {
            for (k in 1..400) {
                if (dp[j][k] < Int.MAX_VALUE / 2) {
                    dp[a + j][b + k] = Math.min(dp[a + j][b + k], dp[j][k] + c)
                }
            }
        }
        dp[a][b] = Math.min(dp[a][b], c)
    }

    var ans = Int.MAX_VALUE
    for (ok in okList) {
