private fun getCompositedMed(flag: Long, length: Int, limit: Int?): IntArray? {
    val sum = intArrayOf(0,0,0)
    var i = length
    while (i > 0) {
        if (limit != null && limit <= sum[2]) {
            return null
        }
        val masked = flag and createBitMask(i)
        if (cache.containsKey(masked)) {
            val cache = cache[masked]!!
            sum[0] += cache[0]
            sum[1] += cache[1]
            sum[2] += cache[2]
            break
        }
        if (masked ushr (i - 1) == 1L) {
            val med = meds[i - 1]
            sum[0] += med[0]
            sum[1] += med[1]
            sum[2] += med[2]
        }
        i--
    }
    cache[flag and createBitMask(length)] = sum
    return sum
}

