fun main(args: Array<String>) {
	val (n, ma, mb) = readListOfInt()
	val medicines = Array(n) { Medicine(0, 0, 0) }
	for(i in 0 until n) {
		val (a, b, c) = readListOfInt()
		medicines[i] = Medicine(a, b, c)
	}
	// dp[i番目の薬品][Aの使用量] [bの使用量] = 金額
	val dp = Array(nMax+1) { Array(nMax * abMax + 1) { Array(nMax * abMax + 1) { inf } } }
	dp[0][0][0] = 0
	medicines.forEachIndexed { i, medicine ->
		for(ca in 0 until nMax * abMax) {
			for(cb in 0 until nMax * abMax) {
				if(dp[i][ca][cb] == inf) continue
				// 使わない場合
				dp[i+1][ca][cb] = Math.min(dp[i+1][ca][cb], dp[i][ca][cb])
				// 使った場合
				dp[i+1][ca + medicine.a][cb + medicine.b] = 
					Math.min(dp[i+1][ca + medicine.a][cb + medicine.b], dp[i][ca][cb] + medicine.c)
			}
		}
	}

	var ans = inf
	for(ca in 1 .. nMax * abMax) {
		for(cb in 1 .. nMax * abMax) {
			if(ca * mb == cb * ma) {
				ans = Math.min(ans, dp[n][ca][cb])
