private val CACHE = mutableMapOf<Long, Med>()
fun getCompositedMed(flag: Long, index: Int): Med {
    if (index == -1) {
        return Med.MED_ZERO
    }

    val masked = flag and createBitMask(index + 1)

    return CACHE.getOrPut(masked) {
        if (masked ushr index == 1L) {
            meds[index] + getCompositedMed(flag, index - 1)
        } else {
            getCompositedMed(flag, index - 1)
        }
    }
}

