private var meds: List<Med> = emptyList()

private const val FILLED_WITH_ONE: Long = 0L.inv()
private inline fun createBitMask(length: Int): Long = FILLED_WITH_ONE.shl(length).inv()

fun main(vararg args: String) {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val input: IntArray = br.readLine().split(" ").map { it.toInt() }.toIntArray()
    val n = input[0]
    val ma = input[1]
    val mb = input[2]

    meds = (0 until n).map { Med(br.readLine().split(" ").map{ it.toInt() }.toIntArray()) }

    var minimumPrice: Int? = null

    for (i in 0L..(FILLED_WITH_ONE and createBitMask(n))) {
        var bitLen = 0
        var tmp = i
        while (tmp != 0L) {
            tmp = tmp ushr 1
            bitLen++
        }
        val med = getCompositedMed(i, bitLen, minimumPrice)

        if (med == null || med == Med.MED_ZERO) continue

        val gcd = gcd(med.a, med.b)
        if (med.a / gcd == ma && med.b / gcd == mb &&
            minimumPrice?.let { it > med.price } ?: true) {
            minimumPrice = med.price
        }
    }
    println(minimumPrice ?: -1)
}

private val CACHE = mutableMapOf<Long, Med>()
private inline fun getCompositedMed(flag: Long, length: Int, limit: Int?): Med? {
    var suma = 0
    var sumb = 0
    var sumprice = 0
    var i = length
    while (i > 0) {
        if (limit?.let { it < sumprice } ?: false) {
            return null
        }
        val masked = flag and createBitMask(i)
        if (CACHE.containsKey(masked)) {
            val cache = CACHE[masked]!!
            suma += cache.a
            sumb += cache.b
            sumprice += cache.price
            break
        }
        if (masked ushr (i - 1) == 1L) {
            val med = meds[i - 1]
            suma += med.a
            sumb += med.b
            sumprice += med.price
        }
        i--
    }
    val med = Med(suma, sumb, sumprice)
    CACHE[flag and createBitMask(length)] = med
    return med
}

