private fun calc(a: Int, b: Int, items: List<List<Int>>, ca: Int = 0, cb: Int = 0, p: Int = 0) {
    (0..items.lastIndex).map { i ->
        val item = items[i]
        val na = ca + item[0]
        val nb = cb + item[1]
        val np = p + item[2]
        if (na * b == nb * a) {
            if (np < min) {
                min = np
            }
        } else if (np < min) {
            calc(a, b, items.subList(i + 1, items.count()).filter { it[2] <= min - np }, ca + item[0], cb + item[1], p + item[2])
        }
    }
}

