fun main(args: Array<String>) {
    Program().solve()
}

class Program {
    fun solve() {
        val sc = FastScanner()

        val n = sc.nextInt()
        val Ma = sc.nextInt()
        val Mb = sc.nextInt()

        // dp[Aの量,bの量] = 最小コスト

        val dp = Array(401) { Array(401) { Int.MAX_VALUE } }

        dp[0][0] = 0

        for (i in 0 until n) {
            val a = sc.nextInt()
            val b = sc.nextInt()
            val c = sc.nextInt()

            for (j in 400 - a downTo 0) {
                for (k in 400 - b downTo 0) {
                    if (dp[j][k] == Int.MAX_VALUE) continue
                    dp[j + a][k + b] = Math.min(dp[j + a][k + b], dp[j][k] + c)
                }
            }
        }
        var ans = Int.MAX_VALUE
        var t = 1
        while (t * Ma <= 400 && t * Mb <= 400) {
            ans = Math.min(ans, dp[Ma * t][Mb * t])
            t++
