const val INF = 2147483647
const val LINF = 9223372036854775807L

fun main(args: Array<String>) {
    solve()
    pw.flush()
}

fun solve() {
    val (n, ma, mb) = nextIntList()
    val a = intAry(n)
    val b = intAry(n)
    val c = intAry(n)
    repeat(n){
        val tmp = nextIntList()
        a[it] = tmp[0]
        b[it] = tmp[1]
        c[it] = tmp[2]
    }
    val dp = intAry3(n + 1, 401, 401, INF / 2)
    dp[0][0][0] = 0

    for (i in 0 until n){
        for (j in 0..400){
            for (k in 0..400){
                if(j < a[i] || k < b[i]) continue
                dp[i + 1][j][k] = dp[i][j][k]
                dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j - a[i]][k - b[i]] + c[i])
            }
        }
    }

    var ans = INF / 3
    for (j in 1..400){
        for (k in 1..400){
            val g = gcd(j, k)
            var tmpa = j
            var tmpb = k
            while(g != 1 && tmpa % g == 0) tmpa /= g
            while(g != 1 && tmpb % g == 0) tmpb /= g
            if(tmpa == ma && tmpb == mb) ans = min(ans, dp[n][j][k])
        }
    }

    println(if(ans == INF / 3) -1 else ans)



}

