/**
 * タイプAの物質とタイプBの物質の混合比が Ma:Mb
 * sum(a_)*mb = sum(b_)*ma
 * よって、a * mb - b * maの合計が0になる組み合わせを探す。
 * cとnについての動的計画法で行う。
 *
 * 発散するかに見えるが、
 * -100 < a * mb - b * ma < 100
 * costの上限は、N * c <= 40 *100
 * 分量の状態は200*40以下
 * で間に合いそう。
 */
fun main(args: Array<String>) {
    class Drug(a: Int, b: Int, val cost: Int, ma: Int, mb: Int) {       // 1≦ai,bi≦10, 1≦ci≦100
        val excess = a * mb - b * ma
    }

    val (n, drugs) = Scanner(System.`in`).use {
        val (n, ma, mb) = Triple(it.nextInt(), it.nextInt(), it.nextInt())    // 1≦N≦40  1≦Ma,Mb≦10
        val drugs: List<Drug> = Array(n) {n ->
            Drug(it.nextInt(), it.nextInt(), it.nextInt(), ma, mb)
        }.toList()

        n to drugs
    }

    // excess a * mb - b * ma 1*1-10*10~10*10-1*1
    val state = 99
    // 値は-99*i - 99*i 添字は 0 - 99*2*i  0は99*iが相当

    // cost == 0 生成量0で目的を満たさないので判定にかけない。
    val maximumCost = drugs.sumBy { it.cost }      // N * c <= 40 *100
    // 初期条件: memo[0] = setOf(0)
    val zeroSet = BooleanArray(state * 2 * n + 1, {false}).apply{ this[state * n] = true }
    val initialMemo: List<BooleanArray> = Array(maximumCost, {BooleanArray(state * 2 * n + 1, {false})}).toList()
    // 漸化式: cell[i+1][c] = cell[i][c] + cell[i][c - drugs[i+1].cost].map{ + drugs[i+1].excess}
    val excessMemo = (0 until n).fold(initialMemo) { memo, i ->
        (0 until memo.size).asSequence().map {cost ->   // 先頭を除いたので、cost は実際のコストより1少ない。
            when {
                cost - drugs[i].cost < -1 -> memo[cost]
                cost - drugs[i].cost == -1 -> memo[cost].clone().apply{ this[state * n + drugs[i].excess] = true }
            // 新しいオブジェクトが生成されるので、変更されたnextMemoの要素をを誤ってmemoの要素として参照することはない。
                else -> BooleanArray(state * 2 * n + 1, { j ->
                    if (j - drugs[i].excess >= 0 && j - drugs[i].excess < state * 2 * n) {
                        memo[cost][j] or memo[cost - drugs[i].cost][j - drugs[i].excess]
                    } else {
                        memo[cost][j]
                    }
                })
            }
        }.takeWhile { !it[state * n] }.toList()    // 条件を満たすなら、それ以上のcostについては考慮する必要がない。
        // これには条件を満たすcost自身が含まれない。
    }

    //条件を満たすものが含まれない分、sizeはlastIndexより1大きいので正解になる。
    println(if (excessMemo.size == maximumCost) -1 else excessMemo.size + 1)    // 先頭を除いた分を足す。
}

