private fun getOutputString(reader: BufferedReader): String {
    val sp = reader.readLine().split(" ")
    val ratio = sp[1].toInt() to sp[2].toInt()

    val list = reader.readLines().map { it.split(" ").map { it.toInt() } }

    // n = 1
    var dp = mutableMapOf((0..list.size - 1).map { 0 }.joinToString("") to Triple(0, 0, 0))

    var minCost = Int.MAX_VALUE
    while (dp[(0..list.size - 1).map { 1 }.joinToString("")] == null) {
        val dpBak = mutableMapOf<String, Triple<Int, Int, Int>>()
        dp.forEach { k, v ->
            for (i in 0..k.length - 1) {
                if (k[i] == '1') continue

                val newK = k.replaceRange(i, i + 1, "1")
                val newA = list[i][0] + v.first
                val newB = list[i][1] + v.second
                val newC = list[i][2] + v.third

                if (newA * ratio.second == newB * ratio.first) minCost = Math.min(minCost, newC)

                dpBak.put(newK, Triple(newA, newB, newC))
            }

            dp = dpBak
        }
    }

    return (if (minCost == Int.MAX_VALUE) -1 else minCost).toString()
}

