 * で間に合いそう。
 */
fun main(args: Array<String>) {
    class Drug(a: Int, b: Int, val cost: Int, ma: Int, mb: Int) {       // 1≦ai,bi≦10, 1≦ci≦100
        val excess = a * mb - b * ma
    }

    data class Input(val n: Int, val ma: Int, val mb: Int, val drugs: List<Drug>)
    val (n, ma, mb, drugs) = Scanner(System.`in`).use<Scanner, Input> {
        val n = it.nextInt()    // 1≦N≦40
        val ma = it.nextInt()   // 1≦Ma,Mb≦10
        val mb = it.nextInt()
        val drugs: List<Drug> = Array(n) {n ->
            Drug(it.nextInt(), it.nextInt(), it.nextInt(), ma, mb)
        }.toList()

        Input(n, ma, mb, drugs)
    }

    // cell[i+1][c] = cell[i][c] + cell[i][c - drugs[i+1].cost].map
    // メモ化テーブル
    var minimumCost = 4001      // N * c <= 40 *100
    var memo: MutableList<Set<Int>>     //Array<Set<Int>> = arrayOf()
    var nextMemo: MutableList<Set<Int>> = Array(minimumCost, {mutableSetOf<Int>()}).toMutableList()        //Array<Set<Int>> = Array(minimumCost, {mutableSetOf<Int>()})
