        for (cost in 1 until memo.size) {
            //nextMemo[cost]
            val next = if (cost - drugs[i].cost < 0) {
                memo[cost]
            } else {
                memo[cost] + memo[cost - drugs[i].cost].map{it + drugs[i].excess}
            }
            nextMemo.add(next)
            // minimumCostより上については考慮する必要がない。
