var n,x,y,i,j:longint;
    a,b,c:array[0..107] of longint;
	f:array[0..57,-10007..10007] of longint;
begin
  readln(n,x,y);
  fillchar(a,sizeof(a),0);
  fillchar(b,sizeof(b),0);
  fillchar(c,sizeof(c),0);
  for i:=1 to n do
  begin
    readln(a[i],b[i],c[i]);
    a[i]:=a[i]*y;
    b[i]:=b[i]*x;
  end;
  for i:=0 to n do
	for j:=-10000 to 10000 do
	  f[i,j]:=maxlongint div 2;
  f[1,a[1]-b[1]]:=c[1];
  for i:=2 to n do
	for j:=-10000 to 10000 do
	  f[i,j]:=min(f[i,j],min(f[i-1,j],f[i-1,j-a[i]+b[i]]+c[i]));
  if (f[n,0]<maxlongint div 2) then writeln(f[n,0]) else writeln(-1);
end.

var a,b,c:array[0..50] of integer;
    dp:array[0..50, 0..500, 0..500] of integer;
    n,ma,mb,i,ca,cb,ans:integer;

Function min(a,b:integer):integer;
    Begin
        if a < b then exit(a)
        else exit(b);
    End;

BEGIN
    readln(n,ma,mb);
    for i:=0 to n-1 do
        readln(a[i],b[i],c[i]);

    for i:=0 to n do
        for ca:=0 to 400 do
            for cb:=0 to 400 do
                dp[i,ca,cb] := maxint;

    dp[0,0,0] := 0;
    for i:=0 to n-1 do
        for ca:=0 to 400 do
            for cb:=0 to 400 do
                if dp[i,ca,cb] <> maxint then
                    Begin
                        dp[i+1, ca, cb] := min(dp[i,ca,cb], dp[i+1, ca, cb]);
                        dp[i+1, ca+a[i], cb+b[i]] := dp[i,ca,cb] + c[i];
                    End;

    ans := maxint;
    for ca:=1 to 400 do
        for cb:=1 to 400 do
            if ma * cb = mb * ca then
                ans := min(ans, dp[n,ca,cb]);

    if ans = maxint then writeln(-1)
    else writeln(ans);
END.

