import java.io.*;
import java.util.*;

public class Main {
    public static PrintWriter out;
    public static FastScanner in;

    private void solve(){
        int n = in.nextInt();
        int ma = in.nextInt();
        int mb = in.nextInt();

        int[][] dp = new int[401][401];
        for(int i=0;i<=400;i++){
            Arrays.fill(dp[i],Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for(int i=0;i<n;i++){
            int a = in.nextInt();
            int b = in.nextInt();
            int c = in.nextInt();

            for(int j=400-a;j>=0;j--){
                for(int k=400-b;k>=0;k--){
                    if(dp[j][k]!=Integer.MAX_VALUE){
                        dp[j+a][k+b] = Math.min(dp[j+a][k+b],dp[j][k]+c);
                    }
                }
            }
        }
        int mn = Integer.MAX_VALUE;
        for(int i=0;i<=400;i++){
            for(int j=0;j<=400;j++){
                if(dp[i][j]!=Integer.MAX_VALUE){
                    int g = gcd(i,j);
                    if(g == 0) continue;
                    if(i/g == ma && j/g == mb){
                        mn = Math.min(mn,dp[i][j]);
                    }
                }
            }
        }
        if(mn == Integer.MAX_VALUE) out.print(-1);
        else out.print(mn);
    }

    private int gcd(int a ,int b){
        if(b==0) return a;
        return gcd(b,a%b);
    }

    private void runIO() {
        in = new FastScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        solve();
        out.close();
    }
    private static class FastScanner {
        BufferedReader bufferedReader;
        StringTokenizer stringTokenizer;

        private FastScanner() {
            bufferedReader = new BufferedReader(new InputStreamReader(System.in));
        }

        private String next() {
            if (stringTokenizer == null || !stringTokenizer.hasMoreElements()) {
                try {
                    stringTokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return stringTokenizer.nextToken();
        }

        private int nextInt() {
            return Integer.parseInt(next());
        }

        private long nextLong() {
            return Long.parseLong(next());
        }

        private String nextLine() {
            String ret = "";
            try {
                ret = bufferedReader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return ret;
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        int ma = sc.nextInt();
        int mb = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];
        int[] c = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            c[i] = sc.nextInt();
        }
        int[][][] dp = new int[n + 1][10 * n + 1][10 * n + 1];
        for (int[][] x : dp) {
            for (int[] y : x) {
                Arrays.fill(y, 100000);
            }
        }
        // System.out.println(Arrays.deepToString(dp));
        dp[0][0][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= 10 * n; j++) {
                for (int k = 0; k <= 10 * n; k++) {
                    if (j - a[i - 1] >= 0 && k - b[i - 1] >= 0) {
                        dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j - a[i - 1]][k - b[i - 1]] + c[i - 1]);
                    }
                    dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j][k]);
                }
            }
        }
        int ans = 100000;
        for (int j = 0; j <= 10 * n; j++) {
            for (int k = 0; k <= 10 * n; k++) {
                if (j == 0 || k == 0) {
                    continue;
                }
                if (ma * k == mb * j) {
                    ans = Math.min(ans, dp[n][j][k]);
                }
            }
        }
        if (ans == 100000) {
            System.out.println(-1);
            return;
        }
        System.out.println(ans);
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte())
            return buffer[ptr++];
        else
            return -1;
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr]))
            ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext())
            throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

