public class Main{
    static ArrayList<int[]> abc;
    static int n, ma, mb;
    static int opt=Integer.MAX_VALUE;
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        n=Integer.parseInt(sc.next());
        ma=Integer.parseInt(sc.next());
        mb=Integer.parseInt(sc.next());
        abc=new ArrayList<int[]>();
        int a,b,c;
        for(int i=0;i<n;i++){
            a=Integer.parseInt(sc.next());
            b=Integer.parseInt(sc.next());
            c=Integer.parseInt(sc.next());
            int[] abc_i={a, b, c};
            abc.add(abc_i);
            // abc.add(new ArrayList<Integer>(Arrays.asList(a,b,c)));
        }
        sc.close();
        Collections.sort(abc,(arr1,arr2)->{
            if(arr1[2]>arr2[2]) return 1;
            else if(arr1[2]<arr2[2]) return -1;
            else return 0;
        });
        int ans=search(0, 0, 0, 0);
        if(ans==Integer.MAX_VALUE) ans=-1;
        System.out.println(ans);

    }

    public static int search(int sumA, int sumB, int sumC, int st){
        if(sumC>=opt) return Integer.MAX_VALUE;
        int a=abc.get(st)[0];
        int b=abc.get(st)[1];
        int c=abc.get(st)[2];
        if(sumA*mb==sumB*ma && sumA!=0){ 
            opt=sumC;
            return sumC;
        }
        else if((sumA+a)*mb==(sumB+b)*ma){
            if(sumC+c>=opt) return Integer.MAX_VALUE;
            opt=sumC+c;
            return sumC+c;
        }
        else{
            if(st==n-1) return Integer.MAX_VALUE;
            else return Math.min(search(sumA+a, sumB+b, sumC+c, st+1), search(sumA, sumB, sumC, st+1));
        }   
    }

}

import java.util.*;

class Main {
	static int N, Ma, Mb;
	static int[] a, b, c;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		Ma = sc.nextInt();
		Mb = sc.nextInt();
		a = new int[N];
		b = new int[N];
		c = new int[N];
		for (int i = 0; i < N; ++i) {
			a[i] = sc.nextInt();
			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		class State implements Comparable<State> {
			int cost;
			int criterion;

			public State(int a_sum, int b_sum, int cost) {
				this.cost = cost;
				criterion = Ma * b_sum - Mb * a_sum;
			}

			public State(int criterion,int cost) {
				this.criterion=criterion;
				this.cost=cost;
			}

			public int compareTo(State o) {
				int comp = -Integer.compare(criterion, o.criterion);
				if (comp == 0) {
					return Integer.compare(cost, o.cost);
				} else
					return comp;
			};
		}
		ArrayList<State> state1 = new ArrayList<>();
		ArrayList<State> state2 = new ArrayList<>();
		ArrayList<State> tmp = new ArrayList<>();
		for (int s = 0; s < (1 << (N / 2)); ++s) {
			int cost = 0, a_sum = 0, b_sum = 0;
			for (int j = 0; j < N / 2; ++j) {
				if ((s & (1 << j)) > 0) {
					a_sum += a[j];
					b_sum += b[j];
					cost += c[j];
				}
			}
			state1.add(new State(a_sum, b_sum, cost));
		}
		for (long s = (1l << N) - 1; s >= 1l << (N / 2); --s) {
			int cost = 0, a_sum = 0, b_sum = 0;
			for (int j = N - 1; j >= N / 2; --j) {
				if ((s & (1l << j)) > 0) {
					a_sum += a[j];
					b_sum += b[j];
					cost += c[j];
				}
			}
			tmp.add(new State(a_sum, b_sum, cost));
		}
		long ans = Long.MAX_VALUE / 16;
		Collections.sort(tmp);
		for (int i = 0; i < tmp.size(); ++i) {
			while (i + 1 < tmp.size() && tmp.get(i).criterion == tmp.get(i + 1).criterion
					&& tmp.get(i).cost >= tmp.get(i + 1).cost)
				++i;
			state2.add(tmp.get(i));
		}
		for (int i = 0; i < state1.size(); ++i) {
			State s1 = state1.get(i);
			int upper = state2.size();
			int lower = -1;
			while (upper - lower > 1) {
				int middle = (upper + lower) / 2;
				if (-state2.get(middle).criterion >= s1.criterion) {
					upper = middle;
				} else {
					lower = middle;
				}
			}
			if (upper < state2.size() && -state2.get(upper).criterion == s1.criterion) {
				ans = Math.min(ans, state2.get(upper).cost + s1.cost);
			}
		}
		if (ans == Long.MAX_VALUE / 16) {
			System.out.println(-1);
		} else {
			System.out.println(ans);
		}
	}
}

import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = false;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private int N;
    private int Ma;
    private int Mb;
    private int[] a;
    private int[] b;
    private int[] c;

    private Map<String, Integer> memo = new HashMap<>();

    private void solve(Scanner sc) {
        N = sc.nextInt();
        Ma = sc.nextInt();
        Mb = sc.nextInt();
        a = new int[N];
        b = new int[N];
        c = new int[N];
        for (int i = 0; i < N; ++i) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            c[i] = sc.nextInt();
        }

        int r = calc(0, 0, 0);
        if (r == Integer.MAX_VALUE) {
            _out.println(-1);
        } else {
            _out.println(r);
        }
    }
    private int calc(int d, int ma, int mb) {
        String key = d + "/" + ma + "/" + mb;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        if (d >= N) {
            if (d == N && ma > 0 && mb > 0 && ma % Ma == 0 && mb % Mb == 0 && ma / Ma == mb / Mb) {
                return 0;
            }
            return Integer.MAX_VALUE;
        }

        int r1 = calc(d + 1, ma, mb);
        int r2 = calc(d + 1, ma + a[d], mb + b[d]);
        if (r2 != Integer.MAX_VALUE) {
            r2 = r2 + c[d];
        }
        int r = Math.min(r1, r2);
        memo.put(key, r);
        return r;
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

