						}
					}
				}
			}
		}

		int ret = INF;
		for (int i = 1;i <= n;i++) {
			for (int j = 1;j <= 400;j++) {
				int a = j*ma;
				int b = j*mb;
				if (a<=400&&b<=400) {
					if (dp[i][a][b]!=-1) {
						ret = Math.min(ret, dp[i][a][b]);
					}
				}
			}
		}
		System.out.println(ret==INF?-1:ret);
	}
}

