public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    int Ma = sc.nextInt();
    int Mb = sc.nextInt();

    int[] a = new int[N];
    int[] b = new int[N];
    int[] c = new int[N];
    for (int i = 0; i < N; i ++) {
      a[i] = sc.nextInt();
      b[i] = sc.nextInt();
      c[i] = sc.nextInt();
    }

    int[][][] dp = new int[N + 1][401][401];
    for (int[][] v : dp) for (int[] u : v) Arrays.fill(u, Integer.MAX_VALUE / 2);
    dp[0][0][0] = 0;

    for (int i = 0; i < N; i ++) {
      for (int j = 0; j <= 400; j ++) {
        for (int k = 0; k <= 400; k ++) {
          dp[i + 1][j][k] = Math.min(dp[i + 1][j][k], dp[i][j][k]);
          if (j >= a[i] && k >= b[i]) {
            dp[i + 1][j][k] = Math.min(dp[i + 1][j][k], dp[i][j - a[i]][k - b[i]] + c[i]); 
          }
        }
      }
    }

    int ret = Integer.MAX_VALUE;
    for (int j = 1; j <= 400; j ++) {
      for (int k = 1; k <= 400; k ++) {
        if (j * Mb == k * Ma) {
          ret = Math.min(dp[N][j][k], ret);
        }
      }
    }
    System.out.println(ret >= Integer.MAX_VALUE / 2 ? -1 : ret);
  }

