  static class TaskD {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      int ma = in.nextInt();
      int mb = in.nextInt();
      int[] a = new int[n];
      int[] b = new int[n];
      int[] c = new int[n];
      IOUtils.readIntArrays(in, a, b, c);
      int[][][] f = new int[n + 1][401][401];
      ArrayUtils.fill(f, Integer.MAX_VALUE);
      f[0][0][0] = 0;
      for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= 400; j++) {
          for (int k = 0; k <= 400; k++) {
            if (j >= a[i - 1] && k >= b[i - 1]) {
              int last = f[i - 1][j - a[i - 1]][k - b[i - 1]];
              if (last < Integer.MAX_VALUE) {
                f[i][j][k] = Math.min(last + c[i - 1], f[i - 1][j][k]);
              } else {
                f[i][j][k] = f[i - 1][j][k];
              }
            } else {
              f[i][j][k] = Math.min(f[i][j][k], f[i - 1][j][k]);
            }
          }
        }
      }
      int answer = Integer.MAX_VALUE;
      for (int j = 1; j <= 400; j++) {
        for (int k = 1; k <= 400; k++) {
          if (j * mb == k * ma) {
            answer = Math.min(answer, f[n][j][k]);
          }
        }
      }
      out.printLine(answer == Integer.MAX_VALUE ? -1 : answer);
    }

  }

  static class OutputWriter {
