			int key = a * Mb - b * Ma;
			key = -key;
			if(map.containsKey(key)) {
				if(cost + map.get(key) == 0)continue;
				ans = min(ans, cost + map.get(key));
			}
		}
		out.println(ans == inf ? -1 : ans);
	}

