        }
        int[][][] dp = new int[N+1][N*100+1][3];
        for (int i = 0; i <= N; i++) {
            dp[i][0][0] = 1;//done
            dp[i][0][1] = 0;//a
            dp[i][0][2] = 0;//b
        }
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= N*100; j++) {
                if (dp[i-1][j][0] == 0) {
                    continue;
                }
                dp[i][j+c[i]][0] = 1;
                dp[i][j+c[i]][1] = dp[i-1][j][1] + a[i];
                dp[i][j+c[i]][2] = dp[i-1][j][2] + b[i];
            }
        }
