            for (int j = 1; j <= N*100; j++) {
                if (dp[i][j][0] == 0) {
                    continue;
                }
                if (dp[i][j][1] * Mb == dp[i][j][2] * Ma) {
                    answer = Math.min(answer, j);
                }
            }
        }
        if (answer == Integer.MAX_VALUE) {
            answer = -1;
        }
        System.out.println(answer);
    }
}

