        // -----------------------------------------
        int INF = 1001001001;
        int N, MA, MB;
        int[] A, B, C;
        int[][][] dp = new int[41][401][401];
        boolean check(int sumA, int sumB) {
        	if(sumA < MA || sumB < MB)				return false;
        	if(sumA % MA != 0 || sumB % MB != 0)	return false;
        	if(sumA / MA * MB != sumB)				return false;
        	return true;
        }
        int calc(int now, int sumA, int sumB) {
        	if(now >= N)					return INF;
        	if(dp[now][sumA][sumB] != INF)	return dp[now][sumA][sumB];
        	if(check(sumA, sumB))			return 0;
        	int ans = calc(now + 1, sumA, sumB);
        	int wk = calc(now + 1, sumA + A[now], sumB + B[now]);
        	ans = Math.min(ans, (wk == INF ? INF : wk + C[now]));
        	return dp[now][sumA][sumB] = ans;
        }
        public void solve() {
        	N = ni();
        	MA = ni();
        	MB = ni();
        	for (int i = 0; i < 41; i++) {
				for (int j = 0; j < 401; j++) {
					for (int j2 = 0; j2 < 401; j2++) {
						dp[i][j][j2] = INF;
					}
				}
			}
        	A = new int[N];
        	B = new int[N];
        	C = new int[N];
        	for (int i = 0; i < N; i++) {
				A[i] = ni();
				B[i] = ni();
				C[i] = ni();
			}
        	int ans = calc(0,0,0);
        	prn((ans == INF ? -1 : ans));
        }

