        	dp[0][0][0] = 0;
        	for (int i = 0; i < N; i++) {
				for (int j = 0; j <= 400; j++) {
					for (int j2 = 0; j2 <= 400; j2++) {
						dp[i+1][j + A[i]][j2 + B[i]] = Math.min(dp[i+1][j + A[i]][j2 + B[i]],
						                                        dp[i][j + A[i]][j2 + B[i]]);
						dp[i+1][j + A[i]][j2 + B[i]] = Math.min(dp[i+1][j + A[i]][j2 + B[i]], 
																dp[i][j][j2] + C[i]);
					}
				}
        	}
        	int ans = INF;
			for (int j = 0; j <= 400; j++) {
				for (int j2 = 0; j2 <= 400; j2++) {
					if(j * MB == j2 * MA) {
						ans = Math.min(ans, dp[N][j][j2]);
//						prn(" ans = " + ans + "  j = " + j + "  j2 = " + j2);
					}
				}
			}
			prn((ans == INF ? -1 : ans));
        }

