      b[i] = Integer.parseInt(sc.next());
      c[i] = Integer.parseInt(sc.next());
      sub[i] = Mb * a[i] - Ma * b[i];
    }

    int origin = 10 * 10 * N;
    int length = origin * 2 + 1;
    int dp[][] = new int[N + 1][length];
    int maxSumCost = 100 * N + 1000;
    for (int i = 0; i < N + 1; i++) {
      for (int j = 0; j < length; j++) {
