          dp[i + 1][j] = Math.min(dp[i][j], dp[i + 1][j]);
          dp[i + 1][j + sub[i]] = Math.min(dp[i][j] + c[i], dp[i + 1][j + sub[i]]);
        } else if (j == origin) {
          dp[i + 1][origin + sub[i]] = Math.min(dp[i][origin + sub[i]], c[i]);
        }
