        System.out.println(result == Integer.MAX_VALUE ? -1 : result);
    }

    private static int[][] dp = new int[50][5000];
    static {
        for (int i = 0; i < dp.length; i++) {
            for (int j = 0; j < dp[i].length; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }
    }
    private static int candidate = Integer.MAX_VALUE;
    private static int allSearch(int i, int nowa, int nowb, int nowc){
        if(nowc != 0){
            if(dp[i][nowc] <= nowc){
                return dp[i][nowc];
            }else{
                dp[i][nowc] = nowc;
            }
            if(nowc >= candidate) return Integer.MAX_VALUE;
            if(isMatch(nowa, nowb)){
                candidate = Integer.min(candidate, nowc);
                return nowc;
            }
        }
        if(i >= abc.length) return Integer.MAX_VALUE;

        int a = abc[i][0], b = abc[i][1], c = abc[i][2];
        return Integer.min(
                allSearch(i + 1, nowa + a, nowb + b, nowc + c),
                allSearch(i + 1, nowa, nowb, nowc)
        );
    }

    private static boolean isMatch(int a, int b) {
        return a * mb == b * ma;
    }
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, ma, mb;
  final int[] as, bs, cs;

  Solver(int n, int ma, int mb, int[] as, int[] bs, int[] cs) {
    this.n = n;
    this.ma = ma;
    this.mb = mb;
    this.as = as;
    this.bs = bs;
    this.cs = cs;
  }

  private static final int INF = 1 << 20;

  private int[][] createCostMap(int indexMin, int indexMax) {
    int[][] costMap = new int[201][201];
    for (int[] array : costMap) {
      Arrays.fill(array, INF);
    }

    int indexDiff = indexMax - indexMin;
    for (int i = 0; i < (1 << indexDiff); i++) {
      int sumA = 0;
      int sumB = 0;
      int sumC = 0;
      for (int j = 0; j < indexDiff; j++) {
        if (((i >> j) & 1) == 1) {
          int index = indexMin + j;
          sumA += as[index];
          sumB += bs[index];
          sumC += cs[index];
        }
      }
      costMap[sumA][sumB] = Math.min(costMap[sumA][sumB], sumC);
    }
    return costMap;
  }

  public int solve() {
    int[][] costMap1 = createCostMap(0, n/2);
    int[][] costMap2 = createCostMap(n/2, n);

    int minCost = INF;
    for (int a = 1; a <= 200; a++) {
      for (int b = 1; b <= 200; b++) {
        if (costMap1[a][b] >= INF) {
          continue;
        }
        for (int k = Math.max(ma / a, mb / b); true; k++) {
          int requireA = ma * k - a;
          int requireB = mb * k - b;
          if (requireA < 0 || requireB < 0) {
            continue;
          }
          if (requireA >= costMap2.length || requireB >= costMap2[0].length) {
            break;
          }
          minCost = Math.min(minCost, costMap1[a][b] + costMap2[requireA][requireB]);
        }
      }
    }
    return minCost < INF ? minCost : -1;
  }
}

