/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        DMixingExperiment solver = new DMixingExperiment();
        solver.solve(1, in, out);
        out.close();
    }

    static class DMixingExperiment {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int ma = in.readInt();
            int mb = in.readInt();
            int[][][] dp = new int[50][500][500];
            int INF = Integer.MAX_VALUE / 2;
            ArrayUtils.fill(dp, INF);
            dp[0][0][0] = 0;
            for (int i = 0; i < n; i++) {
                int a = in.readInt();
                int b = in.readInt();
                int c = in.readInt();
                for (int j = 499; j >= 0; j--) {
                    for (int k = 499; k >= 0; k--) {
                        dp[i + 1][j][k] = dp[i][j][k];
                        if (j + a < 500 && k + b < 500) {
                            dp[i + 1][j + a][k + b] = Math.min(dp[i + 1][j + a][k + b], dp[i][j][k] + c);
                        }
                    }
                }
            }
            int ans = INF;
            for (int i = 1; ma * i < 500 && mb * i < 500; i++) {
                ans = Math.min(ans, dp[n][ma * i][mb * i]);
            }
            if (ans == INF) ans = -1;
            out.printLine(ans);
        }

    }

    static class ArrayUtils {
        public static void fill(int[][] array, int x) {
            for (int[] a : array) {
                Arrays.fill(a, x);
            }
        }

        public static void fill(int[][][] array, int x) {
            for (int[][] a : array) {
                fill(a, x);
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }
}

import java.io.*;
