      int[][][] f = new int[n + 1][401][401];
      ArrayUtils.fill(f, Integer.MAX_VALUE);
      for (int i = 0; i < n; i++) {
        f[1][a[i]][b[i]] = Math.min(c[i], f[1][a[i]][b[i]]);
      }
      for (int i = 2; i <= n; i++) {
        for (int j = 0; j <= 400; j++) {
          for (int k = 0; k <= 400; k++) {
            if (j >= a[i - 1] && k >= b[i - 1]) {
//            f[i][j][k] = f[i - 1][j][k];
