			c[i] = sc.nextInt();
		}

		// Guarantee: Ma < Mb
		if (Mb < Ma) {
			int t = Ma;
			Ma = Mb;
			Mb = t;
		}

		int[][][] dp = new int[N + 1][401][401];
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < dp[0].length; j++) {
				Arrays.fill(dp[i][j], Integer.MAX_VALUE);
			}
		}
		dp[0][0][0] = 0;
		dp[0][a[0]][b[0]] = c[0];
