			for (int j = 0; j < dp[i].length; j++) {
				for (int k = 0; k < dp[i][j].length; k++) {
					dp[i][j][k] = dp[i - 1][j][k];
					if (a[i] <= j && b[i] <= k) {
						if (dp[i - 1][j - a[i]][k - b[i]] == Integer.MAX_VALUE) continue;
						dp[i][j][k] = Math.min(
								dp[i][j][k], dp[i - 1][j - a[i]][k - b[i]] + c[i]
