                drugs[i] = new DMixingExperiment.Drug(in.ints(), in.ints(), in.ints());
            }

            for (int j = 0; j < 500; j++) {
                for (int k = 0; k < 500; k++) {
                    if (dp[j][k] == INF) continue;
                    for (int i = 0; i < n; i++) {
                        if (j + drugs[i].a >= 500 || k + drugs[i].b >= 500) continue;
                        dp[j + drugs[i].a][k + drugs[i].b] = Math.min(dp[j + drugs[i].a][k + drugs[i].b], dp[j][k] + drugs[i].c);
                    }
                }
            }

            int ans = INF;
            int na = ma, nb = mb;
            while (na < 500 && nb < 500) {
                if (dp[na][nb] != INF) {
                    ans = Math.min(ans, dp[na][nb]);
                }
                na += ma;
                nb += mb;
            }
            if (ans >= INF) {
                out.ansln(-1);
            } else {
                out.ansln(ans);
            }
        }

        private static class Drug {
            int a;
            int b;
            int c;

            public Drug(int a, int b, int c) {
                this.a = a;
                this.b = b;
                this.c = c;
            }

        }

    }

