                int k = meds[i].a - meds[i].b;
                if(na == 0&&nb == 0){
                    int o = search(meds,ma,mb,na + meds[i].a,nb + meds[i].b,i,pr + meds[i].pr);
                    min = min > o ? o : min;
                }
                if(k > 0&&ma * nb > mb * na){
                    int o = search(meds,ma,mb,na + meds[i].a,nb + meds[i].b,i,pr + meds[i].pr);
                    min = min > o ? o : min;
                }
                else if(k < 0&&ma * nb < mb * na){
                    int o = search(meds,ma,mb,na + meds[i].a,nb + meds[i].b,i,pr + meds[i].pr);
                    min = min > o ? o : min;
                }
                else if(k == 0){
                    int o = search(meds,ma,mb,na + meds[i].a,nb + meds[i].b,i,pr + meds[i].pr);
                    min = min > o ? o : min;
                }
        }
        return min;
    }


    public static class Med{
        int a,b,pr;
        public Med(int a,int b,int pr){
            this.a = a;
            this.b = b;
            this.pr = pr;
        }
    }



