		costTable[0][0] = 0;
		HashSet<Integer> s = new HashSet<>();

		for (int i = 0; i <= 400; i++) {
			for (int j = 0; j <= 400; j++) {
				int h = new AB(i, j).hashCode();
				s.add(h);
			}
		}
