			this.b = b;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			AB other = (AB) obj;
			if (a != other.a)
				return false;
			if (b != other.b)
				return false;
