    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0L;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public double nextDouble() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            double ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            int cnt = 0;
            for (; i < len; i++) {
            	if(str[i] == '.') {
            		cnt = 10;
            		continue;
            	}
            	if(cnt == 0) {
            		ret = ret * 10 + str[i] - '0';
            	} else {
            		ret = ret + ((double)(str[i] - '0') / cnt);
            		cnt *= 10;
            	}
            }
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

       public String nextString() {
        	String ret = new String(nextDChar()).trim();
            return ret;
        }

        public char[] nextDChar() {
            int len = 0;
            len = reads(len, isSpace);
            char[] ret = new char[len + 1];
            for (int i=0; i < len; i++)		ret[i] = str[i];
            ret[len] = 0x00;
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }
    }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int Ma = sc.nextInt();
		int Mb = sc.nextInt();
		int[] a = new int[N];
		int[] b = new int[N];
		int[] c = new int[N];
		for(int i = 0; i < N; i++) {
			a[i] = sc.nextInt();
			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		sc.close();
		int n = 401;

		int[][][] dp = new int[N + 1][n][n];
		int INF = 100000000;
		for(int i = 0; i <= N; i++) {
			for(int j = 0; j < n; j++) {
				for(int k = 0; k < n; k++) {
					dp[i][j][k] = INF;
				}
			}
		}
		dp[0][0][0] = 0;
		for(int i = 0; i < N; i++) {
			for(int j = 0; j < n; j++) {
				for(int k = 0; k < n; k++) {
					if(dp[i][j][k] != INF) {
						int A = j + a[i];
						int B = k + b[i];
						dp[i + 1][j][k] = dp[i][j][k];
						dp[i + 1][A][B] = dp[i][j][k] + c[i];
					}
				}
			}
		}
		int min = INF;
		for(int j = 1; j < n; j++) {
			for(int k = 0; k < n; k++) {
				if(Ma * j == Mb * k) {
					min = Math.min(min, dp[N][j][k]);
				}
			}
		}
		if(min == INF) min = -1;
		System.out.println(min);
	}
}

import java.util.*;

public class Main {

    private static int N;
    private static int MA;
    private static int MB;
    private static Drag[] D;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        MA = sc.nextInt();
        MB = sc.nextInt();
        D = new Drag[N];
        for (int i = 0; i < N; i++) {
            D[i] = new Drag(sc.nextInt(), sc.nextInt(), sc.nextInt());
        }
        System.out.println(solve());
    }

    private static final int INF = 1_000_000;

    static int solve() {
        int[][][] dp = new int[N+1][N*10+1][N*10+1];
        for (int i = 0; i < N+1; i++) {
            for (int j = 0; j < N*10+1; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }
        dp[0][0][0] = 0;

        for (int i = 1; i <= N; i++) {
            Drag d = D[i-1];

            for (int a = 0; a <= N*10; a++) {
                for (int b = 0; b <= N*10; b++) {
                    int prev = dp[i-1][a][b];
                        // 追加購入
                    if( a + d.a <= N*10 && b + d.b <= N*10 ) {
                        dp[i][a+d.a][b+d.b] = Math.min(dp[i-1][a+d.a][b+d.b], prev + d.cost);
                    }

                    // 買わない
                    dp[i][a][b] = Math.min(prev, dp[i][a][b]);
                }
            }
        }

        // MA:MBになる場所で一番コストの少ない箇所を探す
        int n = 1;
        int cost = INF;
        while(true) {
            int a = n * MA;
            int b = n * MB;
            if( a > N*10 || b > N*10 ) break;

            if( Math.min(dp[N][a][b], cost) != 0 ) {
                cost = Math.min(dp[N][a][b], cost);
            }
            n++;
        }

        if( cost == INF ) return -1;
        else return cost;
    }

    private static class Drag {
        private final int a;
        private final int b;
        private final int cost;

        public Drag(int a, int b, int cost) {
            this.a = a;
            this.b = b;
            this.cost = cost;
        }
    }
}

