			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		memo = new int[N+1][450][450];
		int ans = msd(0, 0, 0, 0);

		if (ans == INF) ans = -1;




		System.out.println(ans);
	}
	int[][][] memo;
	int msd (int n, int sum, int na, int nb) {
		if (memo[n][na][nb] != 0) {
			return memo[n][na][nb] + sum;
		}
		if (na !=0 && na * MB == nb * MA) {
			return sum;
		}
		if (n == N) {

			return INF;

		}
		int min = 0;
		int u = msd(n+1, sum +c[n], na + a[n], nb + b[n]);
		int nu =   msd(n+1, sum, na, nb);
		if (u > nu) {
			memo[n][na][nb] = min - sum;
		}else {
			memo[n][na][nb] = min - (sum + c[n]);
		}
		min = Math.min(nu, u);


		return min;
	}



