        // -----------------------------------------
        // Integer のキーに対して、カウントを管理する（カウントを足したり、引いたりする）
        static class MapCounter {
        	private Map<Integer, Long> map = new HashMap<>();
        	public MapCounter() {}
        	// キーのカウントに値を足す
        	public void add(int key) {
        		add(key, 1);
        	}
           	public void add(int key, int cnt) {
