    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0L;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public double nextDouble() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            double ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            int cnt = 0;
            for (; i < len; i++) {
            	if(str[i] == '.') {
            		cnt = 10;
            		continue;
            	}
            	if(cnt == 0) {
            		ret = ret * 10 + str[i] - '0';
            	} else {
            		ret = ret + ((double)(str[i] - '0') / cnt);
            		cnt *= 10;
            	}
            }
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

       public String nextString() {
        	String ret = new String(nextDChar()).trim();
            return ret;
        }

        public char[] nextDChar() {
            int len = 0;
            len = reads(len, isSpace);
            char[] ret = new char[len + 1];
            for (int i=0; i < len; i++)		ret[i] = str[i];
            ret[len] = 0x00;
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * https://abc054.contest.atcoder.jp/tasks/abc054_d
 */
public class Main {

	static Drag[] drags;
	static int[][][] dp;
	static int SIZE = 400;
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int Ma = sc.nextInt();
		int Mb = sc.nextInt();
		drags = new Drag[N];
		for(int i=0; i<N; i++){
			drags[i] = new Drag(
				Integer.parseInt(sc.next()),
				Integer.parseInt(sc.next()),
				Integer.parseInt(sc.next())
			);
		}
		sc.close();
		dp = new int[drags.length][SIZE+1][SIZE+1];
		for(int i=0; i<N; i++){
			for(int a=0; a<=SIZE; a++){
				for(int b=0; b<=SIZE; b++){
					dp[i][a][b] = -1;
				}
			}
		}

		int ans = Integer.MAX_VALUE;
		for(int a=Ma; a<=400; a+=Ma){
			int b = (a/Ma)*Mb;
			if(b>400) break;
			ans = Math.min(ans, dfs(0,a,b));
		}
		System.out.println(ans>=Integer.MAX_VALUE/2 ? -1 : ans);
	}


	static int dfs(int n, int a, int b) {
		if(a==0 && b==0){
			return 0;
		}else if(n==drags.length) {
			return Integer.MAX_VALUE/2;
		}else if (dp[n][a][b]>=0) {
			return dp[n][a][b];
		}
		int res;
		Drag d = drags[n];
		if(a-d.a<0 || b-d.b<0) {
			res = dfs(n+1, a, b);
		}else{
			res = Math.min(dfs(n+1, a, b), dfs(n+1, a-d.a, b-d.b)+d.c);
		}
		dp[n][a][b] = res;
		return res;
	}

	static String getKey(int n, int a, int b){
		return n+"."+a+"."+b;
	}

	static class Drag{
		int a;
		int b;
		int c;
		Drag(int a, int b, int c){
			this.a = a;
			this.b = b;
			this.c = c;
		}
	}

}

import java.util.Scanner;

public class Main {

	private static int[][][] dp = new int[41][410][410];
	private static int[] a = new int[41];
	private static int[] b = new int[41];
	private static int[] c = new int[41];

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);
		int i , j , k , n , ma , mb;
		n = scan.nextInt();
		ma = scan.nextInt();
		mb = scan.nextInt();

		for (i = 0;i < 41;i ++)
			for (j = 0;j < 410;j ++)
				for (k = 0;k < 410;k ++) {
					dp[i][j][k] = - 1;
				}

		for (i = 0;i < n;i ++) {
			a[i] = scan.nextInt();
			b[i] = scan.nextInt();
			c[i] = scan.nextInt();
		}

		dp[0][a[0]][b[0]] = c[0];
		dp[0][0][0] = 0;

		for (i = 1;i < n;i ++) {
			for (j = 0;j <= 400;j ++)
				for (k = 0;k <= 400;k ++) {
					dp[i][j][k] = dp[i - 1][j][k];
				}
			for (j = 0;j <= 400;j ++)
				for (k = 0;k <= 400;k ++) {
					if (dp[i - 1][j][k] >= 0) {
						int temp = dp[i - 1][j][k] + c[i];
						int x = j + a[i];
						int y = k + b[i];
						if (dp[i][x][y] < 0 || temp < dp[i][x][y]) {
							dp[i][x][y] = temp;
						}
					}
				}
		}
		int ans = - 1;
		for (i = 1;i <= 400;i ++)
			for (j = 1;j <= 400;j ++) {
				if (dp[n - 1][i][j] >= 0) {
					if (i * mb == ma * j) {
						if (dp[n - 1][i][j] < ans || ans < 0)
							ans = dp[n - 1][i][j];
					}
				}
			}
		System.out.println(ans);

	}

}

