      for (int j = 1; j <= M; j++) {
        for (int k = 1; k <= M; k++) {
          dp[i][j][k] = dp[i - 1][j][k];
          if(j >= a[i] && k >= b[i]) {
            dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j - a[i]][k - b[i]] + c[i]);
          }
        }
      }
    }

    //for (int i = 1; i <= N; i++) {
    //  System.out.printf("N = %d\n", i);
    //  for (int j = 1; j <= M; j++) {
    //    for (int k = 1; k <= M; k++) {
