import java.util.Arrays;
import java.util.Scanner;

public class Main {
	int n;
	int ma, mb;
	int[] a, b, c;
	int[][][] dp;

	int dp(int k, int ta, int tb) {
		if (k == 0 && ta == a[0] && tb == b[0]) {
			return c[0];
		}
		if (k < 0 || ta < 0 || tb < 0) {
			return 1 << 20;
		}
		if (dp[k][ta][tb] < (1 << 20)) {
			return dp[k][ta][tb];
		}

		int ret = 1 << 20;
		ret = dp(k - 1, ta, tb);
		ret = Math.min(dp(k - 1, ta - a[k], tb - b[k]) + c[k], ret);
		return dp[k][ta][tb] = ret;
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		n = sc.nextInt();
		ma = sc.nextInt();
		mb = sc.nextInt();
		a = new int[n];
		b = new int[n];
		c = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		dp = new int[n][401][401];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < 401; j++) {
				Arrays.fill(dp[i][j], 1 << 20);
			}
		}
		int min = 1 << 20;
		for (int i = 1; i <= 400; i++) {
			if (400 < ma * i || 400 < mb * i) {
				break;
			}
			int tmp = dp(n - 1, ma * i, mb * i);
			min = Math.min(min, tmp);
		}

		if (min < (1 << 20)) {
			System.out.println(min);
		} else {
			System.out.println(-1);
		}
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

import java.util.*;

class Main {
	static int N, Ma, Mb;
	static int[] a, b, c;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		Ma = sc.nextInt();
		Mb = sc.nextInt();
		a = new int[N];
		b = new int[N];
		c = new int[N];
		for (int i = 0; i < N; ++i) {
			a[i] = sc.nextInt();
			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		class State implements Comparable<State> {
			int a_sum, b_sum;
			int cost;
			int criterion;

			public State(int a_sum, int b_sum, int cost) {
				this.a_sum = a_sum;
				this.b_sum = b_sum;
				this.cost = cost;
				criterion = Ma * b_sum - Mb * a_sum;
			}

			public int compareTo(State o) {
				int comp = -Integer.compare(criterion, o.criterion);
				if (comp == 0) {
					return Integer.compare(cost, o.cost);
				} else
					return comp;
			};
		}
		ArrayList<State> state1 = new ArrayList<>();
		ArrayList<State> state2 = new ArrayList<>();
		for (int s = 0; s < (1 << (N / 2)); ++s) {
			int cost = 0, a_sum = 0, b_sum = 0;
			for (int j = 0; j < N / 2; ++j) {
				if ((s & (1 << j)) > 0) {
					a_sum += a[j];
					b_sum += b[j];
					cost += c[j];
				}
			}
			state1.add(new State(a_sum, b_sum, cost));
		}
		for (long s = (1 << N) - 1; s >= 1 << (N / 2); --s) {
			int cost = 0, a_sum = 0, b_sum = 0;
			for (int j = N - 1; j >= N / 2; --j) {
				if ((s & (1l << j)) > 0) {
					a_sum += a[j];
					b_sum += b[j];
					cost += c[j];
				}
			}
			state2.add(new State(a_sum, b_sum, cost));
		}
		long ans = Long.MAX_VALUE / 16;
		Collections.sort(state2);
		for (int i = 0; i < state1.size(); ++i) {
			State s1 = state1.get(i);
			int upper = state2.size();
			int lower = -1;
			while (upper - lower > 1) {
				int middle = (upper + lower) / 2;
				if (-state2.get(middle).criterion >= s1.criterion) {
					upper = middle;
				} else {
					lower = middle;
				}
			}
			if (upper < state2.size() && -state2.get(upper).criterion == s1.criterion) {
				ans = Math.min(ans, state2.get(upper).cost + s1.cost);
			}
		}
		if (ans == Long.MAX_VALUE / 16) {
			System.out.println(-1);
		} else {
			System.out.println(ans);
		}
	}
}

