class Cart{
        ArrayList<Med> cart;
        int cost;
        int Ag,Bg;
        boolean end;
        Cart(){
                this.cart = new ArrayList<Med>();
                this.cost = 0;
                this.Ag = 0;
                this.Bg = 0;
                this.end = false;
        }
        void buy(Med m){
                this.cart.add(m);
                this.Ag += m.a;
                this.Bg += m.b;
                this.cost += m.c;
        }
        void clearCart(Med[] med){
                this.cart = new ArrayList<Med>();
                for(Med m : med){
                        m.outOfCart();
                }
                this.cost = 0;
                this.end = true;
        }
        double getP(){
                return (double)Ag / (double)Bg;
        }
        boolean checkCart(int Ma,int Mb){
                boolean ch = Ma * this.Bg == Mb * this.Ag;
                return ch;
        }
}

class Med{
        int a,b,c;
        boolean inCart = false;
        double getP(){
                return (double)a / (double)b;
        }
        void intoCart(){
                inCart = true;
        }
        void outOfCart(){
                inCart = false;
        }
}

class Comparator1 implements Comparator<Med>{
        @Override
        public int compare(Med med1,Med med2){
                return Double.compare(med1.getP(),med2.getP());
        }
}

