        	int ans = calc(now + 1, sumA, sumB);
        	int wk = calc(now + 1, sumA + A[now], sumB + B[now]);
        	ans = Math.min(ans, (wk == NOT_FOUND ? NOT_FOUND : wk + C[now]));
        	return dp[now][sumA][sumB] = ans;
        }
