class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int ratioA = sc.nextInt();
    int ratioB = sc.nextInt();
    int[] a = new int[N];
    int[] b = new int[N];
    int[] c = new int[N];
    int sumA = 0;
    int sumB = 0;
    for(int i = 0; i < N; i++) {
      a[i] = sc.nextInt();
      b[i] = sc.nextInt();
      c[i] = sc.nextInt();
      sumA += a[i];
      sumB += b[i];
    }
    int[][][] dp = new int[401][401][N];
    for(int i = 0; i < N; i++) {
      for(int j = 0; j < 401; j++) {
        for(int k = 0; k < 401; k++) {
          dp[j][k][i] = -1;
        }
      }
    }
    dp[a[0]][b[0]][0] = c[0];
    for(int i = 1; i < N; i++) {
      for(int j = 0; j < 401; j++) {
        for(int k = 0; k < 401; k++) {
          if(a[i] <= j && b[i] <= k) {
            int m = Integer.MAX_VALUE;
            if(a[i] == j && b[i] == k) {
              m = c[i];
            } else {
              if(dp[j - a[i]][k - b[i]] != -1) m = c[i] + dp[j - a[i]][k - b[i]];
            }
            if(dp[j][k][i - 1] == -1) {
              if(m == Integer.MAX_VALUE) {
                dp[j][k][i] = -1;
              } else {
                dp[j][k][i] = m;
              }
            } else {
              dp[j][k][i] = Math.min(m, dp[j][k][i - 1]);
            }
          } else {
            dp[j][k][i] = dp[j][k][i - 1];
          }
        }
      }
    }
    int cost = Integer.MAX_VALUE;
    for(int i = 1; i <= Math.min(sumA / ratioA, sumB / ratioB); i++) {
      if(dp[ratioA * i][ratioB * i] != -1) {
        cost = Math.min(cost, dp[ratioA * i][ratioB * i]);
      }
    }
    int res = "";
    if(cost != Integer.MAX_VALUE) {
      res = cost;
    } else {
      res = -1;
    }
    System.out.println(res);
  }
}

import java.util.HashMap;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int Ma = sc.nextInt();
		int Mb = sc.nextInt();
		int[] a = new int[N];
		int[] b = new int[N];
		int[] c = new int[N];
		for (int i = 0; i < N; ++i) {
			a[i] = sc.nextInt();
			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		HashMap<Integer, Integer> map = new HashMap<>();
		for (int s = 0; s < 1 << (N / 2); ++s) {
			int ma = 0, mb = 0, cost = 0;
			for (int i = 0; i < 1 << (N / 2); ++i) {
				if ((s & (1 << i)) > 0) {
					ma += a[i];
					mb += b[i];
					cost += c[i];
				}
			}
			int key = Ma * mb - Mb * ma;
			if (map.containsKey(key)) {
				map.put(key, Math.min(map.get(key), cost));
			} else {
				map.put(key, cost);
			}
		}
		int ans = Integer.MAX_VALUE / 3;
		for (int s = 0; s < 1 << (N - N / 2); ++s) {
			int ma = 0, mb = 0, cost = 0;
			for (int i = 0; i < 1 << (N - N / 2); ++i) {
				if ((s & (1 << i)) > 0) {
					ma += a[N / 2 + i];
					mb += b[N / 2 + i];
					cost += c[N / 2 + i];
				}
			}
			int key = -(Ma * mb - Mb * ma);
			if (map.containsKey(key) && cost + map.get(key) > 0) {
				ans = Math.min(ans, cost + map.get(key));
			}
		}
		System.out.println(ans >= Integer.MAX_VALUE / 4 ? -1 : ans);
	}
}

