        int[][][] dp = new int[41][401][401];
        boolean check(int sumA, int sumB) {
//        	if(sumA < MA || sumB < MB)				return false;
//        	if(sumA % MA != 0 || sumB % MB != 0)	return false;
//        	if(sumA / MA * MB != sumB)				return false;
        	if(sumA == 0 || sumB == 0)	return false;
        	if(sumA * MB != sumB * MA)	return false;
        	return true;
        }
        int calc(int now, int sumA, int sumB) {
        	if(now >= N)					return INF;
        	if(dp[now][sumA][sumB] != INF)	return dp[now][sumA][sumB];
        	if(check(sumA, sumB))			return 0;
        	int wk = calc(now + 1, sumA, sumB);
        	int ans = (wk == INF ? INF + 1 : wk);
        	wk = calc(now + 1, sumA + A[now], sumB + B[now]);
        	ans = Math.min(ans, (wk == INF ? INF + 1 : wk + C[now]));
        	return dp[now][sumA][sumB] = ans;
        }
