    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0L;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public double nextDouble() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            double ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            int cnt = 0;
            for (; i < len; i++) {
            	if(str[i] == '.') {
            		cnt = 10;
            		continue;
            	}
            	if(cnt == 0) {
            		ret = ret * 10 + str[i] - '0';
            	} else {
            		ret = ret + ((double)(str[i] - '0') / cnt);
            		cnt *= 10;
            	}
            }
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

       public String nextString() {
        	String ret = new String(nextDChar()).trim();
            return ret;
        }

        public char[] nextDChar() {
            int len = 0;
            len = reads(len, isSpace);
            char[] ret = new char[len + 1];
            for (int i=0; i < len; i++)		ret[i] = str[i];
            ret[len] = 0x00;
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * https://abc054.contest.atcoder.jp/tasks/abc054_d
 */
public class Main {

	static Drag[] drags;
	static Map<String,Integer> dp = new HashMap<>();
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int Ma = sc.nextInt();
		int Mb = sc.nextInt();
		drags = new Drag[N];
		for(int i=0; i<N; i++){
			drags[i] = new Drag(
				Integer.parseInt(sc.next()),
				Integer.parseInt(sc.next()),
				Integer.parseInt(sc.next())
			);
		}
		sc.close();

		int ans = Integer.MAX_VALUE;
		for(int a=Ma; a<=400; a+=Ma){
			int b = (a/Ma)*Mb;
			if(b>400) break;
			ans = Math.min(ans, dfs(0,a,b));
		}
		System.out.println(ans>=Integer.MAX_VALUE/2 ? -1 : ans);
	}

	static int dfs(int n, int a, int b) {
		if (dp.get(getKey(n, a, b))!=null) {
			return dp.get(getKey(n, a, b));
		}
		int res;
		if(a==0 && b==0){
			res = 0;
		}else if(n==drags.length) {
			res=Integer.MAX_VALUE/2;
		}else{
			Drag d = drags[n];
			if(a-d.a<0 && b-d.b<0) {
				res = dfs(n+1, a, b);
			}else{
				res = Math.min(dfs(n+1, a, b), dfs(n+1, a-d.a, b-d.b)+d.c);
			}
		}
		dp.put(getKey(n, a, b), res);
		return res;
	}

	static String getKey(int n, int a, int b){
		return n+"."+a+"."+b;
	}

	static class Drag{
		int a;
		int b;
		int c;
		Drag(int a, int b, int c){
			this.a = a;
			this.b = b;
			this.c = c;
		}
	}

}

