	int[] a, b, c;
	int[][][] dp;

	int dp(int k, int ta, int tb) {
		if (k == 0 && ta == a[0] && tb == b[0]) {
			return c[0];
		}
		if (k < 0 || ta < 0 || tb < 0) {
			return 1 << 20;
		}
		if (dp[k][ta][tb] < (1 << 20)) {
			return dp[k][ta][tb];
		}

		int ret = 1 << 20;
		ret = dp(k - 1, ta, tb);
		ret = Math.min(dp(k - 1, ta - a[k], tb - b[k]) + c[k], ret);
		return dp[k][ta][tb] = ret;
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		n = sc.nextInt();
		ma = sc.nextInt();
		mb = sc.nextInt();
		a = new int[n];
