			b[i] = sc.nextInt();
			c[i] = sc.nextInt();
		}
		class State implements Comparable<State> {
			int cost;
			int criterion;

			public State(int a_sum, int b_sum, int cost) {
				this.cost = cost;
				criterion = Ma * b_sum - Mb * a_sum;
			}

			public State(int criterion,int cost) {
				this.criterion=criterion;
				this.cost=cost;
			}

			public int compareTo(State o) {
				int comp = -Integer.compare(criterion, o.criterion);
				if (comp == 0) {
					return -Integer.compare(cost, o.cost);
				} else
					return comp;
			};
		}
		ArrayList<State> state1 = new ArrayList<>();
		ArrayList<State> state2 = new ArrayList<>();
		ArrayList<State> tmp = new ArrayList<>();
		for (int s = 0; s < (1 << (N / 2)); ++s) {
			int cost = 0, a_sum = 0, b_sum = 0;
			for (int j = 0; j < N / 2; ++j) {
				if ((s & (1 << j)) > 0) {
					a_sum += a[j];
					b_sum += b[j];
					cost += c[j];
				}
			}
			state1.add(new State(a_sum, b_sum, cost));
		}
		for (long s = (1l << N) - 1; s >= 1l << (N / 2); --s) {
			int cost = 0, a_sum = 0, b_sum = 0;
			for (int j = N - 1; j >= N / 2; --j) {
				if ((s & (1l << j)) > 0) {
					a_sum += a[j];
					b_sum += b[j];
					cost += c[j];
				}
			}
			tmp.add(new State(a_sum, b_sum, cost));
		}
		long ans = Long.MAX_VALUE / 16;
		Collections.sort(tmp);
		for (int i = 0; i < tmp.size(); ++i) {
			while (i + 1 < tmp.size() && tmp.get(i).criterion == tmp.get(i + 1).criterion
					&& tmp.get(i).cost >= tmp.get(i + 1).cost)
				++i;
			state2.add(tmp.get(i));
		}
		for (int i = 0; i < state1.size(); ++i) {
			State s1 = state1.get(i);
			int upper = state2.size();
			int lower = -1;
			while (upper - lower > 1) {
				int middle = (upper + lower) / 2;
				if (-state2.get(middle).criterion >= s1.criterion) {
					upper = middle;
				} else {
					lower = middle;
				}
			}
			if (upper < state2.size() && -state2.get(upper).criterion == s1.criterion) {
				ans = Math.min(ans, state2.get(upper).cost + s1.cost);
			}
		}
		if (ans == Long.MAX_VALUE / 16) {
			System.out.println(-1);
		} else {
			System.out.println(ans);
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.function.Consumer;

public class Main {
    private static final Scanner scanner = new Scanner(System.in);
    private static final Consumer<List<String>> consumer = solve();

    public static void main(String[] args) {
        consumer.accept(readInput());
    }

    private static List<String> readInput() {
        final List<String> lineList = new ArrayList<>();
        while (scanner.hasNextLine()) {
            lineList.add(scanner.nextLine());
        }
        return lineList;
    }

    static Consumer<List<String>> solve() {
        return args -> {
            int N = Integer.parseInt(args.get(0).split(" ")[0]);
            int A = Integer.parseInt(args.get(0).split(" ")[1]);
            int B = Integer.parseInt(args.get(0).split(" ")[2]);
            int[][] items = new int[N][3];
            for (int i = 0; i < N; i++) {
                items[i] = Arrays.stream(args.get(1 + i).split(" "))
                        .mapToInt(Integer::parseInt).toArray();
            }

            int[][][] dp = new int[N + 1][401][401];
            for (int[][] a : dp) {
                for (int[] b : a) {
                    Arrays.fill(b, Integer.MAX_VALUE / 2);
                }
            }
            dp[0][0][0] = 0;
            int min = Integer.MAX_VALUE;
            for (int i = 1; i <= N; i++) {
                for (int a = 0; a < 401; a++) {
                    for (int b = 0; b < 401; b++) {
                        if (a >= items[i - 1][0] && b >= items[i - 1][1]) {
                            dp[i][a][b] = Math.min(
                                    dp[i - 1][a][b],
                                    dp[i - 1][a - items[i - 1][0]][b - items[i - 1][1]] + items[i - 1][2]);
                        } else {
                            dp[i][a][b] = dp[i - 1][a][b];
                        }
                        if (a > 0 && A * b == B * a) {
                            min = Math.min(min, dp[i][a][b]);
                        }
                    }
                }
            }

            System.out.println(min == Integer.MAX_VALUE / 2 ? -1 : min);
        };
    }
}

