public class Main {
    public static PrintWriter out;
    public static FastScanner in;

    private void solve(){
        int n = in.nextInt();
        int ma = in.nextInt();
        int mb = in.nextInt();

        int[][] dp = new int[101][101];
        for(int i=0;i<=100;i++){
            Arrays.fill(dp[i],Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for(int i=0;i<n;i++){
            int a = in.nextInt();
            int b = in.nextInt();
            int c = in.nextInt();

            for(int j=0;j<=100-a;j++){
                for(int k=0;k<=100-b;k++){
                    if(dp[j][k]!=Integer.MAX_VALUE){
                        dp[j+a][k+b] = Math.min(dp[j+a][k+b],dp[j][k]+c);
                    }
                }
            }
        }
        int mn = Integer.MAX_VALUE;
        for(int i=0;i<=100;i++){
            for(int j=0;j<=100;j++){
                if(dp[i][j]!=Integer.MAX_VALUE){
                    int g = gcd(i,j);
                    if(g == 0) continue;
                    if(i/g == ma && j/g == mb){
                        mn = Math.min(mn,dp[i][j]);
                    }
                }
            }
        }
        out.print(mn);
    }

    private int gcd(int a ,int b){
        if(b==0) return a;
        return gcd(b,a%b);
    }

    private void runIO() {
        in = new FastScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        solve();
        out.close();
    }
