class Cart{
        ArrayList<Med> cart;
        int cost;
        int Ag,Bg;
        boolean end;
        Cart(){
                this.cart = new ArrayList<Med>();
                this.cost = 0;
                this.Ag = 0;
                this.Bg = 0;
        }
        void buy(Med m){
                this.cart.add(m);
                this.Ag += m.a;
                this.Bg += m.b;
                this.cost += m.c;
        }
        double getP(){
                return (double)Ag / (double)Bg;
        }
        boolean checkCart(int Ma,int Mb){
                boolean ch = Ma * this.Bg == Mb * this.Ag;
                return ch;
        }
        void clearCart(){
                this.cart.clear();
                this.cost = 0;
                this.Ag = 0;
                this.Bg = 0;
        }
}

class Med{
        int a,b,c;
        double getP(){
                return (double)a / (double)b;
        }
}

class Comparator1 implements Comparator<Med>{
        @Override
        public int compare(Med med1,Med med2){
                return Double.compare(med1.getP(),med2.getP());
        }
}

