        if((i == a[0]) && (j == b[0])) {
          dp[0][i][j] = c[0]; 
        } else {
          if((i != 0) || (j != 0)) dp[0][i][j] = 10000;
        }
      }
    }
    for(int n = 1; n < N; n++) {
