			a[i] = Integer.parseInt(str[0]);
			b[i] = Integer.parseInt(str[1]);
			c[i] = Integer.parseInt(str[2]);
		}

		int sa[] = new int[n];
		int sb[] = new int[n];
		int sc[] = new int[n];

		sa[0] = a[0];
		sb[0] = b[0];
		sc[0] = c[0];

		for (int i = 0; i < n - 1; i++) {
			sa[i + 1] = sa[i] + a[i + 1];
			sb[i + 1] = sb[i] + b[i + 1];
			sc[i + 1] = sc[i] + c[i + 1];
		}

		int ans = Integer.MAX_VALUE;
