  public static class Solver {
    public Solver() {

      int N = sc.nextInt();
      int Ma = sc.nextInt();
      int Mb = sc.nextInt();

      Triplet[] tri = new Triplet[N];
      for (int i=0; i<N; i++) {
        tri[i] = new Triplet(sc.nextInt(), sc.nextInt(), sc.nextInt());
      }

      long[][][] dp = new long[N+1][401][401];
      for (int i=0; i<=N; i++) {
        for (int j=0; j<=400; j++) {
          Arrays.fill(dp[i][j], INF);
        }
      }
      dp[0][0][0] = 0;
      for (int i=1; i<=N; i++) {
        for (int j=0; j<=400; j++) {
          for (int k=0; k<=400; k++) {

            if (j-tri[i-1].a >= 0 && k-tri[i-1].b >= 0) {
              dp[i][j][k] = Math.min(dp[i - 1][j][k], dp[i - 1][j - tri[i-1].a][k - tri[i-1].b] + tri[i-1].c);
            } else {
              dp[i][j][k] = dp[i-1][j][k];
            }

          }
        }
      }

      long ans = INF;
      for (int t=1; ;t++) {
        if (Ma*t > 400 || Mb*t > 400) break;
        ans = Math.min(ans, dp[N][Ma*t][Mb*t]);
      }

      out.println(ans == INF ? -1 : ans);

    }

