import java.util.*;

public class Main {

	public static void main(String[] args) {
		new Main().execute();
	}

	public void execute() {
		Scanner sc = new Scanner(System.in);
		final int N = sc.nextInt();
		final int Ma = sc.nextInt();
		final int Mb = sc.nextInt();
		int[][] costTable = new int[N * 10 + 1][N * 10 + 1];
		for (int i = 0; i < costTable.length; i++) {
			for (int j = 0; j < costTable[i].length; j++) {
				costTable[i][j] = Integer.MAX_VALUE;
			}
		}
		HashSet<AB> created = new HashSet<>();
		for (int i = 0; i < N; i++) {
			int ai = sc.nextInt();
			int bi = sc.nextInt();
			int ci = sc.nextInt();
			costTable[ai][bi] = Math.min(costTable[ai][bi], ci);
			AB thisOne = new AB(ai, bi);
			ArrayList<AB> newCreate = new ArrayList<>();
			for (AB ab : created) {
				costTable[ab.a + ai][ab.b + bi] = Math.min(costTable[ab.a + ai][ab.b + bi], costTable[ab.a][ab.b] + ci);
				AB newAB = new AB(ab.a + ai, ab.b + bi);
				if (!created.contains(newAB)) {
					newCreate.add(newAB);
				}
			}
			if (!created.contains(thisOne)) {
				created.add(thisOne);
			}
			for (AB ab : newCreate) {
				created.add(ab);
			}
		}
		int minCost = Integer.MAX_VALUE;
		for (AB ab : created) {
			if (ab.a * Mb == ab.b * Ma) {
				minCost = Math.min(minCost, costTable[ab.a][ab.b]);
			}
		}
		if (minCost == Integer.MAX_VALUE) {
			minCost = -1;
		}

		System.out.println(minCost);
		sc.close();
	}

	class AB {
		public final int a;
		public final int b;

		public AB(int a, int b) {
			this.a = a;
			this.b = b;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			AB other = (AB) obj;
			if (a != other.a)
				return false;
			if (b != other.b)
				return false;
			return true;
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = 1;
			result = prime * result + a;
			result = prime * result + b;
			return result;
		}

	}

}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.function.Consumer;

public class Main {
    private static final Scanner scanner = new Scanner(System.in);
    private static final Consumer<List<String>> consumer = solve();

    public static void main(String[] args) {
        consumer.accept(readInput());
    }

    private static List<String> readInput() {
        final List<String> lineList = new ArrayList<>();
        while (scanner.hasNextLine()) {
            lineList.add(scanner.nextLine());
        }
        return lineList;
    }

    static Consumer<List<String>> solve() {
        return args -> {
            int N = Integer.parseInt(args.get(0).split(" ")[0]);
            int A = Integer.parseInt(args.get(0).split(" ")[1]);
            int B = Integer.parseInt(args.get(0).split(" ")[2]);
            int[][] items = new int[N][3];
            for (int i = 0; i < N; i++) {
                items[i] = Arrays.stream(args.get(1 + i).split(" "))
                        .mapToInt(Integer::parseInt).toArray();
            }

            int[][][] dp = new int[N + 1][401][401];
            for (int[][] a : dp) {
                for (int[] b : a) {
                    Arrays.fill(b, Integer.MAX_VALUE / 2);
                }
            }
            dp[0][0][0] = 0;
            int min = Integer.MAX_VALUE;
            for (int i = 1; i <= N; i++) {
                for (int a = 0; a < 401; a++) {
                    for (int b = 0; b < 401; b++) {
                        if (a >= items[i - 1][0] && b >= items[i - 1][1]) {
                            dp[i][a][b] = Math.min(
                                    dp[i][a][b],
                                    dp[i - 1][a - items[i - 1][0]][b - items[i - 1][1]] + items[i - 1][2]);
                            if (A * b == B * a) {
                                min = Math.min(min, dp[i][a][b]);
                            }
                        }
                    }
                }
            }

            System.out.println(min == Integer.MAX_VALUE / 2 ? -1 : min);
        };
    }
}

