    int[][] dp2 = new int[M + 1][M + 1];
    for (int i = 0; i <= M; i++) for (int j = 0; j <= M; j++) dp1[i][j] = INF;
    dp1[0][0] = 0;
    for (int j = 0; j <= M; j++) System.arraycopy(dp1[j], 0, dp2[j], 0, M + 1);

