class Simple {
    int N, Ma, Mb;
    int[] a, b, c;
    const int INF = 1234567890;
    void Solve() {
        //intput
        N = io.Int;
        Ma = io.Int;
        Mb = io.Int;
        a = new int[N];
        b = new int[N];
        c = new int[N];
        for (int i = 0; i < N; ++i) {
            a[i] = io.Int;
            b[i] = io.Int;
            c[i] = io.Int;
        }
        //cal
        var dp = new int[50, 500, 500];
        for (int i = 0; i < dp.GetLength(0); ++i)
            for (int j = 0; j < dp.GetLength(1); ++j)
                for (int k = 0; k < dp.GetLength(2); ++k)
                    dp[i, j, k] = INF;
        dp[0, 0, 0] = 0;
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < (N+1)*10+1; ++j)
                for (int k = 0; k < (N+1)*10+1; ++k) {
                    if (dp[i, j, k] == INF) continue;
                    //加える
                    dp[i + 1, j + a[i], k + b[i]] =
                        Math.Min(dp[i + 1, j + a[i], k + b[i]], dp[i, j, k] + c[i]);
                    //加えない
                    dp[i + 1, j, k] = Math.Min(dp[i + 1, j, k], dp[i, j, k]);
                }
        int ans = INF;
        for (int j = 1; j < dp.GetLength(1); ++j)
            for (int k = 1; k < dp.GetLength(2); ++k)
                if (j * Mb == k * Ma)
                    ans = Math.Min(ans, dp[N, j, k]);
        //res
