namespace Kujikatsu052.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc054/tasks/abc054_d
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var (n, ma, mb) = inputStream.ReadValue<int, int, int>();
            var half = n / 2;
            var group1 = new Medicine[n - half];
            var group2 = new Medicine[half];

            for (int i = 0; i < group1.Length; i++)
            {
                var (a, b, c) = inputStream.ReadValue<int, int, int>();
                group1[i] = new Medicine(new Quantity(a, b), c);
            }

            for (int i = 0; i < group2.Length; i++)
            {
                var (a, b, c) = inputStream.ReadValue<int, int, int>();
                group2[i] = new Medicine(new Quantity(a, b), c);
            }


            if (n == 1)
            {
                var gcd = NumericalAlgorithms.Gcd(group1[0].Quantity.A, group1[0].Quantity.B);
                if (group1[0].Quantity.A == ma * gcd && group1[0].Quantity.B == mb * gcd)
                {
                    yield return group1[0].Price;
                }
                else
                {
                    yield return -1;
                }
                yield break;
            }

            var sum1 = HalfSum(group1);
            var sum2 = HalfSum(group2);

            Array.Sort(sum1);
            Array.Sort(sum2);

            int minPrice = int.MaxValue;

            foreach (var sum in sum1.Concat(sum2))
            {
                if (Check(sum, ma, mb))
                {
                    minPrice = Math.Min(minPrice, sum.Price);
                }
            }

            var right = sum2.Length - 1;
            for (int left = 0; left < sum1.Length; left++)
            {
                if (Check(sum1[left] + sum2[right], ma, mb))
                {
                    minPrice = Math.Min(minPrice, sum1[left].Price + sum2[right].Price);
                }

                while (right > 0 && CanProceed(sum1[left] + sum2[right - 1], ma, mb))
                {
                    right--;
                    if (Check(sum1[left] + sum2[right], ma, mb))
                    {
                        minPrice = Math.Min(minPrice, sum1[left].Price + sum2[right].Price);
                    }
                }
            }

            if (minPrice < int.MaxValue)
            {
                yield return minPrice;
            }
            else
            {
                yield return -1;
            }
        }

        bool Check(Medicine medicine, int ma, int mb)
        {
            var gcd = NumericalAlgorithms.Gcd(medicine.Quantity.A, medicine.Quantity.B);
            return medicine.Quantity.A == ma * gcd && medicine.Quantity.B == mb * gcd;
        }

        bool CanProceed(Medicine medicine, int ma, int mb)
        {
            var ratio = medicine.Quantity.A * (long)mb;
            var demand = ma * (long)medicine.Quantity.B;
            return ratio >= demand;
        }

        Medicine[] HalfSum(Medicine[] medicines)
        {
            var sum = new Medicine[(1 << medicines.Length) - 1];
            for (int flag = 1; flag < 1 << medicines.Length; flag++)
            {
                var current = new Medicine();
                for (int i = 0; i < medicines.Length; i++)
                {
                    if ((flag & (1 << i)) > 0)
                    {
                        current += medicines[i];
                    }
                }
                sum[flag - 1] = current;
            }
            return sum;
        }

        [StructLayout(LayoutKind.Auto)]
        readonly struct Medicine : IComparable<Medicine>
        {
            public Quantity Quantity { get; }
            public int Price { get; }

            public Medicine(Quantity ratio, int price)
            {
                Quantity = ratio;
                Price = price;
            }

            public static Medicine operator +(Medicine m1, Medicine m2) => new Medicine(m1.Quantity + m2.Quantity, m1.Price + m2.Price);

            public void Deconstruct(out Quantity ratio, out int price) => (ratio, price) = (Quantity, Price);
            public override string ToString() => $"{nameof(Quantity)}: {Quantity}, {nameof(Price)}: {Price}";

            public int CompareTo([AllowNull] Medicine other)
            {
                var comp = Quantity.CompareTo(other.Quantity);
                if (comp != 0)
                {
                    return comp;
                }
                else
                {
                    return Price - other.Price;
                }
            }
        }

        [StructLayout(LayoutKind.Auto)]
        readonly struct Quantity : IComparable<Quantity>
        {
            public int A { get; }
            public int B { get; }

            public Quantity(int a, int b)
            {
                A = a;
                B = b;
            }

            public static Quantity operator +(Quantity r1, Quantity r2) => new Quantity(r1.A + r2.A, r1.B + r2.B);

            public void Deconstruct(out int a, out int b) => (a, b) = (A, B);
            public override string ToString() => $"{nameof(A)}: {A}, {nameof(B)}: {B}";

            public int CompareTo([AllowNull] Quantity other)
            {
                var me = (long)A * other.B;
                var you = (long)other.A * B;
                return Math.Sign(me - you);
            }
        }
    }
