namespace Test01
{
    class Program
    {
        const int INF = 1000000009;
        static void Main(string[] args)
        {
            int[] input = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            int N = input[0];
            int Ma = input[1];
            int Mb = input[2];

            int[] A = new int[N + 1];
            int[] B = new int[N + 1];
            int[] C = new int[N + 1];
            for(int i = 1; i <= N; i++)
            {
                input = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
                A[i] = input[0];
                B[i] = input[1];
                C[i] = input[2];
            }

            int max = 400;
            int[,,] dp = new int[max + 1, max + 1, N + 1];
            for (int a = 0; a <= max; a++) for (int b = 0; b <= max; b++) for (int i = 0; i <= N; i++) dp[a, b, i] = INF;
            for (int i = 0; i <= N; i++) dp[0, 0, i] = 0;

            for(int a = 1; a <= max; a++)
            {
                for(int b = 1; b <= max; b++)
                {
                    for(int i = 1; i <= N; i++)
                    {
                        dp[a, b, i] = Math.Min(dp[a, b, i], dp[a, b, i - 1]);
                        if (a >= A[i] && b >= B[i]) dp[a, b, i] = Math.Min(dp[a, b, i], dp[a - A[i], b - B[i], i - 1] + C[i]);
                    }
                }
            }

            int sa = Ma;
            int sb = Mb;
            int ans;
            List<int> ans_list = new List<int>();
            while(sa <= max && sb <= max)
            {
                if (dp[sa, sb, N] < INF) ans_list.Add(dp[sa, sb, N]);
                sa += Ma;
                sb += Mb;
            }

            ans_list = ans_list.OrderBy(x => x).ToList();
            if (ans_list.Count == 0) ans = -1;
            else ans = ans_list.First();

            Console.WriteLine(ans);
        }
    }
}

