		A = a;
		B = b;
		C = c;
	}
}


public class MedicineSet : IComparable<MedicineSet>
{
	public int Rate { get; private set; } // sum(a) * Mb - sum(b) * Ma
	public int Cost { get; private set; }

	public MedicineSet(int rate, int cost)
	{
		Rate = rate;
		Cost = cost;
	}

	public int CompareTo(MedicineSet x)
	{
		return Rate - x.Rate;
	}
}


public class D
{
	public static void Main()
	{
		int N = GetInt();
		int Ma = GetInt();
		int Mb = GetInt();

		int size1 = Math.Min(N, 20);
		List<Medicine> list1 = new List<Medicine>(size1);
		for(int i = 0; i < size1; i++)
			list1.Add(new Medicine(GetInt(), GetInt(), GetInt()));

		List<MedicineSet> set1 = new List<MedicineSet>(size1);
		for(int s = 1; s < (1 << size1); s++)
		{
			int rate = 0;
			int cost = 0;
			for(int i = 0; i < size1; i++)
			{
				if(((s >> i) & 1) == 0)
					continue;
				rate += list1[i].A * Mb - list1[i].B * Ma;
				cost += list1[i].C;
			}
			set1.Add(new MedicineSet(rate, cost));
		}

		if(size1 == N)
		{
			var canUse = set1.Where(x => x.Rate == 0);
			if(canUse.Count() == 0)
			{
				Console.WriteLine(-1);
				return;
			}
			else
			{
				Console.WriteLine(canUse.Min(x => x.Cost));
				return;
			}
		}

		int size2 = N - size1;
		List<Medicine> list2 = new List<Medicine>(size2);
		for(int i = 0; i < size2; i++)
			list2.Add(new Medicine(GetInt(), GetInt(), GetInt()));
		List<MedicineSet> set2 = new List<MedicineSet>(size2);
		for(int s = 1; s < (1 << size2); s++)
		{
			int rate = 0;
			int cost = 0;
			for(int i = 0; i < size2; i++)
			{
				if(((s >> i) & 1) == 0)
					continue;
				rate += list2[i].A * Mb - list2[i].B * Ma;
				cost += list2[i].C;
			}
			set2.Add(new MedicineSet(rate, cost));
		}
		set2.Sort((x,y) => x.Rate - y.Rate);

		int ans = int.MaxValue;
		foreach(MedicineSet half in set1)
		{
			int index = set2.BinarySearch(new MedicineSet(-half.Rate, -1));
			if(index == -1)
				continue;
			ans = Math.Min(ans, half.Cost + set2[index].Cost);
		}
		if(ans == int.MaxValue)
		{
			Console.WriteLine(-1);
		}
		else
		{
			Console.WriteLine(ans);
		}
	}
}


