	public static void MultiKeySort(this string[] list) => new MultiSorter(list).QuickSort();
	class MultiSorter
	{
		const int MIN = 0;
		string[] a;
		int max;
		public MultiSorter(string[] l) { a = l; max = a.Max(s => s.Length); }
		public void QuickSort() { if (a.Length <= 1) return; QuickSort(0, a.Length, 0); }
		public int At(int i, int z) => z < a[i].Length ? a[i][z] : MIN;
		public int At(string s, int z) => z < s.Length ? s[z] : MIN;
		public void QuickSort(int l, int r, int z)
		{
			int w = r - l, pl = l, pm = l + w / 2, pn = r - 1, c;
			if (w > 30)
			{
				var d = w / 8;
				pl = Median(pl, pl + d, pl + 2 * d, z);
				pm = Median(pm - d, pm, pm + d, z);
				pn = Median(pn - 2 * d, pn - d, pn, z);
			}
			pm = Median(pl, pm, pn, z);
			var s = a[pm]; a[pm] = a[l]; a[l] = s;
			var pivot = At(l, z);
			int i = l + 1, x = l + 1, j = r - 1, y = r - 1;
			while (true)
			{
				while (i <= j && (c = At(i, z) - pivot) <= 0)
				{
					if (c == 0) { if (i != x) { s = a[i]; a[i] = a[x]; a[x] = s; } x++; }
					i++;
				}
				while (i <= j && (c = At(j, z) - pivot) >= 0)
				{
					if (c == 0) { if (j != y) { s = a[j]; a[j] = a[y]; a[y] = s; } y--; }
					j--;
				}
				if (i > j) break;
				s = a[i]; a[i] = a[j]; a[j] = s;
				i++; j--;
			}
			j++; y++;
			var m = Min(x - l, i - x); SwapRegion(l, i - m, m);
			m = Min(y - j, r - y); SwapRegion(i, r - m, m);
			i += l - x;
			j += r - y;
			if (i - l >= 10) QuickSort(l, i, z); else InsertSort(l, i, z);
			if (pivot != MIN) if (j - i >= 10) QuickSort(i, j, z + 1); else InsertSort(i, j, z + 1);
			if (r - j >= 10) QuickSort(j, r, z); else InsertSort(j, r, z);
		}
		private void SwapRegion(int p, int q, int n)
		{
			string s;
			while (n-- > 0) { s = a[p]; a[p++] = a[q]; a[q++] = s; }
		}
		private void InsertSort(int l, int r, int z)
		{
			string s;
			for (int i = l + 1; i < r; i++)
			{
				var tmp = a[i];
				int x = z, y = z, p, q;
				s = a[i - 1];
				while ((p = At(tmp, x++)) == (q = At(s, y++)) && p != MIN) ;
				if (q > p)
				{
					int j = i;
					while (true)
					{
						a[j] = a[j - 1];
						--j;
						if (j <= l) break;
						x = y = z;
						s = a[j - 1];
						while ((p = At(tmp, x++)) == (q = At(s, y++)) && p != MIN) ;
						if (q <= p) break;
					}
					a[j] = tmp;
				}
			}
		}
		private int Median(int a, int b, int c, int z)
		{
			int p = At(a, z), q = At(b, z);
			if (p == q) return a;
			var r = At(c, z);
			if (r == p || r == q) return c;
			return p < q ?
					(q < r ? b : (p < r ? c : a))
					: (q > r ? b : (p < r ? a : c));
		}
	}
}
class RandomSFMT : Random
{
	int index, coin_bits, byte_pos, range, shift;
	uint coin_save, byte_save, bse;
	protected uint[] x = new uint[40];
	static uint[] ParityData = { 0x00000001U, 0x00000000U, 0x00000000U, 0x20000000U };
	public virtual void gen_rand_all()
	{
		int a = 0, b = 28, c = 32, d = 36; uint y; uint[] p = x;
		do
		{
			y = p[a + 3] ^ (p[a + 3] << 24) ^ (p[a + 2] >> 8) ^ ((p[b + 3] >> 5) & 0xb5ffff7fU);
			p[a + 3] = y ^ (p[c + 3] >> 8) ^ (p[d + 3] << 14);
			y = p[a + 2] ^ (p[a + 2] << 24) ^ (p[a + 1] >> 8) ^ ((p[b + 2] >> 5) & 0xaff3ef3fU);
			p[a + 2] = y ^ ((p[c + 2] >> 8) | (p[c + 3] << 24)) ^ (p[d + 2] << 14);
			y = p[a + 1] ^ (p[a + 1] << 24) ^ (p[a] >> 8) ^ ((p[b + 1] >> 5) & 0x7fefcfffU);
			p[a + 1] = y ^ ((p[c + 1] >> 8) | (p[c + 2] << 24)) ^ (p[d + 1] << 14);
			y = p[a] ^ (p[a] << 24) ^ ((p[b] >> 5) & 0xf7fefffdU);
			p[a] = y ^ ((p[c] >> 8) | (p[c + 1] << 24)) ^ (p[d] << 14);
			c = d; d = a; a += 4; b += 4;
			if (b == 40) b = 0;
		} while (a != 40);
	}
	void period_certification()
	{
		uint work, inner = 0; int i, j;
		index = 40; range = 0; coin_bits = 0; byte_pos = 0;
		for (i = 0; i < 4; i++) inner ^= x[i] & ParityData[i];
		for (i = 16; i > 0; i >>= 1) inner ^= inner >> i;
		inner &= 1;
		if (inner == 1) return;
		for (i = 0; i < 4; i++) for (j = 0, work = 1; j < 32; j++, work <<= 1) if ((work & ParityData[i]) != 0) { x[i] ^= work; return; }
	}
	public void InitMt(uint s)
	{
		unchecked
		{
			x[0] = s;
			for (uint p = 1; p < 40; p++) x[p] = s = 1812433253 * (s ^ (s >> 30)) + p;
			period_certification();
		}
	}
	public RandomSFMT(uint s) { InitMt(s); }
	public void InitMtEx(uint[] init_key)
	{
		uint r, i, j, c, key_len = (uint)init_key.Length;
		unchecked
		{
			for (i = 0; i < 40; i++) x[i] = 0x8b8b8b8b;
			if (key_len + 1 > 40) c = key_len + 1; else c = 40;
			r = x[0] ^ x[17] ^ x[39]; r = (r ^ (r >> 27)) * 1664525;
			x[17] += r; r += key_len; x[22] += r; x[0] = r; c--;
			for (i = 1, j = 0; j < c && j < key_len; j++)
			{
				r = x[i] ^ x[(i + 17) % 40] ^ x[(i + 39) % 40];
				r = (r ^ (r >> 27)) * 1664525; x[(i + 17) % 40] += r;
				r += init_key[j] + i; x[(i + 22) % 40] += r;
				x[i] = r; i = (i + 1) % 40;
			}
			for (; j < c; j++)
			{
				r = x[i] ^ x[(i + 17) % 40] ^ x[(i + 39) % 40];
				r = (r ^ (r >> 27)) * 1664525; x[(i + 17) % 40] += r; r += i;
				x[(i + 22) % 40] += r; x[i] = r; i = (i + 1) % 40;
			}
			for (j = 0; j < 40; j++)
			{
				r = x[i] + x[(i + 17) % 40] + x[(i + 39) % 40];
				r = (r ^ (r >> 27)) * 1566083941; x[(i + 17) % 40] ^= r;
				r -= i; x[(i + 22) % 40] ^= r; x[i] = r; i = (i + 1) % 40;
			}
			period_certification();
		}
	}
	public RandomSFMT(uint[] init_key) { InitMtEx(init_key); }
	public RandomSFMT() : this((uint)(DateTime.Now.Ticks & 0xffffffff)) { }
	public uint NextMt() { if (index == 40) { gen_rand_all(); index = 0; } return x[index++]; }
	public int NextInt(int n) => (int)(n * (1.0 / 4294967296.0) * NextMt());
	public double NextUnif() { uint z = NextMt() >> 11, y = NextMt(); return (y * 2097152.0 + z) * (1.0 / 9007199254740992.0); }
	public int NextBit() { if (--coin_bits == -1) { coin_bits = 31; return (int)(coin_save = NextMt()) & 1; } else return (int)(coin_save >>= 1) & 1; }
	public int NextByte() { if (--byte_pos == -1) { byte_pos = 3; return (int)(byte_save = NextMt()) & 255; } else return (int)(byte_save >>= 8) & 255; }
	public override int Next(int maxValue) => Next(0, maxValue);
	protected override double Sample() => NextUnif();
	public override double NextDouble() => NextUnif();
	public override int Next() => 1 + NextIntEx(int.MaxValue);
	public override void NextBytes(byte[] buffer) { for (var i = 0; i < buffer.Length; i++) buffer[i] = (byte)NextByte(); }
	public override int Next(int min, int max) => min + NextIntEx(max - min);
	public int NextIntEx(int range_)
	{
		uint y_, base_, remain_; int shift_;
		if (range_ <= 0) return 0;
		if (range_ != range)
		{
			bse = (uint)(range = range_);
			for (shift = 0; bse <= (1UL << 30); shift++) bse <<= 1;
		}
		while (true)
		{
			y_ = NextMt() >> 1;
			if (y_ < bse) return (int)(y_ >> shift);
			base_ = bse; shift_ = shift; y_ -= base_;
			remain_ = (1U << 31) - base_;
			for (; remain_ >= (uint)range_; remain_ -= base_)
			{
				for (; base_ > remain_; base_ >>= 1) shift_--;
				if (y_ < base_) return (int)(y_ >> shift_);
				else y_ -= base_;
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Text;
using System.Linq;

class Program
{
    public void Proc()
    {
        Reader.IsDebug = false;
        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();

        int yakuCount = inpt[0];
        this.GoalA = inpt[1];
        this.GoalB = inpt[2];

        for (int i = 0; i < yakuCount; i++)
        {
            this.YakuList.Add(new Yakuhin(Reader.ReadLine()));
        }
        int ans = GetAns(0, 0, 0);
        Console.WriteLine(ans);
    }
    private Dictionary<int, Dictionary<int, Dictionary<int, int>>> dic = new Dictionary<int, Dictionary<int, Dictionary<int, int>>>();
    private int GetAns(int idx, int totalA, int totalB)
    {

        if (totalA % GoalA == 0 && totalB % GoalB == 0)
        {
            if (totalA > 0 && totalB > 0 && totalA / GoalA == totalB / GoalB)
            {
                return 0;
            }
        }
        if (idx >= this.YakuList.Count)
        {
            return -1;
        }

        if (!dic.ContainsKey(idx))
        {
            dic.Add(idx, new Dictionary<int, Dictionary<int, int>>());
        }
        if (!dic[idx].ContainsKey(totalA))
        {
            dic[idx].Add(totalA, new Dictionary<int, int>());
        }

        if (dic[idx][totalA].ContainsKey(totalB))
        {
            return dic[idx][totalA][totalB];
        }
        int ans = int.MaxValue;

        int ret = this.GetAns(idx + 1, totalA, totalB);
        if (ret >= 0)
        {
            ans = ret;
        }
        ret = this.GetAns(idx + 1, totalA + this.YakuList[idx].A, totalB + this.YakuList[idx].B);
        if (ret >= 0)
        {
            ans = Math.Min(ans, ret + this.YakuList[idx].Cost);
        }
        if (ans == int.MaxValue)
        {
            ans = -1;
        }
        dic[idx][totalA][totalB] = ans;
        return ans;
    }


    private int GoalA;
    private int GoalB;
    private List<Yakuhin> YakuList = new List<Yakuhin>();

    public class Yakuhin
    {
        public int A;
        public int B;
        public int Cost;

        public Yakuhin(string inpt)
        {
            int[] tmp = inpt.Split(' ').Select(a => int.Parse(a)).ToArray();
            this.A = tmp[0];
            this.B = tmp[1];
            this.Cost = tmp[2];
        }
    }

    public class Reader
    {
        public static bool IsDebug = true;
        private static String PlainInput = @"



1 1 10
10 10 10



";
        private static System.IO.StringReader Sr = null;
        public static string ReadLine()
        {
            if (IsDebug)
            {
                if (Sr == null)
                {
                    Sr = new System.IO.StringReader(PlainInput.Trim());
                }
                return Sr.ReadLine();
            }
            else
            {
                return Console.ReadLine();
            }
        }
    }
    static void Main()
    {
        Program prg = new Program();
        prg.Proc();
    }
}

using System;
class Program{
	static void Main(){
		int[] s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		int[][] arr=new int[s[0]+1][];
		int m1=0,m2=0,ans=int.MaxValue;
		for(int i=1;i<=s[0];i++){
			arr[i]=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
			m1+=arr[i][0];
			m2+=arr[i][1];
		}
		int[,,] dp=new int[s[0]+1,m1+1,m2+1];
		for(int i=0;i<=s[0];i++){
			for(int j=0;j<=m1;j++){
				for(int k=0;k<=m2;k++){dp[i,j,k]=9999;}
			}
			dp[i,0,0]=0;
		}
		for(int i=1;i<=s[0];i++){
			for(int j=1;j<=m1;j++){
				for(int k=1;k<=m2;k++){
					if(j>=arr[i][0]&&k>=arr[i][1]){dp[i,j,k]=Math.Min(dp[i-1,j-arr[i][0],k-arr[i][1]]+arr[i][2],dp[i-1,j,k]);}
					else{dp[i,j,k]=dp[i-1,j,k];}
				}
			}
		}
		for(int i=s[1],j=s[2];i<=m1&&j<=m2;i+=s[1],j+=s[2]){ans=Math.Min(ans,dp[s[0],i,j]);}
		ans=ans==9999?-1:ans;
		Console.WriteLine("{0}",ans);
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static int N;
    static int Ma, Mb;
    static int[] a;
    static int[] b;
    static int[] c;
    public static void Main(string[] args)
    {
        checked
        {
            N = Input.NextInt();
            Ma = Input.NextInt();
            Mb = Input.NextInt();

            var gcd = (int)MathLib.Gcd(Ma, Mb);
            Ma /= gcd;
            Mb /= gcd;

            a = new int[N];
            b = new int[N];
            c = new int[N];

            for (int i = 0; i < N; i++)
            {
                var s = Input.LineInt();
                a[i] = s[0];
                b[i] = s[1];
                c[i] = s[2];
            }

            var maxa = a.Sum();
            var maxb = b.Sum();

            DPs = new Dictionary<Tuple<int, int, int>, int>();

            int minCost = BigValue;
            for (int i = 1; ; i++)
            {
                var mma = Ma * i;
                var mmb = Mb * i;
                if (mma > maxa)
                    break;
                if (mmb > maxb)
                    break;

                var cost = DP(N, mma, mmb);
                minCost = Math.Min(minCost, cost);
            }

            if (minCost == BigValue)
                minCost = -1;

            Console.WriteLine(minCost);
        }
    }

    public const int BigValue = int.MaxValue / 2;

    static Dictionary<Tuple<int, int, int>, int> DPs;

    static int DP(int i, int ca, int cb)
    {
        if (i == 0)
        {
            if (ca == 0 && cb == 0)
                return 0;
            else
                return BigValue;
        }

        var key = new Tuple<int, int, int>(i, ca, cb);
        if (DPs.ContainsKey(key))
            return DPs[key];

        int cost1;
        {
            var key1 = new Tuple<int, int, int>(i - 1, ca, cb);
            if (DPs.ContainsKey(key1))
                cost1 = DPs[key1];
            else
            {
                cost1 = DP(i - 1, ca, cb);
            }
        }

        int cost2;
        {
            var mca = ca - a[i - 1];
            var mcb = cb - b[i - 1];
            if (mca < 0 || mcb < 0)
            {
                cost2 = BigValue;
            }
            else
            {
                var key2 = new Tuple<int, int, int>(i - 1, mca, mcb);
                if (DPs.ContainsKey(key2))
                    cost2 = DPs[key2];
                else
                {
                    cost2 = DP(i - 1, mca, mcb) + c[i - 1];
                }
            }
        }

        var cost = Math.Min(cost1, cost2);
        DPs[key] = cost;
        return cost;
    }
}

public class MathLib
{
    /// <summary>
    /// 最大公約数を求める
    /// </summary>
    /// <param name="a"></param>
    /// <param name="b"></param>
    /// <returns></returns>
    public static long Gcd(long a, long b)
    {
        return (a < b) ? Gcd(b, a)
             : (b > 0) ? Gcd(b, a % b)
                       : a;
    }

    /// <summary>
    /// 最小公倍数を求める
    /// </summary>
    /// <param name="a"></param>
    /// <param name="b"></param>
    /// <returns></returns>
    public static long Lcm(long a, long b)
    {
        return a / Gcd(a, b) * b;
    }

    /// <summary>
    /// 約数を列挙する。返される順序は一様では<b>ない</b>。
    /// </summary>
    /// <param name="n">約数を求める数字</param>
    /// <returns><paramref name="n"/> の約数の列挙</returns>
    public static IEnumerable<int> GetDivisors(int n)
    {
        for (int i = 1; i < (int)Math.Sqrt(n) + 1; i++)
        {
            if ((n % i) == 0)
            {
                yield return i;
                if (i != n / i)
                {
                    yield return n / i;
                }
            }
        }
        yield break;
    }
}

