    {
        internal int A;
        internal int B;
        internal int C;
    }

    static void Main()
    {
        checked {
            List<string> InputList = GetInputList();

            int[] wkArr = { };
            Action<string> SplitAct = pStr =>
                wkArr = pStr.Split(' ').Select(X => int.Parse(X)).ToArray();

            SplitAct(InputList[0]);
            int MA = wkArr[1];
            int MB = wkArr[2];

