            {
                Ta = ta;
                Tb = tb;
                Tc = tc;
            }

            public Status(Status st) 
                : this(st.Ta, st.Tb, st.Tc) { }
        }

        static void Main(string[] args)
        {
            string[] bufs = Console.ReadLine().Split(' ');
            N = Int32.Parse(bufs[0]);
            Ma = Int32.Parse(bufs[1]);
            Mb = Int32.Parse(bufs[2]);

            a = new int[N];
            b = new int[N];
            c = new int[N];

            int res = Limit;

            for (int i = 0; i < N; i++)
            {
                bufs = Console.ReadLine().Split(' ');
                a[i] = Int32.Parse(bufs[0]);
                b[i] = Int32.Parse(bufs[1]);
                c[i] = Int32.Parse(bufs[2]);
            }

            Status def = new Status(0, 0, 0);
            for (int i = 0; i < N; i++)
            {
                int temp = Purchase(def, i, res);
                if (res > temp) { res = temp; }
            }

            Console.WriteLine((res > 4000) ? -1 : res);
            return;
        }

        static int Purchase(Status st, int item, int resR)
        {
            int resP = Limit;
            Status stat = new Status(st);
            stat.Ta += a[item];
            stat.Tb += b[item];
            stat.Tc += c[item];

            if (stat.Tc > resR) { return Limit; }

            if ((stat.Ta * Mb) == (stat.Tb * Ma))
            {
                resP = stat.Tc;
            }
            else
            {
                for (int i = item + 1; i < N; i++)
                {
                    int resQ = Purchase(stat, i, resR);
                    if (resP > resQ) { resP = resQ; }
                }
            }

            return resP;
        }
    }

