            c[i] = Cin.NextInt();
        }
    }

    public void Solve()
    {
        Scan();
        int[,,] dp;
        int asum = a.Sum();
        int bsum = b.Sum();
        dp = new int[asum + 1, bsum + 1,N+1];
        for (int i = 0; i <asum; i++)
        {
