        dp[0, 0, 0] = 0;
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j <= asum; j++)
            {
                for (int k = 0; k <= bsum; k++)
                {
                    if (dp[j, k, i] != int.MaxValue)
                    {
                        dp[j, k, i + 1] = Math.Min(dp[j, k, i], dp[j, k, i + 1]);
                        if (j + a[i] >= asum || k + b[i] >= bsum) continue;
                        dp[j + a[i], k + b[i], i + 1] = Math.Min(dp[j + b[i], k + b[i], i + 1], dp[j, k, i] + c[i]);
