            c = f;
        }
    }*/


    //半分全列挙
    void Solve()
    {
        int N = cin.Nextint;
        int M = cin.Nextint;
        int L = cin.Nextint;
        var A = new int[N];
        var B = new int[N];
        var C = new int[N];
        for (int i = 0; i < N; i++)
        {
            var T = cin.Scanint;
            A[i] = T[0];
            B[i] = T[1];
            C[i] = T[2];
        }
        int z = N / 2;

        var G = new Dictionary<int, int>();//Keyは負の可能性があるので。

        for (int i = 0; i < 1 << z; i++)
        {
            int aa = 0, bb = 0, cc = 0;
            for (int j = 0; j < z; j++)
            {
                if ((i >> j & 1) == 1)
                {
                    aa += A[j];
                    bb += B[j];
                    cc += C[j];
                }
            }
            int y = bb * M - aa * L;
            if (G.ContainsKey(y))
            {
                G[y] = Math.Min(G[y], cc);
            }
            else
            {
                G[y] = cc;
            }
        }

        int ans = int.MaxValue;
        for (int i = 0; i < 1 << (N - z); i++)
        {
            int aa = 0, bb = 0, cc = 0;
            for (int j = 0; j < N - z; j++)
            {
                if ((i >> j & 1) == 1)
                {
                    aa += A[j + z];
                    bb += B[j + z];
                    cc += C[j + z];
                }
            }
            int y = L * aa - M * bb;
            if (G.ContainsKey(y))
            {
                int cost = G[y] + cc;
                if (cost != 0)
                {
                    ans = Math.Min(cost, ans);
                }
            }
        }
        if (ans == int.MaxValue)
        {
            WriteLine(-1);
            return;
        }
        WriteLine(ans);
    }

}

