            }

            // 半分全列挙
            var first = meds.Take(N / 2).ToArray();
            var last = meds.Skip(N / 2).ToArray();

            var bf = BitSearch(first.Length);
            var lf = BitSearch(last.Length);

            int[,] min = new int[401, 401];
            for (int i = 0; i < 401; i++)
            {
                for (int j = 0; j < 401; j++)
                {
                    min[i, j] = int.MaxValue / 2;
                }
            }

            foreach (var b in bf)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                foreach (var b_ in b)
                {
                    suma += first[b_].a;
                    sumb += first[b_].b;
                    sumc += first[b_].c;
                }
                min[suma, sumb] = Math.Min(min[suma, sumb], sumc);
            }

            int ans = int.MaxValue;
            foreach (var l in lf)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                foreach (var l_ in l)
                {
                    suma += last[l_].a;
                    sumb += last[l_].b;
                    sumc += last[l_].c;
                }

                for (int i = 0; i < canda.Count; i++)
                {
                    int rema = canda[i] - suma;
                    int remb = candb[i] - sumb;
                    if (rema < 0 || remb < 0) continue;
                    int cand = sumc + min[rema, remb];
                    ans = Math.Min(ans, cand);
                }
            }

            if (ans == int.MaxValue / 2) ans = -1;
