public class D
{
	public static void Main()
	{
		int N = GetInt();
		int Ma = GetInt();
		int Mb = GetInt();
		int[] a = new int[N+1];
		int[] b = new int[N+1];
		int[] c = new int[N+1];
		int sumA = 0;
		int sumB = 0;
		for(int i = 1; i <= N; i++)
		{
			a[i] = GetInt();
			sumA += a[i];
			b[i] = GetInt();
			sumB += b[i];
			c[i] = GetInt();
		}

		int[,,] dp = new int[N+1, sumA + 1, sumB + 1];
		for(int i = 0; i <= N; i++)
			for(int ca = 0; ca <= sumA; ca++)
				for(int cb = 0; cb <= sumB; cb++)
					dp[i, ca, cb] = 1000000;
		dp[0,0,0] = 0;
		for(int i = 1; i <= N; i++)
		{
			for(int ca = 0; ca <= sumA; ca++)
			{
				for(int cb = 0; cb <= sumB; cb++)
				{
					dp[i, ca, cb] = Math.Min(dp[i, ca, cb], dp[i-1, ca, cb]);

					if((ca + a[i] > sumA) || (cb + b[i] > sumB))
						continue;
					dp[i, ca + a[i], cb + b[i]] = 
						Math.Min(
							dp[i, ca + a[i], cb + b[i]],
							dp[i-1, ca, cb] + c[i]);
				}
			}
		}

		int ans = int.MaxValue;
		for(int ca = 1; ca <= sumA; ca++)
		{
			for(int cb = 1; cb <= sumB; cb++)
			{
				if((ca * Mb != cb * Ma))
					continue;
				ans = Math.Min(ans, dp[N,ca,cb]);
			}
		}

		Console.WriteLine((ans >= 1000000) ? -1 : ans);
	}
}


