            var dp = Enumerable.Repeat(0, N + 1).Select(s => CreateJaggedArray(limit + 1, limit + 1, 10000)).ToArray();
            dp[0][0][0] = 0;
            for (int i = 0; i < N; i++)
            {
                int a, b, c;
                Multi(out a, out b, out c);
                for (int j = 0; j < limit; j++)
                {
                    for (int k = 0; k < limit; k++)
                    {
                        dp[i + 1][j][k] = Math.Min(dp[i][j][k], (j - a < 0 || k - b < 0) ? 10000 : dp[i][j - a][k - b] + c);
                    }
                }
            }

            var min = 10000;
            for(int i = 1; i <= limit; i++)
            {
                for(int j = 1; j <= limit; j++)
