using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Text;

class Prog
{
    public Prog() { }
    public static int Main()
    {
        new Prog().calc();
        return 0;
    }

    Scanner cin;

    const int max_N = 40;
    const int max_a = 10;
    const int max_c = 100;
    const int INF = 100 * max_c * max_N;

    public void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int Ma = cin.nextInt();
        int Mb = cin.nextInt();

        int[] a = new int[N];
        int[] b = new int[N];
        int[] c = new int[N];

        for(int i = 0;i<N;i++)
        {
            a[i] = cin.nextInt();
            b[i] = cin.nextInt();
            c[i] = cin.nextInt();
        }

        // dp[i][ca][cb] := 1からi番目までの薬品の組み合わせで,物質Aがcaグラム、物質Bがcbグラムとなる
        //                  溶液の最小のコスト

        int[,,] dp = new int[max_N + 1, (max_a + 1) * max_c + 1, max_a * (max_c + 1) + 1];
        for (int i = 0; i < max_N + 1; i++)
            for (int ca = 0; ca < (max_a + 1) * max_c + 1; ca++)
                for (int cb = 0; cb < max_a * (max_c + 1) + 1; cb++)
                    dp[i, ca, cb] = INF;

        dp[0, 0, 0] = 0;

        for (int i = 0; i < N; i++)
        {
            for (int ca = 0; ca < max_a * max_c; ca++)
            {
                for (int cb = 0; cb < max_a * max_c; cb++)
                {
                    if (dp[i, ca, cb] == INF) continue;
                    dp[i + 1, ca, cb] = Math.Min(dp[i + 1, ca, cb], dp[i, ca, cb]);
                    dp[i + 1, ca + a[i], cb + b[i]] = Math.Min(dp[i + 1, ca + a[i], cb + b[i]]
                                                           , dp[i, ca, cb] + c[i]);
                }
            }
        }

        int ans = INF;
        for(int ca = 1;ca< max_a * max_c;ca++)
            for (int cb = 1; cb < max_a * max_c; cb++)
            {
                if (ca * Mb == cb * Ma) ans = Math.Min(ans, dp[N, ca, cb]);
            }

        if (ans == INF) ans = -1;
        Console.WriteLine(ans);
}


    class Scanner
    {
        string[] s;
        int i;

        char[] cs = new char[] { ' ' };

        public Scanner()
        {
            s = new string[0];
            i = 0;
        }

        public string next()
        {
            if (i < s.Length) return s[i++];
            string st = Console.ReadLine();
            while (st == "") st = Console.ReadLine();
            s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
            i = 0;
            return s[i++];
        }

        public int nextInt()
        {
            return int.Parse(next());
        }

        public long nextLong()
        {
            return long.Parse(next());
        }

        public double nextDouble()
        {
            return double.Parse(next());
        }
    }
}

