using System;
using System.Collections.Generic;
using System.Text;

struct Chemical
{
    public int a;
    public int b;
    public int c;
}
class Program
{
    int N;
    int Ma;
    int Mb;
    int Price;

    public static int Main()
    {
        bool loop = false;
#if ES_DEBUG
        loop = true;
#endif
        do
        {
            new Program().solve();
        } while (loop);
        return 0;
    }
    void calc(Chemical[] chem, int A, int B, int C, int depth)
    {
        if (depth >= N) return;

        calc(chem, A, B, C, depth + 1);

        if (C + chem[depth].c < Price)
        {
            if ((A + chem[depth].a) * Mb == (B + chem[depth].b) * Ma)
            {
                Price = C + chem[depth].c;
            }
            else
            {
                calc(chem, A + chem[depth].a, B + chem[depth].b, C + chem[depth].c, depth + 1);
            }
        }
    }
    public void solve()
    {
        string[] str = Console.ReadLine().Split(' ');
        N = int.Parse(str[0]);
        Ma = int.Parse(str[1]);
        Mb = int.Parse(str[2]);

        Chemical[] chem = new Chemical[N];
        for (int i = 0; i < N; ++i)
        {
            str = Console.ReadLine().Split(' ');
            chem[i].a = int.Parse(str[0]);
            chem[i].b = int.Parse(str[1]);
            chem[i].c = int.Parse(str[2]);
        }

        Price = 10000;
        calc(chem, 0, 0, 0, 0);
        if (Price == 10000)
        {
            Console.WriteLine(-1);
        }
        else
        {
            Console.WriteLine(Price);
        }
    }
}

