                for (int i = 0; i < 400; i++)
                {
                    for (int j = 0; j < 400; j++)
                    {
                        dp[i + a, j + b, k + 1] = dp[i, j, k] + c;
                        dp[i+1, j, k + 1] = dp[i, j, k];
                    }
                }
            }
