            for(int i = 0; i < nab[0]; i++)
            {
                abcs[i] = ReadInts();
            }
            var abGrid = new int[401,401];//a,bとなる最小の料金
            for(int i = 0; i <= 400; i++)
            {
                for(int j = 0; j <= 400; j++)
                {
                    abGrid[i, j] = int.MaxValue;
                }
            }
            var posDict = new Dictionary<int, Dictionary<int, bool>>();
            abGrid[0, 0] = 0;
            posDict.Add(0, new Dictionary<int, bool>());
            posDict[0].Add(0, true);
            for(int i = 0; i < nab[0]; i++)
            {
                var tempDict = new Dictionary<int, Dictionary<int, bool>>();
                foreach(int a in posDict.Keys)
                {
                    foreach (int b in posDict[a].Keys)
                    {
                        int v = abGrid[a, b] + abcs[i][2];
                        int newA = a + abcs[i][0];
                        int newB = b + abcs[i][1];
                        abGrid[newA, newB] = Math.Min(v, abGrid[newA, newB]);
                        if (!tempDict.ContainsKey(newA))
                        {
                            tempDict.Add(newA, new Dictionary<int, bool>());
                        }
                        tempDict[newA].Add(newB, true);
                    }
                }
                foreach(int a in tempDict.Keys)
                {
                    if (!posDict.ContainsKey(a))
                    {
                        posDict.Add(a, new Dictionary<int, bool>());
                    }
                    foreach(int b in tempDict[a].Keys)
                    {
                        if (!posDict[a].ContainsKey(b))
                        {
                            posDict[a].Add(b, true);
                        }
                    }
                }
            }

            int res = int.MaxValue;
            for(int i = 1; i <= Math.Min(400 / nab[1], 400 / nab[2]); i++)
            {
                res = Math.Min(res, abGrid[nab[1] * i, nab[2] * i]);
            }
            if (res == int.MaxValue)
            {
                Console.WriteLine(-1);
            }
            else
            {
                Console.WriteLine(res);
            }
        }

