                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        suma += first[i].a;
                        sumb += first[i].b;
                        sumc += first[i].c;
                    }
                }
                min[suma, sumb] = Math.Min(min[suma, sumb], sumc);
            }

            int ans = int.MaxValue / 2;
            n = last.Length;
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                int suma = 0;
                int sumb = 0;
