class Program
{
    static void Main(string[] args)
    {
        const int MAX_G = 401;
        int N, MA, MB;
        int[] A = new int[40];
        int[] B = new int[40];
        int[] C = new int[40];
        int[,] G = new int[MAX_G, MAX_G];
        const int NIL = 999999;

        string[] values = Console.ReadLine().Split(' ');
        N = int.Parse(values[0]);
        MA = int.Parse(values[1]);
        MB = int.Parse(values[2]);

        for (int i = 0; i < N; i++)
        {
            string[] vals = Console.ReadLine().Split(' ');
            A[i] = int.Parse(vals[0]);
            B[i] = int.Parse(vals[1]);
            C[i] = int.Parse(vals[2]);
        }

        for (int a = 0; a < MAX_G; a++)
            for (int b = 0; b < MAX_G; b++)
            {
                G[a, b] = NIL;
            }
        G[0, 0] = 0;

        for (int i = 0; i < N; i++)
        {
            for (int a = MAX_G - 1; a >= 0; a--)
                for (int b = MAX_G - 1; b >= 0; b--)
                {
                    if (G[a, b] != NIL)
                    {
                        int aa = a + A[i];
                        int bb = b + B[i];
                        G[aa, bb] = Math.Min(G[aa, bb], G[a, b] + C[i]);
                    }
                }
        }

        int ret = NIL;
        int ma = MA;
        int mb = MB;
        while (true)
        {
            ret = Math.Min(G[ma, mb], ret);

            ma += MA;
            mb += MB;
            if (ma >= MAX_G || mb >= MAX_G) break;
        }

        if (ret == NIL) ret = -1;
        Console.WriteLine(ret);

    }
}

