public static class MyBinarySearch
{
	public static int LowerBound<T>(
		this List<T> list, int first, int end, T value, IComparer<T> comparer)
	{
		int low = first;
		int high = end;
		while(low < high)
		{
			int mid = ((high - low) >> 1) + low;
			if(comparer.Compare(list[mid], value) < 0)
				low = mid + 1;
			else
				high = mid;
		}
		return low;
	}

	public static int LowerBound<T>(this List<T> list, T value)
	{
		return list.LowerBound(0, list.Count, value, Comparer<T>.Default);
	}

	public static int UpperBound<T>(
		this List<T> list, int first, int end, T value, IComparer<T> comparer)
	{
		int low = first;
		int high = end;
		while(low < high)
		{
			int mid = ((high - low) >> 1) + low;
			if(comparer.Compare(list[mid], value) <= 0)
				low = mid + 1;
			else
				high = mid;
		}
		return low;
	}

	public static int UpperBound<T>(this List<T> list, T value)
	{
		return list.UpperBound(0, list.Count, value, Comparer<T>.Default);
	}
}


