class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int Ma = cin.nextInt();
        int Mb = cin.nextInt();
        int[] a = new int[N];
        int[] b = new int[N];
        int[] c = new int[N];
        int[] d = new int[N];
        for (int i = 0; i < N; i++)
        {
            a[i] = cin.nextInt();
            b[i] = cin.nextInt();
            c[i] = cin.nextInt();
            d[i] = a[i] * Mb - b[i] * Ma;
        }

        int DMAX = 10000;
        int MAX = int.MaxValue / 2;
        int[] dp = new int[DMAX];
        for (int i = 0; i < DMAX; i++)
        {
            dp[i] = MAX;
        }

        for (int i = 0; i < N; i++)
        {
            if (d[i] < 0)
            {
                for (int j = 0; j < DMAX; j++)
                {
                    int start = dp[j];
                    if (j == DMAX / 2) start = 0;
                    if (start == MAX) continue;

                    int next = j + d[i];
                    int ncost = start + c[i];

                    dp[next] = Math.Min(dp[next], ncost);
                }
            }
            else
            {
                for (int j = DMAX - 1; j >= 0; j--)
                {
                    int start = dp[j];
                    if (j == DMAX / 2) start = 0;
                    if (start == MAX) continue;

                    int next = j + d[i];
                    int ncost = start + c[i];

                    dp[next] = Math.Min(dp[next], ncost);
                }
            }
        }

