    class Program
    {
        static void Main(string[] args)
        {
            int N = RInt;
            int Ma = RInt;
            int Mb = RInt;

            List<int> canda = new List<int>();
            List<int> candb = new List<int>();
            int sa = Ma;
            int sb = Mb;
            while (sa <= 400 && sb <= 400)
            {
                canda.Add(sa);
                candb.Add(sb);
                sa += Ma;
                sb += Mb;
            }

            Med[] meds = new Med[N];
            for (int i = 0; i < N; i++)
            {
                int a = RInt;
                int b = RInt;
                int c = RInt;
                meds[i] = new Med { a = a, b = b, c = c };
            }

            // 半分全列挙
            int count = N / 2;
            if (N > 30) count = N / 2 + 2;

            var first = meds.Take(count).ToArray();
            var last = meds.Skip(count).ToArray();

            var bf = BitSearch(first.Length);
            var lf = BitSearch(last.Length);

            int[,] min = new int[401, 401];
            for (int i = 0; i < 401; i++)
            {
                for (int j = 0; j < 401; j++)
                {
                    min[i, j] = int.MaxValue / 2;
                }
            }

            foreach (var b in bf)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                foreach (var b_ in b)
                {
                    suma += first[b_].a;
                    sumb += first[b_].b;
                    sumc += first[b_].c;
                }
                min[suma, sumb] = Math.Min(min[suma, sumb], sumc);
            }

            int ans = int.MaxValue;
            foreach (var l in lf)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                foreach (var l_ in l)
                {
                    suma += last[l_].a;
                    sumb += last[l_].b;
                    sumc += last[l_].c;
                }

                for (int i = 0; i < canda.Count; i++)
                {
                    int rema = canda[i] - suma;
                    int remb = candb[i] - sumb;
                    if (rema < 0 || remb < 0) continue;
                    int cand = sumc + min[rema, remb];
                    ans = Math.Min(ans, cand);
                }
            }

            if (ans == int.MaxValue / 2) ans = -1;
            Console.WriteLine(ans);

        }

        public static int[][] BitSearch(int n)
        {
            int[][] ret = new int[1 << n][];
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                List<int> S = new List<int>();
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        S.Add(i);
                    }
                }

                ret[bit] = S.ToArray();
            }
            return ret;
        }

        struct Med
        {
            public int a;
            public int b;
            public int c;
        }
    }


