    {
        var aaa = A.Sum();
        var bbb = B.Sum();
        var dp = new int[N + 1, aaa, bbb];
        for (int i = 0; i <= N; i++)
            for (int a = 0; a < aaa; a++)
                for (int b = 0; b < bbb; b++)
                    dp[i,a,b] = INF;
        dp[0, 0, 0] = 0;

        for (int i = 0; i < N; i++)
        {
            for (int a = 0; a < aaa; a++)
            {
                for (int b = 0; b < bbb; b++)
                {
                    dp[i + 1, a , b] = Math.Min(dp[i + 1, a, b], dp[i, a, b]);
                    if (a + A[i] < aaa && b + B[i] < bbb)
                    dp[i + 1, a + A[i], b + B[i]] = Math.Min(dp[i + 1, a + A[i], b + B[i]], dp[i, a, b] + C[i]);
