using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Formatters.Binary;

public static class Program {
    private const int MAX = 10000000;

    public static void Main() {
        #region SetAutoFlushIsFalse
#if !DEBUG
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
#endif
        #endregion
        try {

            var nmm = ReadLib.ReadAsIntArray();
            var drugs = Enumerable
                .Repeat(0, nmm[0])
                .Select(d => Drug.Create(ReadLib.ReadAsIntArray()))
                .ToArray();

            var maxA = drugs.Sum(a => a.A);
            var maxB = drugs.Sum(b => b.B);

            var dp = new int[nmm[0] + 1, maxA + 1, maxB + 1];

            for (int i = 0; i <= nmm[0]; i++) {
                for (int j = 0; j <= maxA; j++) {
                    for (int k = 0; k <= maxB; k++) {
                        dp[i, j, k] = MAX;
                    }
                }
            }

            for (int n = 1; n <= nmm[0]; n++) {
                var curDrug = drugs[n - 1];
                for (int a = 1; a <= maxA; a++) {
                    for (int b = 1; b <= maxB; b++) {
                        var cand = new List<int>();
                        cand.Add(dp[n - 1, a, b]);

                        if (a == curDrug.A && b == curDrug.B) {
                            cand.Add(curDrug.Cost);
                        }

                        if (a >= curDrug.A && b >= curDrug.B) {
                            cand.Add(dp[n - 1, a - curDrug.A, b - curDrug.B] + curDrug.Cost);
                        }

                        dp[n, a, b] = cand.Min();
                    }
                }
            }

            var resultCand = new List<int>();
            var mA = nmm[1];
            var mB = nmm[2];
            var pA = mA;
            var pB = mB;
            while(pA <= maxA && pB <= maxB) {
                resultCand.Add(dp[nmm[0], pA, pB]);
                pA += mA;
                pB += mB;
            }
            var r = resultCand.Min();
            Console.WriteLine(r == MAX ? -1 : r);

        } finally {
            #region Flush
#if !DEBUG
        Console.Out.Flush();
        sw.Close();
#endif
            #endregion
        }
    }

    private class Drug {
        public Drug(int[] arr) {
            this.A = arr[0];
            this.B = arr[1];
            this.Cost = arr[2];
        }

        public int A { get; }
        public int B { get; }
        public int Cost { get; }

        internal static Drug Create(int[] arr) {
            return new Drug(arr);
        }
    }
}

