                yield break;
            var s = new Stack<List<int>>();
            for (int i = Arr.Length - 1; i >= 0; i--)
                s.Push(new List<int>() { i });
            while (s.Count > 0) {
                var cur = s.Pop();
                if (cur.Count == Use) {
                    var ret = new List<int>();
                    cur.ForEach(X => ret.Add(Arr[X]));
                    yield return ret.ToArray();
                } else
                    for (int i = Arr.Length - 1; i >= 0; i--)
