    public static void Main(string[] args)
    {
        checked
        {
            N = Input.NextInt();
            Ma = Input.NextInt();
            Mb = Input.NextInt();

            var gcd = (int)MathLib.Gcd(Ma, Mb);
            Ma /= gcd;
            Mb /= gcd;

            a = new int[N];
            b = new int[N];
            c = new int[N];

            for (int i = 0; i < N; i++)
            {
                var s = Input.LineInt();
                a[i] = s[0];
                b[i] = s[1];
                c[i] = s[2];
            }

            var maxa = a.Sum();
            var maxb = b.Sum();

            DPs = new Dictionary<Tuple<int, int, int>, int>();

            int minCost = BigValue;
            for (int i = 1; ; i++)
            {
                var mma = Ma * i;
                var mmb = Mb * i;
                if (mma > maxa)
                    break;
                if (mmb > maxb)
                    break;

                var cost = DP(N, mma, mmb);
                minCost = Math.Min(minCost, cost);
            }

            if (minCost > 2 * 40 * 100)
                minCost = -1;

            Console.WriteLine(minCost);
        }
    }

    public const int BigValue = int.MaxValue;

    static Dictionary<Tuple<int, int, int>, int> DPs;

    static int DP(int i, int ca, int cb)
    {
        if (i == 0)
        {
            if (ca == 0 && cb == 0)
                return 0;
            else
                return BigValue;
        }

        var key = new Tuple<int, int, int>(i, ca, cb);
        if (DPs.ContainsKey(key))
            return DPs[key];

        int cost1;
        {
            var key1 = new Tuple<int, int, int>(i - 1, ca, cb);
            if (DPs.ContainsKey(key1))
                cost1 = DPs[key1];
            else
            {
                cost1 = DP(i - 1, ca, cb);
            }
        }

        int cost2;
        {
            var mca = ca - a[i - 1];
            var mcb = cb - b[i - 1];
            if (mca < 0 || mcb < 0)
            {
                cost2 = BigValue;
            }
            else
            {
                var key2 = new Tuple<int, int, int>(i - 1, mca, mcb);
                if (DPs.ContainsKey(key2))
                    cost2 = DPs[key2];
                else
                {
                    cost2 = DP(i - 1, mca, mcb);
                    if (cost2 != BigValue)
                        cost2 += c[i - 1];
                }
            }
        }

        var cost = Math.Min(cost1, cost2);
        DPs[key] = cost;
        return cost;
    }
}

public class MathLib
{
    /// <summary>
    /// 最大公約数を求める
    /// </summary>
    /// <param name="a"></param>
    /// <param name="b"></param>
    /// <returns></returns>
    public static long Gcd(long a, long b)
    {
        return (a < b) ? Gcd(b, a)
             : (b > 0) ? Gcd(b, a % b)
                       : a;
    }

    /// <summary>
    /// 最小公倍数を求める
    /// </summary>
    /// <param name="a"></param>
    /// <param name="b"></param>
    /// <returns></returns>
    public static long Lcm(long a, long b)
    {
        return a / Gcd(a, b) * b;
    }

    /// <summary>
    /// 約数を列挙する。返される順序は一様では<b>ない</b>。
    /// </summary>
    /// <param name="n">約数を求める数字</param>
    /// <returns><paramref name="n"/> の約数の列挙</returns>
    public static IEnumerable<int> GetDivisors(int n)
    {
        for (int i = 1; i < (int)Math.Sqrt(n) + 1; i++)
        {
            if ((n % i) == 0)
            {
                yield return i;
                if (i != n / i)
                {
                    yield return n / i;
                }
            }
        }
        yield break;
    }
}

