        const int INF = 1234567890;
        void Solve() {
            io.i(out N, out Ma, out Mb);
            io.ini(out a, out b, out c, N);
            int[,,] dp = new int[N + 1, (N + 1) * 10+1, (N + 1) * 10+1];
            for (int i = 0; i < dp.GetLength(0); ++i)
                for (int j = 0; j < dp.GetLength(1); ++j)
                    for (int k = 0; k < dp.GetLength(2); ++k)
                        dp[i, j, k] = INF;
            dp[0, 0, 0] = 0;
            for (int i = 1; i <= N;++i){
                for (int j = 0; j < (N + 1) * 10 + 1;++j){
                    for (int k = 0; k < (N + 1) * 10 + 1;++k){
                        if (j - a[i - 1] < 0) continue;
                        if (k - b[i - 1] < 0) continue;
                        if (dp[i - 1, j - a[i - 1], k - b[i - 1]] != INF)
                            dp[i,j,k] = dp[i - 1, j - a[i - 1], k - b[i - 1]] + c[i - 1];
                    }
                }
            }
            int ans = int.MaxValue;
            for (int i = 0; i <dp.GetLength(0); ++i) {
                for (int j = 1; j < dp.GetLength(1); ++j) {
                    for (int k = 1; k < dp.GetLength(2); ++k) {
                        if (ratio(j, k)&&dp[i,j,k]!=INF)
                            ans = Math.Min(ans, dp[i, j, k]);
                    }
                }
            }
            if(ans==int.MaxValue){
                io.o(-1);
            }else{
                io.o(ans);
            }

        }
