	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			int ma = cin.Int();
			int mb = cin.Int();
			var val = new Tuple<int, int>[n];
			for (int i = 0; i < n; i++) {
				int a = cin.Int();
				int b = cin.Int();
				int c = cin.Int();
				int d = a * mb - b * ma;
				val[i] = new Tuple<int, int>(d, c);
			}

			int offset = 10000;
			int range = offset * 2 + 1;
			int max = 10000000;
			int[,] dp = new int[n + 1, range];
			for (int i = 0; i <= n; i++) {
				for (int j = 0; j < range; j++) {
					dp[i, j] = max;
				}
			}

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < range; j++) {
					if (dp[i, j] != max) {
						dp[i + 1, j + val[i].Item1] = Math.Min(
							dp[i, j + val[i].Item1],
							dp[i, j] + val[i].Item2);
					}
				}

				dp[i + 1, val[i].Item1 + offset] = Math.Min(dp[i, val[i].Item1 + offset], val[i].Item2);
			}

			if (dp[n, offset] == max) {
				Console.WriteLine(-1);
				return;
			}

			Console.WriteLine(dp[n, offset]);
		}
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

using System;
using System.Linq;

class Program
{
    static int N;
    static int Ma;
    static int Mb;
    static int[] a;
    static int[] b;
    static int[] c;

    static void Main()
    {
        /*入力を受け取る*/
        int[] inputs = Console.ReadLine().Split().Select(int.Parse).ToArray();
        N = inputs[0];
        Ma = inputs[1];
        Mb = inputs[2];
        a = new int[N];
        b = new int[N];
        c = new int[N];
        for (int i = 0; i < N; i++)
        {
            inputs = Console.ReadLine().Split().Select(int.Parse).ToArray();
            a[i] = inputs[0];
            b[i] = inputs[1];
            c[i] = inputs[2];
        }

        /*
            DP[i][p,q] : i番目までの商品で、Aをp(g),Bをq(g)買う最小金額(不可能なら∞)
        というDPを行う
         */
        int[][,] DP = new int[N + 1][,];
        int a_sum = a.Sum();
        int b_sum = b.Sum();
        for (int i = 0; i <= N; i++)
            DP[i] = new int[a_sum + 1, b_sum + 1];
        for (int i = 0; i <= N; i++)
            for (int j = 0; j <= a_sum; j++)
                for (int k = 0; k <= b_sum; k++)
                    DP[i][j, k] = (int)1e8;
        DP[0][0, 0] = 0;
        for (int i = 1; i <= N; i++)
        {
            int ai = a[i - 1];
            int bi = b[i - 1];
            int ci = c[i - 1];
            for (int p = 0; p <= a_sum; p++)
            {
                for (int q = 0; q <= b_sum; q++)
                {
                    try
                    {
                        DP[i][p, q] = Math.Min(DP[i - 1][p, q], DP[i - 1][p - ai, q - bi] + ci);
                    }
                    catch
                    {
                        DP[i][p, q] = DP[i - 1][p, q];
                    }
                }
            }
        }

        /*DP[N][Ma * i,Mb * i] (i = 1,2,3,...)の中の最小値が答え*/
        int ans = int.MaxValue;
        for (int i = 1; ; i++)
        {
            try
            {
                ans = Math.Min(ans, DP[N][Ma * i, Mb * i]);
            }
            catch { break; }
        }
        Console.WriteLine(ans >= (int)1e5 ? -1 : ans);
    }
}

