            }

            // 半分全列挙
            int count = N / 2;
            if (N > 30) count = N / 2;

            var first = meds.Take(count).ToArray();
            var last = meds.Skip(count).ToArray();

            var bf = BitSearch(first.Length);

            int[,] min = new int[201, 201];
            for (int i = 0; i < 201; i++)
            {
                for (int j = 0; j < 201; j++)
                {
                    min[i, j] = int.MaxValue / 2;
                }
            }

            foreach (var b in bf)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                foreach (var b_ in b)
                {
                    suma += first[b_].a;
                    sumb += first[b_].b;
                    sumc += first[b_].c;
                }
                min[suma, sumb] = Math.Min(min[suma, sumb], sumc);
            }

            int ans = int.MaxValue / 2;
            int n = last.Length;
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        suma += last[i].a;
                        sumb += last[i].b;
                        sumc += last[i].c;
                    }
                }

                for (int i = 0; i < canda.Count; i++)
                {
                    int rema = canda[i] - suma;
                    int remb = candb[i] - sumb;
                    if (rema < 0 || remb < 0) continue;
                    if (min[rema, remb] == int.MaxValue / 2) continue;
                    int cand = sumc + min[rema, remb];
                    ans = Math.Min(ans, cand);
                }

            }

            if (ans == int.MaxValue / 2) ans = -1;
            Console.WriteLine(ans);

        }

        public static int[][] BitSearch(int n)
        {
            int[][] ret = new int[1 << n][];
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                List<int> S = new List<int>();
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        S.Add(i);
                    }
                }

                ret[bit] = S.ToArray();
            }
            return ret;
        }

        struct Med
        {
            public int a;
            public int b;
            public int c;
        }
    }


