        N = io.Int;
        Ma = io.Int;
        Mb = io.Int;
        a = new int[N];
        b = new int[N];
        c = new int[N];
        for (int i = 0; i < N; ++i) {
            a[i] = io.Int;
            b[i] = io.Int;
            c[i] = io.Int;
        }
        //cal
        var dp = new int[401, 401];
        for (int i = 0; i < dp.GetLength(0); ++i)
            for (int j = 0; j < dp.GetLength(1); ++j)
                dp[i, j] = INF;
        dp[0, 0] = 0;
        for (int i = 0; i < N;++i)
            for (int j = dp.GetLength(0)-1; j >= 0;--j)
                for (int k = dp.GetLength(1) - 1; k >=0;--k)
                    if (dp[j,k]!=INF)
                        dp[j + a[i], k + b[i]] = 
                            Math.Min(dp[j + a[i], k + b[i]], dp[j, k] + c[i]);
        int ans = INF;
        for (int mul = 1; mul * Math.Max(Ma, Mb) < 401;++mul)
            ans = Math.Min(ans, dp[Ma*mul, Mb*mul]);                
        //res
        Console.WriteLine(ans == INF ? -1 : ans);
    }
    SimpleIO io = new SimpleIO();
    public static void Main(string[] args) { new Simple().Stream(); }
    void Stream() {
        Solve();
        io.writeFlush();
    }
