            List<int> candb = new List<int>();
            int sa = Ma;
            int sb = Mb;
            while (sa <= 200 && sb <= 200)
            {
                canda.Add(sa);
                candb.Add(sb);
                sa += Ma;
                sb += Mb;
            }

            Med[] meds = new Med[N];
            for (int i = 0; i < N; i++)
            {
                int a = RInt;
                int b = RInt;
                int c = RInt;
                meds[i] = new Med { a = a, b = b, c = c };
            }

            // 半分全列挙
            int count = N / 2;
            if (N > 30) count = N / 2;

            var first = meds.Take(count).ToArray();
            var last = meds.Skip(count).ToArray();

            int[,] min = new int[201, 201];
            for (int i = 0; i < 201; i++)
            {
                for (int j = 0; j < 201; j++)
                {
                    min[i, j] = int.MaxValue / 2;
                }
            }

            int n = first.Length;
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        suma += last[i].a;
                        sumb += last[i].b;
                        sumc += last[i].c;
                    }
                }
                min[suma, sumb] = Math.Min(min[suma, sumb], sumc);
            }

            int ans = int.MaxValue / 2;
            n = last.Length;
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                int suma = 0;
                int sumb = 0;
                int sumc = 0;
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        suma += last[i].a;
                        sumb += last[i].b;
                        sumc += last[i].c;
                    }
                }

                for (int i = 0; i < canda.Count; i++)
                {
                    int rema = canda[i] - suma;
                    int remb = candb[i] - sumb;
                    if (rema < 0 || remb < 0) continue;
                    if (min[rema, remb] == int.MaxValue / 2) continue;
                    int cand = sumc + min[rema, remb];
                    ans = Math.Min(ans, cand);
                }

            }

            if (ans == int.MaxValue / 2) ans = -1;
            Console.WriteLine(ans);

        }

        public static int[][] BitSearch(int n)
        {
            int[][] ret = new int[1 << n][];
            for (int bit = 0; bit < (1 << n); ++bit)
            {
                List<int> S = new List<int>();
                for (int i = 0; i < n; i++)
                {
                    if ((bit & (1 << i)) != 0)
                    {
                        S.Add(i);
                    }
                }

                ret[bit] = S.ToArray();
            }
            return ret;
        }

