    private object Calc()
    {
        var N = cr.Int;
        var Ma = cr.Int;
        var Mb = cr.Int;
        var yaks = cr.Repeat(N).Select(cr => new Yakuhin { a = cr.Int, b = cr.Int, cost = cr.Int });
        var dp = NewArray(401, 401, int.MaxValue / 2);
        dp[0][0] = 0;
        foreach (var y in yaks)
            for (int i = 400; i >= y.a; i--)
                for (int j = 400; j >= y.b; j--)
                    UpdateMin(ref dp[i][j], dp[i - y.a][j - y.b] + y.cost);

        int res = 111111110;
        for (int i = 1; Ma * i <= 400 && Mb * i <= 400; i++)
            UpdateMin(ref res, dp[Ma * i][Mb * i]);
        if (res > 40000)
            return -1;
        return res;
    }
