public class Program
{
    int N, Ma, Mb;

    int[] A, B, C;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        Ma = sc.NextInt();
        Mb = sc.NextInt();

        A = new int[N];
        B = new int[N];
        C = new int[N];

        for (int i = 0; i < N; i++)
        {
            A[i] = sc.NextInt();
            B[i] = sc.NextInt();
            C[i] = sc.NextInt();
        }

        var dp = new int[401, 401];
        for (int i = 0; i <= 400; i++)
        {
            for (int j = 0; j <= 400; j++)
            {
                dp[i, j] = int.MaxValue;
            }
        }

        dp[0, 0] = 0;

        for (int i = 0; i < N; i++)
        {
            for (int j = 400; j >= 0; j--)
            {
                for (int k = 400; k >= 0; k--)
                {
                    if (dp[j, k] == int.MaxValue) continue;
                    dp[j + A[i], k + B[i]] = Math.Min(dp[j + A[i], k + B[i]], dp[j, k] + C[i]);
                }
            }
        }

        int ans = int.MaxValue;
        for (int i = 1; i * Ma <= 400 && i * Mb <= 400; i++)
        {
            ans = Math.Min(ans, dp[i * Ma, i * Mb]);
        }

        if (ans == int.MaxValue) Console.WriteLine("-1");
        else Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

