class Program
{
    static string InputPattern = "InputX";

    static List<string> GetInputList()
    {
        var WillReturn = new List<string>();

        if (InputPattern == "Input1") {
            WillReturn.Add("3 1 1");
            WillReturn.Add("1 2 1");
            WillReturn.Add("2 1 2");
            WillReturn.Add("3 3 10");
            //3
        }
        else if (InputPattern == "Input2") {
            WillReturn.Add("1 1 10");
            WillReturn.Add("10 10 10");
            //-1
        }
        else {
            string wkStr;
            while ((wkStr = Console.ReadLine()) != null) WillReturn.Add(wkStr);
        }
        return WillReturn;
    }

    struct YakuhinInfoDef
    {
        internal int A;
        internal int B;
        internal int C;
    }

    static void Main()
    {
        List<string> InputList = GetInputList();

        int[] wkArr = { };
        Action<string> SplitAct = pStr =>
            wkArr = pStr.Split(' ').Select(X => int.Parse(X)).ToArray();

        SplitAct(InputList[0]);
        int MA = wkArr[1];
        int MB = wkArr[2];

        var YakuhinInfoList = new List<YakuhinInfoDef>();
        foreach (string EachStr in InputList.Skip(1)) {
            SplitAct(EachStr);
            YakuhinInfoDef WillAdd;
            WillAdd.A = wkArr[0];
            WillAdd.B = wkArr[1];
            WillAdd.C = wkArr[2];
            YakuhinInfoList.Add(WillAdd);
        }

        //最小金額[タイプAの合計,タイプBの合計]なDP表
        var DPDict = new Dictionary<string, int>();
        DPDict["0,0"] = 0;

        foreach (YakuhinInfoDef EachYakuhin in YakuhinInfoList) {
            foreach (string EachKey in DPDict.Keys.ToArray()) {
                string[] wkStr = EachKey.Split(',');
                int CurrA = int.Parse(wkStr[0]);
                int CurrB = int.Parse(wkStr[1]);

                int NewA = CurrA + EachYakuhin.A;
                int NewB = CurrB + EachYakuhin.B;

                int NewC = DPDict[EachKey] + EachYakuhin.C;

                string NewKey = string.Format("{0},{1}", NewA, NewB);
                if (DPDict.ContainsKey(NewKey)) {
                    if (DPDict[NewKey] > NewC)
                        DPDict[NewKey] = NewC;
                }
                else DPDict[NewKey] = NewC;
            }

            //Console.WriteLine("{0}回目のDPの結果", ++DPCnt);
            //foreach (var EachPair in DPDict) {
            //    Console.WriteLine("PrevDP[{0}]={1}", EachPair.Key, EachPair.Value);
            //}
        }

        int Answer = int.MaxValue;
        bool HasAnswer = false;

        foreach (var EachPair in DPDict) {
            string[] wkStr = EachPair.Key.Split(',');
            int CurrA = int.Parse(wkStr[0]);
            int CurrB = int.Parse(wkStr[1]);
            if (CurrA < MA) continue;
            if (CurrB < MB) continue;

            if (CurrA % MA > 0) continue;
            if (CurrB % MB > 0) continue;

            int Syou1 = CurrA / MA;
            int Syou2 = CurrB / MB;
            if (Syou1 != Syou2) continue;

            HasAnswer = true;
            if (Answer > EachPair.Value) {
                Answer = EachPair.Value;
            }
        }
        Console.WriteLine(HasAnswer ? Answer : -1);
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using Kujikatsu052.Algorithms;
using Kujikatsu052.Collections;
using Kujikatsu052.Extensions;
using Kujikatsu052.Numerics;
using Kujikatsu052.Questions;
using System.Diagnostics.CodeAnalysis;

namespace Kujikatsu052.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc054/tasks/abc054_d
    /// </summary>
    public class QuestionF : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var (n, ma, mb) = inputStream.ReadValue<int, int, int>();
            var half = n / 2;
            var group1 = new Medicine[n - half];
            var group2 = new Medicine[half];

            for (int i = 0; i < group1.Length; i++)
            {
                var (a, b, c) = inputStream.ReadValue<int, int, int>();
                group1[i] = new Medicine(new Quantity(a, b), c);
            }

            for (int i = 0; i < group2.Length; i++)
            {
                var (a, b, c) = inputStream.ReadValue<int, int, int>();
                group2[i] = new Medicine(new Quantity(a, b), c);
            }


            if (n == 1)
            {
                var gcd = NumericalAlgorithms.Gcd(group1[0].Quantity.A, group1[0].Quantity.B);
                if (group1[0].Quantity.A == ma * gcd && group1[0].Quantity.B == mb * gcd)
                {
                    yield return group1[0].Price;
                }
                else
                {
                    yield return -1;
                }
                yield break;
            }

            var sum1 = HalfSum(group1);
            var sum2 = HalfSum(group2);

            Array.Sort(sum1);
            sum2 = sum2.OrderBy(m => -m.Quantity.A + m.Quantity.B).ToArray();

            int minPrice = int.MaxValue;

            foreach (var sum in sum1.Concat(sum2))
            {
                if (Check(sum, ma, mb))
                {
                    minPrice = Math.Min(minPrice, sum.Price);
                }
            }

            var right = sum2.Length - 1;
            for (int left = 0; left < sum1.Length; left++)
            {
                if (Check(sum1[left] + sum2[right], ma, mb))
                {
                    minPrice = Math.Min(minPrice, sum1[left].Price + sum2[right].Price);
                }

                while (right > 0 && CanProceed(sum1[left] + sum2[right - 1], ma, mb))
                {
                    right--;
                    if (Check(sum1[left] + sum2[right], ma, mb))
                    {
                        minPrice = Math.Min(minPrice, sum1[left].Price + sum2[right].Price);
                    }
                }
            }

            if (minPrice < int.MaxValue)
            {
                yield return minPrice;
            }
            else
            {
                yield return -1;
            }
        }

        bool Check(Medicine medicine, int ma, int mb)
        {
            var gcd = NumericalAlgorithms.Gcd(medicine.Quantity.A, medicine.Quantity.B);
            return medicine.Quantity.A == ma * gcd && medicine.Quantity.B == mb * gcd;
        }

        bool CanProceed(Medicine medicine, int ma, int mb)
        {
            var ratio = medicine.Quantity.A * (long)mb;
            var demand = ma * (long)medicine.Quantity.B;
            return ratio >= demand;
        }

        Medicine[] HalfSum(Medicine[] medicines)
        {
            var sum = new Medicine[(1 << medicines.Length) - 1];
            for (int flag = 1; flag < 1 << medicines.Length; flag++)
            {
                var current = new Medicine();
                for (int i = 0; i < medicines.Length; i++)
                {
                    if ((flag & (1 << i)) > 0)
                    {
                        current += medicines[i];
                    }
                }
                sum[flag - 1] = current;
            }
            return sum;
        }

        [StructLayout(LayoutKind.Auto)]
        readonly struct Medicine : IComparable<Medicine>
        {
            public Quantity Quantity { get; }
            public int Price { get; }

            public Medicine(Quantity ratio, int price)
            {
                Quantity = ratio;
                Price = price;
            }

            public static Medicine operator +(Medicine m1, Medicine m2) => new Medicine(m1.Quantity + m2.Quantity, m1.Price + m2.Price);

            public void Deconstruct(out Quantity ratio, out int price) => (ratio, price) = (Quantity, Price);
            public override string ToString() => $"{nameof(Quantity)}: {Quantity}, {nameof(Price)}: {Price}";

            public int CompareTo([AllowNull] Medicine other)
            {
                var comp = Quantity.CompareTo(other.Quantity);
                if (comp != 0)
                {
                    return comp;
                }
                else
                {
                    return Price - other.Price;
                }
            }
        }

        [StructLayout(LayoutKind.Auto)]
        readonly struct Quantity : IComparable<Quantity>
        {
            public int A { get; }
            public int B { get; }

            public Quantity(int a, int b)
            {
                A = a;
                B = b;
            }

            public static Quantity operator +(Quantity r1, Quantity r2) => new Quantity(r1.A + r2.A, r1.B + r2.B);

            public void Deconstruct(out int a, out int b) => (a, b) = (A, B);
            public override string ToString() => $"{nameof(A)}: {A}, {nameof(B)}: {B}";

            public int CompareTo([AllowNull] Quantity other)
            {
                var me = (long)A * other.B;
                var you = (long)other.A * B;
                return Math.Sign(me - you);
            }
        }
    }
}

