          for (int j = i * 10; j >= 0; --j)
          {
            for (int k = i * 10; k >= 0; --k)
            {
              if (dp[j, k] < Int32.MaxValue)
              {
                dp[j + A, k + B] = Math.Min(dp[j + A, k + B], dp[j, k] + C);
