    struct YakuhinInfoDef
    {
        internal int A;
        internal int B;
        internal int C;
    }

    static void Main()
    {
        List<string> InputList = GetInputList();

        int[] wkArr = { };
        Action<string> SplitAct = pStr =>
            wkArr = pStr.Split(' ').Select(X => int.Parse(X)).ToArray();

        SplitAct(InputList[0]);
        int MA = wkArr[1];
        int MB = wkArr[2];

        var YakuhinInfoList = new List<YakuhinInfoDef>();
        foreach (string EachStr in InputList.Skip(1)) {
            SplitAct(EachStr);
            YakuhinInfoDef WillAdd;
            WillAdd.A = wkArr[0];
            WillAdd.B = wkArr[1];
            WillAdd.C = wkArr[2];
            YakuhinInfoList.Add(WillAdd);
        }


        //最小金額[タイプAの合計,タイプBの合計]なDP表
        var DPDict = new Dictionary<string, int>();
        DPDict["0,0"] = 0;

        int DPCnt = 0;
        foreach (YakuhinInfoDef EachYakuhin in YakuhinInfoList) {
            foreach (string EachKey in DPDict.Keys.ToArray()) {
                string[] wkStr = EachKey.Split(',');
                int CurrA = int.Parse(wkStr[0]);
                int CurrB = int.Parse(wkStr[1]);

                int NewA = CurrA + EachYakuhin.A;
                int NewB = CurrB + EachYakuhin.B;
                int GCD = DeriveGCD(NewA, NewB);
                NewA /= GCD;
                NewB /= GCD;

                int NewC = DPDict[EachKey] + EachYakuhin.C;

                string NewKey = string.Format("{0},{1}", NewA, NewB);
                if (DPDict.ContainsKey(NewKey)) {
                    if (DPDict[NewKey] > NewC)
                        DPDict[NewKey] = NewC;
                }
                else DPDict[NewKey] = NewC;
            }

            //Console.WriteLine("{0}回目のDPの結果", ++DPCnt);
            //foreach (var EachPair in DPDict) {
            //    Console.WriteLine("PrevDP[{0}]={1}", EachPair.Key, EachPair.Value);
            //}
        }
        string wkKey = string.Format("{0},{1}", MA, MB);
        if (DPDict.ContainsKey(wkKey)) {
            Console.WriteLine(DPDict[wkKey]);
        }
        else Console.WriteLine(-1);
    }

    //ユークリッドの互除法で2数の最大公約数を求める
    static private int DeriveGCD(int pVal1, int pVal2)
    {
        pVal1 = Math.Abs(pVal1);
        pVal2 = Math.Abs(pVal2);

        int WarareruKazu = Math.Max(pVal1, pVal2);
        int WaruKazu = Math.Min(pVal1, pVal2);

        while (true) {
            int Amari = WarareruKazu % WaruKazu;
            if (Amari == 0) return WaruKazu;
            WarareruKazu = WaruKazu;
            WaruKazu = Amari;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public struct Medicine
{
    public int X;
    public int Y;
    public int Cost;
}

public class Program
{
    #region Standard I/O
    readonly TextReader input;
    readonly TextWriter output;

    X[] ReadLine<X>(Func<string, X> func)
    {
        return input.ReadLine().Split(' ').Select(func).ToArray();
    }

    void WriteLineOne(object obj)
    {
        output.WriteLine("{0}", obj);
    }

    void WriteLineMany(params object[] objects)
    {
        output.WriteLine(string.Join(" ", objects.Select(obj => obj.ToString())));
    }
    #endregion

    int n, mx, my;
    Medicine[] medicines;
    int totalX, totalY;

    void Read()
    {
        var line = ReadLine(int.Parse);
        n = line[0];
        mx = line[1];
        my = line[2];

        medicines = new Medicine[n];
        for (var i = 0; i < n; i++)
        {
            var l = ReadLine(int.Parse);
            var x = l[0];
            var y = l[1];
            var c = l[2];

            medicines[i] =
                new Medicine()
                {
                    X = my * x,
                    Y = mx * y,
                    Cost = c,
                };

            totalX += medicines[i].X;
            totalY += medicines[i].Y;
        }
    }

    int Solve()
    {
        var dp = new int[totalX + 1, totalY + 1];

        for (var x = 0; x <= totalX; x++)
        {
            for (var y = 0; y <= totalY; y++)
            {
                dp[x, y] = int.MaxValue;
            }
        }

        dp[0, 0] = 0;

        for (var i = 0; i < n; i++)
        {
            var m = medicines[i];

            for (var x = totalX; x >= m.X; x--)
            {
                for (var y = totalY; y >= m.Y; y--)
                {
                    var cost = dp[x - m.X, y - m.Y];
                    if (cost == int.MaxValue) continue;

                    dp[x, y] = Math.Min(dp[x, y], cost + m.Cost);
                }
            }
        }

        var totalCost = int.MaxValue;

        for (var x = 1; x <= Math.Min(totalX, totalY); x++)
        {
            totalCost = Math.Min(totalCost, dp[x, x]);
        }

        return totalCost == int.MaxValue ? -1 : totalCost;
    }

    public void Run()
    {
        Read();
        WriteLineOne(Solve());
    }

    public Program(TextReader input, TextWriter output)
    {
        this.input = input;
        this.output = output;
    }

    public static void Main(string[] args)
    {
        new Program(Console.In, Console.Out).Run();
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
		long n = long.Parse(input[0]);
		long ma = long.Parse(input[1]);
    long mb = long.Parse(input[2]);
    long[,] vertexes = new long[n,3];
    long answer = long.MaxValue-99999;
    for(long i = 0; i < n; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      vertexes[i,0] = nums[0];
      vertexes[i,1] = nums[1];
      vertexes[i,2] = nums[2];
    }

    long[][][] dp = new long[n+1][][];
    for(long i = 0; i <= n; i++)
    {
      dp[i] = new long[ma*n+1][];
      for(long j = 0; j <= ma*n; j++)
      {
        dp[i][j] = new long[mb*n+1];
      }
    }

    for(long nL = 0; nL <= n; nL++)
    {
      for(long maL = 0; maL <= ma*n; maL++)
      {
        for(long mbL = 0; mbL <= mb*n; mbL++)
        {
          if(nL + maL + mbL > 0) dp[nL][maL][mbL] = long.MaxValue-99999;
          if(nL-1>=0 && maL-vertexes[nL-1,0] >= 0 && mbL-vertexes[nL-1,1] >= 0)
          {
            dp[nL][maL][mbL] = Math.Min
              (dp[nL][maL][mbL], dp[nL-1][maL-vertexes[nL-1,0]][mbL-vertexes[nL-1,1]]+vertexes[nL-1,2]);
          }
          if(nL-1>=0)
          {
            dp[nL][maL][mbL] = Math.Min(dp[nL][maL][mbL], dp[nL-1][maL][mbL]);
          }
          if(ma*mbL == mb*maL && maL != 0) answer = Math.Min(answer, dp[nL][maL][mbL]);
          //Console.WriteLine(nL+" "+maL+" "+mbL+" "+dp[nL][maL][mbL]);
        }
      }
    }
    if(answer == long.MaxValue-99999) answer = -1;
		Console.WriteLine(answer);
	}
}

using System;
