  {
    var tmp = ReadIntArray();
    int n = tmp[0], ma = tmp[1], mb = tmp[2];
    int[] a = new int[n];
    int[] b = new int[n];
    int[] c = new int[n];

    for (int i = 0; i < n; i++)
    {
      tmp = ReadIntArray();
      a[i] = tmp[0]; b[i] = tmp[1]; c[i] = tmp[2];
    }

    int nMax = 40, aMax = 10, bMax = 10, cMax = 100;
    int [,,] d = new int[n+1, (nMax+1)*aMax, (nMax+1)*bMax];

    int inf = 1000000;

    for (int i = 0; i <= n; i++){
      for (int j = 0; j < (nMax+1)*aMax; j++){
    	for (int k = 0; k < (nMax+1)*bMax; k++){
          d[i,j,k] = inf;
        }
      }
    }

    d[0,0,0] = 0;
    for (int i = 0; i < n; i++){
      for (int j = 0; j <= nMax*aMax; j++){
    	for (int k = 0; k <= nMax*bMax; k++){
          if(d[i,j,k] == inf) continue;
          d[i+1,j,k] = Math.Min(d[i+1,j,k], d[i,j,k]);
          d[i+1,j+a[i],k+b[i]] = Math.Min(d[i+1,j+a[i],k+b[i]], d[i,j,k]+c[i]);
        }
      }
    }

    int ans = inf;
    for (int i = 1; i <= nMax*aMax; i++){
      for (int j = 1; j <= nMax*bMax; j++){
        if(i*mb == j*ma) ans = Math.Min(ans, d[n,i,j]);
      }
    }

    WriteLine(ans < inf ? ans : -1);
  }
}

