    public partial class AtCoder
    {
        public void Solve()
        {
            int N, Ma, Mb;
            Multi(out N, out Ma, out Mb);
            var items = GetIntJaggedArray(N).Select(s => new { a = s[0], b = s[1], price = s[2] }).ToArray();

            var dic1 = new Dictionary<int, int>();
            var dic2 = new Dictionary<int, int>();

            for (int bit = 1; bit < (1 << (N / 2)); bit++)
            {
                var sum = 0;
                var psum = 0;
                for (int i = 0; i < (N / 2); i++)
                {
                    if (((bit >> i) & 1) == 1)
                    {
                        sum += items[i].a * Mb - items[i].b * Ma;
                        psum += items[i].price;
                    }
                }
                if (dic1.ContainsKey(sum)) dic1[sum] = Math.Min(dic1[sum], psum);
                else dic1.Add(sum, psum);
            }

            for (int bit = 1; bit < (1 << N - (N / 2)); bit++)
            {
                var sum = 0;
                var psum = 0;
                for (int i = 0; i < N - (N / 2); i++)
                {
                    if (((bit >> i) & 1) == 1)
                    {
                        sum += items[i + N / 2].a * Mb - items[i + N / 2].b * Ma;
                        psum += items[i + N / 2].price;
                    }
                }
                if (dic2.ContainsKey(sum)) dic2[sum] = Math.Min(dic2[sum], psum);
                else dic2.Add(sum, psum);
            }

            var min = 10000;
            foreach (var d1 in dic1)
            {
                if (dic2.ContainsKey(-d1.Key)) min = Math.Min(min, d1.Value + dic2[-d1.Key]);
            }
            if (dic1.ContainsKey(0)) min = Math.Min(min, dic1[0]);
            if (dic2.ContainsKey(0)) min = Math.Min(min, dic2[0]);

            Console.WriteLine(min==10000?-1:min);
        }

    }
