class Program
{
    public static void Main()
    {
	const int MaxAB = 10, Inf = 1000000;

	var tmp = ReadIntArray();
	int n = tmp[0], ma = tmp[1], mb = tmp[2];
	int[] a = new int[n];
	int[] b = new int[n];
	int[] c = new int[n];
	for (int i = 0; i < n; i++)
	{
	    tmp = ReadIntArray();
	    a[i] = tmp[0];
	    b[i] = tmp[1];
	    c[i] = tmp[2];
	}

	int[,,] dp = new int[n+1, n*MaxAB+1, n*MaxAB+1];
	for (int i = 0; i <= n; i++)
	    for (int j = 0; j <= n*MaxAB; j++)
		for (int k = 0; k <= n*MaxAB; k++)
		    dp[i,j,k] = Inf;

	dp[0,0,0] = 0;

	for (int i = 0; i < n; i++)
	{
	    for (int ca = 0; ca <= n*MaxAB; ca++)
	    {
		for (int cb = 0; cb <= n*MaxAB; cb++)
		{
		    if (dp[i,ca,cb] == Inf) continue;
		    dp[i+1,ca,cb] = Math.Min(dp[i+1,ca,cb], dp[i,ca,cb]);
		    dp[i+1,ca+a[i],cb+b[i]] =
			Math.Min(dp[i+1,ca+a[i],cb+b[i]], dp[i,ca,cb]+c[i]);
		}
	    }
	}

	int ans = Inf;
	for (int ca = 1; ca <= n*MaxAB; ca++)
	{
	    for (int cb = 1; cb <= n*MaxAB; cb++)
	    {
		if (ca*mb == cb*ma)
		{
		    ans = Math.Min(ans, dp[n,ca,cb]);
		}
	    }
	}

	if (ans == Inf) ans = -1;
	WriteLine(ans);
    }
}

