            for(int i = 0; i < N; i++)
            {
                int[] p = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
                list.Add(p);
                int a = p[0], b = p[1], c = p[2];
                sumA += a;sumB += b;
