public class D
{
	public static void Main()
	{
		int N = GetInt();
		int Ma = GetInt();
		int Mb = GetInt();
		int[] a = new int[N];
		int[] b = new int[N];
		int[] c = new int[N];
		for(int i = 0; i < N; i++)
		{
			a[i] = GetInt();
			b[i] = GetInt();
			c[i] = GetInt();
		}

		int size0 = (N + 1)/2;
		int size1 = N - size0;

		List<MedicineSet> sets0 = new List<MedicineSet>(size0);
		for(int s = 1; s < (1 << size0); s++)
		{
			int rate = 0;
			int cost = 0;
			for(int i = 0; i < size0; i++)
			{
				if(((s >> i) & 1) == 0)
					continue;
				rate += a[i] * Mb - b[i] * Ma;
				cost += c[i];
			}
			sets0.Add(new MedicineSet(rate, cost));
		}

		List<MedicineSet> sets1 = new List<MedicineSet>(size1);
		for(int s = 1; s < (1 << size1); s++)
		{
			int rate = 0;
			int cost = 0;
			for(int i = 0; i < size1; i++)
			{
				if(((s >> i) & 1) == 0)
					continue;
				rate += a[i + size0] * Mb - b[i + size0] * Ma;
				cost += c[i + size0];
			}
			sets1.Add(new MedicineSet(rate, cost));
		}
		sets1.Sort((x,y) => x.Rate - y.Rate);

		bool exist = false;
		int ans = int.MaxValue;
		foreach(MedicineSet set0 in sets0)
		{
			if(set0.Rate == 0)
			{
				exist = true;
				ans = Math.Min(ans, set0.Cost);
				continue;
			}

			int index = sets1.BinarySearch(new MedicineSet(-set0.Rate, -1));
			if(index < 0)
				continue;

			exist = true;
			ans = Math.Min(ans, set0.Cost + sets1[index].Cost);
		}
		Console.WriteLine(exist ? ans : -1);
	}
}


