namespace Program
{
    public class Solver
    {
        public void Solve()
        {
            var n = sc.Integer();
            var x = sc.Integer();
            var y = sc.Integer();
            const int MAX = 10 * 40 + 1;
            var dp = new int[MAX, MAX];
            for (int i = 0; i < MAX; i++)
                for (int j = 0; j < MAX; j++)
                    dp[i, j] = 100000000;
            dp[0, 0] = 0;
            for (int i = 0; i < n; i++)
            {
                var p = sc.Integer();
                var q = sc.Integer();
                var c = sc.Integer();
                for (int j = MAX - 1; j >= 0; j--)
                    for (int k = MAX - 1; k >= 0; k--)
                    {
                        if (j + p < MAX && k + q < MAX) dp[j + p, k + q] = Math.Min(dp[j + p, k + q], dp[j, k] + c);
                    }
            }
            var ans = 100000000;
            for (int i = 0; i < MAX; i++)
                for (int j = 0; j < MAX; j++)
                {
                    if (i == 0 && j == 0) continue;
                    if (i * y != j * x) continue;
                    ans = Math.Min(ans, dp[i, j]);
                }
            if (ans >= 100000000)
            {
                for (int i = 0; i < 10000000; i++)
                    IO.Printer.Out.WriteLine(ans);
            }
            IO.Printer.Out.WriteLine(ans);
