using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static int N;
    static int Ma, Mb;
    static int[] a;
    static int[] b;
    static int[] c;
    public static void Main(string[] args)
    {
        checked
        {
            N = Input.NextInt();
            Ma = Input.NextInt();
            Mb = Input.NextInt();
            a = new int[N];
            b = new int[N];
            c = new int[N];

            for (int i = 0; i < N; i++)
            {
                var s = Input.LineInt();
                a[i] = s[0];
                b[i] = s[1];
                c[i] = s[2];
            }

            DPs = new Dictionary<Tuple<int, int, int>, int>();

            int minCost = BigValue;
            for (int i = 1; ; i++)
            {
                var mma = Ma * i;
                var mmb = Mb * i;
                if (mma + mmb > N)
                    break;

                var cost = DP(N, mma, mmb);
                minCost = Math.Min(minCost, cost);
            }

            if (minCost >= (BigValue - 10))
                minCost = -1;

            Console.WriteLine(minCost);
        }
    }

    public const int BigValue = 40 * 100 * 10;

    static Dictionary<Tuple<int, int, int>, int> DPs;

    static int DP(int i, int ca, int cb)
    {
        if (i == 0)
        {
            if (ca == 0 && cb == 0)
                return 0;
            else
                return BigValue;
        }

        var key = new Tuple<int, int, int>(i, ca, cb);
        if (DPs.ContainsKey(key))
            return DPs[key];

        int cost1;
        {
            var key1 = new Tuple<int, int, int>(i - 1, ca, cb);
            if (DPs.ContainsKey(key1))
                cost1 = DPs[key1];
            else
            {
                cost1 = DP(i - 1, ca, cb);
            }
        }

        int cost2;
        {
            var mca = ca - a[i - 1];
            var mcb = cb - b[i - 1];
            if (mca < 0 || mcb < 0)
            {
                cost2 = BigValue;
            }
            else
            {
                var key2 = new Tuple<int, int, int>(i - 1, mca, mcb);
                if (DPs.ContainsKey(key2))
                    cost2 = DPs[key2];
                else
                {
                    cost2 = DP(i - 1, mca, mcb) + c[i - 1];
                }
            }
        }

        var cost = Math.Min(cost1, cost2);
        DPs[key] = cost;
        return cost;
    }
}

