    public class Program
    {
        public static void Main(string[] args)
        {
            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            //Out.Flush();
            Read();
        }
        static void Solve()
        {
            const int GETA = 10000;
            const long INI = int.MaxValue;
            (long N, long Ma, long Mb) = Slice3<long>();

            var fstNum = N / 2;
            (long t, long c)[] first = new (long, long)[fstNum];
            for (var i = 0; i < fstNum; ++i)
            {
                (long a, long b, long c) = Slice3<long>();
                var t = Ma * b - Mb * a;
                first[i] = (t, c);
            }
            void fnc(int bits, long[] dp, (long t, long c)[] vs)
            {
                var lst = (1L << bits);
                for (var i = 1; i < lst; ++i)
                {
                    var t = i;
                    var tSum = 0L;
                    var cSum = 0L;
                    for (var b = 0; b < bits; ++b)
                    {
                        if (0 != (t & 1))
                        {
                            tSum += vs[b].t;
                            cSum += vs[b].c;
                        }
                        t >>= 1;
                    }
                    dp[GETA + tSum] = Min(dp[GETA + tSum], cSum);
                }
                return;
            }
            var dp1 = Enumerable.Repeat(INI, GETA * 2).ToArray();
            fnc((int)fstNum, dp1, first);
            var ltrNum = N / 2;
            (long t, long c)[] latter = new (long, long)[ltrNum];
            for (var i = 0; i < ltrNum; ++i)
            {
                (long a, long b, long c) = Slice3<long>();
                var t = Ma * b - Mb * a;
                latter[i] = (t, c);
            }
            var dp2 = Enumerable.Repeat(INI, GETA * 2).ToArray();
            fnc((int)ltrNum, dp2, latter);

            var ans = Min(dp1[GETA], dp2[GETA]);
            for (var i = -4010; i < 4010; ++i)
                ans = Min(ans, dp1[GETA + i] + dp2[GETA - i]);
            if (ans == INI)
                WriteLine(-1);
            else
                WriteLine(ans);
        }


