var n, ma, mb int
var A, B, C []int
var dp [45][410][410]int

func main() {
	tmp := NextIntsLine()
	n, ma, mb = tmp[0], tmp[1], tmp[2]
	for i := 0; i < n; i++ {
		tmp = NextIntsLine()
		A = append(A, tmp[0])
		B = append(B, tmp[1])
		C = append(C, tmp[2])
	}

	inf := 1000000
	// 全体の初期化
	for i := 0; i < n+1; i++ {
		for j := 0; j <= 400; j++ {
			for k := 0; k <= 400; k++ {
				dp[i][j][k] = inf
			}
		}
	}
	dp[0][0][0] = 0
	// 更新
	for i := 0; i < n; i++ {
		for j := 0; j <= 400; j++ {
			for k := 0; k <= 400; k++ {
				// ありえないパターンはパスする
				if dp[i][j][k] == inf {
					continue
				}
				// 1ステップ前の状態を基準に、今注目している薬品を使う・使わないの両方のパターンで更新
				a, b, c := A[i], B[i], C[i]
				dp[i+1][j][k] = Min(dp[i+1][j][k], dp[i][j][k])
				dp[i+1][j+a][k+b] = Min(dp[i+1][j+a][k+b], dp[i][j][k]+c)
			}
		}
	}

	ans := inf
	for j := 1; j <= 400; j++ {
		for k := 1; k <= 400; k++ {
			if j*mb == k*ma {
				ans = Min(ans, dp[n][j][k])
			}
		}
	}
	if ans > n*100 {
		fmt.Println(-1)
	} else {
		fmt.Println(ans)
	}
}

