func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 500001), 500000)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	ma := getNextInt(scanner)
	mb := getNextInt(scanner)

	mm := make([]Medicine, n)

	dp := make([][][]int, n+1)

	a := 0
	b := 0
	for i := 0; i < n; i++ {
		mm[i].a = getNextInt(scanner)
		mm[i].b = getNextInt(scanner)
		mm[i].c = getNextInt(scanner)
		a += mm[i].a
		b += mm[i].b
	}

	for i := 0; i <= n; i++ {
		dp[i] = make([][]int, a+1)
		for ii := 0; ii <= a; ii++ {
			dp[i][ii] = make([]int, b+1)
			for iii := 0; iii <= b; iii++ {
				dp[i][ii][iii] = 1 << 30
			}
		}
	}

	dp[0][0][0] = 0
	for i := 1; i < n+1; i++ {
		for ii := 1; ii < a+1; ii++ {
			for iii := 1; iii < b+1; iii++ {
				dp[i][ii][iii] = dp[i-1][ii][iii]
				if mm[i-1].a > ii {
					continue
				}
				if mm[i-1].b > iii {
					continue
				}
				if dp[i][ii][iii] > dp[i-1][ii-mm[i-1].a][iii-mm[i-1].b]+mm[i-1].c {
					dp[i][ii][iii] = dp[i-1][ii-mm[i-1].a][iii-mm[i-1].b] + mm[i-1].c
				}
			}
		}
	}

	ans := -1
	for i := 1; i*ma < a && i*mb < b; i++ {
		for ii := 1; ii < n+1; ii++ {
			if dp[ii][i*ma][i*mb] == 1<<30 {
				continue
			}
			if ans == -1 || ans > dp[ii][i*ma][i*mb] {
				ans = dp[ii][i*ma][i*mb]
			}
		}
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

