const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N, Ma, Mb := sc.nextInt(), sc.nextInt(), sc.nextInt()
	A := make([]int, N)
	B := make([]int, N)
	C := make([]int, N)
	for i := 0; i < N; i++ {
		a, b, c := sc.nextInt(), sc.nextInt(), sc.nextInt()
		A[i] = a
		B[i] = b
		C[i] = c
	}
	var dp [41][401][401]int
	for i := 0; i < N+1; i++ {
		for j := 0; j < 401; j++ {
			for k := 0; k < 401; k++ {
				dp[i][j][k] = INF
			}
		}
	}
	dp[0][0][0] = 0
	for i := 1; i < N+1; i++ {
		for j := 0; j < 401; j++ {
			for k := 0; k < 401; k++ {
				dp[i][j][k] = dp[i-1][j][k]
				if j >= A[i-1] && k >= B[i-1] {
					dp[i][j][k] = min(dp[i][j][k], dp[i-1][j-A[i-1]][k-B[i-1]]+C[i-1])
				}
			}
		}
	}
	ans := INF
	for i := 1; i < 401; i++ {
		if Ma*i > 400 || Mb*i > 400 {
			continue
		}
		ans = min(ans, dp[N][Ma*i][Mb*i])
	}

	if ans == INF {
		fmt.Fprintln(wtr, -1)
	} else {
		fmt.Fprintln(wtr, ans)
	}
}

