func perm(N int, G [][]bool, size int, used []bool, order []int) int {
	if size == N {
		return 1;
	}
	ans := 0
	for i := 0; i < N; i++ {
		if used[i] {
			continue
		}
		if G[order[size - 1]][i] == false {
			continue
		}
		used[i] = true;
		order[size] = i;
		ans += perm(N, G, size + 1, used, order)
		used[i] = false;
	}
	return ans;
}

func intMin(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	io := NewIo()
	defer io.Flush()
	N := io.NextInt()
	X := io.NextInt()
	Y := io.NextInt()
	K := 400
	A := make([]int, N)
	B := make([]int, N)
	C := make([]int, N)
	for i := 0; i < N; i++ {
		A[i] = io.NextInt()
		B[i] = io.NextInt()
		C[i] = io.NextInt()
	}
	// dp[N][A][B]
	dp := make([][][]int, N)
	for i := 0; i < N; i++ {
		dp[i] = make([][]int, K + 1)
		for j := 0; j <= K; j++ {
			dp[i][j] = make([]int, K + 1)
			for k := 0; k <= K; k++ {
				dp[i][j][k] = math.MaxInt64
			}
		}
	}
	dp[0][0][0] = 0
	dp[0][A[0]][B[0]] = C[0]
	for i := 1; i < N; i++ {
		for j := 0; j <= K; j++ {
			for k := 0; k <= K; k++ {
				if dp[i - 1][j][k] != math.MaxInt64 {
					var x *int
					x = &dp[i][j][k]
					*x = intMin(*x, dp[i - 1][j][k])
					x = &dp[i][j + A[i]][k + B[i]]
					*x = intMin(*x, dp[i - 1][j][k] + C[i])
				}
			}
		}
	}
	ans := math.MaxInt64
	for a := 1; a <= K; a++ {
		for b := 1; b <= K; b++ {
			if a % X != 0 || b % Y != 0 {
				continue
			}
			k := a / X
			if b == k * Y && dp[N - 1][a][b] != math.MaxInt64 {
				//Log("a", a)
				//Log("b", b)
				ans = intMin(ans, dp[N - 1][a][b])
			}
		}
