	dp := make([][][]int, N)
	for i := 0; i < N; i++ {
		dp[i] = make([][]int, K + 1)
		for j := 0; j <= 400; j++ {
			dp[i][j] = make([]int, K + 1)
			for k := 0; k <= 400; k++ {
				dp[i][j][k] = math.MaxInt64
			}
		}
	}
	dp[0][0][0] = 0
	dp[0][A[0]][B[0]] = C[0]
	for i := 1; i < N; i++ {
		for j := 0; j <= 400; j++ {
			for k := 0; k <= 400; k++ {
				if dp[i - 1][j][k] != math.MaxInt64 {
					var x *int
					x = &dp[i][j][k]
					*x = intMin(*x, dp[i - 1][j][k])
					x = &dp[i][j + A[i]][k + B[i]]
					*x = intMin(*x, dp[i - 1][j][k] + C[i])
				}
			}
		}
	}
	ans := math.MaxInt64
	for a := 1; a <= K + 1; a++ {
		for b := 1; b <= K + 1; b++ {
			if a % X != 0 || b % Y != 0 {
				continue
			}
			k := a / X
			if b == k * Y && dp[N - 1][a][b] != math.MaxInt64 {
				//Log("a", a)
				//Log("b", b)
				ans = intMin(ans, dp[N - 1][a][b])
			}
		}
	}
	if ans == math.MaxInt64 {
		io.PrintLn(-1)
	} else {
		io.PrintLn(ans)
	}
}

