func solver(N, Ma, Mb int, A, B, C []int) int {
    dp := make([][][]int, N+1)

    var abMax, cMax int;
    for i := 0; i < N; i++ {
            abMax = max(A[i], abMax)
            abMax = max(B[i], abMax)
            cMax = max(C[i], cMax)
    }

    for i := 0; i < N+1; i++ {
        dp[i] = make([][]int, N*abMax+1)
        for j := 0; j < N*abMax+1; j++ {
            dp[i][j] = make([]int, N*abMax+1)
            for k := 0; k < N*abMax+1; k++ {
                dp[i][j][k] = N*cMax+1
            }
        }
    }
    dp[0][0][0] = 0

    for i := 0; i < N; i++ {
        for j := 0; j < N*abMax+1; j++ {
            for k := 0; k < N*abMax+1; k++ {
                if dp[i][j][k] == N*cMax+1 {
                    continue
                }
                dp[i+1][j][k] = min(dp[i+1][j][k], dp[i][j][k])
                dp[i+1][j+A[i]][k+B[i]] = min(dp[i+1][j+A[i]][k+B[i]], dp[i][j][k]+C[i])
            }
        }
    }

    var ans int = N*cMax+1

    for ca := 1; ca < N*abMax+1; ca++ {
        for cb := 1; cb < N*abMax+1; cb++ {
            if ca * Mb == cb * Ma {
                ans = min(ans, dp[N][ca][cb])
            }
        }
    }

    if ans == N*cMax+1 {
        ans = -1
    }
    return ans
}

