struct Factor
{
    long n;
    long c;
}

//素因数分解
Factor[] factors(long n) pure
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        long c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
//約数をすべて列挙
long[] divisors(long n) pure
{
    long[] list;
    void func(Factor[] fs, long n)
    {
        if(fs.empty){
            list ~= n;
            return;
        }

        foreach(c; 0..fs[0].c+1)
        {
            func(fs[1..$], n * (fs[0].n ^^ c));
        }
    }

    func(factors(n), 1);
    sort(list);
    return list;
}
//nまでの素数のリスト
long[] primes(long n) pure
{
    if(n<2)return [];

    auto table = new long[cast(size_t)n+1];

    long[] res;
    for(size_t i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(size_t a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
//素数判定
bool isPrime(long n) pure
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

import std.stdio, std.string, std.array, std.algorithm, std.conv, std.typecons, std.numeric;

alias M = Tuple!(string, "i", int, "a", int, "b", int, "c");

void main()
{
    immutable nm = readln.chomp.split(" ").map!(to!int).array;
    immutable n = nm[0];
    immutable ma = nm[1];
    immutable mb = nm[2];

    auto meds = new M[n];
    foreach(i, ref m; meds) {
        auto abc = readln.chomp.split(" ").map!(to!int).array;
        m = M(i.to!string, abc[0], abc[1], abc[2]);
    }

    int[string] memo;
    int buy(M bought, M[] rest)
    {
        immutable key = rest.map!(b => b.i).join ~ "-" ~ bought.a.to!string ~ "-" ~ bought.b.to!string ~ "-" ~ bought.c.to!string;
        if (key in memo)
            return memo[key];

        if (rest.empty)
            return ma == bought.a && mb == bought.b ? bought.c : int.max;

        auto head = rest[0];
        auto tail = rest[1..$];
        auto u = bought;

        immutable a = u.a + head.a;
        immutable b = u.b + head.b;

        immutable div = gcd(a, b);
        if (!div) {
            u.a = a;
            u.b = b;
        } else {
            u.a = a / div;
            u.b = b / div;
        }

        u.c += head.c;

        immutable ret = min(buy(bought, tail), buy(u, tail));
        memo[key] = ret;
        return ret;
    }

    immutable min_c = buy(M("", 0, 0, 0), meds);
    writeln(min_c == int.max ? -1 : min_c);
}

import std.stdio, std.string, std.array, std.algorithm, std.conv, std.typecons, std.numeric;

alias M = Tuple!(int, "a", int, "b", int, "c");

void main()
{
    immutable nm = readln.chomp.split(" ").map!(to!int).array;
    immutable n = nm[0];
    immutable ma = nm[1];
    immutable mb = nm[2];

    auto meds = new M[n];
    foreach(ref m; meds) {
        auto abc = readln.chomp.split(" ").map!(to!int).array;
        m = M(abc[0], abc[1], abc[2]);
    }

    int buy(M bought, M[] rest)
    {
        if (rest.empty) {
            immutable div = gcd(bought.a, bought.b);
            if (!div) return int.max;

            immutable a = bought.a / div;
            immutable b = bought.b / div;

            return ma == a && mb == b ? bought.c : int.max;
        }

        auto head = rest[0];
        auto tail = rest[1..$];
        auto updated = bought;

        updated.a += head.a;
        updated.b += head.b;
        updated.c += head.c;

        return min(buy(bought, tail), buy(updated, tail));
    }

    immutable min_c = buy(M(0, 0, 0), meds);
    writeln(min_c == int.max ? -1 : min_c);
}

