void main() {
    int N, Ma, Mb; readf("%d %d %d\n", &N, &Ma, &Mb);
    auto A = new int[N];
    auto B = new int[N];
    auto C = new int[N];
    foreach (i; 0 .. N) {
        int a, b, c; readf("%d %d %d\n", &a, &b, &c);
        A[i] = a;
        B[i] = b;
        C[i] = c;
    }
    int L = min(N, 20);
    int ans = int.max;
    int[Tuple!(int, int)] map;
    map[tuple(0, 0)] = 0;
    for (int bit = 1; bit < (1 << L); bit++) {
        int a = 0, b = 0, c = 0;
        for (int i = 0; i < L; i++) {
            if (bit & (1 << i)) {
                a += A[i];
                b += B[i];
                c += C[i];
            }
        }
        if (a * Mb == b * Ma) {
            ans = min(ans, c);
        }
        auto key = tuple(a, b);
        map[key] = min(map.get(key, int.max), c);
    }
    if (N > 20) {
        auto sa = A.reduce!"a + b";
        auto sb = B.reduce!"a + b";
        int X = N - 20;
        for (int bit = 0; bit < (1 << X); bit++) {
            int a = 0, b = 0, c = 0;
            for (int i = 0; i < X; i++) {
                if (bit & (1 << i)) {
                    a += A[i + 20];
                    b += B[i + 20];
                    c += C[i + 20];
                }
            }
            for (int k = 1; k * Ma <= sa && k * Mb <= sb; k++) {
                int ma = k * Ma,
                    mb = k * Mb;
                auto rkey = tuple(ma - a, mb - b);
                if (rkey in map) {
                    ans = min(ans, map[rkey] + c);
                }
            }
        }
    }
    if (ans == int.max) {
        ans = -1;
    }
    writeln(ans);
}

import std.stdio, std.string, std.array, std.algorithm, std.conv, std.typecons, std.numeric;

alias M = Tuple!(string, "i", int, "a", int, "b", int, "c");

void main()
{
    immutable nm = readln.chomp.split(" ").map!(to!int).array;
    immutable n = nm[0];
    immutable ma = nm[1];
    immutable mb = nm[2];

    auto meds = new M[n];
    foreach(i, ref m; meds) {
        auto abc = readln.chomp.split(" ").map!(to!int).array;
        m = M(i.to!string, abc[0], abc[1], abc[2]);
    }

    int[string] memo;
    int buy(M bought, M[] rest)
    {
        immutable key = rest.map!(b => b.i).join(":") ~ bought.to!string;

        if (key in memo)
            return memo[key];

        if (rest.empty)
            return ma == bought.a && mb == bought.b ? bought.c : int.max;

        auto head = rest[0];
        auto tail = rest[1..$];
        auto u = bought;

        immutable a = u.a + head.a;
        immutable b = u.b + head.b;

        immutable div = gcd(a, b);
        if (!div) {
            u.a = a;
            u.b = b;
        } else {
            u.a = a / div;
            u.b = b / div;
        }

        u.c += head.c;

        immutable ret = min(buy(bought, tail), buy(u, tail));
        memo[key] = ret;
        return ret;
    }

    immutable min_c = buy(M("", 0, 0, 0), meds);
    writeln(min_c == int.max ? -1 : min_c);
}

