		{
			for( auto b = dp[ a ].length.signed - 1; abc[ 1 ] <= b; b-- )
			{
				if( dp[ a - abc[ 0 ] ][ b - abc[ 1 ] ] == long.max ) continue;
				dp[ a ][ b ] = min( dp[ a ][ b ], dp[ a - abc[ 0 ] ][ b - abc[ 1 ] ] + abc[ 2 ] );
