def solve():
    n,A,B = LI()
    G = LIR(n)
    ma = sum([a for (a,_,_) in G])
    mb = sum([b for (_,b,_) in G])
    dp = [[float("inf")]*(mb+1) for i in range(ma+1)]
    dp[0][0] = 0
    for sa in range(ma)[::-1]:
        for sb in range(mb)[::-1]:
            dpsasb = dp[sa][sb]
            for a,b,c in G:
                na = sa+a
                if na > ma:
