import sys
INF = float("inf")


def solve(N: int, M_a: int, M_b: int, a: "List[int]", b: "List[int]", c: "List[int]"):
    M = (max(a+b)+1)*N
    DP = [[INF]*(M) for _ in range(M)]
    for aa, bb, cc in zip(a, b, c):
        DP_next = [DP[i][:] for i in range(M)]
        DP_next[aa][bb] = min(cc, DP_next[aa][bb])
        for i in range(1, M):
            if M <= i + aa:
                break
            for j in range(1, M):
                if M <= j+bb:
                    break
                DP_next[i+aa][j+bb] = min(DP[i][j]+cc, DP_next[i+aa][j+bb])
        DP = DP_next

    m = INF
    for i in range(1, M//M_a):
        anum = M_a*i
        bnum = M_b*i
        if anum >= M or bnum >= M:
            break
        m = min(DP[anum][bnum], m)
    if m == INF:
        print(-1)
    else:
        print(m)
    return


def main():

    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    M_a = int(next(tokens))  # type: int
    M_b = int(next(tokens))  # type: int
    a = [int()] * (N)  # type: "List[int]"
    b = [int()] * (N)  # type: "List[int]"
    c = [int()] * (N)  # type: "List[int]"
    for i in range(N):
        a[i] = int(next(tokens))
        b[i] = int(next(tokens))
        c[i] = int(next(tokens))
    solve(N, M_a, M_b, a, b, c)


if __name__ == '__main__':
    main()

def mixing_experiment(N: int, Ma: int, Mb: int, drags: list) -> int:
    INF = float('inf')
    max_A = max(a for a, _, _ in drags) * N
    max_B = max(b for _, b, _ in drags) * N
    dp = [
        [[INF]*(max_A + 1) for _ in range(max_B + 1)]
        for _ in range(N + 1)
    ]

    dp[0][0][0] = 0
    for n in range(N):
        a, b, c = drags[n]
        for ca in range(max_A + 1):
            for cb in range(max_B + 1):
                # 薬品 n を加えない
                dp[n + 1][ca][cb] = min(dp[n + 1][ca][cb], dp[n][ca][cb])

                if max_A < ca + a or max_B < cb + b:
                    continue

                # 薬品 n を加える
                dp[n + 1][ca + a][cb + b] = \
                    min(dp[n + 1][ca + a][cb + b], dp[n][ca][cb] + c)

    ans = min(
        dp[N][ca][cb]
        for ca in range(max_A + 1)
        for cb in range(max_B + 1)
        if ca * Mb == cb * Ma and ca != 0)
    return ans if 0 < ans and ans < INF else -1


