# read in contents and cost of n chemical packages
pac = []
for i in range(n):
	pac.append(map(int, raw_input().split()))

def reduce(a,b):
	x = a/ma
	y = b/mb
	z = x if x < y else y
	return [a-z*ma, b-z*mb]

def minCost(a,b,index,cost):
	if a == 0 and b == 0:
		return cost

	if index >= n:
		return sys.maxint

	a_p, b_p = reduce(a+pac[index][0], b+pac[index][1])
	costWith = minCost(a_p,b_p,index+1,cost+pac[index][2])
	costWithout = minCost(a,b,index+1,cost)

	return min(costWith, costWithout)

