                    continue
                if ab > MAB and ab_ > 1:
                    continue
                ans = min(ans, f(pick | m, a+a_, b+b_, c+c_))

        return ans
    ans = f(0, 0, 0, 0)
    return -1 if ans == sys.maxsize else ans


