def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


def warshall_floyd(g):
    d = defaultdict(dict)
    V = list(g.keys())
    for v in g.values():
        V.extend(list(v))
    V = set(V)
    for i in V:
        for j in V:
            if i in g and j in g[i]:
                d[i][j] = g[i][j]
            else:
                d[i][j] = sys.maxsize
    for k in g:
        for i in g:
            for j in g:
                if d[i][j] > d[i][k] + d[k][j]:
                    d[i][j] = d[i][k] + d[k][j]

    return d


@mt
def slv(N, MA, MB, ABC):
    MAB = MA/MB

    @lru_cache(maxsize=None)
    def f(pick, a, b, c):
        if a != 0 and b != 0:
            if a == (b*MA)//MB and (b*MA) % MB == 0:
                return c
        ans = sys.maxsize
        ab = 1 if b == 0 else a/b
        for i, (a_, b_, c_) in enumerate(ABC):
            m = (1 << i)
            if pick & m == 0:
                ab_ = a_ / b_
                if ab < MAB and ab_ < 1:
                    continue
                if ab > MAB and ab_ > 1:
                    continue
                ans = min(ans, f(pick | m, a+a_, b+b_, c+c_))

        return ans
    ans = f(0, 0, 0, 0)
    return -1 if ans == sys.maxsize else ans


def main():
    N, MA, MB = read_int_n()
    ABC = [read_int_n() for _ in range(N)]

    print(slv(N, MA, MB, ABC))


