def input(): return sys.stdin.readline().strip()

def resolve():

    N,Ma,Mb=map(int,input().split())
    A, B, C = [0] * N, [0] * N, [0] * N
    for i in range(N):
        A[i], B[i], C[i] = map(int, input().split())

    # https://qiita.com/drken/items/dc53c683d6de8aeacf5a#%E9%A1%9E%E9%A1%8C-3

    INF = 10**10  # INF+INFを計算してもオーバーフローしない範囲で大きく

    P = list(map(int, input().split()))  # P[i]:=i番目の問題の点数
    I, J, K = N,sum(B),sum(C)
    # dpテーブル dp[i][j]:=i番目以下でj点となるなら1．ならないなら0
    dp = [[[INF]*(K+1) for _ in range(J+1)] for _ in range(I+1)]
    # 初期条件
    # for i in range(I+1):
    dp[0][0][0]=0
    # ループ
    for i in range(1, I+1):
        for j in range(J+1):
            for k in range(K+1):
                # i-1番目を選ぶ場合
                if j>=B[i-1] and k>=C[i-1]:
                    dp[i][j][k] = min(dp[i][j][k], dp[i-1][j-B[i-1]][k-C[i-1]]+A[i-1])
                else:
                    dp[i][j][k]=min(dp[i][j][k],dp[i-1][j][k])
    ans=INF
    for j in range(1,J+1):
        for k in range(1,K+1):
            if k*Ma==j*Mb:
                ans=min(ans,dp[I][j][k])

    print(-1 if ans==INF else ans)




