def checker(d, ds, p):
    if len(ds) == 0:
        return (False, 0)
    b = ds[0]
    d2 = d[:]
    # use b
    d[0] += b[0]
    d[1] += b[1]
    d[2] += b[2]
    c = 0
    res = False
    if d[0] / d[1] != p:
        res, c = checker(d, ds[1:], p)
    else:
        res = True
        c = d[2]
    # no use
    res2, c2 = checker(d2, ds[1:], p)

    if res and res2:
        if d[2] < d2[2]:
            return (True, c)
        else:
            return (True, c2)
    elif res:
        return (True, c)
    elif res2:
        return (True, c2)
    return (False, 0)


