fn main() {
    let mut scanner = Scanner::new(stdin());
    let line = scanner.read_vector::<usize>().unwrap();
    let (n, a, b) = (line[0], line[1], line[2]);
    let mut arr = vec![];
    for _ in 0..n {
        let line = scanner.read_vector::<usize>().unwrap();
        arr.push((line[0], line[1], line[2]));
    }
    let ans = solve(n, a, b, &arr);
    if ans < std::usize::MAX {
        println!("{}", ans);
    } else {
        println!("-1");
    }
