        let (a, b, c);
        input!(a, b, c);
        if flag {
            l1.push((a, b, c));
        } else {
            l2.push((a, b, c));
        }
        flag = !flag;
    }

    let mut res1 = vec![];
    let mut res2 = vec![];

    dfs(&l1, 0, &mut res1, 0, 0, 0, ma, mb);
    dfs(&l2, 0, &mut res2, 0, 0, 0, ma, mb);

    let mut ans = usize::max_value();

    res2.sort_by(|a, b| a.2.cmp(&b.2));
    res2.sort_by(|a, b| a.3.cmp(&b.3));

    for i in 0..res1.len() {
        //println!("{}{:?} {}{:?}", i, &res1[i], j, &res2[j]);
        if let Ok(x) = res2.binary_search_by_key(
            &((mb * res1[i].0) as isize - (ma * res1[i].1) as isize),
            |&(_, _, _, a)| a,
        ) {
            if res1[i].2 + res2[x].2 == 0{
                continue;
            }
            ans = std::cmp::min(ans, res1[i].2 + res2[x].2);
        }
    }

    if ans == usize::max_value() {
        p(-1);
    } else {
        p(ans);
    }
}

