fn input<T>() -> T
    where T: std::str::FromStr {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

static ABMAX: usize = 10;
static NMAX: usize = 40;
fn main() {
    let n = input::<usize>();
    let ma = input::<usize>();
    let mb = input::<usize>();
    let abc = (0..n)
        .map(|_| (input::<usize>(), input::<usize>(), input::<usize>()))
        .collect::<Vec<_>>();

    let mut d = vec![vec![vec![usize::max_value(); NMAX*ABMAX+1]; NMAX*ABMAX+1]; NMAX+1];
    d[0][0][0] = 0;
    for (i, (a, b, c)) in abc.into_iter().enumerate() {
        for ca in 0..NMAX * ABMAX {
            for cb in 0..NMAX * ABMAX {
                if d[i][ca][cb] == usize::max_value() {continue;}
                d[i+1][ca][cb] = min(d[i+1][ca][cb], d[i][ca][cb]);
                d[i+1][ca+a][cb+b] = min(d[i+1][ca+a][cb+b], d[i][ca][cb] + c);
            }
        }
    }

    let mut ans = usize::max_value();
    for ca in 1..NMAX * ABMAX {
        for cb in 1..NMAX * ABMAX {
            if ca * mb == cb * ma {
                ans = min(ans, d[n][ca][cb]);
            }
        }
    }

    if ans == usize::max_value() {
        println!("-1");
        return;
    }
    println!("{}", ans);
}

