fn main() {
    input! {
        n: usize,
        m: (u32, u32),
        items: [((u32, u32), u32); n],
    }

    if let Some(c) = (1..1 << n)
        .flat_map(|group| {
            let ((a, b), c) = (0..n)
                .filter(|i| group & (1 << i) != 0)
                .fold(((0, 0), 0), |acc, i| {
                    // println!("{:?}", items[i]);
                    let ((i_a, i_b), i_c) = items[i];
                    let ((a_a, a_b), a_c) = acc;
                    ((i_a + a_a, i_b + a_b), i_c + a_c)
                });
            let g = std::cmp::max(gcd(a, b), 1);
            if (a / g, b / g) == m {
                Some(c)
            } else {
                None
            }
        })
        .min()
    {
        println!("{:?}", c);
    } else {
        println!("-1");
    }
}

fn gcd(a: u32, b: u32) -> u32 {
    match a {
        0 => b,
        _ => gcd(b % a, a),
    }
}

