    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}


fn solve(ma: usize, mb: usize, ns: Vec<(usize, usize, usize)>) -> i64 {
    let len = ns.len();
    let mut dp = vec![vec![vec![std::usize::MAX - 1000; 411]; 411]; len+1];
    dp[0][0][0] = 0;
    for i in 1..len+1 {
        let (a, b, c) = ns[i-1];
        for j in 0..401 {
            for k in 0..401 {
                dp[i][j][k] = std::cmp::min(dp[i-1][j][k], dp[i][j][k]);
                dp[i][j+a][k+b] = std::cmp::min(dp[i][j+a][k+b], dp[i-1][j][k] + c);
            }
        }
    }

    let mut res = std::usize::MAX;
    for i in 1..401 {
        for j in 1..401 {
            if i * mb != j * ma {
                continue;
            }
            if dp[len][i][j] < res {
                res = dp[len][i][j];
            }
        }
    }
    if res >= std::usize::MAX - 1000 {
        -1
    } else {
        res as i64
    }

}



