    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let (n, ma, mb) = scan!(usize, usize, usize);
    let vs = scan!(usize, usize, usize;n);

    let mut dp = vec![vec![vec![1 << 60; n * 10 + 1]; n * 10 + 1]; n + 1];

    dp[0][0][0] = 0;
    for (i, &(a, b, c)) in vs.iter().enumerate() {
        for j in 0..dp[i].len() {
            for k in 0..dp[i][j].len() {
                if j >= a && k >= b {
                    dp[i + 1][j][k] = min(dp[i][j][k], dp[i][j - a][k - b] + c)
                } else {
                    dp[i + 1][j][k] = dp[i][j][k]
                }
            }
        }
    }

    let mut ans = 1 << 60;
    for d in &dp[n] {
        for i in 1..d.len() {
            for j in 1..d.len() {
                if i * mb == j * ma {
                    ans = min(ans, dp[n][i][j])
                }
            }
        }
    }

    if ans != 1 << 60 {
        println!("{}", ans)
    } else {
        println!("-1")
    }
}

