fn main() {
    let mut scanner = Scanner::new(stdin());
    let line = scanner.read_vector::<usize>().unwrap();
    let (n, a, b) = (line[0], line[1], line[2]);
    let mut arr = vec![];
    for _ in 0..n {
        let line = scanner.read_vector::<usize>().unwrap();
        arr.push((line[0], line[1], line[2]));
    }
    let ans = solve(n, a, b, &arr);
    if ans < std::usize::MAX {
        println!("{}", ans);
    } else {
        println!("-1");
    }
}

fn solve(n: usize, a: usize, b: usize, arr: &[(usize, usize, usize)]) -> usize {
    let mut map = HashMap::new();
    let rest = power_set(&arr[(n / 2)..]);
    for (x, y, c) in rest.into_iter() {
        map.insert((x, y), c);
    }
    let max_val = 10 * (n - n / 2);
    let mut minimum_cost = std::usize::MAX;
    let all_cands = power_set(&arr[..(n / 2)]);
    for (x, y, c) in all_cands.into_iter() {
        for i in 1..(max_val + 1) {
            if x > 0 && y > 0 && x * b == y * a {
                minimum_cost = min(c, minimum_cost);
                continue;
            }
            if (x + i) % a != 0 {
                continue;
            }
            let sum = ((x + i) * b) / a;
            if sum <= y {
                continue;
            }
            let j = sum - y;
            if j > max_val {
                continue;
            }
            if !map.contains_key(&(i, j)) {
                continue;
            }
            let cost = map.get(&(i, j)).unwrap();
            minimum_cost = min(c + cost, minimum_cost);
        }
    }
    minimum_cost
}

fn power_set(arr: &[(usize, usize, usize)]) -> Vec<(usize, usize, usize)> {
    let n = arr.len();
    let mut set = vec![(0, 0, 0)];
    for i in 0..n {
        let mut new_set = vec![];
        while set.len() > 0 {
            let (a, b, c) = set.pop().unwrap();
            new_set.push((a, b, c));
            new_set.push((a + arr[i].0, b + arr[i].1, c + arr[i].2));
        }
        set = new_set;
    }
    set
}


