        if $x < $y {
            $x = $y;
            true
        } else {
            false
        }
    };
}


#[allow(unused_macros)]
macro_rules! chmin {
    ($x:expr, $y:expr) => {
        if $x > $y {
            $x = $y;
            true
        } else {
            false
        }
    };
}

fn main() {
    let cin = stdin();
    let mut scan = Scanner::new(cin.lock());
    let n = scan.read::<usize>();
    let ma = scan.read::<usize>();
    let mb = scan.read::<usize>();
    let abc = arr(n, |_| (scan.read::<usize>(), scan.read::<usize>(), scan.read::<i64>()));
    let mut dp = vecs![1i64<<60;41;401;401];
    dp[0][0][0] = 0;
    for i in 0..n {
        let (a,b,c) = abc[i];
        for j in 0..dp[0].len() {
            for k in 0..dp[0][0].len() {
                chmin!(dp[i+1][j][k], dp[i][j][k]);
                if j+a<dp[0].len() && k+b<dp[0][0].len() {chmin!(dp[i+1][j+a][k+b], dp[i][j][k] + c);}
            }
        }
    }
    let mut ret = 1i64 << 60;
    for i in 0..dp[0].len() {
        for j in 0..dp[0][0].len() {
            if i == 0 && j == 0 {continue;}
            if i*mb == j*ma {chmin!(ret, dp[n][i][j]);}
        }
    }
    println!("{}", if ret==1i64<<60 {-1} else {ret});
}

