fn get_min(cur: Option<u64>, next: u64) -> u64 {
    match cur {
        Some(x) => min(x, next),
        None => next
    }
}
fn main() {
    let (n, ma, mb): (usize, usize, usize) = readln();
    let mut a = Vec::new();
    let mut b = Vec::new();
    let mut c = Vec::new();
    for _ in 0..n {
        let (x, y, z): (usize, usize, u64) = readln();
        a.push(x);
        b.push(y);
        c.push(z);
    }
    const MAX: usize = 404;
    let mut dp = [[None; MAX]; MAX];
    dp[0][0] = Some(0 as u64);
    for k in 0..n {
        let x = a[k];
        let y = b[k];
        let z = c[k];
        let mut next = [[None; MAX]; MAX];
        for i in 0..MAX {
            for j in 0..MAX {
                if let Some(val) = dp[i][j] {
                    next[i][j] = Some(get_min(dp[i][j], val));
                    let ni = i + x;
                    let nj = j + y;
                    let nval = val + z;
                    next[ni][nj] = Some(get_min(next[ni][nj], nval));
                }
            }
        }
        dp = next;
    }
    let mut answer: u64 = u64::max_value();
    for i in 0..MAX {
        for j in 0..MAX {
            if i * mb == j * ma && i != 0 && j != 0 {
                if let Some(val) = dp[i][j] {
                    answer = min(answer, val);
                }
            }
        }
    }
    if answer == u64::max_value() {
        println!("-1");
    } else {
        println!("{}", answer);
    }
}

