fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n = sc.read();
    let ma: usize = sc.read();
    let mb: usize = sc.read();
    let abc: Vec<(usize, usize, i32)> = (0..n).map(|_| (sc.read(), sc.read(), sc.read())).collect();
    let mut dp: Vec<Vec<Vec<i32>>> = vec![vec![vec![std::i32::MAX; 401]; 401]; n + 1];
    dp[0][0][0] = 0;
    for i in 0..n {
        for j in 0..=400 {
            for k in 0..=400 {
                if dp[i][j][k] == std::i32::MAX {
                    continue;
                }
                dp[i + 1][j][k] = std::cmp::min(dp[i + 1][j][k], dp[i][j][k]);
                if j + abc[i].0 as usize <= 400 && k + abc[i].1 as usize <= 400 {
                    dp[i + 1][j + abc[i].0][k + abc[i].1] = std::cmp::min(
                        dp[i + 1][j + abc[i].0][k + abc[i].1],
                        dp[i][j][k] + abc[i].2,
                    );
                }
            }
        }
    }
    let mut mul = 1;
    let mut ans = std::i32::MAX;
    while mul * ma <= 400 && mul * mb <= 400 {
        if dp[n][mul * ma][mul * mb] < ans {
            ans = dp[n][mul * ma][mul * mb];
        }
        mul += 1;
    }
    if ans == std::i32::MAX {
        ans = -1;
    }
    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

