                .map(|&(x, cc)| (x + a * mb - b * ma, cc + c)),
        );
    }
    let mut v2 = vec![(0i64, 0i64)];
    for (a, b, c) in &abc[n / 2..] {
        v2.extend(
            v2.clone()
                .iter()
                .map(|&(x, cc)| (x - a * mb + b * ma, cc + c)),
        );
    }
    v1.sort();
    v2.sort();
    let mut ans = std::i64::MAX;
    for (x, c) in v1.into_iter() {
        if (x, c) == (0, 0) {
            continue;
        }
        let i = binary_search(|i| v2[i as usize].0 >= x, v2.len() as i64, -1) as usize;
        if let Some((xx, cc)) = v2.get(i) {
            if *xx == x {
                chmin!(ans, c + cc);
            }
        }
    }
    for (x, c) in v2.into_iter() {
        if (x, c) == (0, 0) {
            continue;
        }
        if x == 0 {
            chmin!(ans, c);
        }
    }
    if ans == std::i64::MAX {
        ans = -1;
    }
    println!("{}", ans);
}

