fn gcd(a: usize, b: usize) -> usize {
   if b == 0 {
      a
   } else {
      gcd(b, b % a)
   }
}

fn f(a: usize, b: usize) -> (usize, usize) {
   let c = gcd(a, b);
   (a / c, b / c)
}

#[fastout]
fn main() {
   input! {
      n: usize,
      ma: usize,
      mb: usize,
      abc: [(usize, usize, usize); n]
   }

