   map.insert((0, 0), 0);
   for &(a, b, c) in abc.iter() {
      let mut map2 = map.clone();
      for (&(an, bn), &cn) in map.iter() {
         map2
            .entry(f(an + a, bn + b))
            .and_modify(|v| *v = std::cmp::min(*v, cn + c))
            .or_insert(cn + c);
      }
      map = map2;
   }
   if let Some(ans) = map.get(&(ma, mb)) {
      println!("{}", ans);
   } else {
      println!("-1");
   }
}

