mod vectools {

///C++のupper_boundと同等の実装
pub fn upper_bound<T>(v: &Vec<T>, k: T) -> usize
where
    T: PartialOrd,
{
    let mut from = 0;
    let mut to = v.len();

    while to - from > 1 {
        let mid = (from + to) / 2;
        if v[mid] <= k {
            from = mid;
        } else {
            to = mid;
        }
    }
    if v[from] > k {
        from
    } else {
        to
    }
}

///C++のlower_boundと同等の実装
pub fn lower_bound<T>(v: &Vec<T>, k: T) -> usize
where
    T: PartialOrd,
{
    let mut from = 0;
    let mut to = v.len();

    while to - from > 1 {
        let mid = (from + to) / 2;
        if v[mid] < k {
            from = mid;
        } else {
            to = mid;
        }
    }

    if v[from] < k {
        to
    } else {
        from
    }
}

///次の順列を求める。
pub fn next_permutation<T>(v: &mut Vec<T>) -> bool
where
    T: PartialOrd,
{
    let mut pivot = v.len() - 1;
    loop {
        if pivot == 0 {
            return false;
        }
        if v[pivot] > v[pivot - 1] {
            pivot -= 1;
            break;
        }
        pivot -= 1;
    }
    let mut pivot_swap = v.len() - 1;
    while v[pivot] >= v[pivot_swap] {
        pivot_swap -= 1;
    }
    v.swap(pivot, pivot_swap);
    v[pivot + 1..].reverse();
    true
}

}

use input::*;
use vectools::*;

fn dfs(
    l: &Vec<(usize, usize, usize)>,
    i: usize,
    res: &mut Vec<(usize, usize, usize, isize)>,
    a: usize,
    b: usize,
    c: usize,
    ma: usize,
    mb: usize,
) {
    if i >= l.len() {
        res.push((a, b, c, (ma * b) as isize - (mb * a) as isize));
        return;
    }
    res.push((a, b, c, (ma * b) as isize - (mb * a) as isize));

    dfs(l, i + 1, res, a, b, c, ma, mb);
    dfs(l, i + 1, res, a + l[i].0, b + l[i].1, c + l[i].2, ma, mb);
}

fn main() {
    let (n, ma, mb): (usize, usize, usize);
    input!(n, ma, mb);
    let mut l1 = vec![];
    let mut l2 = vec![];
    let mut flag = true;
    for _ in 0..n {
        let (a, b, c);
        input!(a, b, c);
        if flag {
            l1.push((a, b, c));
        } else {
            l2.push((a, b, c));
        }
        flag = !flag;
    }

    let mut res1 = vec![];
    let mut res2 = vec![];

    dfs(&l1, 0, &mut res1, 0, 0, 0, ma, mb);
    dfs(&l2, 0, &mut res2, 0, 0, 0, ma, mb);

    let mut ans = usize::max_value();

    res2.sort_by(|a, b| a.2.cmp(&b.2));
    res2.sort_by(|a, b| a.3.cmp(&b.3));

    let mut cpvec = vec![];
    for i in &res2 {
        cpvec.push(i.3);
    }

    for i in 0..res1.len() {
        //println!("{}{:?} {}{:?}", i, &res1[i], j, &res2[j]);
        let f = lower_bound(
            &cpvec,
            (mb * res1[i].0) as isize - (ma * res1[i].1) as isize,
        );
        let t = upper_bound(
            &cpvec,
            (mb * res1[i].0) as isize - (ma * res1[i].1) as isize,
        );
        for j in f..t {
            if j < res2.len() && res2[j].3 == (mb * res1[i].0) as isize - (ma * res1[i].1) as isize
            {
                if res1[i].2 + res2[j].2 == 0 {
                    continue;
                }
                if (res1[i].1 + res2[j].1) * ma != (res2[j].0 + res1[i].0) * mb {
                    panic!("");
                }
                ans = std::cmp::min(ans, res1[i].2 + res2[j].2);
                break;
            }
        }
    }

    if ans == usize::max_value() {
        p(-1);
    } else {
        p(ans);
    }
}

pub trait IterScan: Sized {
    type Output;
    fn scan<'a, I: Iterator<Item = &'a str>>(iter: &mut I) -> Option<Self::Output>;
}
pub trait MarkedIterScan: Sized {
    type Output;
    fn mscan<'a, I: Iterator<Item = &'a str>>(self, iter: &mut I) -> Option<Self::Output>;
}
#[derive(Debug)]
pub struct Scanner<'a> {
    iter: std::str::SplitAsciiWhitespace<'a>,
}
impl<'a> Scanner<'a> {
    #[inline]
    pub fn new(s: &'a str) -> Self {
        let iter = s.split_ascii_whitespace();
        Self { iter }
    }
    #[inline]
    pub fn scan<T: IterScan>(&mut self) -> <T as IterScan>::Output {
        T::scan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn mscan<T: MarkedIterScan>(&mut self, marker: T) -> <T as MarkedIterScan>::Output {
        marker.mscan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn scan_vec<T: IterScan>(&mut self, size: usize) -> Vec<<T as IterScan>::Output> {
        (0..size)
            .map(|_| T::scan(&mut self.iter).unwrap())
            .collect()
    }
    #[inline]
    pub fn scan_chars(&mut self) -> Vec<char> {
        self.iter.next().unwrap().chars().collect::<Vec<char>>()
    }
}
