fn count(data: &Vec<Vec<isize>>, i:usize, a:isize, b:isize, c:isize, ma:isize, mb:isize) -> isize {
  if a > 0 && b > 0 && a*mb == b*ma { c }
  else if i >= data.len() { -1 }
  else {
    let v1 = count(data, i+1, a, b, c, ma, mb);
    let v2 = count(data, i+1, a+data[i][0], b+data[i][1], c+data[i][2], ma, mb);
    if v1*v2 < 0 { cmp::max(v1, v2) }
    else { cmp::min(v1, v2) }
  }
}

