fn dfs(
    l: &Vec<(usize, usize, usize)>,
    i: usize,
    res: &mut Vec<(usize, usize, usize, isize)>,
    a: usize,
    b: usize,
    c: usize,
    ma: usize,
    mb: usize,
) {
    if i >= l.len() {
        res.push((a, b, c, (ma * b) as isize - (mb * a) as isize));
        return;
    }
    res.push((a, b, c, (ma * b) as isize - (mb * a) as isize));

    dfs(l, i + 1, res, a, b, c, ma, mb);
    dfs(l, i + 1, res, a + l[i].0, b + l[i].1, c + l[i].2, ma, mb);
}


fn main() {
    let (n, ma, mb): (usize, usize, usize);
    input!(n, ma, mb);
    let mut l1 = vec![];
    let mut l2 = vec![];
    let mut flag = true;
    for _ in 0..n {
        let (a, b, c);
        input!(a, b, c);
        if flag {
            l1.push((a, b, c));
        } else {
            l2.push((a, b, c));
        }
        flag = !flag;
    }

    let mut res1 = vec![];
    let mut res2 = vec![];

    dfs(&l1, 0, &mut res1, 0, 0, 0, ma, mb);
    dfs(&l2, 0, &mut res2, 0, 0, 0, ma, mb);

    let mut ans = usize::max_value();

    res2.sort_by(|a, b| a.2.cmp(&b.2));
    res2.sort_by(|a, b| a.3.cmp(&b.3));

    let mut cpvec = vec![];
    for i in &res2 {
        cpvec.push(i.3);
    }

    for i in 0..res1.len() {
        //println!("{}{:?} {}{:?}", i, &res1[i], j, &res2[j]);
        let f = lower_bound(
            &cpvec,
            (mb * res1[i].0) as isize - (ma * res1[i].1) as isize,
        );
        let t = upper_bound(
            &cpvec,
            (mb * res1[i].0) as isize - (ma * res1[i].1) as isize,
        );
        for j in f..t {
            if j < res2.len() && res2[j].3 == (mb * res1[i].0) as isize - (ma * res1[i].1) as isize
            {
                if res1[i].2 + res2[j].2 == 0 {
                    continue;
                }
                if (res1[i].1 + res2[j].1) * ma != (res2[j].0 + res1[i].0) * mb {
                    panic!("");
                }
                ans = std::cmp::min(ans, res1[i].2 + res2[j].2);
            }
        }
    }

    if ans == usize::max_value() {
        p(-1);
    } else {
        p(ans);
    }
}

