    let mut ans = std::usize::MAX;
    let mut target = m;
    while target <= size2 {
        //println!("{} {}", dp[target], target);
        ans = min(ans, dp[target]);
        target += m;
    }
    if ans == std::usize::MAX {
        println!("{}", -1);
        return;
    }
    println!("{}", ans);
    // dbg!(dp);
}

