trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}
impl<T: Ord> BinarySearch<T> for [T] {
#[allow(dead_code)]
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
#[allow(dead_code)]
    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

fn solve() {
    let (n, ma, mb) = get!(usize, usize, usize);
    let abc = get!(usize, usize, usize; n);

    let mut cand = Vec::new();
    for i in 1.. {
        if ma * i > 400 || mb * i > 400 {
            break;
        }
        cand.push((ma*i, mb*i));
    }

    let mut vec = Vec::new();
    for i in 0..1<<(n/2) {
        let mut sum = (0,0,0);
        for j in 0..n/2 {
            if (i>>j)%2 == 1 { 
                sum.0 += abc[j].0;
                sum.1 += abc[j].1;
                sum.2 += abc[j].2;
            }
        }
        vec.push(sum);
    }

    vec.sort();

    let mut mn = std::usize::MAX;
    for i in 0..1<<(n-n/2) {
        let mut sum = (0,0,0);
        for j in 0..(n-n/2) {
            if (i>>j)%2 == 1 { 
                let tmp = n/2+j;
                sum.0 += abc[tmp].0;
                sum.1 += abc[tmp].1;
                sum.2 += abc[tmp].2;
            }
        }
        for &(a,b) in &cand {
            if sum.0 > a || sum.0 > b {
                continue;
            }
            let a = a-sum.0;
            let b = b-sum.1;
            let index = vec.lower_bound(&(a,0,0));
            for k in index..vec.len() {
                if vec[k].0 != a {
                    break;
                }
                if vec[k].1 == b {
                    mn = min!(mn, sum.2+vec[k].2);
                }
            }
        }
    }
    if mn == std::usize::MAX {
        println!("-1");
        return;
    }
    println!("{}", mn);
}

