use input::*;

fn dfs(
    l: &Vec<(usize, usize, usize)>,
    i: usize,
    res: &mut Vec<(usize, usize, usize)>,
    a: usize,
    b: usize,
    c: usize,
) {
    if i >= l.len() {
        res.push((a, b, c));
        return;
    }
    res.push((a, b, c));

    dfs(l, i + 1, res, a, b, c);
    dfs(l, i + 1, res, a + l[i].0, b + l[i].1, c + l[i].2);
}

fn main() {
    let (n, ma, mb): (usize, usize, usize);
    input!(n, ma, mb);
    let mut l1 = vec![];
    let mut l2 = vec![];
    let mut flag = true;
    for _ in 0..n {
        let (a, b, c);
        input!(a, b, c);
        if flag {
            l1.push((a, b, c));
        } else {
            l2.push((a, b, c));
        }
        flag = !flag;
    }

    let mut res1 = vec![];
    let mut res2 = vec![];

    dfs(&l1, 0, &mut res1, 0, 0, 0);
    dfs(&l2, 0, &mut res2, 0, 0, 0);

    let mut ans = usize::max_value();

    for i in 0..res1.len() {
        for j in 0..res2.len() {
            //println!("{}{:?} {}{:?}", i, &res1[i], j, &res2[j]);
            if res1[i].0 + res2[j].0 != 0
                && res1[i].1 + res2[j].1 != 0
                && ma * (res1[i].1 + res2[j].1) == mb * (res1[i].0 + res2[j].0)
            {
                ans = std::cmp::min(ans, res1[i].2 + res2[j].2);
            }
        }
    }

    if ans == usize::max_value() {
        p(-1);
    } else {
        p(ans);
    }
}

