fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let ma: usize = sc.ne();
    let mb: usize = sc.ne();
    let a: Vec<(usize, usize, i32)> = (0..n).map(|_| (sc.ne(), sc.ne(), sc.ne())).collect();
    let asum = a.iter().fold(0, |acc, x| acc + x.0) + 1;
    let bsum = a.iter().fold(0, |acc, x| acc + x.1) + 1;
    let an = asum as usize;
    let bn = bsum as usize;
    let inf = 1000000000i32;
    let mut dp = vec![vec![inf; bn]; an];
    dp[0][0] = 0;
    for x in a {
        let mut dp_ = dp.clone();
        for i in 0..an {
            for j in 0..bn {
                if dp[i][j] == inf {
                    continue;
                }
                dp_[i + x.0][j + x.1] = min(dp_[i + x.0][j + x.1], dp[i][j] + x.2);
            }
        }
        dp = dp_;
    }
    let mut ans = inf;
    for i in 1..an {
        for j in 1..bn {
            if i % ma != 0 {
                continue;
            }
            let k = i / ma;
            if j == k * mb {
                ans = min(ans, dp[i][j]);
            }
        }
    }
    if ans == inf {
        ans = -1;
    }
    println!("{}", ans);
}
