const INF: usize = 1_000_000_000_000_000;

fn solve() {
    let (n, ma, mb) = get!(usize, usize, usize);
    let abc = get!(usize, usize, usize; n);

    let mut dp = vec![vec![vec![INF; 401]; 401]; n+1];
    dp[0][0][0] = 0;
    for i in 0..n {
        for a in 0..401 {
            for b in 0..401 {
                dp[i+1][a][b] = if abc[i].0 > a || abc[i].1 > b {
                    dp[i][a][b]
                } else {
                    min!(dp[i][a][b], dp[i][a-abc[i].0][b-abc[i].1]+abc[i].2)
                };
            }
        }
    }
    let mut mn = INF;
    for a in 0..401 {
        for b in 0..401 {
            if a == 0 && b == 0 {
                continue;
            }
            if ma*b == mb*a {
                mn = min!(mn, dp[n][a][b]);
            }
        }
    }
    if mn == INF {
        println!("-1");
        return;
    }
    println!("{}", mn);
}

