fn solve(i: usize, a: usize, b: usize, n: usize, ma: usize, mb: usize, arr: &Vec<(usize, usize, i32)>, dp: &mut Vec<Vec<Vec<i32>>>) -> i32 {
    if i == n { return if a != 0 && b != 0 && a * mb == b * ma { 0 } else { 5000 } }
    if dp[i][a][b] == 0 {
