fn main(){
    let nmm = getvec();
    let (n, ma, mb) = (nmm[0], nmm[1], nmm[2]);
    let mut materials: Vec<Vec<i64>> = Vec::new();
    for _ in 0..n {materials.push(getvec())};
    println!("{}", solve(ma, mb, &materials));
}

fn solve(ma: i64, mb: i64, materials: &Vec<Vec<i64>>) -> i64{
    let inf = 100000;
    let mut dp: [[i64;400];400] = [[inf;400];400];
    for material in materials.iter(){
        let (a, b, c) = (material[0] as usize, material[1] as usize, material[2]);
        if dp[a-1][b-1] > c{
            dp[a-1][b-1] = c
        }
        for i in 0..400-a{
            for j in 0..400-b{
                if dp[i+a][j+b] > dp[i][j]+c{
                    dp[i+a][j+b] = dp[i][j]+c
                }
            }
        }
    }
    let mut ans = inf;
    for i in 1..41{
        let x = dp[(ma*i-1) as usize][(mb*i-1) as usize];
        if x < ans{
            ans = x;
        }
    }
    if ans==inf {-1} else {ans}
}

