// 指定した数までの素数のvec エラトステネスの篩
fn prime_list(n: usize) -> Vec<usize> {
    let mut ret: Vec<usize> = Vec::new();
    let num = n - 1;
    let mut table: Vec<bool> = vec![false; num];
    for i in 0..num {
        if !table[i] {
            let next = i + 2;
            ret.push(next);
            let mut j = i + next;
            while j < num {
                table[j] = true;
                j += next;
            }
        }
    }
    ret
} // [2, 3, 5, 7, ..., n]

// 素因数分解
fn prime_factorization(n: usize) -> Vec<(usize, usize)> {
    let mut ret: Vec<(usize, usize)> = Vec::new();
    let pl = prime_list((n as f64).sqrt() as usize + 1);
    let mut num = n;
    for p in pl { // 各素数で割れるだけ割る
        let mut cnt = 0;
        while (num % p) == 0 {
            num /= p;
            cnt += 1;
        }
        if cnt > 0 { ret.push((p, cnt)); }
    }
    if ret.is_empty() { vec![(n, 1); 1] }
    else { ret }
} // n = 2*2*2 + 3 -> [(2, 3), (3, 1)]

fn is_prime(n: i64) -> bool {
    let mut i = 2;
    loop {
        if (n % i) == 0 {return false; }
        i += 1;
        if (i*i) > n { break; }
    }
    return true;
}

// オイラーのφ関数 nと互いに素（gcdが1）な数の個数が取れる
fn euler_phi_vec(n: usize) -> Vec<u64> {
    let mut f: Vec<u64> = vec![0; n];
    let mut p: Vec<u64> = vec![1; n];
    for i in 0..n { f[i] = i as u64; }
    for i in 2..n {
        if p[i] != 0 {
            f[i] -= f[i] / i as u64;
            let mut j = i + i;
            loop {
                if j >= n { break; }
                p[j] = 0;
                f[j] -= f[j] / i as u64;
                j += i;
            }
        }
    }
    f
}

fn main() {
    let mut pr = ContestPrinter::new();

    let MAX = 1000000;
    let (N, MA, MB) = readl!(usize, usize, usize);
    let mut abc = Vec::new();

    let (N1, A, B) = (N + 1, 401, 401);
    // dp[i][j][k] = k番目まで調べた時の合計幅i，使用枚数jの重要度の最大値
    // 更新: k番目まで調べたけどそれを使わない時が最大 = dp[i][j][k-1] か，
    //                           使う時が最大 = dp[i-a[k-1]][j-1][k-1] + b[k-1]　のどちらか
    let mut dp: Vec<Vec<Vec<i32>>> = vec![vec![vec![MAX; B]; A]; N1];

    for i in 0..N {
        let (a, b, c) = readl!(usize, usize, i32);
        abc.push((a, b, c));
//        dp[1][a][b] = c;
    }
    dp[0][0][0] = 0;

    for i in 1..N1 {
        for j in 1..A {
            for k in 1..B {
                let (a, b, c) = abc[i - 1];
                let mut n_use = min(dp[i - 1][j][k], dp[i][j][k]);
                let mut y_use = if (a > j) | (b > k) { dp[i][j][k] }
                            else { dp[i - 1][j - a][k - b] };   
                dp[i][j][k] = min(n_use, y_use + c);
            }
        }
    }

    let mut ans = MAX;
    for i in 1..A {
        for j in 1..B {
            if (i*MB) != (j*MA) { continue; }
            let v = dp[N][i][j];
            ans = min(ans, v);
        }
    }

    pr.println(if ans == MAX { -1 } else { ans });
}

