const ITEM_MAX: usize = 401;
const INF: usize = 10_000_000;
use std::cmp::min;

fn main() {
    input! {
        n: usize,
        m: (usize, usize),
        items: [((usize, usize), usize); n],
    }

    let mut dp = vec![vec![vec![INF; ITEM_MAX]; ITEM_MAX]; n + 1];

    dp[0][0][0] = 0;

    for i in 0..n {
        for j in 0..ITEM_MAX {
            for k in 0..ITEM_MAX {
                if dp[i][j][k] == INF {
                    continue;
                }
                // 加えない場合
                // なにも変わらないので、次の値と比較して小さい方で更新
                dp[i + 1][j][k] = min(dp[i + 1][j][k], dp[i][j][k]);

                // 加える場合
                let ((a, b), c) = items[i];
                let next_a = j + a;
                let next_b = k + b;
                // 他のパターンですでに更新されている場合もありうるので、今の値にCを足したものと、次のテーブルの対象の値とを比較して小さい方で更新
                dp[i + 1][next_a][next_b] = min(dp[i + 1][next_a][next_b], dp[i][j][k] + c);
            }
        }
    }

    let mut min_c = None;

    // 一番小さいCの合計を探す
    for j in 1..ITEM_MAX {
        for k in 1..ITEM_MAX {
            // 比率が同じ場合のみ
            // a:b = Ma:Mb => a*Mn == b*Ma
            if j * m.1 == k * m.0 {
                let c = dp[n][j][k];
                min_c = min_c.or(Some(c)).map(|x| min(x, c));
            }
        }
    }
    match min_c {
        Some(x) => println!("{:?}", x),
        _ => println!("-1"),
    }
}

