fn solve(n: usize, a: usize, b: usize, arr: &[(usize, usize, usize)]) -> usize {
    let mut map = HashMap::new();
    let rest = power_set(&arr[(n / 2)..]);
    for (x, y, c) in rest.into_iter() {
        map.insert((x, y), c);
    }
    let max_val = 10 * (n - n / 2);
    let mut minimum_cost = std::usize::MAX;
    let all_cands = power_set(&arr[..(n / 2)]);
    for (x, y, c) in all_cands.into_iter() {
        if c > minimum_cost {
            continue;
        }
        let mut i = if x % a == 0 { 0 } else { a - x % a };
        while i <= max_val {
            let sum = ((x + i) * b) / a;
            if sum < y {
                i += a;
                continue;
            }
            let j = sum - y;
            if j > max_val {
                break;
            }
            if !map.contains_key(&(i, j)) {
                i += a;
                continue;
            }
            let cost = map.get(&(i, j)).unwrap();
            if c + *cost > 0 {
                minimum_cost = min(c + *cost, minimum_cost);
            }
            i += a;
        }
    }
    minimum_cost
}

fn power_set(arr: &[(usize, usize, usize)]) -> Vec<(usize, usize, usize)> {
    let n = arr.len();
    let mut set = vec![(0, 0, 0)];
    for i in 0..n {
        let mut new_set = Vec::with_capacity(2 * set.len());
        while set.len() > 0 {
            let (a, b, c) = set.pop().unwrap();
            new_set.push((a, b, c));
            new_set.push((a + arr[i].0, b + arr[i].1, c + arr[i].2));
        }
        set = new_set;
    }
    set
}


