const BIG_STACK_SIZE: bool = true;
#[allow(dead_code)]
fn main() {
    use std::thread;
    if BIG_STACK_SIZE {
        thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}
fn solve() {
    input! {
        N: usize, Ma: usize, Mb: usize,
        ABC: [(usize,usize,usize);N],
    }

    // dp[i][sum_a][sum_b]の最小コスト
    let mut dp = vec![vec![vec![1<<40; 401]; 401]; N+1];
    dp[0][0][0] = 0;
    for i in 1..N+1 {
        let (ai,bi,ci) = ABC[i-1];
        for a in 0..401 {
            for b in 0..401 {
                if dp[i-1][a][b] == 1<<40 { continue; }
                dp[i][a][b] = min(dp[i][a][b], dp[i-1][a][b]);
                dp[i][a+ai][b+bi] = min(dp[i][a+ai][b+bi], dp[i-1][a][b]+ci);
            }
        }
    }
    let mut res = 1<<40;
    for a in 1..401 {
        for b in 1..401 {
            let c = dp[N][a][b];
            if Mb*a == Ma*b {
                res = min(res,c);
            }
        }
    }
    if res == 1<<40 {
        println!("-1");
    } else {
        println!("{}", res);
    }
}

