struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> { self.cin::<String>().chars().collect() }
    fn vec<T: FromStr>(&mut self, n: usize) -> Vec<T> { (0..n).map(|_| self.cin()).collect() }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    let v:Vec<usize> = read_vec();
    let (n, ma, mb) = (v[0], v[1], v[2]);
    let mut a = vec![0usize; n];
    let mut b = vec![0usize; n];
    let mut c = vec![0usize; n];

    for i in 0..n {
        let v:Vec<usize> = read_vec();
        a[i] = v[0];
        b[i] = v[1];
        c[i] = v[2];
    }

    let sum_a: usize = a.iter().sum();
    let sum_b: usize = b.iter().sum();
    // println!("sum_a {0} sum_b {1}", sum_a, sum_b);
    let mut dp = vec![vec![std::usize::MAX; sum_b + 1]; sum_a + 1];
    dp[0][0] = 0;

    for ni in 0..n {
        for ai in (0..sum_a + 1).rev() {
            for bi in (0..sum_b + 1).rev() {
                if dp[ai][bi] == std::usize::MAX {
                    continue;
                }
                dp[ai + a[ni]][bi + b[ni]] = std::cmp::min(dp[ai + a[ni]][bi + b[ni]],
                                                           dp[ai][bi] + c[ni]);
            }
        }
    }

    let mut ans = std::usize::MAX;
    for ai in 1..sum_a + 1 {
        for bi in 1..sum_b + 1 {
            if ai % ma == 0 && bi % mb == 0  && ai != 0 && ai * mb == bi * ma {
                // println!("{0} {1}", ai, bi);
                ans = std::cmp::min(ans, dp[ai][bi]);
            }
        }
    }
    if ans == std::usize::MAX {
        println!("-1");
    } else {
        println!("{:?}", ans);
    }
}

fn get_min(cur: Option<u64>, next: u64) -> u64 {
    match cur {
        Some(x) => min(x, next),
        None => next
    }
}
fn main() {
    let (n, ma, mb): (usize, usize, usize) = readln();
    let mut a = Vec::new();
    let mut b = Vec::new();
    let mut c = Vec::new();
    for _ in 0..n {
        let (x, y, z): (usize, usize, u64) = readln();
        a.push(x);
        b.push(y);
        c.push(z);
    }
    const MAX: usize = 404;
    let mut dp = [[None; MAX]; MAX];
    dp[0][0] = Some(0 as u64);
    for k in 0..n {
        let x = a[k];
        let y = b[k];
        let z = c[k];
        let mut next = [[None; MAX]; MAX];
        for i in 0..MAX {
            for j in 0..MAX {
                if let Some(val) = dp[i][j] {
                    next[i][j] = Some(get_min(next[i][j], val));
                    let ni = i + x;
                    let nj = j + y;
                    let nval = val + z;
                    next[ni][nj] = Some(get_min(next[ni][nj], nval));
                }
            }
        }
        dp = next;
    }
    let mut answer: u64 = u64::max_value();
    for i in 0..MAX {
        for j in 0..MAX {
            if i * mb == j * ma && i != 0 && j != 0 {
                if let Some(val) = dp[i][j] {
                    answer = min(answer, val);
                }
            }
        }
    }
    if answer == u64::max_value() {
        println!("-1");
    } else {
        println!("{}", answer);
    }
}

